planRouter.post("/workstation/tool-observation", (req, res) => {
  const parsed = workstationToolObservationRequestSchema.safeParse(req.body ?? {});
  if (!parsed.success) {
    return res.status(400).json({
      ok: false,
      error: "invalid_workstation_tool_observation",
      issues: parsed.error.issues,
    });
  }
  return res.status(200).json(appendWorkstationToolObservation(parsed.data));
});

planRouter.post("/situation/standby-observation", (req, res) => {
  const parsed = situationStandbyObservationRequestSchema.safeParse(req.body ?? {});
  if (!parsed.success) {
    return res.status(400).json({
      ok: false,
      error: "invalid_situation_standby_observation",
      issues: parsed.error.issues,
    });
  }
  const input = parsed.data;
  const appendResult = appendWorkstationToolObservation({
    schema: "helix.workstation.tool_observation.v1",
    thread_id: input.thread_id ?? null,
    turn_id: input.turn_id ?? null,
    session_id: input.session_id ?? null,
    trace_id: input.trace_id ?? null,
    setup_call_id: input.salience_receipt.receipt_id,
    action: {
      panel_id: "situation-room-pipelines",
      action_id: "standby_observation",
    },
    receipt: {
      schema: "helix.situation_standby_observation.v1",
      room_id: input.room_id,
      graph_id: input.graph_id ?? null,
      salience_receipt: input.salience_receipt,
      interjection_proposal: input.interjection_proposal ?? null,
    },
    ok: true,
    error: null,
  });
  if (input.salience_receipt.should_request_user_input && input.thread_id && input.turn_id) {
    appendHelixThreadEvent({
      route: "/ask",
      event_type: "server_request_created",
      thread_id: input.thread_id,
      turn_id: input.turn_id,
      session_id: input.session_id ?? null,
      trace_id: input.trace_id ?? null,
      request_id: `standby_request:${input.salience_receipt.receipt_id}`,
      request_kind: "request_user_input",
      request_payload: {
        schema: "helix.situation_standby_request.v1",
        room_id: input.room_id,
        graph_id: input.graph_id ?? null,
        salience_receipt_id: input.salience_receipt.receipt_id,
        reason: input.salience_receipt.reason,
        summary: input.salience_receipt.summary,
      },
      meta: {
        kind: "situation_standby_request",
      },
    });
  }
  return res.status(200).json({
    ...appendResult,
    should_request_user_input: input.salience_receipt.should_request_user_input,
    should_speak: input.salience_receipt.should_speak,
  });
});

