const buildLiveAnswerEnvironmentReadResponse = (args: {
  environment: ReturnType<typeof getLiveAnswerEnvironment>;
  threadId?: string | null;
  limit?: number;
}) => {
  const limit = Number.isFinite(args.limit) ? Math.max(0, Math.min(80, Math.trunc(args.limit ?? 30))) : 30;
  const deltas = args.environment
    ? listLiveAnswerEnvironmentDeltas(args.environment.environment_id).slice(-limit)
    : [];
  const latestDelta = deltas.at(-1) ?? null;
  const latestContextPack = args.environment
    ? buildSituationContextPack({
        threadId: args.environment.thread_id,
        roomId: args.environment.room_id ?? null,
      })
    : null;
  const sourceDescriptors = args.environment
    ? listLiveSourceDescriptors({
        threadId: args.environment.thread_id,
        environmentId: args.environment.environment_id,
        limit: 40,
      })
    : [];
  const fallbackSourceDescriptors = args.environment && sourceDescriptors.length === 0
    ? listLiveSourceDescriptors({
        threadId: args.environment.thread_id,
        limit: 40,
      }).filter((descriptor) => args.environment?.source_ids.includes(descriptor.source_id))
    : sourceDescriptors;
  const schemaSelection = args.environment
    ? selectLiveSchemaForEnvironment({
        environment: args.environment,
        descriptors: fallbackSourceDescriptors,
      })
    : null;
  const schemaCompatibility = args.environment && schemaSelection
    ? inspectLiveSchemaCompatibility({
        environment: args.environment,
        selection: schemaSelection,
        descriptors: fallbackSourceDescriptors,
      })
    : null;
  const navigationState = args.environment?.room_id
    ? queryMinecraftNavigationState({ roomId: args.environment.room_id, limit: 6 })
    : null;
  return {
    ok: true,
    schema: "helix.live_answer_environment_read.v1",
    environment: args.environment ?? null,
    deltas,
    latest_context_pack: latestContextPack,
    source_descriptors: fallbackSourceDescriptors,
    schema_selection: schemaSelection,
    schema_compatibility: schemaCompatibility,
    navigation_state: navigationState,
    debug: {
      thread_id: args.environment?.thread_id ?? args.threadId ?? null,
      environment_id: args.environment?.environment_id ?? null,
      delta_count: deltas.length,
      last_delta_id: latestDelta?.delta_id ?? null,
      last_next_hash: latestDelta?.next_hash ?? null,
      source_descriptor_count: fallbackSourceDescriptors.length,
      schema_selection_id: schemaSelection?.selection_id ?? null,
      schema_compatibility_ok: schemaCompatibility?.ok ?? null,
      navigation_state_id: navigationState?.navigation_state?.state_id ?? null,
      raw_transcript_included: false,
      raw_audio_included: false,
      deterministic_content_role: "observation_not_assistant_answer",
    },
  };
};

