planRouter.post("/situation/live-agentic-review/request", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const environmentId = typeof body.environment_id === "string" ? body.environment_id.trim() : "";
  const threadId = typeof body.thread_id === "string" ? body.thread_id.trim() : "helix-ask:desktop";
  const environment = environmentId
    ? getLiveAnswerEnvironment(environmentId)
    : getActiveLiveAnswerEnvironmentForThread(threadId);
  if (!environment) {
    return res.status(404).json({
      ok: false,
      schema: "helix.live_agentic_review_receipt.v1",
      request: null,
      error: "environment_not_found",
    });
  }
  const question = typeof body.question === "string" && body.question.trim()
    ? body.question.trim()
    : "Review the latest live environment state.";
  const trigger =
    body.trigger === "commentary_request" ||
    body.trigger === "salience_threshold" ||
    body.trigger === "windowed_review" ||
    body.trigger === "manual_button"
      ? body.trigger
      : "user_direct";
  const request = buildLiveAgenticReviewRequest({
    environment,
    question,
    trigger,
  });
  const receipt = recordLiveAgenticReviewRequest({ request });
  return res.status(200).json(receipt);
});

const liveContinuationString = (value: unknown): string | null =>
  typeof value === "string" && value.trim() ? value.trim() : null;

const liveContinuationStringArray = (value: unknown): string[] =>
  Array.isArray(value)
    ? Array.from(new Set(value.filter((entry): entry is string => typeof entry === "string" && entry.trim().length > 0).map((entry) => entry.trim())))
    : [];

const LIVE_CONTINUATION_TRIGGER_VALUES = new Set<LiveContinuationTrigger>([
  "world_event",
  "salience",
  "source_health",
  "manual_refresh",
  "agentic_review",
  "cadence",
]);

const LIVE_CONTINUATION_LANE_VALUES = new Set<LiveContinuationLane>([
  "source_health",
  "world_state",
  "risk_watch",
  "objective_progress",
  "route_watch",
  "resource_status",
  "prediction_reflection",
  "voice_gate",
]);

const liveContinuationTriggerFromBody = (
  value: unknown,
): LiveContinuationTrigger =>
  typeof value === "string" && LIVE_CONTINUATION_TRIGGER_VALUES.has(value as LiveContinuationTrigger)
    ? (value as LiveContinuationTrigger)
    : "manual_refresh";

const findLiveContinuationJob = (
  body: Record<string, unknown>,
): LiveContinuationJob | null => {
  const jobId = liveContinuationString(body.job_id ?? body.jobId);
  if (jobId) {
    return (
      listLiveContinuationJobs({ includeStopped: true, status: "any" }).find(
        (job) => job.job_id === jobId,
      ) ?? null
    );
  }
  const roomId = liveContinuationString(body.room_id ?? body.roomId);
  if (roomId) return getActiveLiveContinuationJobForRoom(roomId);
  const threadId = liveContinuationString(body.thread_id ?? body.threadId);
  if (threadId) return listLiveContinuationJobs({ threadId, status: "active" })[0] ?? null;
  return null;
};

const buildLiveContinuationJobReceipt = (args: {
  action: string;
  job: LiveContinuationJob | null;
  status: "started" | "queried" | "paused" | "resumed" | "stopped" | "missing_input" | "not_found";
  evidenceRefs?: string[];
}) => ({
  schema: "helix.live_continuation_job_receipt.v1",
  receipt_id: `live_continuation_job:${crypto.randomUUID()}`,
  action: args.action,
  job_id: args.job?.job_id ?? null,
  thread_id: args.job?.thread_id ?? null,
  room_id: args.job?.room_id ?? null,
  environment_id: args.job?.environment_id ?? null,
  contract_id: args.job?.contract_id ?? null,
  source_ids: args.job?.source_ids ?? [],
  status: args.status,
  job_status: args.job?.status ?? null,
  mode: args.job?.mode ?? "single_agent",
  evidence_threshold: args.job?.evidence_threshold ?? "observed",
  ...helixReceiptNotAnswerFlags,
  evidence_refs: args.evidenceRefs ?? (args.job ? [`live_continuation_job:${args.job.job_id}`] : []),
});

planRouter.post("/situation/live-continuation/start", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = liveContinuationString(body.thread_id ?? body.threadId);
  const roomId = liveContinuationString(body.room_id ?? body.roomId);
  const objective = liveContinuationString(body.objective);
  if (!threadId || !roomId || !objective) {
    return res.status(400).json({
      ok: false,
      receipt: buildLiveContinuationJobReceipt({
        action: "live_continuation.start",
        job: null,
        status: "missing_input",
        evidenceRefs: ["missing:thread_id", "missing:room_id", "missing:objective"],
      }),
      error: "missing_live_continuation_start_input",
    });
  }
  const sourceIds = liveContinuationStringArray(body.source_ids ?? body.sourceIds);
  const singleSourceId = liveContinuationString(body.source_id ?? body.sourceId);
  const requestedSourceIds = sourceIds.length
    ? sourceIds
    : singleSourceId
      ? [singleSourceId]
      : [];
  if (
    rejectLegacyRoomSourceWorldEvents(
      requestedSourceIds.map((source_id) => ({ source_id })),
      res,
    )
  ) {
    return;
  }
  const lanesEnabled = liveContinuationStringArray(body.lanes_enabled ?? body.lanesEnabled)
    .filter((lane): lane is LiveContinuationLane => LIVE_CONTINUATION_LANE_VALUES.has(lane as LiveContinuationLane));
  const job = upsertLiveContinuationJob({
    thread_id: threadId,
    room_id: roomId,
    environment_id: liveContinuationString(body.environment_id ?? body.environmentId),
    contract_id: liveContinuationString(body.contract_id ?? body.contractId),
    source_ids: requestedSourceIds,
    objective,
    status: "active",
    voice_policy:
      body.voice_policy === "muted" ||
      body.voice_policy === "propose_only" ||
      body.voice_policy === "confirm_speak_required" ||
      body.voice_policy === "automatic_when_policy_allows"
        ? body.voice_policy
        : undefined,
    evidence_threshold:
      body.evidence_threshold === "likely" || body.evidence_threshold === "confirmed" || body.evidence_threshold === "observed"
        ? body.evidence_threshold
        : undefined,
    lanes_enabled: lanesEnabled.length ? lanesEnabled : undefined,
    cooldowns: typeof body.min_tick_interval_ms === "number"
      ? { min_tick_interval_ms: body.min_tick_interval_ms }
      : undefined,
  });
  return res.status(200).json({
    ok: true,
    receipt: buildLiveContinuationJobReceipt({ action: "live_continuation.start", job, status: "started" }),
    job,
    raw_content_included: false,
    assistant_answer: false,
  });
});

planRouter.post("/situation/live-continuation/query", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const jobId = liveContinuationString(body.job_id ?? body.jobId);
  const threadId = liveContinuationString(body.thread_id ?? body.threadId);
  const roomId = liveContinuationString(body.room_id ?? body.roomId);
  const sourceId = liveContinuationString(body.source_id ?? body.sourceId);
  const status = liveContinuationString(body.status);
  const jobs = listLiveContinuationJobs({
    threadId,
    roomId,
    sourceId,
    includeStopped: status === "any" || status === "stopped",
    status: status === "any" || status === "active" || status === "paused" || status === "blocked" || status === "stale" || status === "stopped"
      ? status
      : "any",
  }).filter((job) => !jobId || job.job_id === jobId);
  return res.status(200).json({
    ok: true,
    receipt: buildLiveContinuationJobReceipt({ action: "live_continuation.query", job: jobs[0] ?? null, status: "queried" }),
    jobs,
    ...helixReceiptNotAnswerFlags,
    evidence_refs: jobs.map((job) => `live_continuation_job:${job.job_id}`),
  });
});

const handleLiveContinuationLifecycle =
  (
    action: "pause" | "resume" | "stop",
    updater: (jobId: string, now?: string) => LiveContinuationJob | null,
  ) =>
  (req: Request, res: Response) => {
    const body =
      req.body && typeof req.body === "object"
        ? (req.body as Record<string, unknown>)
        : {};
    const jobId = liveContinuationString(body.job_id ?? body.jobId);
    if (!jobId) {
    return res.status(400).json({
      ok: false,
      receipt: buildLiveContinuationJobReceipt({
        action: `live_continuation.${action}`,
        job: null,
        status: "missing_input",
        evidenceRefs: ["missing:job_id"],
      }),
      error: "missing_live_continuation_job_id",
    });
  }
    const job = updater(jobId, new Date().toISOString());
    if (!job) {
    return res.status(404).json({
      ok: false,
      receipt: buildLiveContinuationJobReceipt({
        action: `live_continuation.${action}`,
        job: null,
        status: "not_found",
        evidenceRefs: [`live_continuation_job:${jobId}:not_found`],
      }),
      error: "live_continuation_job_not_found",
    });
  }
    return res.status(200).json({
    ok: true,
    receipt: buildLiveContinuationJobReceipt({
      action: `live_continuation.${action}`,
      job,
      status: action === "pause" ? "paused" : action === "resume" ? "resumed" : "stopped",
    }),
    job,
  });
  };

planRouter.post("/situation/live-continuation/pause", handleLiveContinuationLifecycle("pause", pauseLiveContinuationJob));
planRouter.post("/situation/live-continuation/resume", handleLiveContinuationLifecycle("resume", resumeLiveContinuationJob));
planRouter.post("/situation/live-continuation/stop", handleLiveContinuationLifecycle("stop", stopLiveContinuationJob));

