const handleLiveAnswerEnvironmentCreate = (req: Request, res: Response) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = typeof body.thread_id === "string" && body.thread_id.trim() ? body.thread_id.trim() : "helix-ask:desktop";
  const objective = typeof body.objective === "string" && body.objective.trim()
    ? body.objective.trim()
    : "Create a live answer environment.";
  const cadenceControlIntent = classifyLiveSourceContinuationIntent(objective);
  if (
    cadenceControlIntent?.kind === "live_pipeline_control" &&
    /\b(?:interval|cadence|rate|every\s+\d{1,3})\b/i.test(objective) &&
    /\b(?:visual|screen|frame|frames|capture|source|tab|window)\b/i.test(objective)
  ) {
    const requestedCadenceMs = Math.max(5_000, cadenceControlIntent.requested_rate_ms ?? readLiveSourceRequestedRateMs(objective) ?? 15_000);
    const runtimeContext = resolveLiveRuntimeContext({ threadId });
    const bodySourceIds = Array.isArray(body.source_ids)
      ? body.source_ids.map((entry) => String(entry ?? "").trim()).filter(Boolean)
      : [];
    const latestVisualSource = listVisualSnapshotSources({ threadId }).at(-1) ?? null;
    const sourceId =
      (typeof body.source_id === "string" && body.source_id.trim() ? body.source_id.trim() : null) ??
      bodySourceIds.find((entry) => /\bvisual|frame|screen|capture/i.test(entry)) ??
      runtimeContext.active_visual_source_id ??
      latestVisualSource?.source_id ??
      `source:visual_frame:${threadId}`;
    const activeEnvironment =
      getActiveLiveAnswerEnvironmentForThread(threadId) ??
      getActiveLiveAnswerEnvironmentForThread("helix-ask:desktop");
    const cadenceResult = setVisualProducerCadence({
      threadId,
      sourceId,
      environmentId:
        typeof body.environment_id === "string"
          ? body.environment_id
          : (activeEnvironment?.environment_id ?? null),
      pipelineId: runtimeContext.active_pipeline_id,
      cadenceMs: requestedCadenceMs,
      captureMode: "interval",
      clientStreamConfirmed: runtimeContext.visual_status === "active" || runtimeContext.visual_status === "stale",
      status:
        runtimeContext.visual_status === "permission_required" || runtimeContext.visual_status === "configured_missing"
          ? "permission_required"
          : "waiting_for_client",
    });
    return res.status(200).json({
      ok: true,
      schema: "helix.live_answer_environment_control_redirect_response.v1",
      redirected_from: "live_answer_environment_create",
      action: "situation-room.live-source.set_rate",
      action_id: "situation-room.live-source.set_rate",
      thread_id: threadId,
      source_id: sourceId,
      cadence_ms: requestedCadenceMs,
      visual_producer_cadence_receipt: cadenceResult.receipt,
      workspace_action_receipt: {
        schema: "helix.workspace_action_receipt.v1",
        ok: true,
        action_id: "situation-room.live-source.set_rate",
        panel_id: "situation-room-pipelines",
        target_action_id: "live-source.set_rate",
        receipt: cadenceResult.receipt,
        state_observed: true,
        assistant_answer: false,
        raw_content_included: false,
        context_policy: "compact_context_pack_only",
      },
      state_observed: true,
      visual_producer_id: cadenceResult.receipt.cadence.producer_id,
      producer_binding_status: cadenceResult.binding.status,
      live_runtime_context: runtimeContext,
      live_answer_environment: activeEnvironment,
      buffer_status: getLiveSourceBufferStatus({ threadId }),
      assistant_answer: false,
      raw_content_included: false,
      context_policy: "compact_context_pack_only",
    });
  }
  const createdTurnId = typeof body.created_turn_id === "string" && body.created_turn_id.trim()
    ? body.created_turn_id.trim()
    : `setup:live_answer:${crypto.createHash("sha256").update(`${threadId}:${objective}`).digest("hex").slice(0, 16)}`;
  const preset = typeof body.preset === "string" ? body.preset : null;
  const defaultSourceIds =
    preset === "calculator_prime_stream"
      ? ["source:calculator-prime-stream"]
      : preset === "calculator_equation_interpreter"
        ? ["source:calculator-equation-live"]
      : preset === "physics_stability_tracker"
        ? ["source:physics-simulation"]
        : [];
  const sourceIds = Array.isArray(body.source_ids)
    ? body.source_ids.map((entry) => String(entry ?? "").trim()).filter(Boolean)
    : typeof body.source_id === "string" && body.source_id.trim()
      ? [body.source_id.trim()]
      : defaultSourceIds;
  try {
    let { environment, receipt } = createLiveAnswerEnvironment({
      thread_id: threadId,
      created_turn_id: createdTurnId,
      objective,
      room_id: typeof body.room_id === "string" ? body.room_id : null,
      source_ids: sourceIds,
      graph_id: typeof body.graph_id === "string" ? body.graph_id : null,
      preset,
      line_schema: Array.isArray(body.line_schema)
        ? (body.line_schema as any)
        : null,
      mode: typeof body.mode === "string" ? body.mode : null,
    });
    let schemaSelection = selectLiveSchemaForEnvironment({
      environment,
      descriptors: listLiveSourceDescriptors({ threadId: environment.thread_id, limit: 80 })
        .filter((descriptor) => environment.source_ids.length === 0 || environment.source_ids.includes(descriptor.source_id)),
      explicitPreset: preset && preset !== "custom" ? preset : null,
    });
    if (!Array.isArray(body.line_schema) && schemaSelection.preset_authority !== "explicit_user_selected") {
      const schemaDefinitions = liveSchemaSelectionToLineDefinitions(schemaSelection);
      const selectedKeys = schemaDefinitions.map((line) => line.key).join(",");
      const currentKeys = environment.line_schema.map((line) => line.key).join(",");
      if (selectedKeys && selectedKeys !== currentKeys) {
        const updated = setLiveAnswerEnvironmentLineSchema({
          environment_id: environment.environment_id,
          line_schema: schemaDefinitions,
        });
        if (updated?.environment) {
          environment = updated.environment;
          schemaSelection = selectLiveSchemaForEnvironment({
            environment,
            descriptors: listLiveSourceDescriptors({ threadId: environment.thread_id, limit: 80 })
              .filter((descriptor) => environment.source_ids.length === 0 || environment.source_ids.includes(descriptor.source_id)),
            explicitPreset: null,
          });
        }
      }
    }
    let lineSchemaDerivation: ReturnType<typeof deriveLiveLineSchema> | null = null;
    const shouldSeedFromLatestVisual =
      /\b(?:active\s+visual|visual\s+source|visual\s+capture|screen\s*share|screen|window|tab|first\s+frame|derive\s+the\s+live\s+card)\b/i.test(objective);
    if (shouldSeedFromLatestVisual) {
      const latestVisualEvidence = listVisualFrameEvidence({ threadId: environment.thread_id, limit: 1 }).at(-1) ?? null;
      const capabilities = buildSituationSourceCapabilities({
        threadId: environment.thread_id,
        roomId: environment.room_id ?? null,
      });
      lineSchemaDerivation = deriveLiveLineSchema({
        environment,
        visualEvidence: latestVisualEvidence,
        activeModalities: capabilities.filter((entry) => entry.status === "active").map((entry) => entry.modality),
      });
      const derived = setLiveAnswerEnvironmentLineSchema({
        environment_id: environment.environment_id,
        line_schema: lineSchemaDerivation.line_schema,
      });
      if (derived?.environment) {
        environment = derived.environment;
      }
    }
    for (const sourceId of sourceIds) {
      if (
        sourceId.startsWith("source:calculator") || preset === "calculator_prime_stream" || preset === "calculator_equation_interpreter"
      ) {
        upsertWorkstationLiveSource({
          source_id: sourceId,
          kind: "calculator_series",
          panel_id: "scientific-calculator",
          thread_id: environment.thread_id,
          environment_id: environment.environment_id,
          tick_rate_ms:
            body.source_config && typeof body.source_config === "object" && typeof (body.source_config as Record<string, unknown>).tick_rate_ms === "number"
              ? (body.source_config as Record<string, number>).tick_rate_ms
              : 1000,
          config:
            body.source_config && typeof body.source_config === "object"
              ? (body.source_config as Record<string, unknown>)
              : {},
        });
      }
      if (
        sourceId.startsWith("source:physics") || preset === "physics_stability_tracker"
      ) {
        upsertWorkstationLiveSource({
          source_id: sourceId,
          kind: "physics_simulation",
          panel_id: "situation-room-pipelines",
          thread_id: environment.thread_id,
          environment_id: environment.environment_id,
          config:
            body.source_config && typeof body.source_config === "object"
              ? (body.source_config as Record<string, unknown>)
              : {},
        });
      }
    }
    if (environment.room_id && environment.source_ids.length > 0) {
      createSituationThreadBinding({
        room_id: environment.room_id,
        source_id: environment.source_ids[0] ?? null,
        graph_id: environment.graph_id ?? null,
        world_id:
          typeof body.world_id === "string"
            ? body.world_id
            : environment.room_id?.includes("minecraft")
              ? "minecraft:minehut"
              : null,
        thread_id: environment.thread_id,
        turn_id: environment.created_turn_id,
        mode: "standby_receipts",
        append_policy: "salient_only",
      });
    }
    appendHelixThreadEvent({
      route: "/ask",
      thread_id: environment.thread_id,
      turn_id: environment.created_turn_id,
      session_id: environment.thread_id,
      event_type: "item_completed",
      item_id: `live_answer_environment:${environment.environment_id}`,
      item_type: "toolObservation",
      item_stream: "observation",
      item_status: "completed",
      observation_ref: {
        ...receipt,
        environment,
        provenance: "workstation_tool",
        model_invoked: false,
        context_role: "observation_not_assistant_answer",
      },
      meta: {
        kind: "live_answer_environment_receipt",
        primary_user_visible: false,
        model_invoked: false,
      },
    });
    const workerLanes = ensureDefaultLiveWorkerLanes(environment);
    return res.status(200).json({
      ok: true,
      schema: "helix.live_answer_environment_start_response.v1",
      receipt,
      live_answer_environment: environment,
      line_schema_derivation: lineSchemaDerivation,
      schema_selection: schemaSelection,
      schema_compatibility: inspectLiveSchemaCompatibility({
        environment,
        selection: schemaSelection,
        descriptors: listLiveSourceDescriptors({ threadId: environment.thread_id, limit: 80 })
          .filter((descriptor) => environment.source_ids.length === 0 || environment.source_ids.includes(descriptor.source_id)),
      }),
      live_worker_lanes: workerLanes,
      worker_lane_count: workerLanes.length,
    });
  } catch (error) {
    return res.status(400).json({
      ok: false,
      schema: "helix.live_answer_environment_start_response.v1",
      error: error instanceof Error ? error.message : "live_answer_environment_start_failed",
      receipt: {
        schema: "helix.live_answer_environment_receipt.v1",
        ok: false,
        thread_id: threadId,
        objective,
        source_ids: sourceIds,
        line_keys: [],
        attachment_policy: "manual_only",
        context_injection: "explicit_attachment_only",
        command_lane_enabled: false,
        error: error instanceof Error ? error.message : "live_answer_environment_start_failed",
      },
    });
  }
};

planRouter.post("/situation/live-answer-environment/start", handleLiveAnswerEnvironmentCreate);

planRouter.post("/situation/live-answer-environment/create", handleLiveAnswerEnvironmentCreate);

const handleLiveAnswerEnvironmentStatus = (
  status: "active" | "paused" | "completed",
) => (req: Request, res: Response) => {
  const environmentId = typeof req.params.environmentId === "string" ? decodeURIComponent(req.params.environmentId).trim() : "";
  if (!environmentId) {
    return res.status(400).json({
      ok: false,
      error: "missing_environment_id",
      message: "live answer environment lifecycle update requires environmentId.",
    });
  }
  const result = setLiveAnswerEnvironmentStatus({
    environment_id: environmentId,
    status,
  });
  if (!result) {
    return res.status(404).json({
      ok: false,
      error: "environment_not_found",
      message: `No live answer environment found for ${environmentId}.`,
    });
  }
  appendHelixThreadEvent({
    route: "/ask",
    thread_id: result.environment.thread_id,
    turn_id: result.environment.created_turn_id,
    session_id: result.environment.thread_id,
    event_type: "item_completed",
    item_id: `live_answer_environment:${result.environment.environment_id}:status:${status}`,
    item_type: "validation",
    item_stream: "observation",
    item_status: "completed",
    observation_ref: {
      schema: "helix.live_answer_environment_lifecycle_receipt.v1",
      ok: true,
      environment_id: result.environment.environment_id,
      status,
      model_invoked: false,
      deterministic: true,
      context_role: "observation_not_assistant_answer",
      delta: result.delta,
    },
    meta: {
      kind: "live_answer_environment_lifecycle",
      primary_user_visible: false,
      model_invoked: false,
    },
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.live_answer_environment_lifecycle_receipt.v1",
    environment: result.environment,
    delta: result.delta,
  });
};

