planRouter.post("/situation/live-workstation-pipeline/create", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = typeof body.thread_id === "string" && body.thread_id.trim() ? body.thread_id.trim() : "helix-ask:desktop";
  const objective = typeof body.objective === "string" && body.objective.trim()
    ? body.objective.trim()
    : typeof body.prompt === "string" && body.prompt.trim()
      ? body.prompt.trim()
      : "Create a live workstation pipeline.";
  const createdTurnId = typeof body.created_turn_id === "string" && body.created_turn_id.trim()
    ? body.created_turn_id.trim()
    : `setup:live_pipeline:${crypto.createHash("sha256").update(`${threadId}:${objective}`).digest("hex").slice(0, 16)}`;
  const sourceIds = Array.isArray(body.source_ids)
    ? body.source_ids.map((entry) => String(entry ?? "").trim()).filter(Boolean)
    : typeof body.source_id === "string" && body.source_id.trim()
      ? [body.source_id.trim()]
      : [];
  const inferredArgs = buildLiveWorkstationPipelineArgs({
    transcript: objective,
    threadId,
    sourceIds,
    environmentId: typeof body.environment_id === "string" ? body.environment_id : null,
    mode: typeof body.mode === "string" ? body.mode : null,
  });
  const effectiveSourceIds = Array.isArray(inferredArgs.source_ids)
    ? Array.from(new Set((inferredArgs.source_ids as unknown[]).map((entry) => String(entry ?? "").trim()).filter(Boolean)))
    : sourceIds;
  const requestedEnvironmentId = typeof body.environment_id === "string" && body.environment_id.trim()
    ? body.environment_id.trim()
    : null;
  const plan = planLiveWorkstationPipeline({
    prompt: objective,
    threadId,
    sourceIds: effectiveSourceIds,
    environmentId: requestedEnvironmentId,
  });
  const environmentId = requestedEnvironmentId ?? (() => {
    const { environment } = createLiveAnswerEnvironment({
      thread_id: threadId,
      created_turn_id: createdTurnId,
      objective,
      source_ids: effectiveSourceIds,
      preset: "custom",
      line_schema: plan.line_schema,
      mode: typeof body.mode === "string" ? body.mode : "text_only",
    });
    return environment.environment_id;
  })();
  const planWithEnvironment = {
    ...plan,
    sinks: plan.sinks.map((sink) =>
      sink.kind === "live_answer_environment" ? { ...sink, target_id: sink.target_id ?? environmentId } : sink,
    ),
  };
  const { pipeline, receipt } = createLiveWorkstationPipeline({
    thread_id: threadId,
    created_turn_id: createdTurnId,
    objective,
    source_ids: effectiveSourceIds,
    environment_id: environmentId,
    plan: planWithEnvironment,
  });
  const workerEnvironment = getLiveAnswerEnvironment(environmentId);
  const workerLanes = workerEnvironment ? ensureDefaultLiveWorkerLanes(workerEnvironment) : [];
  appendHelixThreadEvent({
    route: "/ask",
    thread_id: pipeline.thread_id,
    turn_id: pipeline.created_turn_id,
    session_id: pipeline.thread_id,
    event_type: "item_completed",
    item_id: `live_workstation_pipeline:${pipeline.pipeline_id}`,
    item_type: "toolObservation",
    item_stream: "observation",
    item_status: "completed",
    observation_ref: {
      ...receipt,
      plan: planWithEnvironment,
      pipeline,
      model_invoked: false,
      context_role: "observation_not_assistant_answer",
    },
    meta: {
      kind: "live_workstation_pipeline_receipt",
      primary_user_visible: false,
      model_invoked: false,
    },
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.live_workstation_pipeline_create_response.v1",
    plan: planWithEnvironment,
    receipt,
    pipeline,
    live_worker_lanes: workerLanes,
    worker_lane_count: workerLanes.length,
    missing_bindings: plan.missing_bindings,
    raw_logs_included: false,
    raw_transcript_included: false,
  });
});

