const handleWorkstationLiveSourceEvent = (req: Request, res: Response) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const sourceId = typeof body.source_id === "string" && body.source_id.trim()
    ? body.source_id.trim()
    : "source:manual-feed";
  const kind = typeof body.kind === "string" ? body.kind : typeof body.source_family === "string" ? body.source_family : "manual_feed";
  const seq =
    typeof body.seq === "number"
      ? body.seq
      : typeof body.tick_index === "number"
        ? body.tick_index
        : undefined;
  const payload =
    kind === "physics_simulation" && (!body.payload || Object.keys(body.payload as Record<string, unknown>).length === 0)
      ? (buildPhysicsStabilityTick({
          config:
            body.source_config && typeof body.source_config === "object"
              ? (body.source_config as any)
              : null,
          sample_index: seq ?? 1,
        }) as unknown as Record<string, unknown>)
      : body.payload && typeof body.payload === "object"
        ? (body.payload as Record<string, unknown>)
        : {};
  const result = ingestWorkstationLiveSourceEvent({
    source_id: sourceId,
    kind,
    event_type: typeof body.event_type === "string" ? body.event_type : "source_tick",
    payload,
    environment_id: typeof body.environment_id === "string" ? body.environment_id : null,
    seq,
    ts: typeof body.ts === "string" ? body.ts : undefined,
    panel_id: typeof body.panel_id === "string" ? body.panel_id : null,
    thread_id: typeof body.thread_id === "string" ? body.thread_id : null,
    trace:
      body.trace && typeof body.trace === "object"
        ? (body.trace as Record<string, unknown>)
        : null,
    evidence_refs: Array.isArray(body.evidence_refs) ? body.evidence_refs.map(String) : undefined,
  });
  const modality = normalizeLiveSourceModality(kind === "minecraft_world_events"
    ? "world_event"
    : kind === "calculator_series"
      ? "calculator_stream"
      : kind === "physics_simulation"
        ? "simulation_stream"
        : kind === "screen_summary"
          ? "visual_frame"
          : kind === "browser_audio_transcript"
            ? "audio_transcript"
            : "text_chat");
  const chunkResult = appendLiveSourceChunk({
    source_id: sourceId,
    thread_id: result.event.thread_id ?? (typeof body.thread_id === "string" ? body.thread_id : "helix-ask:desktop"),
    environment_id: typeof body.environment_id === "string" ? body.environment_id : null,
    modality,
    ts: result.event.ts,
    compact_summary: `${result.event.event_type} from ${kind}`,
    payload_ref: result.event.event_id,
    evidence_refs: result.event.evidence_refs,
    capture_mode: kind === "minecraft_world_events" ? "push" : "on_change",
  });
  const analysisJob = queueLiveSourceAnalysisJob({
    chunk: chunkResult.chunk,
  });
  return res.status(200).json({
    schema: "helix.workstation_live_source_ingest_response.v1",
    ...result,
    live_source_chunk: chunkResult.chunk,
    live_source_analysis_job: analysisJob,
    live_source_buffer_status: chunkResult.buffer_status,
  });
};

