planRouter.post("/situation/test-harness/live-visual-source", (req, res) => {
  if (process.env.NODE_ENV === "production" && process.env.ENABLE_HELIX_TEST_HARNESS !== "1") {
    return res.status(404).json({
      ok: false,
      schema: "helix.backend_live_visual_source_seed_receipt.v1",
      error_code: "test_harness_disabled",
      assistant_answer: false,
      raw_content_included: false,
    });
  }
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const scenario = typeof body.scenario === "string" ? body.scenario.trim() : "";
  const receipt = scenario === "active_run_with_unbound_visual_source"
    ? seedBackendLiveVisualSourceSwitchForAskTest(body)
    : scenario === "live_source_identity_wrong_environment"
      ? seedBackendLiveVisualWrongEnvironmentForAskTest(body)
      : /^live_source_identity_(?:missing_environment_source|no_situation_run|no_field_evaluations|stale_interpretation)$/.test(scenario)
        ? seedBackendLiveVisualIdentityGapForAskTest(body)
      : seedBackendLiveVisualSourceForAskTest(body);
  return res.status(200).json(receipt);
});

