const readRouteString = (value: unknown): string | null =>
  typeof value === "string" && value.trim() ? value.trim() : null;

const readVisualCaptureOrigin = (input: Record<string, unknown>): "browser_getDisplayMedia" | "browser_getUserMedia" =>
  input.source_origin === "browser_getUserMedia"
    ? "browser_getUserMedia"
    : "browser_getDisplayMedia";

const readVisualCaptureSurface = (input: Record<string, unknown>): string =>
  readRouteString(input.surface) ??
  readRouteString(input.capture_surface) ??
  (readVisualCaptureOrigin(input) === "browser_getUserMedia" ? "camera" : "screen");

const readRouteNumber = (value: unknown): number | null =>
  typeof value === "number" && Number.isFinite(value) ? value : null;

