planRouter.get("/situation/live-schema/inspect", (req, res) => {
  const environmentId = readRouteString(req.query.environment_id);
  const threadId = readRouteString(req.query.thread_id) ?? "helix-ask:desktop";
  const environment = environmentId
    ? getLiveAnswerEnvironment(environmentId)
    : getActiveLiveAnswerEnvironmentForThread(threadId);
  if (!environment) {
    return res.status(404).json({
      ok: false,
      error: "environment_not_found",
      assistant_answer: false,
      raw_content_included: false,
    });
  }
  const descriptors = listLiveSourceDescriptors({
    threadId: environment.thread_id,
    environmentId: environment.environment_id,
    limit: 80,
  });
  const fallbackDescriptors = descriptors.length > 0
    ? descriptors
    : listLiveSourceDescriptors({ threadId: environment.thread_id, limit: 80 }).filter((descriptor) => environment.source_ids.includes(descriptor.source_id));
  const selection = selectLiveSchemaForEnvironment({
    environment,
    descriptors: fallbackDescriptors,
    objectiveText: readRouteString(req.query.objective) ?? environment.objective,
  });
  const compatibility = inspectLiveSchemaCompatibility({
    environment,
    selection,
    descriptors: fallbackDescriptors,
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.live_schema_inspect_response.v1",
    environment_id: environment.environment_id,
    source_descriptors: fallbackDescriptors,
    schema_selection: selection,
    schema_compatibility: compatibility,
    assistant_answer: false,
    raw_content_included: false,
  });
});

planRouter.post("/situation/live-schema/reselect", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const environmentId = readRouteString(body.environment_id);
  const threadId = readRouteString(body.thread_id) ?? "helix-ask:desktop";
  const environment = environmentId
    ? getLiveAnswerEnvironment(environmentId)
    : getActiveLiveAnswerEnvironmentForThread(threadId);
  if (!environment) {
    return res.status(404).json({
      ok: false,
      error: "environment_not_found",
      assistant_answer: false,
      raw_content_included: false,
    });
  }
  const descriptors = listLiveSourceDescriptors({ threadId: environment.thread_id, limit: 80 })
    .filter((descriptor) => descriptor.environment_id === environment.environment_id || environment.source_ids.includes(descriptor.source_id));
  const selection = selectLiveSchemaForEnvironment({
    environment,
    descriptors,
    objectiveText: readRouteString(body.objective_text) ?? environment.objective,
    explicitPreset: readRouteString(body.explicit_preset),
  });
  const lineSchema = liveSchemaSelectionToLineDefinitions(selection);
  const updated = setLiveAnswerEnvironmentLineSchema({
    environment_id: environment.environment_id,
    line_schema: lineSchema,
  });
  const nextEnvironment = updated?.environment ?? environment;
  const compatibility = inspectLiveSchemaCompatibility({
    environment: nextEnvironment,
    selection,
    descriptors,
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.live_schema_reselect_response.v1",
    action_id: "situation-room.live-schema.reselect",
    schema_selection: selection,
    schema_compatibility: compatibility,
    live_answer_environment: nextEnvironment,
    delta: updated?.delta ?? null,
    assistant_answer: false,
    raw_content_included: false,
  });
});

planRouter.post("/situation/live-schema/repair", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const environmentId = readRouteString(body.environment_id);
  const threadId = readRouteString(body.thread_id) ?? "helix-ask:desktop";
  const environment = environmentId
    ? getLiveAnswerEnvironment(environmentId)
    : getActiveLiveAnswerEnvironmentForThread(threadId);
  if (!environment) {
    return res.status(404).json({
      ok: false,
      error: "environment_not_found",
      assistant_answer: false,
      raw_content_included: false,
    });
  }
  const descriptors = listLiveSourceDescriptors({ threadId: environment.thread_id, limit: 80 })
    .filter((descriptor) => descriptor.environment_id === environment.environment_id || environment.source_ids.includes(descriptor.source_id));
  const selection = selectLiveSchemaForEnvironment({
    environment,
    descriptors,
    objectiveText: readRouteString(body.objective_text) ?? environment.objective,
    explicitPreset: readRouteString(body.explicit_preset),
  });
  const compatibility = inspectLiveSchemaCompatibility({ environment, selection, descriptors });
  const updated = compatibility.ok || !compatibility.recommended_schema
    ? null
    : setLiveAnswerEnvironmentLineSchema({
        environment_id: environment.environment_id,
        line_schema: compatibility.recommended_schema,
      });
  return res.status(200).json({
    ok: true,
    schema: "helix.live_schema_repair_response.v1",
    action_id: "situation-room.live-schema.repair",
    repaired: Boolean(updated),
    schema_selection: selection,
    schema_compatibility: compatibility,
    live_answer_environment: updated?.environment ?? environment,
    delta: updated?.delta ?? null,
    assistant_answer: false,
    raw_content_included: false,
  });
});

const requestVisualProducerClientAdoption = (input: {
  threadId: string;
  sourceId: string;
  producerId?: string | null;
  environmentId?: string | null;
  pipelineId?: string | null;
  cadenceMs?: number | null;
  captureMode?: string | null;
  clientStreamConfirmed?: boolean;
}) => requestClientCapabilityAction({
  thread_id: input.threadId,
  environment_id: input.environmentId ?? null,
  pipeline_id: input.pipelineId ?? null,
  target_client: "current_browser",
  capability: "visual_capture",
  action: input.clientStreamConfirmed ? "adopt_producer" : "request_permission",
  requires_user_gesture: input.clientStreamConfirmed !== true,
  args: {
    producer_id: input.producerId ?? null,
    source_id: input.sourceId,
    cadence_ms: input.cadenceMs ?? null,
    capture_mode: input.captureMode ?? "interval",
    modality: "visual_frame",
  },
  status: "requested",
});

