planRouter.post("/client-action/:actionRequestId/adopt", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const actionRequestId = req.params.actionRequestId;
  const action = getClientCapabilityAction(actionRequestId);
  if (!action) {
    return res.status(404).json({
      ok: false,
      error: "client_action_request_not_found",
      assistant_answer: false,
      raw_content_included: false,
    });
  }
  const adoption = recordClientCapabilityAdoption({
    ...body,
    action_request_id: actionRequestId,
    thread_id: readRouteString(body.thread_id) ?? action.thread_id,
  });
  const observed =
    body.observed_state && typeof body.observed_state === "object"
      ? (body.observed_state as Record<string, unknown>)
      : {};
  const sourceId = readRouteString(body.source_id) ?? readRouteString(observed.source_id);
  if (action.capability === "visual_capture" && sourceId) {
    const priorDescriptor = getLatestLiveSourceDescriptorForSource(sourceId);
    const captureObservation: Record<string, unknown> = {
      ...observed,
      source_origin:
        readRouteString(observed.source_origin) ??
        priorDescriptor?.serving_context.source_origin,
      surface:
        readRouteString(observed.surface) ??
        readRouteString(observed.capture_surface) ??
        priorDescriptor?.serving_context.surface,
    };
    upsertLiveSourceDescriptor({
      source_id: sourceId,
      thread_id: adoption.thread_id,
      environment_id: action.environment_id ?? null,
      pipeline_id: action.pipeline_id ?? null,
      modality: "visual_frame",
      source_origin: readVisualCaptureOrigin(captureObservation),
      surface: readVisualCaptureSurface(captureObservation),
      app_hint: observed.app_hint,
      window_title_hint: observed.window_title_hint,
      current_state: adoption.ok && observed.interval_active === true ? "active_interval" : adoption.ok ? "active" : "stale",
      cadence_ms: typeof observed.cadence_ms === "number" ? observed.cadence_ms : action.args && typeof action.args === "object" ? (action.args as Record<string, unknown>).cadence_ms : null,
      capabilities: ["capture_frame", "interval_capture", "client_adoption"],
    });
  }
  return res.status(200).json({
    ok: true,
    schema: "helix.client_capability_adoption_response.v1",
    adoption,
    action: getClientCapabilityAction(actionRequestId),
    assistant_answer: false,
    raw_content_included: false,
  });
});

