planRouter.post("/situation/interpreted-log/steer", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = typeof body.thread_id === "string" && body.thread_id.trim() ? body.thread_id.trim() : "";
  const prompt = typeof body.prompt === "string" && body.prompt.trim() ? body.prompt.trim() : "";
  const roomId = typeof body.room_id === "string" && body.room_id.trim() ? body.room_id.trim() : null;
  if (!threadId || !prompt) {
    return res.status(400).json({
      ok: false,
      error: "missing_thread_id_or_prompt",
      message: "user steering requires thread_id and prompt.",
    });
  }
  const activeArtifact = getActiveLiveSituationArtifactForThread(threadId);
  const targetIds = [
    ...(Array.isArray(body.target_ids) ? body.target_ids.map(String) : []),
    ...(activeArtifact && (!roomId || activeArtifact.room_id === roomId) ? [activeArtifact.artifact_id] : []),
  ];
  const steering = buildUserSteeringEvent({
    threadId,
    roomId: roomId ?? activeArtifact?.room_id ?? null,
    prompt,
    targetIds,
    evidenceRefs: activeArtifact?.evidence_refs ?? [],
  });
  const interpretedEvent = recordInterpretedEventForUserSteering(steering);
  const steeringEvidence = recordUserSteeringEvidence({
    threadId,
    source: "helix_ask_text",
    userClaim: prompt,
    targetHypothesisIds: targetIds,
    evidenceRefs: [interpretedEvent.event_id, ...steering.evidence_refs],
  });
  const appliedSteering = applyUserSteeringEvidence({
    steering: steeringEvidence,
    roomId: roomId ?? activeArtifact?.room_id ?? null,
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.user_steering_response.v1",
    steering,
    steering_evidence: steeringEvidence,
    interpreted_event: interpretedEvent,
    applied_steering: appliedSteering,
    live_artifact_delta: appliedSteering.live_artifact_delta?.delta ?? null,
    live_environment_delta: appliedSteering.live_environment_delta?.delta ?? null,
    present_state_card: projectPresentStateCard({
      threadId,
      roomId: roomId ?? activeArtifact?.room_id ?? null,
    }),
    raw_logs_included: false,
    deterministic_content_role: "evidence_not_assistant_answer",
  });
});

