planRouter.post("/situation/clarification-dialogue/answer", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = typeof body.thread_id === "string" && body.thread_id.trim() ? body.thread_id.trim() : "";
  const roomId = typeof body.room_id === "string" && body.room_id.trim() ? body.room_id.trim() : null;
  const questionId = typeof body.question_id === "string" && body.question_id.trim() ? body.question_id.trim() : null;
  const storedQuestion = questionId ? getClarificationQuestion(questionId) : null;
  const userClaim = typeof body.user_claim === "string" && body.user_claim.trim()
    ? body.user_claim.trim()
    : typeof body.answer === "string" && body.answer.trim()
      ? body.answer.trim()
      : "";
  if (!threadId || !userClaim) return res.status(400).json({ ok: false, error: "missing_thread_id_or_user_claim" });
  const targetHypothesisIds = Array.isArray(body.target_hypothesis_ids)
    ? body.target_hypothesis_ids.map(String)
    : typeof body.target_hypothesis_id === "string"
      ? [body.target_hypothesis_id]
      : storedQuestion?.ranking?.hypothesis_id
        ? [storedQuestion.ranking.hypothesis_id]
      : [];
  const clarificationNeedId =
    typeof body.need_id === "string" && body.need_id.trim()
      ? body.need_id.trim()
      : (storedQuestion?.need_id ?? null);
  const profileId = typeof body.profile_id === "string" && body.profile_id.trim() ? body.profile_id.trim() : null;
  const steeringEvidence = recordUserSteeringEvidence({
    threadId,
    source: body.source === "discord_voice" || body.source === "discord_text" || body.source === "manual_ui"
      ? body.source
      : "helix_ask_text",
    userClaim,
    targetHypothesisIds,
    evidenceRefs: [
      ...(clarificationNeedId ? [clarificationNeedId] : []),
      ...(questionId ? [questionId] : []),
      ...(storedQuestion?.ranking?.evidence_refs ?? []),
    ],
    effect:
      body.effect === "confirm" ||
      body.effect === "reject" ||
      body.effect === "rename" ||
      body.effect === "refine_goal" ||
      body.effect === "add_missing_evidence_target" ||
      body.effect === "set_priority" ||
      body.effect === "unknown"
        ? body.effect
        : undefined,
  });
  const applied = applyUserSteeringEvidence({
    steering: steeringEvidence,
    roomId,
    clarificationNeedId,
    profileId,
  });
  const answeredQuestion = questionId
    ? markClarificationQuestionAnswered({ questionId, answer: userClaim })
    : null;
  appendInterpretedEvent({
    event_id: makeInterpretedEventId({
      threadId,
      kind: "steering_applied",
      sourceId: steeringEvidence.steering_id,
    }),
    thread_id: threadId,
    room_id: roomId,
    kind: "steering_applied",
    title: "steering applied",
    summary: `User steering applied as ${steeringEvidence.effect}: ${userClaim}`,
    confidence: steeringEvidence.confidence_delta ?? null,
    evidence_refs: [steeringEvidence.steering_id, applied.synthetic_evidence.evidence_id],
    source_event_ids: [steeringEvidence.steering_id],
    related_artifact_ids: targetHypothesisIds,
    model_invoked: false,
    deterministic: true,
    created_at: steeringEvidence.created_at,
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.user_steering_evidence_response.v1",
    steering_evidence: steeringEvidence,
    answered_question: answeredQuestion,
    applied,
    live_artifact_delta: applied.live_artifact_delta?.delta ?? null,
    live_environment_delta: applied.live_environment_delta?.delta ?? null,
    steering_memory: applied.steering_memory,
    pattern_confirmation: applied.pattern_confirmation,
    present_state_card: projectPresentStateCard({ threadId, roomId }),
    raw_content_included: false,
    assistant_answer: false,
  });
});

