planRouter.post("/situation/categorization-jobs/start", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = typeof body.thread_id === "string" && body.thread_id.trim() ? body.thread_id.trim() : "";
  const sourceFamily = typeof body.source_family === "string" && body.source_family.trim() ? body.source_family.trim() : "";
  if (!threadId || !sourceFamily) return res.status(400).json({ ok: false, error: "missing_thread_id_or_source_family" });
  if (![
    "minecraft_events",
    "discord_voice",
    "calculator_stream",
    "physics_simulation",
    "browser_transcript",
    "research_session",
    "custom",
  ].includes(sourceFamily)) {
    return res.status(400).json({ ok: false, error: "invalid_source_family" });
  }
  const result = startContinuousCategorizationJob({
    threadId,
    profileId: typeof body.profile_id === "string" ? body.profile_id : null,
    roomId: typeof body.room_id === "string" ? body.room_id : null,
    sourceFamily: sourceFamily as ContinuousCategorizationSourceFamily,
    sourceIds: Array.isArray(body.source_ids) ? body.source_ids.map(String) : typeof body.source_id === "string" ? [body.source_id] : [],
    worldId: typeof body.world_id === "string" ? body.world_id : null,
    objective: typeof body.objective === "string" && body.objective.trim() ? body.objective.trim() : "Continuous categorization job.",
    policy: {
      archive_on_stop: body.archive_on_stop !== false,
      surface_policy: body.surface_policy === "silent" || body.surface_policy === "debug_trace" ? body.surface_policy : "danger_progress",
    },
  });
  return res.status(200).json({ ok: true, schema: "helix.continuous_categorization_job_start_response.v1", ...result });
});

for (const [routeName, status, action] of [
  ["pause", "paused", "pause"],
  ["resume", "active", "resume"],
  ["stop", "stopped", "stop"],
] as const) {
  planRouter.post(`/situation/categorization-jobs/:jobId/${routeName}`, (req, res) => {
    const result = setContinuousCategorizationJobStatus({
      jobId: decodeURIComponent(req.params.jobId ?? ""),
      status,
      action,
    });
    return res.status(result.job ? 200 : 404).json({
      ok: Boolean(result.job),
      schema: "helix.continuous_categorization_job_lifecycle_response.v1",
      job: result.job,
      receipt: result.receipt,
      error: result.job ? null : "job_not_found",
    });
  });
}

