planRouter.post("/situation/live-line-tool-requests/plan", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = typeof body.thread_id === "string" && body.thread_id.trim()
    ? body.thread_id.trim()
    : "helix-ask:desktop";
  const environmentId = typeof body.environment_id === "string" && body.environment_id.trim()
    ? body.environment_id.trim()
    : "";
  const environment = environmentId
    ? getLiveAnswerEnvironment(environmentId)
    : getActiveLiveAnswerEnvironmentForThread(threadId);
  if (!environment) {
    return res.status(404).json({
      ok: false,
      schema: "helix.live_line_tool_request_plan_response.v1",
      error: "live_answer_environment_not_found",
      thread_id: threadId,
      request_count: 0,
      raw_logs_included: false,
      assistant_answer: false,
      deterministic_content_role: "evidence_not_assistant_answer",
    });
  }
  const contextPack = buildSituationContextPack({
    threadId: environment.thread_id,
    roomId: environment.room_id,
    liveAnswerEnvironmentId: environment.environment_id,
  });
  const visibleLines = environment.lines.filter((line) => line.visibility === "answer_card");
  const requestLines = (visibleLines.length > 0 ? visibleLines : environment.lines).map((line) => ({
    key: line.key,
    label: line.label,
    value: String(line.value ?? ""),
    evidence_refs: line.evidence_refs ?? [],
  }));
  const requests = planLiveLineToolRequests({
    threadId: environment.thread_id,
    environmentId: environment.environment_id,
    lines: requestLines,
    hypotheses: contextPack.utility_hypotheses ?? [],
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.live_line_tool_request_plan_response.v1",
    thread_id: environment.thread_id,
    environment_id: environment.environment_id,
    room_id: environment.room_id ?? null,
    request_count: requests.length,
    requests,
    raw_logs_included: false,
    assistant_answer: false,
    deterministic_content_role: "evidence_not_assistant_answer",
    poison_guard: {
      live_line_tool_requests_are_answers: false,
      confidence_requires_receipt_or_validation: true,
    },
  });
});

planRouter.post("/situation/live-line-tool-request/run", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = typeof body.thread_id === "string" ? body.thread_id : null;
  const requestId = typeof body.request_id === "string" ? body.request_id : null;
  if (!threadId || !requestId) {
    return res.status(400).json({
      ok: false,
      error: "missing_thread_or_request_id",
      raw_logs_included: false,
      assistant_answer: false,
    });
  }
  try {
    const result = runLiveLineToolChainWithReceipt({
      threadId,
      requestId,
      roomId: typeof body.room_id === "string" ? body.room_id : null,
      sourceId: typeof body.source_id === "string" ? body.source_id : null,
      worldId: typeof body.world_id === "string" ? body.world_id : null,
      limit: typeof body.limit === "number" ? body.limit : 40,
    });
    return res.json({
      ok: true,
      schema: "helix.live_line_tool_request_run_response.v1",
      ...result,
      raw_logs_included: false,
      assistant_answer: false,
      deterministic_content_role: "evidence_not_assistant_answer",
    });
  } catch (error) {
    return res.status(404).json({
      ok: false,
      error: error instanceof Error ? error.message : "line_tool_request_run_failed",
      raw_logs_included: false,
      assistant_answer: false,
    });
  }
});

