const updateVisualSourceRoute =
  (status: "permission_required" | "paused" | "active" | "stopped") =>
  (req: Request, res: Response) => {
    const body =
      req.body && typeof req.body === "object"
        ? (req.body as Record<string, unknown>)
        : {};
    const sourceId = typeof body.source_id === "string" && body.source_id.trim() ? body.source_id.trim() : "";
    if (!sourceId) {
    return res.status(400).json({
      ok: false,
      error: "missing_source_id",
      assistant_answer: false,
      raw_image_included: false,
      context_policy: "compact_context_pack_only",
    });
  }
    const receipt = setVisualSnapshotSourceStatus({ sourceId, status });
    const activationReceipt = buildSourceActivationReceipt({
    sourceId,
    threadId: receipt.source?.thread_id ?? "helix-ask:desktop",
    modality: "visual_frame",
    requestedStatus: status,
    observedStatus: receipt.source?.status ?? "error",
    ok: receipt.ok,
    summary: receipt.ok
      ? `Visual source ${sourceId} is ${receipt.source?.status ?? status}.`
      : "Visual source status update failed.",
    nextRequiredAction: receipt.source?.status === "permission_required" ? "grant_visual_capture_permission" : null,
  });
    return res.status(receipt.ok ? 200 : 404).json({
    ok: receipt.ok,
    schema: "helix.visual_snapshot_source_status_response.v1",
    receipt,
    activation_receipt: activationReceipt,
    source: receipt.source ?? null,
    assistant_answer: false,
    raw_image_included: false,
    context_policy: "compact_context_pack_only",
  });
  };

planRouter.post("/situation/visual-source/pause", updateVisualSourceRoute("paused"));
planRouter.post("/situation/visual-source/resume", updateVisualSourceRoute("active"));
planRouter.post("/situation/visual-source/stop", updateVisualSourceRoute("stopped"));
planRouter.post("/situation/visual-source/permission-required", updateVisualSourceRoute("permission_required"));
planRouter.post("/situation/visual-source/permission-granted", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const sourceId = typeof body.source_id === "string" && body.source_id.trim() ? body.source_id.trim() : "";
  if (!sourceId) {
    return res.status(400).json({
      ok: false,
      error: "missing_source_id",
      assistant_answer: false,
      raw_image_included: false,
      context_policy: "compact_context_pack_only",
    });
  }
  if (body.client_stream_confirmed !== true) {
    const current = listVisualSnapshotSources().find((source) => source.source_id === sourceId);
    const activationReceipt = buildSourceActivationReceipt({
      sourceId,
      threadId: current?.thread_id ?? "helix-ask:desktop",
      modality: "visual_frame",
      requestedStatus: "active",
      observedStatus: current?.status ?? "permission_required",
      ok: false,
      summary: "Visual source cannot become active until the browser client confirms an active capture stream.",
      nextRequiredAction: "grant_visual_capture_permission",
    });
    return res.status(409).json({
      ok: false,
      schema: "helix.visual_snapshot_source_status_response.v1",
      receipt: null,
      activation_receipt: activationReceipt,
      source: current ?? null,
      error: "client_stream_not_confirmed",
      assistant_answer: false,
      raw_image_included: false,
      context_policy: "compact_context_pack_only",
    });
  }
  const receipt = setVisualSnapshotSourceStatus({ sourceId, status: "active" });
  if (receipt.source) {
    recordSituationSourceHeartbeat({
      source_id: sourceId,
      thread_id: receipt.source.thread_id,
      room_id: receipt.source.room_id ?? null,
      modality: "visual_frame",
      status: "active",
    });
    upsertLiveSourceDescriptor({
      source_id: sourceId,
      thread_id: receipt.source.thread_id,
      environment_id: readRouteString(body.environment_id),
      pipeline_id: readRouteString(body.pipeline_id),
      modality: "visual_frame",
      source_origin: readVisualCaptureOrigin(body),
      surface: readVisualCaptureSurface(body),
      app_hint: body.app_hint,
      window_title_hint: body.window_title_hint,
      current_state: "active",
      capabilities: ["capture_frame", "interval_capture", "client_adoption"],
    });
  }
  const activationReceipt = buildSourceActivationReceipt({
    sourceId,
    threadId: receipt.source?.thread_id ?? "helix-ask:desktop",
    modality: "visual_frame",
    requestedStatus: "active",
    observedStatus: receipt.source?.status ?? "error",
    ok: receipt.ok,
    summary: receipt.ok
      ? "Visual capture permission confirmed by the browser client."
      : "Visual capture permission could not be confirmed.",
    nextRequiredAction: receipt.ok ? null : "grant_visual_capture_permission",
  });
  return res.status(receipt.ok ? 200 : 404).json({
    ok: receipt.ok,
    schema: "helix.visual_snapshot_source_status_response.v1",
    receipt,
    activation_receipt: activationReceipt,
    source: receipt.source ?? null,
    assistant_answer: false,
    raw_image_included: false,
    context_policy: "compact_context_pack_only",
  });
});

