planRouter.post("/situation/audio-source/transcript-chunk", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const sourceId = typeof body.source_id === "string" && body.source_id.trim()
    ? body.source_id.trim()
    : `audio_transcript:${typeof body.thread_id === "string" ? body.thread_id : "helix-ask:desktop"}`;
  const threadId = typeof body.thread_id === "string" && body.thread_id.trim() ? body.thread_id.trim() : "helix-ask:desktop";
  const roomId = typeof body.room_id === "string" ? body.room_id : null;
  const environmentId = typeof body.environment_id === "string" && body.environment_id.trim() ? body.environment_id.trim() : null;
  const transcript = typeof body.transcript === "string" ? body.transcript : "";
  const durationMs = typeof body.duration_ms === "number" && Number.isFinite(body.duration_ms)
    ? Math.max(0, Math.round(body.duration_ms))
    : null;
  const capability = recordSituationSourceHeartbeat({
    source_id: sourceId,
    thread_id: threadId,
    room_id: roomId,
    modality: "audio_transcript",
    status: "active",
    ts: typeof body.ts === "string" ? body.ts : null,
  });
  const liveSourceResult = ingestWorkstationLiveSourceEvent({
    source_id: sourceId,
    kind: "browser_audio_transcript",
    event_type: "transcript_chunk",
    thread_id: threadId,
    ts: typeof body.ts === "string" ? body.ts : undefined,
    payload: {
      transcript,
      transcript_is_final: typeof body.transcript_is_final === "boolean" ? body.transcript_is_final : false,
      speaker_id: typeof body.speaker_id === "string" ? body.speaker_id : null,
      direct_address_classification: typeof body.direct_address_classification === "string" ? body.direct_address_classification : "unclassified",
      raw_transcript_included: false,
    },
    evidence_refs: Array.isArray(body.evidence_refs) ? body.evidence_refs.map(String) : [`transcript:${sourceId}`],
  });
  const chunkResult = appendLiveSourceChunk({
    source_id: sourceId,
    thread_id: threadId,
    environment_id: environmentId,
    modality: "audio_transcript",
    ts: typeof body.ts === "string" ? body.ts : null,
    duration_ms: durationMs,
    compact_summary: transcript ? `Transcript chunk: ${transcript.slice(0, 160)}` : "Audio transcript chunk recorded.",
    payload_ref: liveSourceResult.event.event_id,
    evidence_refs: liveSourceResult.event.evidence_refs,
    capture_mode: "push",
  });
  const analysisJob = queueLiveSourceAnalysisJob({
    chunk: chunkResult.chunk,
    analyzerId: "transcript_intent",
  });
  const liveSourceMailItem = enqueueAudioTranscriptMailFromChunk({
    threadId,
    roomId,
    environmentId,
    sourceId,
    transcript,
    eventRef: liveSourceResult.event.event_id,
    chunkRef: chunkResult.chunk.chunk_id,
    analysisJobRef: analysisJob.job_id,
    evidenceRefs: liveSourceResult.event.evidence_refs,
    durationMs,
    now: typeof body.ts === "string" ? body.ts : undefined,
  });
  const rawSessionBufferEntry = recordStagePlayRawSessionBufferEntry({
    threadId,
    roomId,
    sourceId,
    modality: "audio_transcript",
    sourceEventId: liveSourceResult.event.event_id,
    fromTs: typeof body.from_ts === "string" ? body.from_ts : typeof body.ts === "string" ? body.ts : null,
    toTs: typeof body.to_ts === "string" ? body.to_ts : typeof body.ts === "string" ? body.ts : null,
    rawKind: "transcript",
    rawRef: liveSourceResult.event.event_id,
    rawTextPreview: transcript,
    retentionPolicy: "session_ttl",
    evidenceRefs: [liveSourceResult.event.event_id, chunkResult.chunk.chunk_id, ...liveSourceResult.event.evidence_refs],
  });
  const activationReceipt = buildSourceActivationReceipt({
    sourceId,
    threadId,
    modality: "audio_transcript",
    requestedStatus: "active",
    observedStatus: capability.status,
    ok: true,
    summary: "Audio transcript chunk recorded as source evidence.",
    evidenceRefs: liveSourceResult.event.evidence_refs,
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.audio_transcript_chunk_response.v1",
    capability,
    activation_receipt: activationReceipt,
    source_event: {
      item_type: "toolObservation",
      source_family: "audio_transcript",
      event_id: liveSourceResult.event.event_id,
      thread_id: liveSourceResult.event.thread_id,
      assistant_answer: false,
      raw_transcript_included: false,
      context_policy: "compact_context_pack_only",
    },
    live_source_event: liveSourceResult.event,
    live_source_chunk: chunkResult.chunk,
    live_source_analysis_job: analysisJob,
    live_source_mail_item: liveSourceMailItem,
    raw_session_buffer_entry_id: rawSessionBufferEntry?.entryId ?? null,
    live_source_buffer_status: chunkResult.buffer_status,
    assistant_answer: false,
    raw_content_included: false,
    raw_transcript_included: false,
    context_policy: "compact_context_pack_only",
  });
});

