planRouter.post("/situation/visual-frame/analyze", async (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  try {
    const inlineImage = parseInlineVisualImage(body);
    let analysisBody = { ...body };
    const requestedObserverProfileId =
      typeof body.visual_observer_profile_id === "string"
        ? body.visual_observer_profile_id
        : typeof body.visualObserverProfileId === "string"
          ? body.visualObserverProfileId
          : null;
    let inlineChunk: ReturnType<typeof appendLiveSourceChunk>["chunk"] | null = null;
    let inlineAnalysisJob: ReturnType<typeof queueLiveSourceAnalysisJob> | null = null;
    if (inlineImage && typeof analysisBody.frame_id !== "string") {
      const imageBuffer = Buffer.from(inlineImage.imageBase64, "base64");
      const imageHash = crypto.createHash("sha256").update(imageBuffer).digest("hex");
      const frame = recordVisualFrame({
        ...analysisBody,
        image_ref: `ephemeral://helix-ask-upload/${imageHash.slice(0, 16)}`,
        image_sha256: imageHash,
        mime_type: inlineImage.mimeType,
        raw_image_storage_policy: "ephemeral",
      });
      analysisBody = {
        ...analysisBody,
        thread_id: frame.thread_id,
        frame_id: frame.frame_id,
        source_id: frame.source_id,
        mime_type: frame.mime_type,
      };
      const chunkResult = appendLiveSourceChunk({
        source_id: frame.source_id,
        thread_id: frame.thread_id,
        environment_id: typeof body.environment_id === "string" ? body.environment_id : null,
        participant_id: typeof body.participant_id === "string" ? body.participant_id : null,
        modality: "visual_frame",
        ts: frame.ts,
        compact_summary: "Visual frame submitted for inline analysis.",
        payload_ref: frame.frame_id,
        evidence_refs: [frame.frame_id, ...(frame.related_event_refs ?? [])],
        capture_mode:
          typeof body.capture_mode === "string"
            ? (body.capture_mode as any)
            : "manual",
      });
      inlineChunk = chunkResult.chunk;
      inlineAnalysisJob = queueLiveSourceAnalysisJob({
        chunk: chunkResult.chunk,
        analyzerId: "visual_analysis",
      });
      recordPipelineChunkLifecycle({
        chunk: chunkResult.chunk,
        analysisJob: inlineAnalysisJob,
      });
    }
    if (inlineImage && typeof analysisBody.summary !== "string") {
      const genericClientPrompt = "Summarize this permission-bound live frame as compact evidence for the current live environment. Focus on visible scene, activity, objects, UI/game context, and uncertainty.";
      const genericServerPrompt = "Describe this image for Helix Ask. Focus on visible objects, spatial relations, UI/game scene context, and uncertainty. Keep it compact and factual.";
      const incomingPrompt = typeof body.prompt === "string" && body.prompt.trim()
        ? body.prompt.trim()
        : null;
      const sourceIdForProfile = typeof analysisBody.source_id === "string"
        ? analysisBody.source_id
        : typeof body.source_id === "string"
          ? body.source_id
          : null;
      const observerProfile =
        (requestedObserverProfileId ? getStagePlayVisualObserverProfile(requestedObserverProfileId) : null) ??
        getActiveStagePlayVisualObserverProfileForSource({ sourceId: sourceIdForProfile });
      const promptLooksGeneric =
        !incomingPrompt ||
        incomingPrompt === genericClientPrompt ||
        incomingPrompt === genericServerPrompt ||
        incomingPrompt === defaultVisionPrompt(genericServerPrompt);
      const prompt =
        observerProfile && promptLooksGeneric
          ? observerProfile.prompt
          : (incomingPrompt ?? defaultVisionPrompt(genericServerPrompt));
      const provider = getVisionProvider();
      const summary = await provider.describeImage(inlineImage.imageBase64, inlineImage.mimeType, prompt);
      const providerHealth = getVisionProviderHealth();
      analysisBody = {
        ...analysisBody,
        image_model: process.env.VISION_HTTP_MODEL || process.env.LLM_HTTP_MODEL || "gpt-4o-mini",
        visual_observer_profile_id: observerProfile?.profileId ?? null,
        visual_observer_profile_title: observerProfile?.title ?? null,
        visual_prompt_hash: stagePlayVisualObserverPromptHash(prompt),
        visual_output_mode: observerProfile?.outputMode ?? (observerProfile ? "semi_structured_json" : "prose"),
        summary: summary?.trim() ||
          (providerHealth.configured
            ? "Visual frame was recorded, but the configured vision provider did not return an image description."
            : "Visual frame was recorded, but no configured vision provider returned an image description."),
        uncertainty: Array.isArray(analysisBody.uncertainty)
          ? analysisBody.uncertainty
          : summary
            ? []
            : [providerHealth.last_error || "vision_provider_unavailable_or_empty_response"],
      };
    }
    delete (analysisBody as Record<string, unknown>).image_base64;
    delete (analysisBody as Record<string, unknown>).image_data_url;
    const evidence = analyzeVisualFrame(analysisBody);
    const matchingChunk = inlineChunk ?? listLiveSourceChunks({
      sourceId: evidence.source_id,
      threadId: evidence.thread_id,
      modality: "visual_frame",
      limit: 50,
    }).reverse().find((chunk) => chunk.payload_ref === evidence.frame_id || chunk.evidence_refs.includes(evidence.frame_id)) ?? null;
    const rawSessionBufferEntry = inlineImage
      ? recordStagePlayRawSessionBufferEntry({
          threadId: evidence.thread_id,
          roomId: typeof body.room_id === "string" ? body.room_id : null,
          sourceId: evidence.source_id,
          modality: "visual_frame",
          sourceEventId: evidence.frame_id,
          fromTs: evidence.ts,
          toTs: evidence.ts,
          rawKind: "frame_ref",
          rawRef: evidence.frame_id,
          rawTextPreview: evidence.summary,
          retentionPolicy: "session_ttl",
          evidenceRefs: [evidence.evidence_id, evidence.frame_id, matchingChunk?.chunk_id].filter((ref): ref is string => Boolean(ref)),
        })
      : null;
    const completedAnalysisJobs = matchingChunk
      ? completeLiveSourceAnalysisJobsForChunk({
          chunkId: matchingChunk.chunk_id,
          threadId: evidence.thread_id,
          status: "completed",
          outputRefs: [evidence.evidence_id],
          summary: "Visual analysis produced compact visual evidence from live-source chunk.",
        })
      : [];
    const routedVisualOutput = matchingChunk && completedAnalysisJobs.at(-1)
      ? routeLiveSourceAnalysisOutput({
          job: completedAnalysisJobs.at(-1)!,
          chunk: matchingChunk,
          status: "completed",
          summary: evidence.summary,
          outputRefs: [evidence.evidence_id],
          lineValues: {
            scene: { value: evidence.summary, confidence: 0.7 },
            place: { value: evidence.summary, confidence: 0.7 },
            activity: { value: evidence.summary, confidence: 0.62 },
            evidence: { value: "Latest visual frame was analyzed into compact evidence.", confidence: 0.7 },
            next_check: { value: "Capture another frame or align the visual evidence with fresh source events.", confidence: 0.55 },
          },
          modelInvoked: true,
        })
      : null;
    if (completedAnalysisJobs.at(-1)) {
      recordPipelineAnalysisLifecycle({
        job: completedAnalysisJobs.at(-1)!,
        output: routedVisualOutput,
        ok: true,
      });
    }
    appendInterpretedEvent({
      thread_id: evidence.thread_id,
      room_id: typeof body.room_id === "string" ? body.room_id : null,
      source_family: "visual_snapshot",
      kind: "visual_observation",
      title: "Visual frame analyzed",
      summary: evidence.summary,
      evidence_refs: [evidence.evidence_id],
      source_event_ids: [evidence.frame_id],
      model_invoked: evidence.model_invoked,
      deterministic: false,
      created_at: evidence.ts,
    });
    const liveSourceMailItem = enqueueVisualSummaryMailFromEvidence({
      threadId: evidence.thread_id,
      roomId: typeof body.room_id === "string" ? body.room_id : null,
      environmentId: typeof body.environment_id === "string" ? body.environment_id : null,
      sourceId: evidence.source_id,
      visualFrameRef: evidence.frame_id,
      visualEvidenceRef: evidence.evidence_id,
      summary: evidence.summary,
      confidence: evidence.supports_claims[0]?.confidence ?? null,
      analysisState: "analysis_ready",
      objective: typeof body.objective === "string" ? body.objective : null,
      now: evidence.ts,
    });
    return res.status(200).json({
      ok: true,
      schema: "helix.visual_frame_analysis_response.v1",
      evidence,
      validation: {
        kind: "visual_frame_evidence",
        evidence_id: evidence.evidence_id,
        model_invoked: true,
        assistant_answer: false,
        raw_image_included: false,
        context_policy: "compact_context_pack_only",
      },
      live_source_chunk: matchingChunk,
      live_source_analysis_jobs: completedAnalysisJobs,
      live_source_analysis_output: routedVisualOutput,
      stage_play_live_source_mail_item: liveSourceMailItem,
      raw_session_buffer_entry_id: rawSessionBufferEntry?.entryId ?? null,
      assistant_answer: false,
      raw_image_included: false,
      context_policy: "compact_context_pack_only",
    });
  } catch (error) {
    return res.status(404).json({
      ok: false,
      error: error instanceof Error ? error.message : "visual_frame_analysis_failed",
      assistant_answer: false,
      raw_image_included: false,
      context_policy: "compact_context_pack_only",
    });
  }
});

