planRouter.post("/situation/visual-frame/align-with-events", (req, res) => {
  const body =
    req.body && typeof req.body === "object"
      ? (req.body as Record<string, unknown>)
      : {};
  const threadId = typeof body.thread_id === "string" && body.thread_id.trim()
    ? body.thread_id.trim()
    : "helix-ask:desktop";
  const eventRefs = Array.isArray(body.event_refs)
    ? body.event_refs.map((entry) => String(entry ?? "").trim()).filter(Boolean)
    : [];
  const recentWindow = eventRefs.length === 0
    ? queryEventJournal({
        thread_id: threadId,
        source_family: "minecraft",
        limit: typeof body.limit === "number" ? body.limit : 40,
        include_raw_events: false,
      })
    : null;
  const inferredEventRefs = recentWindow?.events.map((event) => event.journal_event_id) ?? [];
  const alignment = alignVisualFrameWithEvents({
    ...body,
    thread_id: threadId,
    event_refs: eventRefs.length > 0 ? eventRefs : inferredEventRefs,
    summary: typeof body.summary === "string" && body.summary.trim()
      ? body.summary
      : inferredEventRefs.length > 0
        ? `Latest visual frame aligned with ${inferredEventRefs.length} recent Minecraft event${inferredEventRefs.length === 1 ? "" : "s"}.`
        : undefined,
  });
  const interpretedAlignmentEvent = appendInterpretedEvent({
    thread_id: alignment.thread_id,
    room_id: typeof body.room_id === "string" ? body.room_id : null,
    source_family: "visual_snapshot",
    kind: "visual_event_alignment",
    title: "Visual evidence aligned with event window",
    summary: alignment.summary,
    confidence: alignment.confidence,
    evidence_refs: [alignment.alignment_id, ...alignment.frame_ids, ...alignment.event_refs],
    source_event_ids: alignment.event_refs,
    related_artifact_ids: [alignment.alignment_id, ...alignment.frame_ids],
    model_invoked: false,
    deterministic: true,
    created_at: new Date().toISOString(),
  });
  return res.status(200).json({
    ok: true,
    schema: "helix.visual_event_alignment_response.v1",
    alignment,
    interpreted_event: interpretedAlignmentEvent,
    synthetic_evidence: {
      kind: "visual_event_alignment",
      alignment_id: alignment.alignment_id,
      frame_ids: alignment.frame_ids,
      event_refs: alignment.event_refs,
      assistant_answer: false,
      raw_image_included: false,
      context_policy: "compact_context_pack_only",
    },
    assistant_answer: false,
    raw_image_included: false,
    context_policy: "compact_context_pack_only",
  });
});

