const appendSituationGoalSessionReceiptToThread = (args: {
  threadId: string;
  sessionId: string;
  receipt: Record<string, unknown>;
  artifact?: Record<string, unknown> | null;
}): void => {
  const now = new Date().toISOString();
  const turnId = `turn:situation-goal:${crypto.randomUUID()}`;
  const itemId = `item:situation-goal:${crypto.randomUUID()}`;
  const artifactItemId = args.artifact ? `item:live-situation-artifact:${crypto.randomUUID()}` : null;
  const base = {
    route: "/ask" as const,
    thread_id: args.threadId,
    turn_id: turnId,
    session_id: args.threadId,
    trace_id: null,
    turn_kind: "auxiliary" as const,
    answer_surface_mode: null,
    ts: now,
  };
  appendHelixThreadEvent({
    ...base,
    event_type: "turn_started",
    meta: { kind: "situation_goal_session", visibility: "standby_trace" },
  });
  appendHelixThreadEvent({
    ...base,
    event_type: "item_started",
    item_id: itemId,
    item_type: "toolObservation",
    item_stream: "observation",
    item_status: "in_progress",
    meta: {
      kind: "situation_goal_session_receipt",
      primary_user_visible: false,
      model_invoked: false,
      context_policy: "observation_only",
    },
  });
  appendHelixThreadEvent({
    ...base,
    event_type: "item_completed",
    item_id: itemId,
    item_type: "toolObservation",
    item_stream: "observation",
    item_status: "completed",
    observation_ref: {
      ...args.receipt,
      evidence_refs: [`situation_goal_session:${args.sessionId}`],
      provenance: "deterministic_dictionary",
      model_invoked: false,
      context_role: "observation_only",
      safe_for_future_context: true,
      user_visible: true,
    },
    meta: {
      kind: "situation_goal_session_receipt",
      primary_user_visible: false,
      model_invoked: false,
      context_policy: "observation_only",
    },
  });
  if (args.artifact && artifactItemId) {
    appendHelixThreadEvent({
      ...base,
      event_type: "item_started",
      item_id: artifactItemId,
      item_type: "validation",
      item_stream: "observation",
      item_status: "in_progress",
      meta: {
        kind: "live_situation_artifact_created",
        primary_user_visible: false,
        model_invoked: false,
        context_policy: "compact_context_pack_only",
      },
    });
    appendHelixThreadEvent({
      ...base,
      event_type: "item_completed",
      item_id: artifactItemId,
      item_type: "validation",
      item_stream: "observation",
      item_status: "completed",
      observation_ref: {
        ...args.artifact,
        provenance: "deterministic_world_reduction",
        model_invoked: false,
        context_role: "observation_not_assistant_answer",
        safe_for_future_context: true,
        user_visible: false,
      },
      meta: {
        kind: "live_situation_artifact_created",
        primary_user_visible: false,
        model_invoked: false,
        context_policy: "compact_context_pack_only",
      },
    });
  }
  appendHelixThreadEvent({
    ...base,
    event_type: "turn_completed",
    thread_status: "idle",
    meta: { kind: "situation_goal_session", assistant_text: null },
  });
};

const startSituationGoalSessionFromRequest = (
  body: z.infer<typeof situationGoalSessionRequestSchema>,
) => {
  const seenSources = listWorldSourcesSeen();
  const requestedRoomId = body.room_id?.trim() || null;
  const requestedSourceId = body.source_id?.trim() || body.source_ids[0]?.trim() || null;
  const requestedWorldId = body.world_id?.trim() || null;
  const objectiveText = body.objective?.trim().toLowerCase() ?? "";
  const worldEventSourceMissing =
    /\bvisual[-\s]?only\b/.test(objectiveText) ||
    /\b(?:do\s+not|don't|without|no)\b[\s\S]{0,80}\b(?:minecraft\s+)?(?:plugin|world[-\s]?event|server\s+log|server\s+source|minecraft\s+source)\b/.test(objectiveText) ||
    /\b(?:minecraft\s+)?(?:plugin|world[-\s]?event|server\s+log|server\s+source|minecraft\s+source)\b[\s\S]{0,80}\b(?:not\s+attached|missing|unavailable|inactive)\b/.test(objectiveText);
  const exactSeen =
    seenSources.find(
      (source) =>
        (!requestedRoomId || source.room_id === requestedRoomId) &&
        (!requestedSourceId || source.source_id === requestedSourceId) &&
        (!requestedWorldId || source.world_id === requestedWorldId),
    ) ?? null;
  if (!worldEventSourceMissing && seenSources.length > 0 && (requestedRoomId || requestedSourceId || requestedWorldId) && !exactSeen) {
    return {
      status: 409,
      body: {
        schema: "helix.situation_goal_session_receipt.v1",
        ok: false,
        session: null,
        ledger: null,
        error: "source_identity_mismatch",
        message: "Requested Minecraft source does not match a detected live source.",
        detected_sources: seenSources,
      },
    };
  }
  const resolvedSource = worldEventSourceMissing
    ? null
    : (exactSeen ?? seenSources[0] ?? null);
  const roomId = requestedRoomId ?? resolvedSource?.room_id ?? "room:minecraft-minehut";
  const sourceId = worldEventSourceMissing
    ? null
    : (requestedSourceId ??
      resolvedSource?.source_id ??
      "source:minecraft-server");
  const worldId = worldEventSourceMissing
    ? null
    : (requestedWorldId ?? resolvedSource?.world_id ?? "minecraft:minehut");
  const bindingReceipt = createSituationThreadBinding({
    room_id: roomId,
    source_id: sourceId,
    graph_id: body.graph_id ?? null,
    world_id: worldId,
    thread_id: body.thread_id,
    session_id: body.thread_id,
    mode: body.mode === "observe_only" || body.standby_mode === "off" ? "observe_only" : "standby_receipts",
    append_policy: "salient_only",
  });
  if (!bindingReceipt.ok) {
    return {
      status: 400,
      body: {
        schema: "helix.situation_goal_session_receipt.v1",
        ok: false,
        session: null,
        ledger: null,
        binding_id: null,
        graph_id: body.graph_id ?? null,
        source_id: sourceId,
        error: bindingReceipt.error ?? "binding_failed",
        message: bindingReceipt.message,
      },
    };
  }
  const receipt = createSituationGoalSession({
    thread_id: body.thread_id,
    room_id: roomId,
    source_id: sourceId,
    source_ids: Array.from(new Set([...body.source_ids, ...(sourceId ? [sourceId] : [])])),
    graph_id: body.graph_id ?? null,
    world_id: worldId,
    objective: body.objective ?? "Watch my Minecraft run and tell me about danger or progress.",
    mode: body.mode ?? (body.standby_mode === "off" ? "observe_only" : undefined),
    standby_mode: body.standby_mode,
    append_policy: body.append_policy,
    voice_output_enabled: body.voice_output_enabled === true,
    binding_id: bindingReceipt.binding?.binding_id ?? null,
  });
  if (receipt.ok && receipt.session) {
    const liveArtifact = createLiveSituationArtifact({
      thread_id: receipt.session.thread_id,
      created_turn_id: `setup:${receipt.session.session_id}`,
      session_id: receipt.session.session_id,
      room_id: receipt.session.room_id,
      world_id: receipt.session.world_id ?? null,
      source_ids: receipt.session.source_ids,
      graph_id: receipt.session.graph_id ?? null,
      mode: receipt.session.standby_mode ?? receipt.session.mode,
      objective: receipt.session.objective,
      current_goal: receipt.session.current_goal ?? null,
    });
    appendSituationGoalSessionReceiptToThread({
      threadId: receipt.session.thread_id,
      sessionId: receipt.session.session_id,
      receipt: receipt as unknown as Record<string, unknown>,
      artifact: liveArtifact as unknown as Record<string, unknown>,
    });
    return {
      status: 200,
      body: {
        ...receipt,
        live_situation_artifact: liveArtifact,
        message: "Minecraft situation is active. I'll watch for danger and progress in text-only mode.",
      },
    };
  }
  return { status: receipt.ok ? 200 : 400, body: receipt };
};

