const updateSituationGoalSessionStatusRoute = (
  req: Request,
  res: Response,
  status: "paused" | "active" | "stopped",
) => {
  const parsed = situationGoalSessionStatusRequestSchema.safeParse(req.body ?? {});
  if (!parsed.success) return res.status(400).json({ ok: false, error: "invalid_goal_session_status_request" });
  const sessionId =
    parsed.data.session_id ??
    (parsed.data.thread_id ? getActiveSituationGoalSessionForThread(parsed.data.thread_id)?.session_id : null);
  if (!sessionId) {
    return res.status(404).json({
      schema: "helix.situation_goal_session_receipt.v1",
      ok: false,
      session: null,
      ledger: null,
      error: "session_not_found",
      message: "No active Situation Goal Session matched the request.",
    });
  }
  return res.status(200).json(updateSituationGoalSessionStatus({ session_id: sessionId, status }));
};

