function extractQuestionFromPrompt(prompt: string): string {
  const match = prompt.match(/(?:^|\n)Question:\s*([^\n]+)/i);
  return normalizeBundledQuestion((match?.[1] ?? "").trim());
}

function resolveHelixAskQuestionText(args: {
  question?: string | null;
  prompt?: string | null;
}): string {
  const normalizedQuestion = normalizeBundledQuestion((args.question ?? "").trim());
  if (normalizedQuestion) return normalizedQuestion;
  const prompt = (args.prompt ?? "").trim();
  if (!prompt) return "";
  const extractedFromPrompt = extractQuestionFromPrompt(prompt);
  if (extractedFromPrompt) return extractedFromPrompt;
  // Allow prompt-only API clients to route correctly when they provide plain question text.
  const promptLines = prompt
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  const compactPrompt = promptLines.join(" ").trim();
  if (promptLines.length <= 2 && compactPrompt.length <= 600) {
    const normalizedPrompt = normalizeBundledQuestion(compactPrompt);
    return normalizedPrompt || compactPrompt;
  }
  const firstLine = promptLines[0] ?? "";
  if (!firstLine) return "";
  const normalizedFirstLine = normalizeBundledQuestion(firstLine);
  return normalizedFirstLine || firstLine;
}

function normalizeBundledQuestion(value: string): string {
  const raw = String(value ?? "").trim();
  if (!raw) return "";
  const stripWrapper = (input: string): string =>
    input
      .replace(/^\s*question:\s*/i, "")
      .replace(/^[`"'[\](){}.,;\s]+/, "")
      .replace(/[`"'[\](){}.,;\s]+$/, "")
      .trim();
  const normalized = stripWrapper(raw);
  if (!normalized) return "";
  const bundledParts = normalized
    .split(/['"`]\s*,\s*['"`]/)
    .map((entry) => stripWrapper(entry))
    .filter(Boolean);
  if (bundledParts.length > 1) {
    return bundledParts[0] ?? "";
  }
  if (/question:/i.test(raw) && (normalized.match(/\?/g)?.length ?? 0) > 1) {
    const firstQuestion = normalized.match(/^[^?]+\?/);
    if (firstQuestion?.[0]) {
      return stripWrapper(firstQuestion[0]);
    }
  }
  const malformedCommonality = normalized.match(
    /^what\s+is\s+(.+?)\s+and\s+(.+?)\s+have\s+in\s+common\??$/i,
  );
  if (malformedCommonality) {
    const left = stripWrapper(malformedCommonality[1] ?? "");
    const right = stripWrapper(malformedCommonality[2] ?? "");
    if (left && right) {
      return `What do ${left} and ${right} have in common?`;
    }
  }
  return normalized;
}

function extractContextFromPrompt(prompt: string): string {
  const marker = "\nContext:\n";
  const start = prompt.indexOf(marker);
  if (start < 0) return "";
  const after = prompt.slice(start + marker.length);
  const end = after.lastIndexOf("\nFINAL:");
  const context = end >= 0 ? after.slice(0, end) : after;
  return context.trim();
}

const SCAFFOLD_JUNK_LINE_RE = [
    /^",?\s*no headings\./i,
    /^general reasoning\s*:/i,
    /^repo evidence\s*:/i,
    /^evidence\s*:/i,
  /^ts[x]?[`.)\s]/i,
    /^(md|json|html)[`.)\s]/i,
  ];

const INLINE_JSON_TEXT_RE = /\{\s*"text"\s*:\s*"([^"]+)"[^}]*\}/g;
const NO_EVIDENCE_RE =
    /\b(no|not enough)\s+repo[-\s]?evidenced?\b|\bno\s+repo\s+evidence\b|\bno\s+evidence\s+(was|is)\s+found\b|\bno\s+repo[-\s]?grounded\b|\bcould\s+not\s+confirm\b/i;

function stripInlineJsonArtifacts(value: string): string {
    if (!value) return value;
    return value.replace(INLINE_JSON_TEXT_RE, (_match, text: string) => {
      const decoded = text
        .replace(/\\"/g, '"')
        .replace(/\\n/g, " ")
        .replace(/\\r/g, " ")
        .replace(/\\t/g, " ")
        .replace(/\\\\/g, "\\")
        .trim();
      return decoded || text;
    });
  }

function normalizeScaffoldText(value: string): string {
    const lines = value
      .split(/\r?\n/)
      .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .filter((line) => !/^(error:|srv\s+send_error)/i.test(line))
    .filter((line) => !/request\s*\(\d+\s+tokens\)\s+exceeds/i.test(line))
    .filter((line) => !SCAFFOLD_JUNK_LINE_RE.some((re) => re.test(line)));
  if (!lines.length) return "";
  const listed = lines.filter((line) => /^(\d+\.\s+|[-*]\s+)/.test(line));
  const trimmed = (listed.length ? listed : lines).slice(0, 12);
  return trimmed.join("\n");
}

function filterExistingEvidencePaths(paths: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of paths) {
    const trimmed = raw.trim();
    if (!trimmed) continue;
    if (/^(gate|certificate):/i.test(trimmed)) {
      if (!seen.has(trimmed)) {
        seen.add(trimmed);
        out.push(trimmed);
      }
      continue;
    }
    const normalized = (normalizeEvidenceRef(trimmed) ?? trimmed).replace(/\\/g, "/");
    if (!normalized) continue;
    const fullPath = path.resolve(process.cwd(), normalized);
    if (!fs.existsSync(fullPath)) continue;
    if (seen.has(normalized)) continue;
    seen.add(normalized);
    out.push(normalized);
  }
  return out;
}

function resolveEvidencePaths(
  evidence: string,
  contextFiles: string[],
  contextText?: string,
  limit = 6,
): string[] {
  const evidencePaths = filterExistingEvidencePaths(extractFilePathsFromText(evidence));
  if (evidencePaths.length > 0) {
    return Array.from(new Set(evidencePaths)).slice(0, limit);
  }
  const contextPaths = filterExistingEvidencePaths([
    ...contextFiles.filter(Boolean),
    ...(contextText ? extractFilePathsFromText(contextText) : []),
  ]);
  if (contextPaths.length === 0) return [];
  return Array.from(new Set(contextPaths)).slice(0, limit);
}

function appendEvidenceSources(
  evidence: string,
  contextFiles: string[],
  limit = 6,
  contextText?: string,
): string {
  const trimmed = evidence?.trim() ?? "";
  if (extractFilePathsFromText(trimmed).length > 0) return evidence;
  const sources = resolveEvidencePaths(trimmed, contextFiles, contextText, limit);
  if (sources.length === 0) return evidence;
  if (!trimmed) {
    return `Sources: ${sources.join(", ")}`;
  }
  return `${trimmed}\n\nSources: ${sources.join(", ")}`;
}

const EVIDENCE_BULLET_RE = /^\s*(\d+\.\s+|[-*]\s+)/;

function filterEvidenceBulletsByPath(
    text: string,
    allowPath: (path: string) => boolean,
  ): string {
    const trimmed = text?.trim() ?? "";
    if (!trimmed) return "";
    const lines = trimmed.split(/\r?\n/);
    const groups: string[][] = [];
    let current: string[] = [];
    let preamble: string[] = [];
    let sawBullet = false;
    for (const line of lines) {
      if (EVIDENCE_BULLET_RE.test(line)) {
        if (!sawBullet && preamble.length) {
          groups.push(preamble);
          preamble = [];
        }
        sawBullet = true;
        if (current.length) groups.push(current);
        current = [line];
        continue;
      }
      if (current.length) {
        current.push(line);
        continue;
      }
      if (!sawBullet) {
        preamble.push(line);
      }
    }
    if (current.length) groups.push(current);
    if (!sawBullet && preamble.length) groups.push(preamble);
    if (groups.length === 0) {
      const paths = extractFilePathsFromText(trimmed);
      return paths.some((path) => allowPath(path)) ? trimmed : "";
    }
  const kept = groups.filter((group) => {
    const paths = extractFilePathsFromText(group.join("\n"));
    return paths.some((path) => allowPath(path));
  });
  if (kept.length === 0) return "";
  return kept.map((group) => group.join("\n")).join("\n");
}

function buildDocEvidenceBullet(
  block: { path: string; block: string },
  label: "Definition" | "Evidence",
): string {
  const lines = block.block.split(/\r?\n/).slice(1);
  const referenceLines = lines.filter((line) =>
    DOC_PROOF_SPAN_RE.test(line) || DOC_SECTION_LINE_RE.test(line),
  );
  const content = lines
    .filter((line) => !DOC_PROOF_SPAN_RE.test(line))
    .filter((line) => !DOC_SECTION_LINE_RE.test(line))
    .join(" ")
    .trim();
  const snippet = clipAskText(content, 240);
  const prefix = referenceLines.length ? `${referenceLines.join(" ")} ` : "";
  const summary =
    snippet ? ensureSentence(snippet) : "See the documentation for more detail.";
  const pathRef = block.path?.trim();
  return pathRef
    ? `- ${label}: ${prefix}${summary} (see ${pathRef})`
    : `- ${label}: ${prefix}${summary}`;
}

function buildDefinitionDocBullet(block: { path: string; block: string }): string {
  return buildDocEvidenceBullet(block, "Definition");
}

function buildDocEvidenceScaffold(
  blocks: Array<{ path: string; block: string }>,
  options: { maxBlocks: number; definitionFocus: boolean },
): string {
  if (!blocks.length || options.maxBlocks <= 0) return "";
  const selected = blocks.slice(0, options.maxBlocks);
  const bullets = selected.map((block, index) => {
    const label = options.definitionFocus && index === 0 ? "Definition" : "Evidence";
    return buildDocEvidenceBullet(block, label);
  });
  return bullets.join("\n");
}

function buildCodeEvidenceBullet(span: HelixAskCodeSpan): string {
  const spanLabel = span.span ? `${span.span} ` : "";
  const snippet = clipAskText(span.snippet, 240);
  const prefix = span.isTest ? "Test" : "Code";
  const summary = snippet ? ensureSentence(snippet) : "See the implementation for details.";
  const pathRef = span.filePath?.trim();
  return pathRef
    ? `- ${prefix}: ${spanLabel}${summary} (see ${pathRef})`
    : `- ${prefix}: ${spanLabel}${summary}`;
}

const SYMBOL_TOKEN_RE = /\b[A-Za-z_][A-Za-z0-9_]{2,}\b/g;
const SYMBOL_STOPWORDS = new Set(
  [
    "the",
    "and",
    "for",
    "with",
    "from",
    "this",
    "that",
    "into",
    "what",
    "does",
    "mean",
    "repo",
    "docs",
    "document",
    "definition",
    "overview",
    "section",
    "span",
    "file",
    "files",
    "path",
    "paths",
    "system",
    "module",
    "modules",
    "function",
    "functions",
    "class",
    "classes",
    "types",
    "type",
    "data",
    "info",
    "note",
    "notes",
    "key",
    "keys",
    "value",
    "values",
  ].map((entry) => entry.toLowerCase()),
);

const extractSymbolCandidates = (blocks: Array<{ path: string; block: string }>): string[] => {
  const counts = new Map<string, number>();
  const pushToken = (token: string) => {
    const trimmed = token.trim();
    if (trimmed.length < 3) return;
    const lower = trimmed.toLowerCase();
    if (SYMBOL_STOPWORDS.has(lower)) return;
    const symbolLike =
      /[A-Z]/.test(trimmed) || /_/.test(trimmed) || /\d/.test(trimmed) || /::|\./.test(trimmed);
    if (!symbolLike) return;
    counts.set(trimmed, (counts.get(trimmed) ?? 0) + 1);
  };
  for (const block of blocks) {
    const content = block.block.split(/\r?\n/).slice(1).join(" ");
    const matches = content.match(SYMBOL_TOKEN_RE) ?? [];
    for (const match of matches) {
      pushToken(match);
    }
  }
  return Array.from(counts.entries())
    .sort((a, b) => b[1] - a[1] || b[0].length - a[0].length)
    .map(([token]) => token);
};

const extractCodeSpanFromFile = (
  filePath: string,
  symbol: string,
): { snippet: string; span?: string } => {
  const resolved = path.resolve(filePath);
  if (!fs.existsSync(resolved)) {
    return { snippet: "" };
  }
  try {
    const raw = fs.readFileSync(resolved, "utf8");
    const lines = raw.split(/\r?\n/);
    const lowerSymbol = symbol.toLowerCase();
    let index = lines.findIndex((line) => line.includes(symbol));
    if (index < 0) {
      index = lines.findIndex((line) => line.toLowerCase().includes(lowerSymbol));
    }
    if (index < 0) return { snippet: "" };
    const start = Math.max(0, index - 2);
    const end = Math.min(lines.length - 1, index + 2);
    const snippet = lines.slice(start, end + 1).join("\n").trim();
    const span = `Span: L${start + 1}-L${end + 1}`;
    return { snippet, span };
  } catch {
    return { snippet: "" };
  }
};

const buildGraphEvidenceCodeSpans = async (args: {
  evidence: HelixAskGraphEvidence[];
  question: string;
  topicProfile?: HelixAskTopicProfile | null;
}): Promise<HelixAskCodeSpan[]> => {
  if (!HELIX_ASK_CODE_ALIGNMENT) return [];
  const entries = args.evidence.filter((entry) => entry.type !== "doc");
  if (entries.length === 0) return [];
  const spans: HelixAskCodeSpan[] = [];
  const seen = new Set<string>();
  let bytesUsed = 0;
  let snapshot: Awaited<ReturnType<typeof loadCodeLattice>> | null = null;
  const ensureSnapshot = async () => {
    if (snapshot === null) {
      snapshot = await loadCodeLattice();
    }
    return snapshot;
  };
  for (const entry of entries) {
    if (spans.length >= HELIX_ASK_CODE_ALIGN_MAX_SPANS) break;
    const symbol = (entry.symbol ?? entry.field ?? entry.contains ?? "").trim();
    if (!symbol) continue;
    let filePath = entry.path;
    if (!filePath) {
      const lattice = await ensureSnapshot();
      if (!lattice) continue;
      const multi = await collectAskCandidatesMultiChannel(lattice, symbol, args.question, {
        topicProfile: args.topicProfile,
      });
      const flat = multi.lists.flatMap((list) => list.candidates);
      flat.sort((a, b) => b.score - a.score);
      if (entry.type === "test") {
        const testCandidate = flat.find((candidate) =>
          /(^|\/)(tests?|specs?)[/\\]/i.test(candidate.filePath ?? "") || /\.spec\./i.test(candidate.filePath ?? ""),
        );
        if (testCandidate?.filePath) {
          filePath = testCandidate.filePath;
        }
      }
      if (!filePath) {
        filePath = flat[0]?.filePath;
      }
    }
    if (!filePath) continue;
    const { snippet, span } = extractCodeSpanFromFile(filePath, symbol);
    const trimmedSnippet = snippet ? clipAskText(snippet, 400) : "";
    if (!trimmedSnippet) continue;
    const key = `${symbol}|${filePath}`.toLowerCase();
    if (seen.has(key)) continue;
    const candidateBytes = trimmedSnippet.length;
    if (bytesUsed + candidateBytes > HELIX_ASK_CODE_ALIGN_MAX_BYTES && spans.length > 0) break;
    bytesUsed += candidateBytes;
    const isTest =
      entry.type === "test" ||
      /(^|\/)(tests?|specs?)[/\\]/i.test(filePath) ||
      /\.spec\./i.test(filePath);
    spans.push({
      symbol,
      filePath,
      snippet: trimmedSnippet,
      span,
      isTest,
    });
    seen.add(key);
  }
  return spans;
};

const buildCodeAlignmentFromDocBlocks = async (
  blocks: Array<{ path: string; block: string }>,
  question: string,
  topicProfile?: HelixAskTopicProfile | null,
): Promise<HelixAskCodeAlignment> => {
  if (!HELIX_ASK_CODE_ALIGNMENT || blocks.length === 0) {
    return { spans: [], symbols: [], resolved: [] };
  }
  const symbols = extractSymbolCandidates(blocks).slice(0, HELIX_ASK_CODE_ALIGN_MAX_SYMBOLS);
  if (symbols.length === 0) {
    return { spans: [], symbols: [], resolved: [] };
  }
  const snapshot = await loadCodeLattice();
  if (!snapshot) {
    return { spans: [], symbols, resolved: [] };
  }
  const spans: HelixAskCodeSpan[] = [];
  const resolved: string[] = [];
  let bytesUsed = 0;
  for (const symbol of symbols) {
    if (spans.length >= HELIX_ASK_CODE_ALIGN_MAX_SPANS) break;
    const multi = await collectAskCandidatesMultiChannel(snapshot, symbol, question, {
      topicProfile,
    });
    const flat = multi.lists.flatMap((list) => list.candidates);
    flat.sort((a, b) => b.score - a.score);
    const top = flat[0];
    if (!top?.filePath) continue;
    const { snippet, span } = extractCodeSpanFromFile(top.filePath, symbol);
    const trimmedSnippet = snippet ? clipAskText(snippet, 400) : "";
    if (!trimmedSnippet) continue;
    const candidateBytes = trimmedSnippet.length;
    if (bytesUsed + candidateBytes > HELIX_ASK_CODE_ALIGN_MAX_BYTES && spans.length > 0) break;
    bytesUsed += candidateBytes;
    const isTest = /(^|\/)(tests?|specs?)[/\\]/i.test(top.filePath) || /\.spec\./i.test(top.filePath);
    spans.push({
      symbol,
      filePath: top.filePath,
      snippet: trimmedSnippet,
      span,
      isTest,
    });
    resolved.push(top.filePath);
    if (HELIX_ASK_CODE_ALIGN_TESTS && !isTest) {
      const testCandidate = flat.find((entry) =>
        /(^|\/)(tests?|specs?)[/\\]/i.test(entry.filePath) || /\.spec\./i.test(entry.filePath),
      );
      if (testCandidate && spans.length < HELIX_ASK_CODE_ALIGN_MAX_SPANS) {
        const testSpan = extractCodeSpanFromFile(testCandidate.filePath, symbol);
        if (testSpan.snippet) {
          spans.push({
            symbol,
            filePath: testCandidate.filePath,
            snippet: clipAskText(testSpan.snippet, 320),
            span: testSpan.span,
            isTest: true,
          });
          resolved.push(testCandidate.filePath);
        }
      }
    }
  }
  return { spans, symbols, resolved };
};

const buildPromptItemHash = (type: string, content: string): string => {
  return crypto.createHash("sha256").update(`${type}\n${content}`).digest("hex").slice(0, 12);
};

const buildHelixAskPromptItems = (args: {
  intentId?: string;
  intentDomain?: string;
  intentTier?: string;
  queries?: string[];
  contextFiles?: string[];
  retrievalConfidence?: number;
  docBlocks?: Array<{ path: string; block: string }>;
  codeAlignment?: HelixAskCodeAlignment | null;
  treeWalk?: string;
  slotCoverage?: { missingSlots: string[]; ratio: number } | null;
  docCoverage?: { missingSlots: string[]; ratio: number } | null;
  graphPack?: HelixAskGraphPack | null;
}): HelixAskPromptItem[] => {
  const items: HelixAskPromptItem[] = [];
  const pushItem = (type: string, content: string, label?: string) => {
    const trimmed = content.trim();
    if (!trimmed) return;
    const hash = buildPromptItemHash(type, trimmed);
    items.push({
      id: `${type}:${hash}`,
      type,
      label,
      content: trimmed,
      hash,
      size: trimmed.length,
    });
  };
  if (args.intentId) {
    pushItem(
      "intent",
      `intent=${args.intentId} domain=${args.intentDomain ?? "-"} tier=${args.intentTier ?? "-"}`,
    );
  }
  if (args.queries?.length || args.contextFiles?.length) {
    const lines = [
      args.queries?.length ? `queries: ${args.queries.join("; ")}` : "",
      args.contextFiles?.length ? `files: ${args.contextFiles.slice(0, 12).join(", ")}` : "",
      typeof args.retrievalConfidence === "number"
        ? `confidence: ${args.retrievalConfidence.toFixed(2)}`
        : "",
    ]
      .filter(Boolean)
      .join("\n");
    pushItem("retrieval_summary", lines);
  }
  if (args.graphPack?.treeIds?.length) {
    pushItem("selected_trees", args.graphPack.treeIds.join(", "));
  }
  if (args.docBlocks?.length) {
    const docLines = args.docBlocks
      .map((block) => `- ${extractDocBlockHeader(block)} (${block.path})`)
      .join("\n");
    pushItem("doc_spans", docLines);
  }
  if (args.codeAlignment?.spans?.length) {
    const codeLines = args.codeAlignment.spans
      .map((span) => `- ${span.symbol} ${span.span ?? ""} (${span.filePath})`)
      .join("\n");
    pushItem("code_spans", codeLines);
  }
  if (args.treeWalk?.trim()) {
    pushItem("tree_walk", args.treeWalk.trim());
  }
  if (args.slotCoverage || args.docCoverage) {
    const coverageLines = [
      args.slotCoverage
        ? `slot_coverage: ${args.slotCoverage.ratio.toFixed(2)} missing=${args.slotCoverage.missingSlots.join(",") || "none"}`
        : "",
      args.docCoverage
        ? `doc_coverage: ${args.docCoverage.ratio.toFixed(2)} missing=${args.docCoverage.missingSlots.join(",") || "none"}`
        : "",
    ]
      .filter(Boolean)
      .join("\n");
    pushItem("slot_coverage", coverageLines);
  }
  return items;
};

const buildToolResultsBlock = (items: HelixAskPromptItem[]): string => {
  if (!items.length) return "";
  const lines: string[] = ["TOOL_RESULTS"];
  for (const item of items) {
    if (!["retrieval_summary", "doc_spans", "code_spans", "tree_walk"].includes(item.type)) {
      continue;
    }
    lines.push(`[${item.type}]`);
    lines.push(item.content);
    lines.push("");
  }
  lines.push("END_TOOL_RESULTS");
  const raw = lines.join("\n").trim();
  if (raw.length <= HELIX_ASK_TOOL_RESULTS_MAX_CHARS) return raw;
  const clipped = clipAskText(raw, HELIX_ASK_TOOL_RESULTS_MAX_CHARS);
  if (clipped.includes("END_TOOL_RESULTS")) return clipped;
  return `${clipped}\nEND_TOOL_RESULTS`;
};

const toolResultsHas = (toolResultsBlock: string | undefined, type: string): boolean => {
  if (!toolResultsBlock?.trim()) return false;
  return toolResultsBlock.includes(`[${type}]`);
};

const buildToolResultsFallbackAnswer = (args: {
  definitionFocus: boolean;
  docBlocks: Array<{ path: string; block: string }>;
  codeAlignment?: HelixAskCodeAlignment | null;
  treeWalk?: string;
}): string => {
  const lines: string[] = ["Confirmed:"];
  const fallbackDocBlocks = filterFallbackDocBlocks(args.docBlocks);
  const docBlocks = fallbackDocBlocks.length > 0 ? fallbackDocBlocks : args.docBlocks;
  if (docBlocks.length > 0) {
    const limit = Math.min(docBlocks.length, 3);
    for (let i = 0; i < limit; i += 1) {
      const label = args.definitionFocus && i === 0 ? "Definition" : "Evidence";
      lines.push(buildDocEvidenceBullet(docBlocks[i], label));
    }
  }
  if (args.codeAlignment?.spans?.length) {
    const limit = Math.min(args.codeAlignment.spans.length, 3);
    for (let i = 0; i < limit; i += 1) {
      lines.push(buildCodeEvidenceBullet(args.codeAlignment.spans[i]));
    }
  }
  if (args.treeWalk?.trim()) {
    lines.push("");
    lines.push(args.treeWalk.trim());
  }
  return lines.join("\n");
};

const stripEvidenceBulletPrefix = (value: string): string =>
  value.replace(/^\s*-\s*/, "").trim();

const filterFallbackDocBlocks = (
  docBlocks: Array<{ path: string; block: string }>,
): Array<{ path: string; block: string }> => {
  if (!docBlocks.length) return docBlocks;
  return docBlocks.filter((block) => {
    const normalized = block.path.replace(/\\/g, "/").toLowerCase();
    if (normalized.includes("/warp-web/")) return false;
    if (/\.(html?|xhtml)$/i.test(normalized)) return false;
    return true;
  });
};

const SCIENTIFIC_SECTION_HEADINGS = [
  "Confirmed:",
  "Unverified:",
  "Reasoned connections (bounded):",
  "Hypotheses (optional):",
  "Next evidence:",
] as const;

const normalizeScientificSectionLayout = (value: string): string => {
  if (!value.trim()) return value;
  let cleaned = value;
  for (let i = 1; i < SCIENTIFIC_SECTION_HEADINGS.length; i += 1) {
    const heading = SCIENTIFIC_SECTION_HEADINGS[i];
    const escaped = heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const re = new RegExp(`(?<!\\n)\\s*${escaped}`, "gi");
    cleaned = cleaned.replace(re, `\n\n${heading}`);
  }
  return cleaned.replace(/\n{3,}/g, "\n\n").trim();
};

const extractOrderedAnswerSentences = (value: string, limit = 3): string[] => {
  if (!value.trim()) return [];
  const ordered: string[] = [];
  const orderedRe = /(?:^|\s)\d+\.\s+([\s\S]*?)(?=(?:\s+\d+\.\s+)|$)/g;
  for (const match of value.matchAll(orderedRe)) {
    const sentence = (match[1] ?? "").replace(/\s+/g, " ").trim();
    if (sentence.length >= 24) {
      ordered.push(ensureSentence(sentence));
    }
    if (ordered.length >= limit) break;
  }
  if (ordered.length > 0) return Array.from(new Set(ordered)).slice(0, limit);
  const fallback = splitGroundedSentences(value)
    .map((entry) => ensureSentence(entry))
    .filter((entry) => entry.length >= 24);
  return Array.from(new Set(fallback)).slice(0, limit);
};

const buildSingleLlmShortAnswerFallback = (args: {
  question: string;
  definitionFocus: boolean;
  docBlocks: Array<{ path: string; block: string }>;
  codeAlignment?: HelixAskCodeAlignment | null;
  evidenceText?: string;
  treeWalk?: string;
  missingSlots?: string[];
  slotPlan?: HelixAskSlotPlan | null;
  anchorFiles?: string[];
  searchedTerms?: string[];
  searchedFiles?: string[];
  planClarify?: string;
  headingSeedSlots?: HelixAskSlotPlanEntry[];
  requiresRepoEvidence?: boolean;
}): string => {
  const sanitizeFallbackHintText = (value: string): string =>
    value
      .normalize("NFKD")
      .replace(/[^\x09\x0A\x0D\x20-\x7E]/g, "")
      .replace(/\s+/g, " ")
      .trim();
  const implementationQuestion = isImplementationQuestion(args.question);
  const derivedDocBlocks = args.docBlocks.length
    ? args.docBlocks
    : (args.codeAlignment?.spans ?? [])
        .filter((span) => isDocEvidencePath(span.filePath))
        .map((span) => ({
          path: span.filePath,
          block: `${span.filePath}\nSection: Retrieved Span\n${span.span ?? "Span: L?-L?"}\n${span.snippet}`,
        }));
  const filteredDocBlocks = filterFallbackDocBlocks(derivedDocBlocks);
  const docBlocksForRanking = filteredDocBlocks.length > 0 ? filteredDocBlocks : derivedDocBlocks;
  const relevanceTokens = tokenizeCoverageRelevance(args.question);
  const rankedDocBlocks = docBlocksForRanking
    .map((block) => ({
      block,
      relevance: scoreCoverageRelevance(
        relevanceTokens,
        `${block.path}\n${extractDocBlockHeader(block)}\n${block.block}`,
      ),
    }))
    .sort((a, b) => b.relevance - a.relevance);
  const docSource =
    rankedDocBlocks.some((entry) => entry.relevance > 0)
      ? rankedDocBlocks.filter((entry) => entry.relevance > 0).map((entry) => entry.block)
      : derivedDocBlocks;
  const rankedCodeSpans = (args.codeAlignment?.spans ?? [])
    .filter((span) => isCodeEvidencePath(span.filePath) || span.isTest)
    .map((span) => {
      const relevance = scoreCoverageRelevance(
        relevanceTokens,
        `${span.filePath}\n${span.symbol}\n${span.snippet}`,
      );
      return { span, relevance };
    })
    .filter((entry) => implementationQuestion || entry.relevance >= 0.45)
    .sort((a, b) => b.relevance - a.relevance);
  const codeSource =
    rankedCodeSpans.some((entry) => entry.relevance > 0)
      ? rankedCodeSpans.filter((entry) => entry.relevance > 0).map((entry) => entry.span)
      : [];
  const docLimit = Math.min(derivedDocBlocks.length, args.definitionFocus ? 5 : 4);
  const codeLimit = Math.min(codeSource.length, implementationQuestion ? 4 : 2);
  const docBullets = docSource
    .slice(0, docLimit)
    .map((block, index) =>
      buildDocEvidenceBullet(block, args.definitionFocus && index === 0 ? "Definition" : "Evidence"),
    );
  const codeBullets = codeSource.slice(0, codeLimit).map((span) => buildCodeEvidenceBullet(span));
  const anchorEvidenceHints = normalizeCitations([
    ...(args.anchorFiles ?? []),
    ...extractFilePathsFromText(args.evidenceText ?? ""),
    ...extractCitationTokensFromText(args.evidenceText ?? ""),
  ]).slice(0, 4);
  if (docBullets.length === 0 && codeBullets.length === 0 && anchorEvidenceHints.length > 0) {
    docBullets.push(`- Retrieved grounded repository anchors: ${anchorEvidenceHints.join(", ")}.`);
  }
  const normalizedEvidence = [...docBullets, ...codeBullets].map(stripEvidenceBulletPrefix);
  const hasConfirmedEvidence = docBullets.length > 0 || codeBullets.length > 0;
  const lines: string[] = [hasConfirmedEvidence ? "Confirmed:" : "Unverified:"];
  if (docBullets.length === 0 && codeBullets.length === 0) {
    lines.push(
      `- ${
        args.requiresRepoEvidence
          ? "No repo-evidenced claims were confirmed yet."
          : "No confirmed evidence was found yet."
      }`,
    );
  } else {
    for (const bullet of docBullets) lines.push(bullet);
    for (const bullet of codeBullets) lines.push(bullet);
  }
  lines.push("");
  lines.push("Reasoned connections (bounded):");
  if (normalizedEvidence.length >= 2) {
    lines.push(
      `- ${clipAskText(normalizedEvidence[0], 220)} ${clipAskText(normalizedEvidence[1], 220)} Bounded linkage supported by cited repo evidence.`,
    );
  } else {
    lines.push("- Need at least two grounded points before drawing a connection.");
  }
  if (args.treeWalk?.trim()) {
    lines.push("");
    lines.push("Tree walk (bound):");
    lines.push(args.treeWalk.trim());
  }
  const nextEvidence = buildNextEvidenceHints({
    question: args.question,
    missingSlots: args.missingSlots,
    slotPlan: args.slotPlan,
    anchorFiles: args.anchorFiles,
    searchedTerms: args.searchedTerms,
    searchedFiles: args.searchedFiles,
    includeSearchSummary: true,
    planClarify: args.planClarify,
    headingSeedSlots: args.headingSeedSlots,
    suppressClarify: normalizedEvidence.length >= 2 && !(args.missingSlots?.length ?? 0),
    limit: 6,
  });
  lines.push("");
  lines.push("Next evidence:");
  if (nextEvidence.length > 0) {
    nextEvidence
      .map((item) => sanitizeFallbackHintText(item))
      .filter(Boolean)
      .forEach((item) => lines.push(`- ${item}`));
  } else {
    lines.push("- Provide the file path or doc section that defines the missing terms.");
  }
  return lines.join("\n").trim();
};

const shouldOverrideClarifyForGroundedEvidence = (args: {
  alignmentGateDecision: "PASS" | "FAIL" | "BORDERLINE";
  openWorldBypassMode: "off" | "active";
  atlasRequirementFailed: boolean;
  requiresRepoEvidence: boolean;
  evidenceGateOk: boolean;
  mustIncludeOk: boolean;
  viabilityMustIncludeOk: boolean;
  topicMustIncludeOk?: boolean;
  retrievalConfidence: number;
  repoThreshold: number;
  hasRepoHints: boolean;
  hasFilePathHints: boolean;
  contextFileCount: number;
}): boolean => {
  if (!args.requiresRepoEvidence) return false;
  if (args.alignmentGateDecision !== "FAIL") return false;
  if (args.openWorldBypassMode === "active") return false;
  if (args.atlasRequirementFailed) return false;
  if (!args.evidenceGateOk) return false;
  if (!args.mustIncludeOk || !args.viabilityMustIncludeOk || args.topicMustIncludeOk !== true) return false;
  const hasRepoEvidenceContext =
    args.contextFileCount > 0 || args.hasRepoHints || args.hasFilePathHints;
  if (!hasRepoEvidenceContext) return false;
  const confidenceFloor = Math.max(0.65, args.repoThreshold - 0.05);
  return args.retrievalConfidence >= confidenceFloor;
};

const buildDeterministicRepoRuntimeFallback = (args: {
  question: string;
  format: HelixAskFormat;
  definitionFocus: boolean;
  docBlocks: Array<{ path: string; block: string }>;
  codeAlignment?: HelixAskCodeAlignment | null;
  evidenceText: string;
  anchorFiles: string[];
}): string | null => {
  const allowedCitations = normalizeCitations([
    ...args.anchorFiles,
    ...extractFilePathsFromText(args.evidenceText),
    ...extractCitationTokensFromText(args.evidenceText),
  ]);
  if (allowedCitations.length === 0) return null;
  const contract = sanitizeHelixAskAnswerContract(
    buildDeterministicAnswerContractFallback({
      question: args.question,
      format: args.format,
      definitionFocus: args.definitionFocus,
      docBlocks: args.docBlocks,
      codeAlignment: args.codeAlignment,
      evidenceText: args.evidenceText,
      allowedCitations,
    }),
    allowedCitations,
  );
  const rendered = renderHelixAskAnswerContract(contract, args.format, args.question).trim();
  if (!rendered) return null;
  const cleaned = sanitizeSourcesLine(rendered, allowedCitations, allowedCitations).trim();
  return cleaned || null;
};

const buildDeterministicFamilyRepoRuntimeFallback = (args: {
  question: string;
  family?: string | null;
  intentDomain: HelixAskDomain;
  queryConstraints: HelixAskQueryConstraints;
  equationPrompt: boolean;
  definitionFocus: boolean;
  equationIntentContract: HelixAskIntentContract | null;
  selectorPrimaryKey: string | null;
  selectorLocked: boolean;
  selectorFamily: string | null;
  lockIdSeed: string;
  allowedCitations: string[];
  contextFiles: string[];
  turnContract: HelixAskTurnContract | null;
  slotCoverageRatio: number;
  slotMissing: string[];
  connectedHintPathCount: number;
  retrievalConfidence: number;
  objectiveSupport: HelixAskEvidencePackObjectiveSupport[];
  existingText: string;
}): string | null => {
  const fallbackTurnContract = buildHelixAskTurnContract({
    question: args.question,
    intentDomain: args.intentDomain,
    requiresRepoEvidence: args.intentDomain !== "general",
    queryConstraints: args.queryConstraints,
    equationPrompt: args.equationPrompt,
    definitionFocus: args.definitionFocus,
    equationIntentContract: args.equationIntentContract,
    plannerMode: "deterministic",
    plannerValid: true,
    plannerSource: "family_runtime_fallback",
    maxObjectives: HELIX_ASK_OBJECTIVE_PLANNER_MAX_OBJECTIVES,
    maxRequiredSlots: HELIX_ASK_OBJECTIVE_PLANNER_MAX_REQUIRED_SLOTS,
    maxQueryHints: HELIX_ASK_OBJECTIVE_PLANNER_MAX_QUERY_HINTS,
    version: HELIX_ASK_TURN_CONTRACT_VERSION,
    dependencies: HELIX_ASK_TURN_CONTRACT_BUILDER_DEPENDENCIES,
  });
  const turnContract = args.turnContract ?? fallbackTurnContract;
  const family = turnContract.output_family.trim();
  if (
    family !== "definition_overview" &&
    family !== "implementation_code_path" &&
    family !== "roadmap_planning" &&
    family !== "troubleshooting_diagnosis" &&
    family !== "recommendation_decision"
  ) return null;
  const evidenceGap =
    args.slotMissing.length > 0 ||
    (turnContract.constraints.requires_repo_evidence &&
      args.retrievalConfidence < (family === "roadmap_planning" ? 0.45 : 0.3));
  const plan = buildHelixAskAnswerPlanShadow({
    question: args.question,
    intentDomain: args.intentDomain,
    queryConstraints: args.queryConstraints,
    equationPrompt: args.equationPrompt,
    definitionFocus: args.definitionFocus,
    equationIntentContract: args.equationIntentContract,
    requiredOutputs: args.equationIntentContract?.required_outputs ?? [],
    selectorPrimaryKey: args.selectorPrimaryKey,
    selectorLocked: args.selectorLocked,
    selectorFamily: args.selectorFamily,
    lockIdSeed: args.lockIdSeed,
    allowedCitations: args.allowedCitations,
    contextFileCount: args.contextFiles.length,
    turnContract,
    slotCoverageRatio: args.slotCoverageRatio,
    slotMissing: args.slotMissing,
    connectedHintPathCount: args.connectedHintPathCount,
    retrievalConfidence: args.retrievalConfidence,
    evidenceGap,
    objectiveSupport: args.objectiveSupport,
    evidenceText: args.existingText,
    promptResearchRetrievalContract: null,
  });
  const rendered = buildHelixAskUniversalFamilyDegradeAnswer({
    plan,
    question: args.question,
    existingText: args.existingText,
    reason: "pre_answer_deterministic_direct",
  }).trim();
  if (!rendered) return null;
  const validation = validateHelixAskAnswerPlanShadow({
    plan,
    renderedText: rendered,
  });
  if (!validation.schema_valid) {
    if (family === "definition_overview") {
      return rendered;
    }
    return null;
  }
  return rendered;
};

const selectDeterministicRepoRuntimeFallbackCandidate = (args: {
  promptFamily?: string | null;
  familyFallback?: string | null;
  baseFallback?: string | null;
}): string | null => {
  const familyFallback =
    typeof args.familyFallback === "string" ? args.familyFallback.trim() : "";
  if (familyFallback) return familyFallback;
  const family = (args.promptFamily ?? "").trim();
  if (family === "definition_overview") {
    return null;
  }
  const baseFallback =
    typeof args.baseFallback === "string" ? args.baseFallback.trim() : "";
  return baseFallback || null;
};

const shouldDirectUseDeterministicRepoRuntimeFallback = (args: {
  fallbackText?: string | null;
  promptFamily?: string | null;
  repoGrounded: boolean;
  relationIntentActive: boolean;
  forceLlmProbe: boolean;
  compositeEnabled: boolean;
}): boolean => {
  if (!args.repoGrounded) return false;
  if (args.relationIntentActive) return false;
  if (args.forceLlmProbe) return false;
  if (args.compositeEnabled) return false;
  const fallbackText =
    typeof args.fallbackText === "string" ? args.fallbackText.trim() : "";
  if (!fallbackText) return false;
  const family = (args.promptFamily ?? "").trim();
  if (family === "definition_overview") {
    return true;
  }
  if (family === "implementation_code_path") {
    return (
      /^Where in repo:/im.test(fallbackText) &&
      /^Call chain:/im.test(fallbackText) &&
      /^Sources:/im.test(fallbackText)
    );
  }
  if (family === "roadmap_planning") {
    return (
      /^Repo-Grounded Findings:/im.test(fallbackText) &&
      /^Implementation Roadmap:/im.test(fallbackText) &&
      /^Evidence Gaps:/im.test(fallbackText) &&
      /^Next Anchors Needed:/im.test(fallbackText) &&
      /^Sources:/im.test(fallbackText)
    );
  }
  if (family === "troubleshooting_diagnosis") {
    return (
      /^Symptoms:/im.test(fallbackText) &&
      /^Most likely causes:/im.test(fallbackText) &&
      /^Fixes:/im.test(fallbackText) &&
      /^Sources:/im.test(fallbackText)
    );
  }
  if (family === "recommendation_decision") {
    return (
      /^Decision:/im.test(fallbackText) &&
      /^Rationale:/im.test(fallbackText) &&
      /^Constraints:/im.test(fallbackText) &&
      /^Risks:/im.test(fallbackText) &&
      /^Sources:/im.test(fallbackText)
    );
  }
  return false;
};

const hasHelixAskFiveSectionShape = (text: string): boolean => {
  const normalized = text.toLowerCase();
  const required = [
    "short answer:",
    "conceptual baseline:",
    "how repo solves it:",
    "evidence + proof anchors:",
    "uncertainty / open gaps:",
  ];
  return required.every((heading) => normalized.includes(heading));
};

const hasHelixAskFamilyFallbackShape = (text: string): boolean => {
  const normalized = text.toLowerCase();
  const familyShapes = [
    ["where in repo:", "call chain:", "sources:"],
    ["mechanism explanation:", "inputs/outputs:", "sources:"],
    ["definition:", "repo anchors:", "sources:"],
    ["repo-grounded findings:", "implementation roadmap:", "sources:"],
  ];
  return familyShapes.some((shape) => shape.every((heading) => normalized.includes(heading)));
};

const hasAcceptedHelixAskRepoFallbackShape = (text: string): boolean =>
  hasHelixAskFiveSectionShape(text) || hasHelixAskFamilyFallbackShape(text);

const shouldApplyTermPriorGeneralArbiterLock = (args: {
  termPriorGeneralRouteLock: boolean;
  termPriorRepoOverrideApplied: boolean;
  explicitRepoExpectation: boolean;
  hasFilePathHints: boolean;
  endpointHintCount: number;
  relationHeuristicPrompt: boolean;
}): boolean => {
  if (!args.termPriorGeneralRouteLock) return false;
  if (args.termPriorRepoOverrideApplied) return false;
  if (args.explicitRepoExpectation) return false;
  if (args.hasFilePathHints) return false;
  if (args.endpointHintCount > 0) return false;
  if (args.relationHeuristicPrompt) return false;
  return true;
};

const shouldApplyTermPriorPhysicsRelationGeneralRoute = (args: {
  termPriorApplied: boolean;
  termPriorPreferGeneralRouting: boolean;
  termPriorRelationCue: boolean;
  explicitRepoExpectation: boolean;
  hasFilePathHints: boolean;
  endpointHintCount: number;
  relationHeuristicPrompt: boolean;
  initialIntentProfileId?: string;
}): boolean => {
  if (!args.termPriorApplied) return false;
  if (!args.termPriorPreferGeneralRouting) return false;
  if (!args.termPriorRelationCue) return false;
  const initialIntentProfileId = String(args.initialIntentProfileId ?? "")
    .trim()
    .toLowerCase();
  if (/^repo\.warp_/.test(initialIntentProfileId)) return false;
  if (args.explicitRepoExpectation) return false;
  if (args.hasFilePathHints) return false;
  if (args.endpointHintCount > 0) return false;
  if (args.relationHeuristicPrompt) return false;
  return true;
};

const shouldDirectUseDeterministicRelationPacketAnswer = (args: {
  relationQuestionFastPath: boolean;
  relationPacketPresent: boolean;
  relationDualDomainOk: boolean;
  forceLlmProbe: boolean;
  controllerPrimaryPreferred: boolean;
}): boolean => {
  if (!args.relationQuestionFastPath) return false;
  if (!args.relationPacketPresent) return false;
  if (!args.relationDualDomainOk) return false;
  if (args.forceLlmProbe) return false;
  if (args.controllerPrimaryPreferred) return false;
  return true;
};

const shouldPreserveHelixAskDeterministicAnswerAcrossComposer = (args: {
  llmInvoked: boolean;
  answerPath: string[];
}): boolean => {
  const frontierDeterministicAnswer = args.answerPath.some(
    (entry) =>
      entry === "qualityFloor:frontier_contract" || entry === "frontier:final_contract_enforced",
  );
  if (frontierDeterministicAnswer) return true;
  if (args.llmInvoked) return false;
  return args.answerPath.some((entry) =>
    entry === "answer:repo_runtime_deterministic_direct" ||
    entry === "answerContract:deterministic_pre_llm" ||
    entry === "answerContract:relation_packet_pre_llm" ||
    entry === "qualityFloor:frontier_contract" ||
    entry === "frontier:final_contract_enforced",
  );
};

const shouldBlockHelixAskDeterministicPreserveAcrossComposer = (args: {
  preserveDeterministicCandidate: boolean;
  preserveForcedAnswer: boolean;
  answerPath: string[];
}): boolean => {
  if (!args.preserveDeterministicCandidate || args.preserveForcedAnswer) return false;
  const hardContractDeterministicAnswer = args.answerPath.some((entry) =>
    entry === "qualityFloor:frontier_contract" ||
    entry === "frontier:final_contract_enforced" ||
    entry === "frontier:hard_guard_clarify" ||
    entry === "relationFallback:deterministic_guard",
  );
  return !hardContractDeterministicAnswer;
};

const shouldEscalateHelixAskComposerSoftGuardObserve = (args: {
  softSectionGuardFailureObserved: boolean;
  familyFormatAccuracy: number;
  minAccuracy: number;
  failReasons: string[];
  gateMode: "observe" | "enforce";
}): boolean => {
  if (!args.softSectionGuardFailureObserved) return false;
  if (args.gateMode === "enforce") return false;
  const normalizedFailReasons = new Set(
    (args.failReasons ?? []).map((reason) => String(reason ?? "").trim().toLowerCase()),
  );
  if (normalizedFailReasons.has("debug_leak") || normalizedFailReasons.has("anchor_integrity_violation")) {
    return true;
  }
  const familyFormatAccuracy = Number(args.familyFormatAccuracy);
  const minAccuracy = Number.isFinite(args.minAccuracy) ? clampNumber(args.minAccuracy, 0, 1) : 1;
  if (!Number.isFinite(familyFormatAccuracy)) return true;
  return familyFormatAccuracy <= minAccuracy;
};

const shouldPinHelixAskDeterministicAnswerPreFinalize = (args: {
  deterministicRepoRuntimeFallbackUsed: boolean;
  answerPath: string[];
}): boolean => {
  if (args.deterministicRepoRuntimeFallbackUsed) return true;
  return args.answerPath.some((entry) =>
    entry === "answer:repo_runtime_deterministic_direct" ||
    entry === "answerContract:deterministic_pre_llm" ||
    entry === "answerContract:relation_packet_pre_llm" ||
    entry === "qualityFloor:frontier_contract" ||
    entry === "frontier:final_contract_enforced",
  );
};

const shouldRestoreHelixAskDeterministicPlatonicAnswer = (args: {
  preserveDeterministicPlatonicAnswer: boolean;
  ungatedReasoningAnswer: string;
  platonicAnswer: string;
}): boolean =>
  args.preserveDeterministicPlatonicAnswer &&
  args.ungatedReasoningAnswer.trim() !== args.platonicAnswer.trim();

const sanitizePinnedHelixAskDeterministicAnswer = (value: string): string => {
  if (!value) return value;
  let cleaned = stripCitationRepairArtifacts(stripInlineJsonArtifacts(value)).trim();
  cleaned = cleanDanglingFileExtensionFragments(cleaned);
  cleaned = dedupeAdjacentCitationBrackets(cleaned);
  cleaned = cleaned.replace(/[ \t]{2,}/g, " ").replace(/\n{3,}/g, "\n\n").trim();
  return cleaned;
};

const finalizePinnedHelixAskDeterministicAnswer = (args: {
  answer: string;
  allowedSourcePaths: string[];
  citationTokens: string[];
}): string => {
  let cleaned = sanitizePinnedHelixAskDeterministicAnswer(args.answer);
  cleaned = sanitizeSourcesLine(cleaned, args.allowedSourcePaths, args.citationTokens);
  cleaned = sanitizePinnedHelixAskDeterministicAnswer(cleaned);
  return cleaned;
};

const stripHelixAskInstructionPlaceholderArtifacts = (value: string): string => {
  if (!value) return value;
  let cleaned = value;
  cleaned = cleaned.replace(
    /\bfor\s+State what remains uncertain or under-evidenced in this turn\.?/gi,
    "for this turn",
  );
  cleaned = cleaned.replace(
    /State what remains uncertain or under-evidenced in this turn\.?/gi,
    "this turn",
  );
  cleaned = cleaned
    .replace(/;\s*;\s*/g, "; ")
    .replace(/\s{2,}/g, " ")
    .replace(/\n{3,}/g, "\n\n");
  return cleaned.trim();
};

const stripHelixAskObjectiveCheckpointArtifacts = (value: string): string => {
  if (!value) return value;
  let cleaned = value;
  cleaned = cleaned.replace(
    /Objective checkpoints:\s*[\s\S]*?(?=(?:\nSources:\s|\bSources:\s|$))/gi,
    "",
  );
  cleaned = cleaned.replace(
    /(?:^|\n)\s*(status|missing|evidence|summary)\s*=[^\n]*(?=\n|$)/gi,
    "",
  );
  cleaned = cleaned
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\s+\n/g, "\n")
    .trim();
  return cleaned;
};

const HELIX_ASK_PLAN_STREAM_LEAK_RE_LIST: RegExp[] = [
  /(?:^|\n)\s*Objective checkpoints:\b/i,
  /(?:^|\n)\s*Objective:\s+/i,
  /(?:^|\n)\s*(?:objective_id|objective_label|required_slots|matched_slots|missing_slots|responseLanguage)\s*=/i,
  /(?:^|\n)\s*(?:status|missing|evidence|summary)\s*=/i,
  /(?:^|\n)\s*(?:Planner Objectives|Objective Loop State|Objective Step Transcripts)\b/i,
  /(?:^|\n)\s*(?:PLAN|RETRIEVE|MINI_SYNTH|MINI_CRITIC|UNKNOWN_TERMINAL|ASSEMBLE)\s*:/i,
];

const hasHelixAskPlanStreamLeakage = (value: string): boolean => {
  const normalized = String(value ?? "");
  if (!normalized.trim()) return false;
  return HELIX_ASK_PLAN_STREAM_LEAK_RE_LIST.some((pattern) => pattern.test(normalized));
};

const stripHelixAskPlanStreamArtifacts = (value: string): string => {
  if (!value) return value;
  let cleaned = value;
  cleaned = cleaned.replace(
    /Objective checkpoints:\s*[\s\S]*?(?=(?:\nSources:\s|\bSources:\s|$))/gi,
    "",
  );
  cleaned = cleaned.replace(/(?:^|\n)\s*Objective:\s*[^\n]*(?=\n|$)/gi, "");
  cleaned = cleaned.replace(
    /(?:^|\n)\s*(?:objective_id|objective_label|required_slots|matched_slots|missing_slots|responseLanguage)\s*=[^\n]*(?=\n|$)/gi,
    "",
  );
  cleaned = cleaned.replace(
    /(?:^|\n)\s*(?:status|missing|evidence|summary)\s*=[^\n]*(?=\n|$)/gi,
    "",
  );
  cleaned = cleaned.replace(
    /(?:^|\n)\s*(?:Planner Objectives|Objective Loop State|Objective Step Transcripts)\b[^\n]*(?=\n|$)/gi,
    "",
  );
  cleaned = cleaned.replace(
    /(?:^|\n)\s*(?:PLAN|RETRIEVE|MINI_SYNTH|MINI_CRITIC|UNKNOWN_TERMINAL|ASSEMBLE)\s*:[^\n]*(?=\n|$)/gi,
    "",
  );
  cleaned = cleaned
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\s+\n/g, "\n")
    .trim();
  return cleaned;
};

const shouldSkipCitationRelinkingForStructuredDeterministicAnswer = (args: {
  deterministicAnswerPinnedPreFinalize: boolean;
  answerPath: string[];
  text: string;
}): boolean => {
  if (!args.deterministicAnswerPinnedPreFinalize) return false;
  if (args.answerPath.includes("platonic:deterministic_restore_final")) return true;
  return HELIX_ASK_STRUCTURED_DETERMINISTIC_SECTION_RE.test(args.text);
};

const scrubSkippedLlmTransportErrors = (
  target:
    | {
        llm_invoke_attempted?: boolean;
        llm_error_code?: string | null;
        llm_error_rate_limit_source?: string | null;
        llm_first_rate_limited_source?: string | null;
      }
    | null
    | undefined,
): void => {
  if (!target || target.llm_invoke_attempted === true) return;
  const record = target as Record<string, unknown>;
  const errorCode =
    typeof record.llm_error_code === "string" ? String(record.llm_error_code).trim() : "";
  const errorRateLimitSource =
    typeof record.llm_error_rate_limit_source === "string"
      ? String(record.llm_error_rate_limit_source).trim()
      : "";
  const firstRateLimitSource =
    typeof record.llm_first_rate_limited_source === "string"
      ? String(record.llm_first_rate_limited_source).trim()
      : "";
  const localCooldownOnly =
    /^llm_http_429(?::\d+)?$/i.test(errorCode) &&
    (errorRateLimitSource === "local_cooldown" || firstRateLimitSource === "local_cooldown");
  const circuitOpenOnly = errorCode === "llm_http_circuit_open";
  if (!localCooldownOnly && !circuitOpenOnly) return;
  record.llm_transport_state_suppressed = errorCode || null;
  record.llm_transport_state_suppressed_reason = localCooldownOnly
    ? "no_llm_invocation_local_cooldown"
    : "no_llm_invocation_circuit_open";
  const fieldsToClear = [
    "llm_error_code",
    "llm_error_class",
    "llm_error_status",
    "llm_error_retry_after_ms",
    "llm_error_timeout_ms",
    "llm_error_max_tokens_requested",
    "llm_error_max_tokens_effective",
    "llm_error_prompt_messages_count",
    "llm_error_prompt_chars",
    "llm_error_prompt_tokens_estimate",
    "llm_error_request_body_bytes",
    "llm_error_transient",
    "llm_error_circuit_open",
    "llm_error_circuit_remaining_ms",
    "llm_error_rate_limit_source",
    "llm_error_rate_limit_kind",
    "llm_error_provider_request_id",
    "llm_error_provider_retry_after_raw",
    "llm_error_provider_error_text",
    "llm_error_provider_headers",
    "llm_error_provider_text",
    "llm_first_rate_limited_stage",
    "llm_first_rate_limited_source",
    "llm_first_local_429_stage",
    "llm_first_local_429_remaining_ms",
    "llm_first_provider_429_stage",
    "llm_first_provider_429_kind",
    "llm_first_provider_429_request_id",
    "llm_first_provider_429_prompt_tokens_estimate",
  ];
  for (const key of fieldsToClear) {
    delete record[key];
  }
};

type HelixAskEvidencePacketV2Route = "constraint" | "hybrid" | "repo" | "prompt" | "general";

type HelixAskEvidencePacketV2SectionId =
  | "constraint"
  | "repo"
  | "pipeline"
  | "prompt"
  | "general";

type HelixAskEvidencePacketV2SectionInput = {
  id: HelixAskEvidencePacketV2SectionId;
  label: string;
  content: string;
};

type HelixAskEvidencePacketV2 = {
  version: "repo_atlas_evidence_packet_v2";
  route: HelixAskEvidencePacketV2Route;
  question: string;
  intentId: string;
  intentDomain: HelixAskDomain;
  contextFiles: string[];
  docBlockPaths: string[];
  sections: Array<{
    id: HelixAskEvidencePacketV2SectionId;
    label: string;
    content: string;
  }>;
  evidenceText: string;
  evidenceCardsText: string;
  retrieval: {
    confidence: number;
    docShare: number;
  };
  coverage: {
    slotRatio: number;
    slotMissing: string[];
    docRatio: number;
    docMissing: string[];
  };
  channelContributions?: Record<string, unknown> | null;
  sources: string[];
};

const buildHelixAskEvidencePacketV2 = (args: {
  route: HelixAskEvidencePacketV2Route;
  question: string;
  intentId: string;
  intentDomain: HelixAskDomain;
  contextFiles: string[];
  contextText: string;
  docBlocks: Array<{ path: string; block: string }>;
  retrievalConfidence?: number;
  retrievalDocShare?: number;
  slotCoverage?: { ratio: number; missingSlots: string[] } | null;
  docCoverage?: { ratio: number; missingSlots: string[] } | null;
  channelContributions?: Record<string, unknown> | null;
  sections: HelixAskEvidencePacketV2SectionInput[];
  preferredEvidenceText?: string;
}): HelixAskEvidencePacketV2 => {
  const sections = args.sections
    .map((section) => ({
      id: section.id,
      label: section.label.trim(),
      content: section.content.trim(),
    }))
    .filter((section) => section.label.length > 0 && section.content.length > 0);
  const sectionEvidence = sections.map((section) => section.content).join("\n\n");
  const evidenceText = (args.preferredEvidenceText?.trim() ?? "") || sectionEvidence;
  const evidenceCardsText = sections.map((section) => `${section.label}:\n${section.content}`).join("\n\n");
  const contextFiles = filterExistingEvidencePaths([
    ...args.contextFiles,
    ...extractFilePathsFromText(evidenceText),
    ...extractCitationTokensFromText(evidenceText),
  ]);
  const docBlockPaths = Array.from(
    new Set(
      args.docBlocks
        .map((block) => block.path.replace(/\\/g, "/").trim())
        .filter(Boolean),
    ),
  );
  const sources = resolveEvidencePaths(evidenceText, contextFiles, args.contextText, 8);
  return {
    version: "repo_atlas_evidence_packet_v2",
    route: args.route,
    question: args.question,
    intentId: args.intentId,
    intentDomain: args.intentDomain,
    contextFiles,
    docBlockPaths,
    sections,
    evidenceText,
    evidenceCardsText,
    retrieval: {
      confidence: Number.isFinite(args.retrievalConfidence ?? NaN)
        ? Math.max(0, Math.min(1, Number(args.retrievalConfidence)))
        : 0,
      docShare: Number.isFinite(args.retrievalDocShare ?? NaN)
        ? Math.max(0, Math.min(1, Number(args.retrievalDocShare)))
        : 0,
    },
    coverage: {
      slotRatio: Number.isFinite(args.slotCoverage?.ratio ?? NaN)
        ? Math.max(0, Math.min(1, Number(args.slotCoverage?.ratio)))
        : 0,
      slotMissing: args.slotCoverage?.missingSlots?.slice() ?? [],
      docRatio: Number.isFinite(args.docCoverage?.ratio ?? NaN)
        ? Math.max(0, Math.min(1, Number(args.docCoverage?.ratio)))
        : 0,
      docMissing: args.docCoverage?.missingSlots?.slice() ?? [],
    },
    channelContributions: args.channelContributions ?? null,
    sources,
  };
};

const applyHelixAskEvidencePacketV2 = (
  packet: HelixAskEvidencePacketV2,
  debugPayload?: { evidence_cards?: string } | null,
): string => {
  if (debugPayload) {
    if (packet.evidenceCardsText.trim()) {
      debugPayload.evidence_cards = packet.evidenceCardsText;
    }
    const debugRecord = debugPayload as Record<string, unknown>;
    debugRecord.evidence_packet_v2_used = true;
    debugRecord.evidence_packet_v2 = {
      version: packet.version,
      route: packet.route,
      intent_id: packet.intentId,
      intent_domain: packet.intentDomain,
      section_ids: packet.sections.map((section) => section.id),
      section_count: packet.sections.length,
      evidence_text_chars: packet.evidenceText.length,
      evidence_cards_chars: packet.evidenceCardsText.length,
      context_file_count: packet.contextFiles.length,
      doc_block_count: packet.docBlockPaths.length,
      retrieval_confidence: Number(packet.retrieval.confidence.toFixed(3)),
      retrieval_doc_share: Number(packet.retrieval.docShare.toFixed(3)),
      slot_coverage_ratio: Number(packet.coverage.slotRatio.toFixed(3)),
      slot_missing_count: packet.coverage.slotMissing.length,
      doc_coverage_ratio: Number(packet.coverage.docRatio.toFixed(3)),
      doc_missing_count: packet.coverage.docMissing.length,
      sources: packet.sources.slice(0, 8),
      channel_contributions: packet.channelContributions ?? undefined,
    };
  }
  return packet.evidenceText;
};

type HelixAskCanonicalEvidenceContext = {
  evidenceText: string;
  evidenceWithSources: string;
  contextFiles: string[];
  allowedPaths: string[];
  citationTokens: string[];
};

const resolveHelixAskCanonicalEvidenceContext = (args: {
  packet?: HelixAskEvidencePacketV2 | null;
  evidenceText: string;
  contextFiles: string[];
  contextText?: string;
  extraPaths?: string[];
  extraCitationTokens?: string[];
  sourceLimit?: number;
}): HelixAskCanonicalEvidenceContext => {
  const packet = args.packet ?? null;
  const preferredEvidence = packet?.evidenceText?.trim() ?? "";
  const rawEvidenceText = preferredEvidence || args.evidenceText || "";
  const combinedContextFiles = filterExistingEvidencePaths([
    ...args.contextFiles,
    ...(packet?.contextFiles ?? []),
    ...(packet?.sources ?? []),
    ...(args.extraPaths ?? []),
    ...extractFilePathsFromText(rawEvidenceText),
    ...extractCitationTokensFromText(rawEvidenceText),
  ]);
  const allowedPaths = filterExistingEvidencePaths([
    ...combinedContextFiles,
    ...(args.extraPaths ?? []),
  ]);
  const citationTokens = normalizeCitations([
    ...allowedPaths,
    ...(packet?.sources ?? []),
    ...extractCitationTokensFromText(rawEvidenceText),
    ...(args.extraCitationTokens ?? []),
  ]);
  const evidenceWithSources = appendEvidenceSources(
    rawEvidenceText,
    combinedContextFiles,
    args.sourceLimit ?? 8,
    args.contextText,
  );
  return {
    evidenceText: rawEvidenceText,
    evidenceWithSources,
    contextFiles: combinedContextFiles,
    allowedPaths,
    citationTokens,
  };
};

type HelixAskAnswerExtensionResult = {
  available: boolean;
  text?: string;
  citations: string[];
  itemCount: number;
  docItems: number;
  codeItems: number;
};

type HelixAskAnswerExtensionItem = {
  kind: "doc" | "code";
  path: string;
  summary: string;
  treeJson?: boolean;
};

const shouldApplyStage0CodeFloor = (
  intentDomain: HelixAskDomain,
  question: string,
): boolean =>
  HELIX_ASK_STAGE0_CODE_FLOOR_ENABLED &&
  HELIX_ASK_STAGE0_CODE_FLOOR_DOMAIN_SET.has(intentDomain) &&
  isImplementationQuestion(question);

const STAGE0_CODE_FLOOR_CLARIFY_LINE =
  "I need at least two implementation-code references to ground this answer. Please share a module, file path, or symbol to target.";

const summarizeForExtension = (value: string): string => {
  const cleaned = stripEvidenceBulletPrefix(value)
    .replace(/\s+/g, " ")
    .trim();
  return clipAskText(cleaned, 220);
};

const COVERAGE_RELEVANCE_STOPWORDS = new Set([
  "about",
  "connect",
  "define",
  "does",
  "explain",
  "from",
  "in",
  "into",
  "mean",
  "repo",
  "this",
  "what",
  "where",
  "which",
  "with",
]);

const tokenizeCoverageRelevance = (text: string): string[] =>
  dedupeTokens(tokenizeAskQuery(text))
    .map((token) => token.toLowerCase())
    .filter((token) => token.length >= 4 && !COVERAGE_RELEVANCE_STOPWORDS.has(token));

const scoreCoverageRelevance = (questionTokens: string[], value: string): number => {
  if (!questionTokens.length || !value.trim()) return 0;
  const normalized = value.toLowerCase();
  let overlap = 0;
  for (const token of questionTokens) {
    if (normalized.includes(token)) overlap += 1;
  }
  return overlap / questionTokens.length;
};

const scoreNovelty = (answerLower: string, summary: string): number => {
  if (!summary.trim()) return 1;
  const tokens = dedupeTokens(tokenizeAskQuery(summary)).filter((token) => token.length >= 4);
  if (tokens.length === 0) return 1;
  let overlap = 0;
  for (const token of tokens) {
    if (answerLower.includes(token)) overlap += 1;
  }
  return 1 - overlap / tokens.length;
};

const isImplementationQuestion = (question: string): boolean =>
  /\b(where|implement|implementation|code|codebase|function|module|class|route|endpoint|test|validate|computed|compute|file|files|wiring|runtime|orchestrate|orchestration)\b/i.test(
    question,
  );

const buildAnswerCoverageExtension = (args: {
  answerText: string;
  question?: string;
  docBlocks: Array<{ path: string; block: string }>;
  codeAlignment?: HelixAskCodeAlignment | null;
}): HelixAskAnswerExtensionResult => {
  const answer = args.answerText?.trim() ?? "";
  if (!answer) {
    return {
      available: false,
      citations: [],
      itemCount: 0,
      docItems: 0,
      codeItems: 0,
    };
  }
  const answerLower = answer.toLowerCase();
  const questionTokens = tokenizeCoverageRelevance(args.question ?? "");
  const citedPathKeys = new Set(
    extractFilePathsFromText(answer)
      .map((entry) => normalizePathKey(entry))
      .filter(Boolean),
  );
  const candidates: HelixAskAnswerExtensionItem[] = [];
  const pushCandidate = (item: HelixAskAnswerExtensionItem) => {
    if (!item.path || !item.summary) return;
    candidates.push(item);
  };
  for (let index = 0; index < args.docBlocks.length; index += 1) {
    const block = args.docBlocks[index];
    if (!isDocEvidencePath(block.path)) continue;
    const bullet = buildDocEvidenceBullet(
      block,
      index === 0 ? "Definition" : "Evidence",
    );
    const summary = summarizeForExtension(bullet);
    if (!summary) continue;
    pushCandidate({
      kind: "doc",
      path: block.path,
      summary,
      treeJson: isTreeJsonCitationPath(block.path),
    });
  }
  for (const span of args.codeAlignment?.spans ?? []) {
    if (!(isCodeEvidencePath(span.filePath) || span.isTest || isDocEvidencePath(span.filePath))) {
      continue;
    }
    const summary = summarizeForExtension(buildCodeEvidenceBullet(span));
    if (!summary) continue;
    pushCandidate({
      kind: "code",
      path: span.filePath,
      summary,
      treeJson: isTreeJsonCitationPath(span.filePath),
    });
  }
  if (candidates.length === 0) {
    return {
      available: false,
      citations: [],
      itemCount: 0,
      docItems: 0,
      codeItems: 0,
    };
  }
  const ranked = candidates
    .map((item) => {
      const pathKey = normalizePathKey(item.path);
      const pathNovel = pathKey ? !citedPathKeys.has(pathKey) : true;
      const novelty = scoreNovelty(answerLower, item.summary);
      const relevance = scoreCoverageRelevance(questionTokens, `${item.path}\n${item.summary}`);
      const treePenalty = item.treeJson ? 0.45 : 0;
      const score = (pathNovel ? 1 : 0) + novelty + relevance * 1.25 - treePenalty;
      return { ...item, pathKey, pathNovel, novelty, relevance, score };
    })
    .sort((a, b) => b.score - a.score || Number(b.pathNovel) - Number(a.pathNovel));
  const selected: HelixAskAnswerExtensionItem[] = [];
  const seenPathKeys = new Set<string>();
  let selectedNonTree = 0;
  for (const item of ranked) {
    if (selected.length >= HELIX_ASK_ANSWER_EXTENSION_MAX_ITEMS) break;
    if (item.pathKey && seenPathKeys.has(item.pathKey)) continue;
    if (item.treeJson && selectedNonTree >= 2 && ranked.some((entry) => !entry.treeJson)) {
      continue;
    }
    if (item.pathKey) {
      seenPathKeys.add(item.pathKey);
    }
    if (item.pathNovel || item.novelty >= 0.35 || item.relevance >= 0.34 || selected.length === 0) {
      selected.push({
        kind: item.kind,
        path: item.path,
        summary: item.summary,
        treeJson: item.treeJson,
      });
      if (!item.treeJson) selectedNonTree += 1;
    }
  }
  if (selected.length === 0) {
    return {
      available: false,
      citations: [],
      itemCount: 0,
      docItems: 0,
      codeItems: 0,
    };
  }
  const citations = Array.from(new Set(selected.map((item) => item.path)));
  const extensionLines = ["Additional repo context:"];
  for (const item of selected) {
    extensionLines.push(`- ${ensureSentence(item.summary)} (see ${item.path})`);
  }
  return {
    available: true,
    text: extensionLines.join("\n").trim(),
    citations,
    itemCount: selected.length,
    docItems: selected.filter((item) => item.kind === "doc").length,
    codeItems: selected.filter((item) => item.kind === "code").length,
  };
};

const repairSparseScientificSections = (
  text: string,
  citationPaths: string[],
  fallbackSentences?: string[],
): string => {
  if (!text.trim()) return text;
  const normalized = normalizeScientificSectionLayout(text);
  const citations = citationPaths.filter(Boolean).slice(0, 3);
  const fallback = (fallbackSentences ?? []).filter(Boolean);
  let repaired = normalized;
  if (/(Confirmed:|Unverified:)\s*\n\s*\nReasoned connections \(bounded\):/i.test(repaired)) {
    const confirmedLine =
      fallback[0] ??
      (citations.length
        ? `- Evidence spans were retrieved from ${citations.join(", ")}.`
        : "- Evidence spans were retrieved from the current repo context.");
    repaired = repaired.replace(
      /(Confirmed:|Unverified:)\s*\n\s*\nReasoned connections \(bounded\):/i,
      `$1\n${confirmedLine}\n\nReasoned connections (bounded):`,
    );
  }
  if (/Reasoned connections \(bounded\):\s*\n\s*\nNext evidence:/i.test(repaired)) {
    const boundedLine = fallback.length >= 2
      ? `- ${clipAskText(fallback[0], 220)} ${clipAskText(fallback[1], 220)} Bounded linkage supported by cited evidence.`
      : citations.length >= 2
        ? `- Bounded linkage supported by cited repo evidence (${citations[0]} and ${citations[1]}).`
        : "- Need at least two grounded points before drawing a connection.";
    repaired = repaired.replace(
      /Reasoned connections \(bounded\):\s*\n\s*\nNext evidence:/i,
      `Reasoned connections (bounded):\n${boundedLine}\n\nNext evidence:`,
    );
  }
  return repaired;
};

const extractScientificSectionBody = (text: string, heading: string): string => {
  if (!text.trim()) return "";
  const normalized = normalizeScientificSectionLayout(text);
  const escapedHeading = heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const otherHeadings = SCIENTIFIC_SECTION_HEADINGS
    .filter((entry) => entry !== heading)
    .map((entry) => entry.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
    .join("|");
  const bodyRe = new RegExp(
    `${escapedHeading}\\s*([\\s\\S]*?)(?=\\n{2,}(?:${otherHeadings})|$)`,
    "i",
  );
  const match = normalized.match(bodyRe);
  return (match?.[1] ?? "").trim();
};

const extractScientificPrimaryBody = (text: string): string =>
  extractScientificSectionBody(text, "Confirmed:") ||
  extractScientificSectionBody(text, "Unverified:");

const extractSectionBullets = (body: string): string[] =>
  body
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => /^[-*]\s+/.test(line))
    .map((line) => line.replace(/^[-*]\s+/, "").trim())
    .filter(Boolean);

const isLowSignalScientificBullet = (value: string): boolean => {
  const trimmed = value.trim();
  if (!trimmed) return true;
  if (/^\d+[.)]?$/.test(trimmed)) return true;
  if (/^[a-z]\.?$/i.test(trimmed)) return true;
  const alphaChars = trimmed.replace(/[^a-z]/gi, "").length;
  if (alphaChars < 10) return true;
  return false;
};

const hasWeakScientificSections = (text: string): boolean => {
  if (!isScientificMicroReport(text)) return false;
  const confirmedBody = extractScientificPrimaryBody(text);
  const reasonedBody = extractScientificSectionBody(text, "Reasoned connections (bounded):");
  const confirmedRawBullets = extractSectionBullets(confirmedBody);
  const reasonedRawBullets = extractSectionBullets(reasonedBody);
  const confirmedBullets = confirmedRawBullets.filter(
    (entry) => !isLowSignalScientificBullet(entry),
  );
  const reasonedBullets = reasonedRawBullets.filter(
    (entry) => !isLowSignalScientificBullet(entry),
  );
  if (confirmedBullets.length === 0) return true;
  // If most confirmed bullets are numeric/list noise, treat the section as weak.
  if (confirmedRawBullets.length >= 2 && confirmedBullets.length <= 1) return true;
  if (reasonedBullets.length === 0) return true;
  if (reasonedRawBullets.length >= 2 && reasonedBullets.length <= 1) return true;
  return false;
};

const rewriteConversationScientificVoice = (text: string): string => {
  if (!isScientificMicroReport(text)) return text;
  const confirmedBullets = extractSectionBullets(extractScientificPrimaryBody(text)).filter(
    (entry) => !isLowSignalScientificBullet(entry),
  );
  const reasonedBullets = extractSectionBullets(
    extractScientificSectionBody(text, "Reasoned connections (bounded):"),
  ).filter((entry) => !isLowSignalScientificBullet(entry));
  const nextEvidenceBullets = extractSectionBullets(
    extractScientificSectionBody(text, "Next evidence:"),
  ).filter(
    (entry) => {
      if (/^(Searched terms|Clarify:|Search )/i.test(entry)) return false;
      if (/^Checked files:/i.test(entry)) {
        const payload = entry.replace(/^Checked files:\s*/i, "").trim();
        if (!payload || payload.startsWith(",") || !/[a-z0-9]/i.test(payload) || !/[/.]/.test(payload)) {
          return false;
        }
      }
      if (/Search docs headings for\s+["']?\d+(?:[.)]|["'])/i.test(entry)) return false;
      return !isLowSignalScientificBullet(entry);
    },
  );

  const primaryLine = confirmedBullets[0] ?? reasonedBullets[0] ?? "";
  const reasonedLine = reasonedBullets[0] ?? "";
  const nextStepLine = nextEvidenceBullets[0] ?? "";

  const lines: string[] = [];
  if (primaryLine) {
    lines.push(ensureSentence(primaryLine));
  }
  if (
    reasonedLine &&
    (!primaryLine || !primaryLine.toLowerCase().includes(reasonedLine.toLowerCase()))
  ) {
    lines.push(ensureSentence(`In practical terms, ${reasonedLine}`));
  }
  if (nextStepLine) {
    lines.push(ensureSentence(`Next step: ${nextStepLine}`));
  }
  const sourcesLine = text.match(/^Sources?:.*$/im)?.[0]?.trim();
  if (sourcesLine) lines.push(sourcesLine);
  return lines.length > 0 ? lines.join("\n\n").trim() : text;
};

const rewriteIdeologyScientificVoice = (text: string, question: string): string => {
  if (!isScientificMicroReport(text)) return text;
  const confirmedBullets = extractSectionBullets(extractScientificPrimaryBody(text));
  const reasonedBullets = extractSectionBullets(
    extractScientificSectionBody(text, "Reasoned connections (bounded):"),
  );
  const nextEvidenceBullets = extractSectionBullets(extractScientificSectionBody(text, "Next evidence:"));

  const confirmedLine =
    confirmedBullets.find((entry) => !isLowSignalScientificBullet(entry)) ??
    "Policy choices should be grounded in verified public signals before action.";
  const reasonedLine =
    reasonedBullets.find((entry) => !isLowSignalScientificBullet(entry)) ??
    "When evidence is thin, treat conclusions as provisional and avoid rumor-driven escalation.";

  const lowerQ = question.toLowerCase();
  const referencesTownCouncil = /town council|council|rumor spikes|online rumor/.test(lowerQ);
  const referencesCivicSignalLoop = /civic signal loop/.test(lowerQ);
  const referencesThreeTenets = /three tenets loop/.test(lowerQ);

  const intro =
    /feedback loop hygiene/.test(lowerQ)
      ? "In plain language, Feedback Loop Hygiene means acting on verified civic signals, not momentum or rumor."
      : "In plain language, this is about slowing decisions until public signals are verified.";
  const mechanismParts = [reasonedLine];
  if (referencesTownCouncil) {
    mechanismParts.push(
      "For a town council, that means pausing amplification, checking source quality, publishing what is verified, and then choosing reversible actions first.",
    );
  }
  if (referencesCivicSignalLoop || referencesThreeTenets) {
    const loopLinks: string[] = [];
    if (referencesCivicSignalLoop) {
      loopLinks.push("Civic Signal Loop (measure and publish real civic signal quality)");
    }
    if (referencesThreeTenets) {
      loopLinks.push("Three Tenets Loop (apply integrity, transparency, and reversibility)");
    }
    mechanismParts.push(`It connects to ${loopLinks.join(" and ")} so decisions stay accountable under pressure.`);
  }

  const takeawaySeed =
    nextEvidenceBullets.find((entry) => !/^(Clarify:|Search )/i.test(entry)) ??
    "When evidence is incomplete, communicate uncertainty plainly and verify before policy escalation.";
  const takeaway = ensureSentence(`Takeaway: ${takeawaySeed}`);

  const sourcesLineMatch = text.match(/^Sources?:.*$/im);
  const sourcesLine = sourcesLineMatch?.[0]?.trim() ?? "";
  return [intro, ensureSentence(confirmedLine), mechanismParts.join(" "), takeaway, sourcesLine]
    .filter(Boolean)
    .join("\n\n")
    .trim();
};

const enforceIdeologyNarrativeContracts = (text: string, question: string): string => {
  const input = text.trim();
  if (!input) return text;
  const lowerQ = question.toLowerCase();
  const ideologyNarrative =
    HELIX_ASK_IDEOLOGY_NARRATIVE_QUERY_RE.test(question) ||
    /feedback loop hygiene|mission ethos|ideology|societ(y|al)|town council|rumor/i.test(lowerQ);
  if (!ideologyNarrative) return input;

  let out = input;
  const appendIfMissing = (pattern: RegExp, line: string) => {
    if (pattern.test(out)) return;
    out = `${out}\n\n${line}`.trim();
  };

  const asksSocietalNarrative =
    /societ(y|al)|impact|affect|conversational|plain language|root-to-leaf|narrative|takeaway/i.test(lowerQ);
  if (asksSocietalNarrative) {
    appendIfMissing(
      /\bFeedback Loop Hygiene\b/i,
      "Feedback Loop Hygiene anchor: Feedback Loop Hygiene keeps governance tied to verified civic signals, explicit uncertainty handling, and reversible interventions under stress. [docs/knowledge/ethos/feedback-loop-hygiene.md]",
    );
    appendIfMissing(
      /\bMission Ethos\b/i,
      "Mission Ethos anchor: Mission Ethos keeps policy actions tied to accountable stewardship and evidence-first governance. [docs/ethos/ideology.json]",
    );
    appendIfMissing(
      /\bexample\b/i,
      "For example, local leaders can publish verified signals before policy escalation so the public sees what is known versus unknown. [docs/knowledge/ethos/civic-signal-loop.md]",
    );
    appendIfMissing(
      /\btakeaway\b/i,
      "takeaway: verify civic signals first, communicate uncertainty plainly, and use reversible actions when evidence is still forming. [docs/ethos/ideology.json]",
    );
  }

  const asksTownCouncilFlow =
    /town council|council|online rumor|rumor spikes|civic signal loop|three tenets loop/i.test(lowerQ);
  if (asksTownCouncilFlow) {
    appendIfMissing(
      /\btown council\b/i,
      "For a town council, Feedback Loop Hygiene means pausing rumor amplification, publishing verified updates, and selecting reversible interventions first. [docs/knowledge/ethos/civic-signal-loop.md]",
    );
    appendIfMissing(
      /\bCivic Signal Loop\b/i,
      "Civic Signal Loop connection: gather signal quality, publish verification status, and then act on measured civic evidence. [docs/knowledge/ethos/civic-signal-loop.md]",
    );
    appendIfMissing(
      /\bThree Tenets Loop\b/i,
      "Three Tenets Loop connection: not-knowing, bearing witness, and taking action in public keeps governance adaptive under uncertainty. [docs/ethos/ideology.json]",
    );
  }

  return out.trim();
};

const shouldForceScientificFallback = (
  text: string,
  docBlocks: Array<unknown>,
  codeAlignment?: { spans?: Array<unknown> } | null,
): boolean => {
  if (!isScientificMicroReport(text)) return false;
  const confirmedBody = extractScientificPrimaryBody(text);
  const reasonedBody = extractScientificSectionBody(text, "Reasoned connections (bounded):");
  const confirmedBullets = extractSectionBullets(confirmedBody).filter(
    (entry) => !isLowSignalScientificBullet(entry),
  );
  const reasonedBullets = extractSectionBullets(reasonedBody).filter(
    (entry) => !isLowSignalScientificBullet(entry),
  );
  const evidenceCount =
    (docBlocks?.length ?? 0) + (codeAlignment?.spans?.length ?? 0);
  if (evidenceCount <= 0) return false;
  if (confirmedBullets.length < 2) return true;
  if (reasonedBullets.length < 1) return true;
  return false;
};

const isUnverifiedScaffoldScientificReport = (text: string): boolean => {
  if (!isScientificMicroReport(text)) return false;
  const primaryBullets = extractSectionBullets(extractScientificPrimaryBody(text));
  const reasonedBullets = extractSectionBullets(
    extractScientificSectionBody(text, "Reasoned connections (bounded):"),
  );
  const primaryPlaceholder =
    primaryBullets.length === 0 ||
    primaryBullets.every((entry) =>
      /(No repo-evidenced claims were confirmed yet|No confirmed evidence was found yet)/i.test(
        entry,
      ),
    );
  const reasonedPlaceholder =
    reasonedBullets.length === 0 ||
    reasonedBullets.every((entry) =>
      /Need at least two grounded points before drawing a connection/i.test(entry),
    );
  return primaryPlaceholder && reasonedPlaceholder;
};

type HelixAskTreeWalkMetrics = {
  treeCount: number;
  nodeCount: number;
  nodesWithText: number;
  nodesWithoutText: number;
  stepCount: number;
  treeIds: string[];
  primaryTreeId?: string;
  boundCount?: number;
};

type HelixAskTreeWalkMode = "full" | "root_to_anchor" | "root_to_leaf" | "root_only" | "anchor_only";

const normalizeTreeWalkKey = (value: string): string =>
    value.toLowerCase().replace(/[^a-z0-9]+/g, "").trim();

const TREE_TOKEN_STOPWORDS = new Set([
    "a",
    "an",
    "and",
    "are",
    "as",
    "at",
    "be",
    "by",
    "does",
    "for",
    "from",
    "how",
    "in",
    "into",
    "is",
    "it",
    "mean",
    "of",
    "on",
    "or",
    "repo",
    "the",
    "this",
    "to",
    "what",
    "with",
    "within",
  ]);

const TREE_SHORT_TOKENS = new Set(["ts", "qi", "gr", "ai", "ml", "ui", "ux"]);

const tokenizeTreeText = (value: string): string[] =>
    value
      .toLowerCase()
      .split(/[^a-z0-9]+/g)
      .map((token) => token.trim())
      .filter((token) => {
        if (!token) return false;
        if (TREE_TOKEN_STOPWORDS.has(token)) return false;
        if (token.length >= 3) return true;
        if (token.length === 2) return TREE_SHORT_TOKENS.has(token);
        return false;
      });

const TREE_DOCS_DIR = "docs/knowledge/trees";
type DefinitionTreeDocEntry = { key: string; path: string; tokens: string[] };
let definitionTreeDocCache: DefinitionTreeDocEntry[] | null = null;

const sanitizeTreeDocSlug = (value: string): string =>
  value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .trim();

const collectTreeFiles = (dir: string): string[] => {
  if (!fs.existsSync(dir)) return [];
  const entries: string[] = [];
  const stack = [dir];
  while (stack.length > 0) {
    const current = stack.pop();
    if (!current) continue;
    let children: string[] = [];
    try {
      children = fs.readdirSync(current);
    } catch {
      continue;
    }
    for (const child of children) {
      const full = path.join(current, child);
      let stat: fs.Stats | null = null;
      try {
        stat = fs.statSync(full);
      } catch {
        stat = null;
      }
      if (!stat) continue;
      if (stat.isDirectory()) {
        stack.push(full);
        continue;
      }
      if (child.endsWith("-tree.json")) {
        entries.push(full);
      }
    }
  }
  return entries;
};

const loadDefinitionTreeDocIndex = (): DefinitionTreeDocEntry[] => {
    if (definitionTreeDocCache) return definitionTreeDocCache;
    const index: DefinitionTreeDocEntry[] = [];
    const treeFiles = collectTreeFiles(path.resolve(process.cwd(), "docs/knowledge"));
  for (const treeFile of treeFiles) {
    let raw = "";
    try {
      raw = fs.readFileSync(treeFile, "utf8");
    } catch {
      continue;
    }
    let parsed:
      | {
          rootId?: string;
          nodes?: Array<{
            id?: string;
            title?: string;
            label?: string;
            tags?: string[];
            aliases?: string[];
          }>;
        }
      | null = null;
    try {
      parsed = JSON.parse(raw);
    } catch {
      parsed = null;
    }
    if (!parsed) continue;
    const rootId = typeof parsed.rootId === "string" ? parsed.rootId : path.basename(treeFile, ".json");
    const slug = sanitizeTreeDocSlug(rootId || "");
    if (!slug) continue;
    const docPath = path.join(TREE_DOCS_DIR, `${slug}.md`).replace(/\\/g, "/");
    const fullDocPath = path.resolve(process.cwd(), docPath);
    if (!fs.existsSync(fullDocPath)) continue;
      const nodes = Array.isArray(parsed.nodes) ? parsed.nodes : [];
      for (const node of nodes) {
        const title = node?.title ?? node?.label ?? node?.id ?? "";
        const id = node?.id ?? "";
        const tags = Array.isArray(node?.tags) ? node.tags : [];
        const aliases = Array.isArray(node?.aliases) ? node.aliases : [];
        if (!title && !id && tags.length === 0 && aliases.length === 0) continue;
        const key = normalizeTreeWalkKey(title || id);
        const tokenSet = new Set<string>();
        [title, id, ...tags, ...aliases]
          .filter(Boolean)
          .forEach((value) => {
            tokenizeTreeText(String(value)).forEach((token) => tokenSet.add(token));
          });
        const tokens = Array.from(tokenSet);
        if (!key && tokens.length === 0) continue;
        index.push({ key, path: docPath, tokens });
      }
    }
    definitionTreeDocCache = index;
    return index;
  };

const findDefinitionTreeDocPaths = (question: string, limit = 3): string[] => {
    const normalizedQuestion = normalizeTreeWalkKey(question);
    const questionTokens = new Set(tokenizeTreeText(question));
    if (!normalizedQuestion && questionTokens.size === 0) return [];
    const entries = loadDefinitionTreeDocIndex();
    const scores = new Map<string, number>();
    for (const entry of entries) {
      let score = 0;
      if (entry.key && normalizedQuestion && normalizedQuestion.includes(entry.key)) {
        score += 3;
      }
      if (entry.tokens.length && questionTokens.size) {
        let overlap = 0;
        for (const token of entry.tokens) {
          if (questionTokens.has(token)) overlap += 1;
        }
        if (overlap > 0) score += overlap;
      }
      if (score <= 0) continue;
      const current = scores.get(entry.path) ?? 0;
      if (score > current) scores.set(entry.path, score);
    }
    return Array.from(scores.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, Math.max(1, limit))
      .map(([path]) => path);
  };

const findDefinitionTreeDocPathsForPack = (
    graphPack?: HelixAskGraphPack | null,
    limit = 3,
  ): string[] => {
    if (!graphPack?.frameworks?.length) return [];
    const paths: string[] = [];
    const seen = new Set<string>();
    const resolveDocPath = (candidate: string): string | null => {
      const slug = sanitizeTreeDocSlug(candidate);
      if (!slug) return null;
      const docPath = path.join(TREE_DOCS_DIR, `${slug}.md`).replace(/\\/g, "/");
      const fullDocPath = path.resolve(process.cwd(), docPath);
      return fs.existsSync(fullDocPath) ? docPath : null;
    };
    const pushCandidate = (candidate: string) => {
      if (!candidate) return;
      const docPath = resolveDocPath(candidate);
      if (!docPath || seen.has(docPath)) return;
      seen.add(docPath);
      paths.push(docPath);
    };
    for (const framework of graphPack.frameworks) {
      const treeId = framework.treeId || framework.rootId || "";
      const fallbackId = framework.sourcePath
        ? path.basename(framework.sourcePath, ".json")
        : "";
      const candidates = [treeId, fallbackId].filter(Boolean);
      for (const candidate of candidates) {
        pushCandidate(candidate);
        if (!candidate.endsWith("-tree")) {
          pushCandidate(`${candidate}-tree`);
        } else {
          pushCandidate(candidate.replace(/-tree$/, ""));
        }
        if (paths.length >= limit) break;
      }
      if (paths.length >= limit) break;
    }
    return paths;
  };

const ATOMIC_TREE_ID = "atomic-systems";
const ATOMIC_TREE_PATH = "docs/knowledge/physics/atomic-systems-tree.json";
const ATOMIC_PANEL_ID = "electron-orbital";
const ATOMIC_VIEWER_ID = "atomic-orbital";
const ORBITAL_LETTER_L_MAP: Record<string, number> = {
  s: 0,
  p: 1,
  d: 2,
  f: 3,
  g: 4,
};
type AtomicLaunchDraft = {
  panelId?: string;
  viewer?: string;
  model?: string;
  Z?: number;
  n?: number;
  l?: number;
  m?: number;
  sampleCount?: number;
};

const normalizeLaunchKey = (value: string): string =>
  value.toLowerCase().replace(/[^a-z0-9]/g, "");

const readRecordValue = (
  record: Record<string, unknown>,
  aliases: string[],
): unknown => {
  const aliasSet = new Set(aliases.map(normalizeLaunchKey));
  for (const [key, value] of Object.entries(record)) {
    if (aliasSet.has(normalizeLaunchKey(key))) return value;
  }
  const name = record.name;
  if (typeof name === "string" && aliasSet.has(normalizeLaunchKey(name))) {
    if ("value" in record) return record.value;
    if ("default" in record) return record.default;
  }
  return undefined;
};

const toInteger = (value: unknown): number | undefined => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.trunc(value);
  }
  if (typeof value === "string") {
    const parsed = Number(value.trim());
    if (Number.isFinite(parsed)) return Math.trunc(parsed);
  }
  return undefined;
};

const clampInteger = (value: unknown, min: number, max: number): number | undefined => {
  const integer = toInteger(value);
  if (integer == null) return undefined;
  return Math.max(min, Math.min(max, integer));
};

const parseAtomicModel = (value: unknown): HelixAskAtomicLaunchModel | undefined => {
  if (typeof value !== "string") return undefined;
  const normalized = value.trim().toLowerCase();
  if (normalized === "quantum") return "quantum";
  if (normalized === "classical") return "classical";
  return undefined;
};

const extractAtomicDraftFromNode = (node: HelixAskGraphResolvedNode): AtomicLaunchDraft => {
  const draft: AtomicLaunchDraft = {};
  const records: Array<Record<string, unknown>> = [];
  if (node.environment && typeof node.environment === "object") {
    records.push(node.environment);
  }
  for (const entry of node.inputs ?? []) {
    if (entry && typeof entry === "object") records.push(entry);
  }
  for (const entry of node.outputs ?? []) {
    if (entry && typeof entry === "object") records.push(entry);
  }

  for (const record of records) {
    const panelId = readRecordValue(record, ["panelId", "panel_id", "panel", "targetPanelId"]);
    if (typeof panelId === "string" && !draft.panelId) {
      draft.panelId = panelId.trim();
    }
    const viewer = readRecordValue(record, ["viewer", "viewerId", "viewer_id"]);
    if (typeof viewer === "string" && !draft.viewer) {
      draft.viewer = viewer.trim();
    }
    const model = parseAtomicModel(
      readRecordValue(record, ["model", "atomModel", "atom_model", "mode"]),
    );
    if (model && !draft.model) {
      draft.model = model;
    }
    const nuclearCharge = toInteger(
      readRecordValue(record, ["Z", "z", "nuclearCharge", "nuclear_charge"]),
    );
    if (nuclearCharge != null && draft.Z == null) {
      draft.Z = nuclearCharge;
    }
    const principalN = toInteger(
      readRecordValue(record, ["n", "principal", "principalN", "principal_n"]),
    );
    if (principalN != null && draft.n == null) {
      draft.n = principalN;
    }
    const azimuthalL = toInteger(
      readRecordValue(record, ["l", "azimuthal", "orbitalL", "orbital_l", "angular"]),
    );
    if (azimuthalL != null && draft.l == null) {
      draft.l = azimuthalL;
    }
    const magneticM = toInteger(
      readRecordValue(record, ["m", "magnetic", "magneticM", "magnetic_m"]),
    );
    if (magneticM != null && draft.m == null) {
      draft.m = magneticM;
    }
    const sampleCount = toInteger(
      readRecordValue(record, ["sampleCount", "sample_count", "samples", "points"]),
    );
    if (sampleCount != null && draft.sampleCount == null) {
      draft.sampleCount = sampleCount;
    }
  }

  return draft;
};

const parseAtomicQuestionOverrides = (question: string): AtomicLaunchDraft => {
  const draft: AtomicLaunchDraft = {};
  const normalized = question.toLowerCase();

  const classicalMatch = /\b(classical|bohr|trajectory)\b/i.exec(question);
  const quantumMatch = /\b(quantum|wavefunction|orbital cloud)\b/i.exec(question);
  if (classicalMatch && (!quantumMatch || classicalMatch.index > quantumMatch.index)) {
    draft.model = "classical";
  } else if (quantumMatch) {
    draft.model = "quantum";
  }

  const zMatch = /\b(?:z|nuclear charge)\s*(?:=|:|is)?\s*(\d{1,3})\b/i.exec(question);
  if (zMatch) {
    draft.Z = Number(zMatch[1]);
  } else {
    for (const entry of ELEMENT_Z_LOOKUP) {
      if (new RegExp(`\\b${entry.name}\\b`, "i").test(normalized)) {
        draft.Z = entry.Z;
        break;
      }
    }
  }

  const nMatch = /\bn\s*(?:=|:|is)?\s*(\d{1,2})\b/i.exec(question);
  if (nMatch) {
    draft.n = Number(nMatch[1]);
  }
  const lMatch = /\bl\s*(?:=|:|is)?\s*(-?\d{1,2})\b/i.exec(question);
  if (lMatch) {
    draft.l = Number(lMatch[1]);
  }
  const mMatch = /\bm\s*(?:=|:|is)?\s*(-?\d{1,2})\b/i.exec(question);
  if (mMatch) {
    draft.m = Number(mMatch[1]);
  }

  const orbitalNotationMatch = /\b(\d{1,2})\s*([spdfg])\b/i.exec(question);
  if (orbitalNotationMatch) {
    draft.n = Number(orbitalNotationMatch[1]);
    const mappedL = ORBITAL_LETTER_L_MAP[orbitalNotationMatch[2].toLowerCase()];
    if (mappedL != null) {
      draft.l = mappedL;
      if (draft.m == null) draft.m = 0;
    }
  }

  const sampleMatch = /\b(?:sample(?:s| count)?|points?)\s*(?:=|:|is)?\s*(\d{2,5})\b/i.exec(
    question,
  );
  if (sampleMatch) {
    draft.sampleCount = Number(sampleMatch[1]);
  }

  return draft;
};

const buildAtomicStressEnergyProxy = (params: {
  model: HelixAskAtomicLaunchModel;
  Z: number;
  n: number;
  l: number;
  m: number;
}): HelixAskAtomicStressEnergyProxy => {
  const baseScale = 9.0e10;
  const orbitalWeight = (params.n + params.l + Math.abs(params.m) + 1) / params.n;
  const modelWeight = params.model === "quantum" ? 1 : 0.82;
  const value_J_m3 = Number((baseScale * params.Z * orbitalWeight * modelWeight).toPrecision(12));
  const relative_1sigma = 0.12;
  const absolute_1sigma_J_m3 = Number((value_J_m3 * relative_1sigma).toPrecision(12));
  return {
    schema_version: "atomic_stress_energy_proxy/1",
    value_J_m3,
    units: {
      value: "J/m^3",
      uncertainty: "relative_1sigma",
    },
    uncertainty: {
      relative_1sigma,
      absolute_1sigma_J_m3,
      confidence: 0.95,
    },
    equation: {
      id: "atomic_stress_energy_proxy_eq.v1",
      expression: "u_proxy = 9.0e10 * Z * ((n + l + |m| + 1) / n) * model_weight",
    },
    citations: [
      "docs/knowledge/physics/atomic-systems-tree.json#atomic-stress-energy-bridge-placeholder",
      "tests/fixtures/graph-congruence-conditions-tree.json#atomic-stress-energy-bridge-placeholder",
    ],
    claim_tier: "diagnostic",
    provenance_class: "proxy",
    certifying: false,
  };
};

const normalizeAtomicLaunchParams = (draft: AtomicLaunchDraft): HelixAskAtomicLaunchParams => {
  const model = parseAtomicModel(draft.model) ?? "quantum";
  let n = clampInteger(draft.n, 1, 7) ?? 1;
  let l = clampInteger(draft.l, 0, 9) ?? 0;
  if (l > n - 1) {
    n = Math.min(7, l + 1);
  }
  l = Math.min(l, n - 1);
  let m = clampInteger(draft.m, -9, 9) ?? 0;
  if (m < -l) m = -l;
  if (m > l) m = l;
  const sampleCount = clampInteger(draft.sampleCount, 96, 4000);
  const claim_tier: HelixAskAtomicClaimTier = "diagnostic";
  const provenance_class: HelixAskAtomicProvenanceClass = model === "quantum" ? "simulation" : "proxy";
  const normalizedCore = {
    model,
    Z: clampInteger(draft.Z, 1, 118) ?? 1,
    n,
    l,
    m,
  };
  return {
    ...normalizedCore,
    ...(sampleCount != null ? { sampleCount } : {}),
    stress_energy_proxy: buildAtomicStressEnergyProxy(normalizedCore),
    claim_tier,
    provenance_class,
    certifying: false,
  };
};

const resolveAtomicViewerLaunch = (
  graphPack: HelixAskGraphPack | null,
  question: string,
): HelixAskViewerLaunch | null => {
  if (!graphPack?.frameworks?.length) return null;
  const atomicFrameworks = graphPack.frameworks.filter((framework) => {
    if (framework.treeId === ATOMIC_TREE_ID) return true;
    return framework.sourcePath.replace(/\\/g, "/").endsWith(ATOMIC_TREE_PATH);
  });
  if (atomicFrameworks.length === 0) return null;

  const draft: AtomicLaunchDraft = {};
  const nodes = atomicFrameworks
    .flatMap((framework) => [...(framework.path ?? []), ...(framework.anchors ?? [])])
    .slice()
    .sort((a, b) => b.score - a.score);

  for (const node of nodes) {
    const nodeDraft = extractAtomicDraftFromNode(node);
    if (!draft.panelId && nodeDraft.panelId) draft.panelId = nodeDraft.panelId;
    if (!draft.viewer && nodeDraft.viewer) draft.viewer = nodeDraft.viewer;
    if (!draft.model && nodeDraft.model) draft.model = nodeDraft.model;
    if (draft.Z == null && nodeDraft.Z != null) draft.Z = nodeDraft.Z;
    if (draft.n == null && nodeDraft.n != null) draft.n = nodeDraft.n;
    if (draft.l == null && nodeDraft.l != null) draft.l = nodeDraft.l;
    if (draft.m == null && nodeDraft.m != null) draft.m = nodeDraft.m;
    if (draft.sampleCount == null && nodeDraft.sampleCount != null) {
      draft.sampleCount = nodeDraft.sampleCount;
    }
  }

  const questionOverrides = parseAtomicQuestionOverrides(question);
  const merged: AtomicLaunchDraft = {
    ...draft,
    ...questionOverrides,
  };
  const params = normalizeAtomicLaunchParams(merged);
  const sourcePath = atomicFrameworks[0]?.sourcePath;

  return {
    viewer: ATOMIC_VIEWER_ID,
    panel_id: ATOMIC_PANEL_ID,
    tree_id: atomicFrameworks[0]?.treeId || ATOMIC_TREE_ID,
    ...(sourcePath ? { source_path: sourcePath } : {}),
    claim_tier: params.claim_tier,
    provenance_class: params.provenance_class,
    policy: {
      allowedCL: "CL4",
      allowConceptual: false,
      allowProxies: false,
      chart: "comoving_cartesian",
    },
    params,
  };
};

const resolveHelixAskTreeWalkMode = (
  raw: string,
  verbosity: HelixAskVerbosity,
): HelixAskTreeWalkMode => {
  const normalized = raw.trim().toLowerCase().replace(/-/g, "_");
  if (normalized === "auto") {
    return verbosity === "brief" ? "root_to_anchor" : "full";
  }
  if (normalized === "root" || normalized === "root_only") return "root_only";
  if (normalized === "anchor" || normalized === "anchor_only") return "anchor_only";
  if (normalized === "root_to_anchor" || normalized === "root2anchor") return "root_to_anchor";
  if (normalized === "root_to_leaf" || normalized === "root2leaf") return "root_to_leaf";
  return "full";
};

const buildTreeWalkBindingSet = (
  pack: HelixAskGraphPack | null,
  docBlocks: Array<{ path: string; block: string }>,
): Set<string> => {
  const bound = new Set<string>();
  if (!pack?.frameworks?.length || docBlocks.length === 0) return bound;
  const docText = docBlocks.map((block) => block.block.toLowerCase()).join("\n");
  const headerTerms = new Set<string>();
  const pathTerms = new Set<string>();
  for (const block of docBlocks) {
    const header = extractDocBlockHeader(block);
    if (header) headerTerms.add(normalizeTreeWalkKey(header));
    const fileStem = path.basename(block.path, path.extname(block.path));
    if (fileStem) pathTerms.add(normalizeTreeWalkKey(fileStem));
  }
  for (const framework of pack.frameworks) {
    for (const node of framework.path ?? []) {
      const title = node.title ?? "";
      const id = node.id ?? "";
      const titleKey = normalizeTreeWalkKey(title);
      const idKey = normalizeTreeWalkKey(id);
      const titleHit =
        (title && docText.includes(title.toLowerCase())) ||
        (titleKey && (headerTerms.has(titleKey) || pathTerms.has(titleKey)));
      const idHit =
        (id && docText.includes(id.toLowerCase())) ||
        (idKey && (headerTerms.has(idKey) || pathTerms.has(idKey)));
      if (titleHit || idHit) {
        if (id) bound.add(id);
        if (titleKey) bound.add(titleKey);
        if (idKey) bound.add(idKey);
      }
    }
  }
  return bound;
};

function buildHelixAskTreeWalk(
  pack: HelixAskGraphPack | null,
  options: { mode: HelixAskTreeWalkMode; maxSteps: number; boundNodes?: Set<string> },
): { text: string; metrics: HelixAskTreeWalkMetrics | null } {
  if (!pack?.frameworks?.length) {
    return { text: "", metrics: null };
  }
  const lines: string[] = [];
  let nodeCount = 0;
  let nodesWithText = 0;
  let nodesWithoutText = 0;
  let boundCount = 0;
  const stepCap = options.maxSteps > 0 ? options.maxSteps : null;
  for (const framework of pack.frameworks) {
    const label = framework.treeLabel ?? framework.treeId;
    const header = `Tree Walk: ${label} (tree-derived; source: ${framework.sourcePath})`;
    lines.push(header);
    const pathModeLabel = framework.pathMode ?? "full";
    const fallback = framework.pathFallbackReason
      ? ` | continuity: fallback ${framework.pathFallbackReason}`
      : "";
    lines.push(`Chain scaffold: ${pathModeLabel}${fallback}`);
    const anchorIds = new Set(framework.anchors.map((node) => node.id));
    const path = framework.path ?? [];
    if (!path.length) {
      lines.push("1. Walk: (no nodes resolved) - no tree path available.");
      lines.push("");
      continue;
    }
    const rootIndexFromId = framework.rootId
      ? path.findIndex((node) => node.id === framework.rootId)
      : -1;
    const minDepth = path.reduce(
      (min, node) => Math.min(min, node.depth ?? 0),
      Number.POSITIVE_INFINITY,
    );
    const rootIndexFromDepth = path.findIndex((node) => (node.depth ?? 0) === minDepth);
    const rootIndex =
      rootIndexFromId >= 0
        ? rootIndexFromId
        : rootIndexFromDepth >= 0
          ? rootIndexFromDepth
          : 0;
    const anchorIndex = path.findIndex(
      (node, idx) => idx >= rootIndex && anchorIds.has(node.id),
    );
    let selected = path.slice();
    switch (options.mode) {
      case "anchor_only":
        selected = path.filter((node) => anchorIds.has(node.id));
        break;
      case "root_only":
        selected = [path[rootIndex] ?? path[0]];
        break;
      case "root_to_anchor":
        if (anchorIndex >= 0) {
          selected = path.slice(rootIndex, anchorIndex + 1);
        }
        break;
      case "root_to_leaf":
        selected = path.slice(rootIndex);
        break;
      case "full":
      default:
        selected = path.slice();
        break;
    }
    if (selected.length === 0) {
      selected = path.slice();
    }
    if (stepCap && selected.length > stepCap) {
      selected = selected.slice(0, stepCap);
    }
    selected.forEach((node, idx) => {
      nodeCount += 1;
      const title = node.title ?? node.id;
      const normalizedTitle = normalizeTreeWalkKey(title);
      const bound =
        !options.boundNodes ||
        options.boundNodes.has(node.id) ||
        options.boundNodes.has(normalizedTitle);
      if (bound) boundCount += 1;
      const roleLabel = node.role
        ? `Role:${node.role}`
        : anchorIds.has(node.id)
          ? "Anchor"
          : "Walk";
      const role = bound ? roleLabel : "Hint";
      const idSuffix =
        node.id && normalizeTreeWalkKey(title) !== normalizeTreeWalkKey(node.id)
          ? ` (${node.id})`
          : "";
      let detail = node.excerpt?.trim() ?? "";
      if (!detail && node.artifact) {
        detail = `Minimal artifact: ${node.artifact.trim()}`;
      }
      if (detail) {
        nodesWithText += 1;
        detail = ensureSentence(clipAskText(detail, 200));
      } else {
        nodesWithoutText += 1;
        detail = "No detail provided in the tree node.";
      }
      if (!bound) {
        detail = "Navigation hint only; no doc span bound.";
      }
      lines.push(
        `${idx + 1}. ${role}: ${title}${idSuffix} - ${detail} (${framework.sourcePath})`,
      );
    });
    lines.push("");
  }
  const trimmed = lines.join("\n").trim();
  const metrics: HelixAskTreeWalkMetrics = {
    treeCount: pack.frameworks.length,
    nodeCount,
    nodesWithText,
    nodesWithoutText,
    stepCount: nodeCount,
    treeIds: pack.treeIds,
    primaryTreeId: pack.primaryTreeId,
    boundCount,
  };
  return { text: trimmed, metrics };
}

function ensureTreeWalkInAnswer(
  answerText: string,
  treeWalkBlock: string,
): { text: string; injected: boolean } {
  const trimmedWalk = treeWalkBlock.trim();
  if (!trimmedWalk) return { text: answerText, injected: false };
  const current = answerText ?? "";
  const hasTreeWalk =
    /(^|\n)\s*Tree Walk:/i.test(current) ||
    current.includes(trimmedWalk.split(/\r?\n/)[0] ?? "");
  if (hasTreeWalk) return { text: current, injected: false };
  const base = current.trim();
  if (!base) return { text: trimmedWalk, injected: true };
  return { text: `${base}\n\n${trimmedWalk}`, injected: true };
}

function appendContextBlock(contextText: string, block: string): string {
  const trimmedBlock = block?.trim() ?? "";
  if (!trimmedBlock) return contextText;
  const trimmedContext = contextText?.trim() ?? "";
  if (!trimmedContext) return trimmedBlock;
  if (trimmedContext.includes(trimmedBlock)) return contextText;
  return `${trimmedContext}\n\n${trimmedBlock}`;
}

function mergeEvidenceScaffolds(base: string, extra: string): string {
  const baseTrimmed = base?.trim() ?? "";
  const extraTrimmed = extra?.trim() ?? "";
  if (!extraTrimmed) return baseTrimmed;
  if (!baseTrimmed) return extraTrimmed;
  const baseLines = baseTrimmed.split(/\r?\n/);
  const existing = new Set(baseLines.map((line) => line.trim().toLowerCase()).filter(Boolean));
  const extraLines = extraTrimmed
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0 && !existing.has(line.toLowerCase()));
  if (extraLines.length === 0) return baseTrimmed;
  return `${baseTrimmed}\n${extraLines.join("\n")}`;
}

function buildHelixAskScaffoldPrompt(
  question: string,
  context: string,
  format: HelixAskFormat,
  stageTags: boolean,
): string {
  const lines = [
    "You are Helix Ask evidence distiller.",
    "Use only the evidence in the context below. Do not speculate.",
  ];
  if (format === "steps") {
    lines.push("Return a numbered list (6-9 items) of the concrete steps the system actually performs.");
    if (stageTags) {
      lines.push(
        "Tag each step with the stage in parentheses (observe, hypothesis, experiment, analysis, explain).",
      );
    } else {
      lines.push("Do not include stage tags or parenthetical labels unless explicitly requested.");
    }
    lines.push("Each step must cite at least one file path from the context in parentheses.");
  } else {
    lines.push("Return 6-9 short evidence bullets (not steps) grounded in the context.");
    lines.push("Each bullet must cite at least one file path from the context in parentheses.");
    lines.push("Do not include stage tags or parenthetical labels unless explicitly requested.");
  }
  lines.push('No preamble, no question restatement, no "FINAL:", no headings.');
  lines.push("");
  lines.push(`Question: ${question}`);
  lines.push("");
  lines.push("Context:");
  lines.push(context || "No repo context was attached to this request.");
  lines.push("");
  return lines.join("\n");
}

function buildHelixAskEvidencePrompt(
  question: string,
  context: string,
  format: HelixAskFormat,
  stageTags: boolean,
  composite = false,
  anchorHints: string[] = [],
): string {
  const definitionFocus = isDefinitionQuestion(question);
  const lines = [
    "You are Helix Ask evidence distiller.",
    "Use only the evidence in the context below. Do not speculate.",
  ];
  if (anchorHints.length) {
    lines.push("Prefer evidence from these verification anchors when present in context:");
    lines.push(...anchorHints.map((entry) => `- ${entry}`));
    lines.push("At least one bullet must cite a verification anchor if available.");
    lines.push("Avoid UI-only files unless the question explicitly asks about UI.");
  }
  if (format === "steps") {
    lines.push("Return a numbered list (6-9 items) of evidence steps the system actually performs.");
    if (stageTags) {
      lines.push(
        "Tag each step with the stage in parentheses (observe, hypothesis, experiment, analysis, explain).",
      );
    } else {
      lines.push("Do not include stage tags or parenthetical labels unless explicitly requested.");
    }
    lines.push("Each step should be 1-2 sentences and cite at least one file path or prompt chunk id from the context.");
  } else {
    const count = composite ? "4-6" : definitionFocus ? "8-12" : "6-9";
    lines.push(`Return ${count} short evidence bullets grounded in the context.`);
    lines.push("Each bullet should be 1-2 sentences and cite at least one file path or prompt chunk id from the context.");
    lines.push("Do not include stage tags or parenthetical labels unless explicitly requested.");
    if (composite) {
      lines.push("Prefer evidence from domain docs (ethos/knowledge) and core GR viability files over UI or prompt infrastructure.");
      lines.push("Do not mention 'anchors' or list files without tying them to the question.");
    }
    if (definitionFocus) {
      lines.push("Include at least one bullet that directly defines the term using a docs/*.md source (not *-tree.json).");
      lines.push("If a context block includes Section/Span lines, preserve them verbatim in that definition bullet.");
      lines.push("Treat graph/tree JSON as derivation hints only; bind them to .md docs before citing.");
    }
  }
  lines.push('No preamble, no question restatement, no "FINAL:", no headings.');
  lines.push("");
  lines.push(`Question: ${question}`);
  lines.push("");
  lines.push("Context:");
  lines.push(context || "No repo context was attached to this request.");
  lines.push("");
  return lines.join("\n");
}

