const HELIX_ASK_CITATION_REPAIR_SCHEMA = z
  .object({
    text: z.string().min(1),
    sources: z.array(z.string()).optional(),
    citations: z.array(z.string()).optional(),
  })
  .strict();

type HelixAskCitationRepairPayload = z.infer<typeof HELIX_ASK_CITATION_REPAIR_SCHEMA>;

const HELIX_ASK_ANSWER_CONTRACT_CLAIM_SCHEMA = z
  .object({
    text: z.string().min(1),
    evidence: z.array(z.string().min(1)).max(8).optional(),
  })
  .strict();

const HELIX_ASK_ANSWER_CONTRACT_COMPARE_SCHEMA = z
  .object({
    label: z.string().min(1),
    detail: z.string().min(1),
    evidence: z.array(z.string().min(1)).max(8).optional(),
  })
  .strict();

const HELIX_ASK_ANSWER_CONTRACT_SCHEMA = z
  .object({
    summary: z.string().min(1),
    claims: z.array(HELIX_ASK_ANSWER_CONTRACT_CLAIM_SCHEMA).max(8).optional(),
    steps: z.array(z.string().min(1)).max(8).optional(),
    comparisons: z.array(HELIX_ASK_ANSWER_CONTRACT_COMPARE_SCHEMA).max(8).optional(),
    uncertainty: z.string().min(1).optional(),
    tone: z.enum(["plain", "neutral", "technical"]).optional(),
    sources: z.array(z.string().min(1)).max(16).optional(),
  })
  .strict();

type HelixAskAnswerContract = z.infer<typeof HELIX_ASK_ANSWER_CONTRACT_SCHEMA>;

const normalizeContractText = (value: string, maxChars = 280): string =>
  value.replace(/\s+/g, " ").trim().slice(0, maxChars).trim();

const sanitizeDeterministicContractLine = (value: string): string => {
  const source = stripEvidenceBulletPrefix(value).replace(/\s+/g, " ").trim();
  if (!source) return "";
  const definitionMatch = source.match(/\bDefinition:\s*([\s\S]+)/i);
  let candidate = definitionMatch ? definitionMatch[1] : source;
  candidate = candidate
    .replace(HELIX_ASK_LABEL_PREFIX_RE, "")
    .replace(/\(see\s+[^\)]*\)/gi, " ")
    .replace(/\b(?:Doc|Title|Heading|Subheading|Section):\s*[^.]+(?:\.)?/gi, " ")
    .replace(/\bSpan:\s*L\d+(?:-L?\d+)?\b/gi, " ")
    .replace(
      /\b(?:id|slug|label|aliases|scope|intenthints|topictags|mustincludefiles|version|rootid|nodes|children)\s*:\s*[^,;]+/gi,
      " ",
    )
    .replace(/notes?\s*:\s*[^.]+(?:\.)?/gi, " ")
    .replace(/tags?\s*:\s*[^.]+(?:\.)?/gi, " ")
    .replace(/(^|\s)---(\s|$)/g, " ")
    .replace(/\{[^{}]*\}/g, " ")
    .replace(/[{}]/g, " ")
    .replace(/[|]{2,}/g, " ")
    .replace(/\s\|\s/g, " ")
    .replace(/`{1,3}[^`]+`{1,3}/g, " ")
    .replace(/\/\*[\s\S]*?\*\//g, " ")
    .replace(/^(?:Definition|Evidence|Code|Test)\s*:\s*/i, "")
    .replace(/\bminimal\s+artifact\s*:\s*[^.]+\.?/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!candidate) return "";
  return ensureSentence(normalizeContractText(candidate, 280));
};

const DETERMINISTIC_METADATA_LINE_RE =
  /\b(?:title|heading|subheading|id|slug|label|aliases|scope|intenthints|topictags|mustincludefiles|version|rootid|nodes|children)\b/i;
const DETERMINISTIC_CODE_LINE_RE =
  /\b(?:import\s+|export\s+(?:function|const|class)|const\s+\[|const\s+[a-z_]\w*\s*=\s*(?:\(|async\b|{)|let\s+[a-z_]\w*\s*=|function\s+[a-z_]\w*\s*\(|=>|useState|from\s+["']react["'])\b/i;
const DETERMINISTIC_FACTUAL_VERB_RE =
  /\b(?:is|are|means|describes?|defines?|refers?|implements?|models?)\b/i;
const DETERMINISTIC_MATH_SIGNAL_RE =
  /[=+*/^]|\\(?:frac|partial|nabla)|\b(?:psi|rho|kappa|tau|beta|gamma|theta|omega|delta|hbar)\b/i;
const DETERMINISTIC_SECTION_HEADER_RE =
  /\b(?:goals?\s*&\s*invariants?|components?|objective|non-goals?|inputs?|outputs?|overview|checklist|roadmap|pipeline|architecture|runtime)\b/i;
const DETERMINISTIC_EVENT_LOG_LINE_RE = /^\s*\[\d{1,2}:\d{2}:\d{2}(?:\.\d+)?\]\s+tool=/i;
const DETERMINISTIC_UI_SECTION_LINE_RE =
  /^(?:details|tree walk|proof|key files|context sources|convergence snapshot|capsule guards|reasoning event log)\s*:?\s*$/i;
const RELATION_MODEL_PLACEHOLDER_RE =
  /^(?:(?:\w+\.)?llm\.local(?:\s+stub result)?|placeholder|unable to answer|i cannot answer|model error)\b/i;
const RELATION_CODE_NOISE_RE =
  /\b(?:import\s+|export\s+(?:function|const|class)|const\s+\[|const\s+[a-z_]\w*\s*=\s*(?:\(|async\b|{)|let\s+[a-z_]\w*\s*=|function\s+[a-z_]\w*\s*\(|=>|usestate|from\s+["']react["'])\b/i;
const STUB_TEXT_RE = /\bllm\.local\s+stub\s+result\b/i;
const GENERIC_GROUNDED_RE = /^answer grounded in retrieved evidence\.?$/i;
const HELIX_ASK_MECHANISM_SENTENCE_RE = /\bMechanism:\s*.+->.+->.+/i;
const HELIX_ASK_MATURITY_LABEL_RE = /\bMaturity\s*\((?:exploratory|reduced-order|diagnostic|certified)\)\s*:/i;
const HELIX_ASK_MISSING_EVIDENCE_RE = /\bMissing evidence:\s*[^\n]{12,}/i;
const HELIX_ASK_ADAPTIVE_RESCUE_REASONS = new Set<string>([
  "placeholder",
  "stub_text",
  "generic_grounding_scaffold",
  "metadata_noise",
  "code_noise",
  "path_index_body",
  "artifact_json_spill",
  "citation_missing",
  "text_too_short",
  "semantic_density_low",
  "open_world_claim_floor",
  "open_world_mechanism_missing",
  "security_actionable_missing",
  "citation_only_body",
  "generic_fallback_citation_only",
  "requested_path_citation_missing",
]);

const HELIX_ASK_ARTIFACT_JSON_SPILL_RE =
  /"(?:bodyMD|title|summary|claims|steps|comparisons)"\s*:|\bwhat_is_[a-z0-9_]+\s*:|\bhow_they_connect\s*:|\bconstraints?_and_falsifiability\s*:/i;

const hasArtifactJsonSpill = (value: string): boolean => {
  const normalized = value.replace(/\s+/g, " ").trim();
  if (!normalized) return false;
  if (HELIX_ASK_ARTIFACT_JSON_SPILL_RE.test(normalized)) return true;
  if (/this tree maps the client ui surfaces/i.test(normalized)) return true;
  if (/minimal artifact:/i.test(normalized)) return true;
  return false;
};

const hasModelPlaceholderOrStub = (value: string): boolean => {
  const normalized = value.trim();
  if (!normalized) return false;
  return (
    RELATION_MODEL_PLACEHOLDER_RE.test(normalized) ||
    STUB_TEXT_RE.test(normalized) ||
    GENERIC_GROUNDED_RE.test(normalized)
  );
};

const isDeterministicHeadingScaffoldNoise = (value: string): boolean => {
  const normalized = value.replace(/\s+/g, " ").trim();
  if (!normalized) return true;
  if (DETERMINISTIC_EVENT_LOG_LINE_RE.test(normalized)) return true;
  if (DETERMINISTIC_UI_SECTION_LINE_RE.test(normalized)) return true;
  const headingHits = normalized.match(
    /\b(?:goals?|invariants?|components?|objective|non-goals?|inputs?|outputs?|overview|checklist|roadmap|pipeline|tools?|architecture|runtime)\b/gi,
  );
  const digitHits = normalized.match(/\b\d+\b/g);
  const lowSignal =
    !DETERMINISTIC_FACTUAL_VERB_RE.test(normalized) &&
    !DETERMINISTIC_MATH_SIGNAL_RE.test(normalized);
  if (lowSignal && (headingHits?.length ?? 0) >= 3 && (digitHits?.length ?? 0) >= 2) {
    return true;
  }
  if (
    lowSignal &&
    /\b(?:components?|goals?\s*&\s*invariants?|objective|inputs?|outputs?)\b(?:\s+\d+\s+[A-Za-z][A-Za-z0-9_-]{2,}){1,}/i.test(
      normalized,
    )
  ) {
    return true;
  }
  if (lowSignal && DETERMINISTIC_SECTION_HEADER_RE.test(normalized) && !/[.!?]$/.test(normalized)) {
    return true;
  }
  return false;
};

const HELIX_ASK_LABELED_PATH_INDEX_ENTRY_RE =
  /(?:^|[\n;]\s*|\s)(?:[A-Za-z][A-Za-z0-9 _-]{2,84})\s*:\s*(?:[A-Za-z0-9_.-]+[\\/])+[A-Za-z0-9_.-]+\.(?:md|json|ts|tsx|js|jsx|py|yml|yaml)\b/gi;

const isPathIndexStyleAnswer = (value: string): boolean => {
  const text = value.trim();
  if (!text) return false;
  const pathMatches = extractFilePathsFromText(text);
  if (pathMatches.length < 2) return false;
  const labeledEntries = text.match(HELIX_ASK_LABELED_PATH_INDEX_ENTRY_RE) ?? [];
  const proseSentences = splitGroundedSentences(text).filter((sentence) => {
    if (!sentence.trim()) return false;
    if (extractFilePathsFromText(sentence).length > 0) return false;
    return /[A-Za-z]{3,}/.test(sentence);
  });
  const claimCount = extractClaimCandidates(text, 6).length;
  const textWithoutIndexLabels = text.replace(HELIX_ASK_LABELED_PATH_INDEX_ENTRY_RE, " ");
  const hasMechanismSignal =
    /\b(is|are|means|refers?|because|therefore|comes from|derived from|involves|related to|difference|through)\b/i.test(
      textWithoutIndexLabels,
    );
  if (labeledEntries.length >= 2 && proseSentences.length === 0) {
    return true;
  }
  if (pathMatches.length >= 3 && proseSentences.length <= 1 && claimCount <= 1 && !hasMechanismSignal) {
    return true;
  }
  return false;
};

const detectRelationDeterministicFallbackReasons = (value: string): string[] => {
  const reasons = new Set<string>();
  const normalized = value.replace(/\s+/g, " ").trim();
  if (!normalized) {
    reasons.add("empty");
    return Array.from(reasons);
  }
  if (RELATION_MODEL_PLACEHOLDER_RE.test(normalized)) {
    reasons.add("placeholder");
  }
  if (normalized.length < 160) {
    reasons.add("too_short");
  }
  const hasWarpSignal =
    /\b(warp|bubble|alcubierre|natario|spacetime|shift vector|expansion)\b/i.test(normalized);
  const hasEthosSignal =
    /\b(mission ethos|ethos|ideology|stewardship|compassion|governance)\b/i.test(normalized);
  if (!hasWarpSignal || !hasEthosSignal) {
    reasons.add("missing_dual_domain_terms");
  }
  if (hasArtifactJsonSpill(value)) {
    reasons.add("artifact_json_spill");
  }
  if (isDeterministicMetadataNoise(normalized)) {
    reasons.add("metadata_noise");
  }
  if (RELATION_CODE_NOISE_RE.test(normalized)) {
    reasons.add("code_noise");
  }
  if (
    /\b(current evidence is incomplete|primary implementation anchors? for .* remain partial in this turn|missing slots:)\b/i.test(
      normalized,
    )
  ) {
    reasons.add("template_gap_scaffold");
  }
  return Array.from(reasons);
};

const detectRepoAnswerQualityFloorReasons = (args: {
  text: string;
  relationQuery: boolean;
  relationPacket: boolean;
  requiresRepoEvidence: boolean;
  intentDomain: string;
  openWorldExplainer?: boolean;
  securityRiskPrompt?: boolean;
  enforceGlobalFloor?: boolean;
}): string[] => {
  const reasons = new Set<string>();
  const normalized = args.text.replace(/\s+/g, " ").trim();
  if (!normalized) {
    reasons.add("empty");
    return Array.from(reasons);
  }
  if (hasModelPlaceholderOrStub(normalized)) {
    reasons.add("placeholder");
  }
  if (STUB_TEXT_RE.test(normalized)) {
    reasons.add("stub_text");
  }
  if (GENERIC_GROUNDED_RE.test(normalized)) {
    reasons.add("generic_grounding_scaffold");
  }
  if (isDeterministicMetadataNoise(normalized)) {
    reasons.add("metadata_noise");
  }
  if (isPathIndexStyleAnswer(args.text)) {
    reasons.add("path_index_body");
  }
  if (hasArtifactJsonSpill(args.text)) {
    reasons.add("artifact_json_spill");
  }
  if (RELATION_CODE_NOISE_RE.test(normalized)) {
    reasons.add("code_noise");
  }
  const hasCitations =
    extractFilePathsFromText(args.text).length > 0 || hasSourcesLine(args.text);
  const enforceCitations =
    args.enforceGlobalFloor ||
    args.requiresRepoEvidence ||
    args.intentDomain === "repo" ||
    args.intentDomain === "hybrid" ||
    args.relationQuery;
  if (enforceCitations && !hasCitations) {
    reasons.add("citation_missing");
  }
  const minChars = args.relationQuery
    ? HELIX_ASK_RELATION_QUALITY_MIN_TEXT_CHARS
    : HELIX_ASK_QUALITY_MIN_TEXT_CHARS;
  const semanticFloorMinChars = Math.max(minChars, args.openWorldExplainer || args.securityRiskPrompt ? 260 : minChars);
  const enforceMinLength =
    args.enforceGlobalFloor ||
    args.intentDomain === "repo" ||
    args.intentDomain === "hybrid" ||
    args.relationQuery ||
    Boolean(args.openWorldExplainer) ||
    Boolean(args.securityRiskPrompt);
  if (enforceMinLength && normalized.length < semanticFloorMinChars) {
    reasons.add("text_too_short");
  }
  const tokens = normalized.toLowerCase().split(/[^a-z0-9]+/).filter((token) => token.length >= 3);
  const unique = new Set(tokens);
  const semanticDensity = tokens.length > 0 ? unique.size / tokens.length : 0;
  if ((args.openWorldExplainer || args.securityRiskPrompt) && semanticDensity < 0.42) {
    reasons.add("semantic_density_low");
  }
  if (args.openWorldExplainer) {
    const claimCandidates = extractClaimCandidates(args.text, 8);
    if (claimCandidates.length < 2) {
      reasons.add("open_world_claim_floor");
    }
    const hasMechanism = /\b(because|therefore|which leads to|so that|drives|enables|causes|through|by\s+[^\n]{4,}\b)\b/i.test(
      normalized,
    );
    if (!hasMechanism) {
      reasons.add("open_world_mechanism_missing");
    }
  }
  if (args.securityRiskPrompt) {
    const hasActionableSection =
      /\b(action|actions|checklist|steps|do this|protect|mitigation|safety|defense|monitor|freeze|alert|2fa|mfa|password manager|contact your bank)\b/i.test(
        normalized,
      ) ||
      /\n\s*(?:[-*]|\d+\.)\s+/.test(args.text);
    if (!hasActionableSection) {
      reasons.add("security_actionable_missing");
    }
  }
  if (hasSourcesLine(args.text) && extractClaimCandidates(args.text, 4).length === 0) {
    reasons.add("citation_only_body");
  }
  if (args.relationQuery && args.relationPacket) {
    for (const reason of detectRelationDeterministicFallbackReasons(args.text)) {
      reasons.add(`relation_${reason}`);
    }
  }
  return Array.from(reasons);
};

const isDeterministicMetadataNoise = (value: string): boolean => {
  const normalized = value.toLowerCase();
  if (!normalized) return true;
  if (
    /\bscore=\d/.test(normalized) ||
    /\bsymbol=[a-z0-9_.-]+/.test(normalized) ||
    /\bfile=(?:[a-z0-9_.-]+[\\/])+[a-z0-9_.-]+/.test(normalized)
  ) {
    return true;
  }
  if (/^\s*stage-0 candidate:/i.test(value)) return true;
  if (isDeterministicHeadingScaffoldNoise(value)) return true;
  if (
    /\b(?:title|heading|subheading|id|slug|label|aliases|scope|intenthints|topictags|mustincludefiles|version|rootid|nodes|children)\s*:/i.test(
      value,
    )
  ) {
    return true;
  }
  if (/^\s*---\s*$/.test(normalized)) return true;
  if (normalized.startsWith("title:") || normalized.startsWith("heading:")) return true;
  const matches = normalized.match(
    /\b(?:title|heading|subheading|id|slug|label|aliases|scope|intenthints|topictags|mustincludefiles|version|rootid|nodes|children)\b/g,
  );
  return (matches?.length ?? 0) >= 2;
};

const isDeterministicSingleCharSpill = (value: string): boolean => {
  const compact = value.replace(/\s+/g, " ").trim();
  if (!compact) return true;
  const tokens = compact.split(" ").filter(Boolean);
  if (tokens.length < 20) return false;
  const singleCharTokens = tokens.filter((token) => token.length === 1).length;
  if (singleCharTokens / tokens.length >= 0.45) return true;
  const alnumChars = compact.replace(/[^a-z0-9]/gi, "");
  if (alnumChars.length >= 80 && !/[.!?]/.test(compact) && !/\b(?:is|are|means|defines|models|implements)\b/i.test(compact)) {
    return true;
  }
  return false;
};

const isDeterministicCodeNoiseLine = (value: string): boolean => {
  const compact = value.replace(/\s+/g, " ").trim();
  if (!compact) return true;
  if (DETERMINISTIC_CODE_LINE_RE.test(compact)) return true;
  if (/\b[a-z_]\w*\s*:\s*[A-Z][A-Za-z0-9_<>[\]|&?]*/.test(compact)) return true;
  if (/\bparams?\s*:\s*[A-Za-z0-9_<>{}\[\]|&?]+/.test(compact)) return true;
  if (/\b(?:return|await|new)\b/.test(compact) && /[;{}]/.test(compact)) return true;
  return false;
};

const collectDeterministicEvidenceClaims = (args: {
  question: string;
  evidenceText: string;
  conceptual: boolean;
}): string[] => {
  const sentenceSource = splitGroundedSentences(args.evidenceText);
  const lineSource = args.evidenceText
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  const ranked = [...sentenceSource, ...lineSource]
    .map((line) => sanitizeDeterministicContractLine(line))
    .filter((line) => line.length >= 24)
    .filter((line) => !/^sources?:/i.test(line))
    .filter((line) => !/\b(?:notes?|tags?|minimal\s+artifact)\s*:/i.test(line))
    .filter((line) => !isDeterministicMetadataNoise(line))
    .filter((line) => !isDeterministicSingleCharSpill(line))
    .filter((line) => !isDeterministicHeadingScaffoldNoise(line))
    .filter((line) => !isDeterministicCodeNoiseLine(line))
    .map((line) => {
      let score = 0;
      if (DETERMINISTIC_FACTUAL_VERB_RE.test(line)) score += 2;
      if (/\b(warp|bubble)\b/i.test(line)) score += 2;
      if (/\b(mission|ethos|ideology)\b/i.test(line)) score += 2;
      if (/\b(compassion|stewardship|constraint|physics)\b/i.test(line)) score += 1;
      if (DETERMINISTIC_METADATA_LINE_RE.test(line)) score -= 3;
      if (isDeterministicCodeNoiseLine(line)) score -= 4;
      if (isDeterministicSingleCharSpill(line)) score -= 5;
      return { line, score };
    })
    .sort((a, b) => b.score - a.score || b.line.length - a.line.length);
  const out: string[] = [];
  const seen = new Set<string>();
  for (const item of ranked) {
    const key = item.line.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item.line);
    if (out.length >= 6) break;
  }
  return out;
};

const detectDeterministicContractNoiseReasons = (args: {
  contract: HelixAskAnswerContract;
  conceptual: boolean;
  relationQuery: boolean;
}): string[] => {
  const reasons = new Set<string>();
  const lines = [
    args.contract.summary ?? "",
    ...(args.contract.claims ?? []).map((claim) => claim.text ?? ""),
    ...(args.contract.steps ?? []),
    ...(args.contract.comparisons ?? []).map((entry) => `${entry.label}: ${entry.detail}`),
  ]
    .map((line) => normalizeContractText(String(line ?? ""), 320))
    .filter(Boolean);
  if (lines.some((line) => isDeterministicMetadataNoise(line))) {
    reasons.add("metadata_noise");
  }
  if (args.conceptual && lines.some((line) => DETERMINISTIC_CODE_LINE_RE.test(line))) {
    reasons.add("code_noise");
  }
  if (lines.some((line) => line.length < 18)) {
    reasons.add("claim_too_short");
  }
  if (args.relationQuery) {
    const merged = lines.join(" ").toLowerCase();
    const hasWarp = /\bwarp\b|\bbubble\b/.test(merged);
    const hasEthos = /\bethos\b|\bideology\b|\bmission\b/.test(merged);
    if (!hasWarp || !hasEthos) {
      reasons.add("relation_link_missing");
    }
  }
  return Array.from(reasons);
};

const evaluateRelationContractHardFail = (args: {
  contract: HelixAskAnswerContract;
  relationPacket: RelationAssemblyPacket | null;
}): string[] => {
  if (!args.relationPacket) return [];
  const reasons: string[] = [];
  if ((args.relationPacket.bridge_claims?.length ?? 0) < 2) reasons.push("bridge_claims_lt_2");
  const sources = args.contract.sources ?? [];
  const hasWarp = sources.some((entry) => /warp|physics|module/i.test(entry));
  const hasEthos = sources.some((entry) => /ethos|ideology/i.test(entry));
  if (!(hasWarp && hasEthos)) reasons.push("single_domain_citations");
  const merged = [
    args.contract.summary ?? "",
    ...(args.contract.claims ?? []).map((claim) => claim.text),
  ].join(" ");
  if (/\b(?:title:|heading:|slug:|import\s+|export\s+|const\s+\w+\s*=)\b/i.test(merged)) {
    reasons.push("metadata_or_code_noise");
  }
  if ((args.relationPacket.falsifiability_hooks?.length ?? 0) === 0) reasons.push("missing_falsifiability_hook");
  return reasons;
};

type RelationCompletenessSlot = "entity_a" | "entity_b" | "mechanism";

type RelationSemanticCompleteness = {
  pass: boolean;
  missing: RelationCompletenessSlot[];
  hasEntityA: boolean;
  hasEntityB: boolean;
  hasMechanism: boolean;
};

const RELATION_ENTITY_A_RE = /\b(?:warp|warp-bubble|bubble|spacetime|metric)\b/i;
const RELATION_ENTITY_B_RE = /\b(?:mission\s+ethos|ethos|stewardship|ideology|policy)\b/i;
const RELATION_MECHANISM_RE =
  /\b(?:constrain(?:s|ed|ing)?|bind(?:s|ing)?|link(?:s|ed|ing)?|connect(?:s|ed|ion)?|bridge|govern(?:s|ed|ance)?|gate(?:s|d)?|verif(?:y|ies|ied|ication)|checkpoint|audit(?:able)?|evidence|falsifi(?:able|ability)|constraint)\b/i;

const evaluateRelationSemanticCompleteness = (answer: string): RelationSemanticCompleteness => {
  const normalized = normalizeContractText(String(answer ?? ""), 6000);
  const hasEntityA = RELATION_ENTITY_A_RE.test(normalized);
  const hasEntityB = RELATION_ENTITY_B_RE.test(normalized);
  const hasMechanism = RELATION_MECHANISM_RE.test(normalized) && (hasEntityA || hasEntityB);
  const missing: RelationCompletenessSlot[] = [];
  if (!hasEntityA) missing.push("entity_a");
  if (!hasEntityB) missing.push("entity_b");
  if (!hasMechanism) missing.push("mechanism");
  return {
    pass: missing.length === 0,
    missing,
    hasEntityA,
    hasEntityB,
    hasMechanism,
  };
};

const repairRelationSemanticCompleteness = (args: {
  answer: string;
  relationPacket: RelationAssemblyPacket | null;
  missing: RelationCompletenessSlot[];
}): {
  text: string;
  applied: boolean;
  missingBefore: RelationCompletenessSlot[];
} => {
  const missing = args.missing.slice();
  if (!args.answer.trim() || missing.length === 0) {
    return { text: args.answer, applied: false, missingBefore: missing };
  }
  const fallbackWarp =
    "Warp context: a warp bubble is a bounded spacetime configuration under this repository's warp model.";
  const fallbackEthos =
    "Ethos context: mission ethos constrains capability claims to verified, non-harmful operation.";
  const fallbackMechanism =
    "Mechanism: ethos constraints gate warp viability claims through auditable evidence checkpoints and falsifiability hooks.";
  const warpLine = ensureRelationContractSentence(
    args.relationPacket?.definitions.warp_definition ?? "",
    fallbackWarp,
  );
  const ethosLine = ensureRelationContractSentence(
    args.relationPacket?.definitions.ethos_definition ?? "",
    fallbackEthos,
  );
  const mechanismSeed =
    args.relationPacket?.bridge_claims?.[0] ??
    args.relationPacket?.constraints?.physics_bound ??
    args.relationPacket?.falsifiability_hooks?.[0] ??
    "";
  const mechanismLine = ensureRelationContractSentence(mechanismSeed, fallbackMechanism);
  const repairSentences: string[] = [];
  if (missing.includes("entity_a")) repairSentences.push(warpLine);
  if (missing.includes("entity_b")) repairSentences.push(ethosLine);
  if (missing.includes("mechanism")) repairSentences.push(mechanismLine);
  if (repairSentences.length === 0) {
    return { text: args.answer, applied: false, missingBefore: missing };
  }
  const repairBlock = repairSentences.join("\n");
  const lines = args.answer.split(/\r?\n/);
  const sourceIndex = lines.findIndex((line) => /^\s*Sources?\s*:/i.test(line));
  let nextText = args.answer.trim();
  if (sourceIndex >= 0) {
    const before = lines.slice(0, sourceIndex).join("\n").trimEnd();
    const after = lines.slice(sourceIndex).join("\n").trimStart();
    nextText = `${before}\n\n${repairBlock}\n\n${after}`.trim();
  } else {
    nextText = `${nextText}\n\n${repairBlock}`.trim();
  }
  return {
    text: nextText,
    applied: true,
    missingBefore: missing,
  };
};

const RELATION_PATH_ONLY_RE =
  /^(?:[A-Za-z]:)?[A-Za-z0-9_./\\-]+\.(?:md|json|ts|tsx|js|jsx|py)(?:#[A-Za-z0-9:_-]+)?\.?$/i;

const isLowSignalRelationArtifactText = (value: string): boolean => {
  if (!value) return true;
  if (RELATION_CODE_NOISE_RE.test(value)) return true;
  if (/\bexport\s+default\s+function\b/i.test(value)) return true;
  if (/\bconst\s+[A-Za-z_]\w*\s*=/.test(value) && /[;{}()]/.test(value)) return true;
  if (RELATION_PATH_ONLY_RE.test(value)) return true;
  const pathHits = extractFilePathsFromText(value);
  if (
    pathHits.length > 0 &&
    !/\b(is|are|means|requires|constrains|connects|relates|because|must|binds|enables|links)\b/i.test(
      value,
    )
  ) {
    return true;
  }
  return false;
};

const ensureRelationContractSentence = (value: string, fallback: string): string => {
  const normalized = value.replace(/\s+/g, " ").trim();
  if (!normalized) return fallback;
  if (isLowSignalRelationArtifactText(normalized)) return fallback;
  return /[.!?]$/.test(normalized) ? normalized : `${normalized}.`;
};

const buildRelationModeContractFromPacket = (packet: RelationAssemblyPacket): HelixAskAnswerContract => {
  const relationSources = Object.values(packet.source_map).slice(0, 8);
  const warpDefinition = ensureRelationContractSentence(
    packet.definitions.warp_definition,
    "A warp bubble is a bounded spacetime configuration under this repository's warp model.",
  );
  const ethosDefinition = ensureRelationContractSentence(
    packet.definitions.ethos_definition,
    "Mission ethos constrains capability claims to verified, non-harmful operation.",
  );
  const bridgeMechanism = ensureRelationContractSentence(
    packet.bridge_claims.slice(0, 3).join(" "),
    "Warp development is constrained by mission-ethos checkpoints tied to reproducible evidence.",
  );
  const constraintAndHook = ensureRelationContractSentence(
    [packet.constraints.join(" "), packet.falsifiability_hooks[0] ?? ""]
      .map((entry) => entry.trim())
      .filter(Boolean)
      .join(" "),
    "Constraint and falsifiability hooks must pass before viability claims are accepted.",
  );
  return {
    summary: warpDefinition,
    claims: [
      { text: ethosDefinition, evidence: relationSources.slice(0, 2) },
      { text: bridgeMechanism, evidence: relationSources.slice(0, 4) },
      { text: constraintAndHook, evidence: relationSources.slice(0, 6) },
    ],
    sources: relationSources,
  };
};
const buildHelixAskAnswerContractPrompt = (
  question: string,
  evidence: string,
  format: HelixAskFormat,
  scaffoldHint?: string,
): string => {
  const lines: string[] = [];
  lines.push("You are Helix Ask answer-contract generator.");
  lines.push("Return strict JSON only. Do NOT include markdown or commentary.");
  lines.push(
    'Schema: {"summary":"string","claims":[{"text":"string","evidence":["citation"]}],"steps":["string"],"comparisons":[{"label":"string","detail":"string","evidence":["citation"]}],"uncertainty":"string","sources":["citation"]}.',
  );
  lines.push("Generate the full contract directly from the evidence.");
  lines.push("Keep claims grounded in evidence. Do not invent facts.");
  lines.push("Use only citation identifiers that appear in the evidence list.");
  lines.push("Each claim should carry evidence[] when support exists.");
  lines.push("Include sources[] with 3-8 high-signal citations when available.");
  lines.push("Never repeat identical lines or bullets.");
  lines.push(`Target format: ${format}.`);
  if (format === "steps") {
    lines.push("Prefer concise procedural steps in steps[] (max 6).");
  } else if (format === "compare") {
    lines.push("Prefer clear compare points in comparisons[] (max 4).");
  } else {
    lines.push("Prefer brief summary + key claims.");
  }
  lines.push("");
  lines.push("Question:");
  lines.push(clipAskText(question, 600));
  lines.push("");
  lines.push("Evidence:");
  lines.push(clipAskText(evidence || "No evidence available.", 2600));
  if (scaffoldHint?.trim()) {
    lines.push("");
    lines.push("Scaffold hints:");
    lines.push(clipAskText(scaffoldHint, 1200));
  }
  return lines.join("\n");
};

