const parseHelixAskAnswerContractPayload = (raw: string): HelixAskAnswerContract | null => {
  const trimmed = raw.trim();
  if (!trimmed) return null;
  const jsonCandidate = extractJsonObject(trimmed) ?? trimmed;
  try {
    const parsed = HELIX_ASK_ANSWER_CONTRACT_SCHEMA.safeParse(JSON.parse(jsonCandidate));
    if (parsed.success) return parsed.data;
  } catch {
    return null;
  }
  return null;
};

const buildAllowedCitationLookup = (allowed: string[]): Map<string, string> => {
  const lookup = new Map<string, string>();
  for (const raw of allowed) {
    const trimmed = raw.trim();
    if (!trimmed) continue;
    const normalized = (normalizeEvidenceRef(trimmed) ?? trimmed).replace(/\\/g, "/");
    if (!normalized) continue;
    const lower = normalized.toLowerCase();
    if (!lookup.has(lower)) lookup.set(lower, normalized);
    if (!lookup.has(trimmed.toLowerCase())) lookup.set(trimmed.toLowerCase(), trimmed);
  }
  return lookup;
};

const filterAllowedContractCitations = (
  values: string[] | undefined,
  lookup: Map<string, string>,
): string[] => {
  if (!values?.length) return [];
  const out: string[] = [];
  const seen = new Set<string>();
  for (const raw of values) {
    const trimmed = raw.trim();
    if (!trimmed) continue;
    const normalized = (normalizeEvidenceRef(trimmed) ?? trimmed).replace(/\\/g, "/");
    const key = normalized.toLowerCase();
    const matched = lookup.get(key) ?? lookup.get(trimmed.toLowerCase());
    if (!matched) continue;
    const dedupeKey = matched.toLowerCase();
    if (seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);
    out.push(matched);
  }
  return out;
};

const deriveFallbackContractSources = (
  contract: HelixAskAnswerContract,
  allowedCitations: string[],
  limit = 6,
): string[] => {
  const merged = normalizeCitations([
    ...(contract.sources ?? []),
    ...(contract.claims?.flatMap((claim) => claim.evidence ?? []) ?? []),
    ...(contract.comparisons?.flatMap((entry) => entry.evidence ?? []) ?? []),
  ]);
  if (merged.length > 0) return merged.slice(0, limit);
  return normalizeCitations(allowedCitations).slice(0, limit);
};

type HelixAskClaimGroundingEntry = {
  text: string;
  evidenceIds: string[];
  mode: "explicit" | "unsupported";
};

type HelixAskClaimGroundingGateResult = {
  contract: HelixAskAnswerContract;
  entries: HelixAskClaimGroundingEntry[];
  groundedCount: number;
  unsupportedCount: number;
  unsupportedClaims: string[];
  movedToUncertainty: boolean;
};

const applyHelixAskClaimGroundingGate = (args: {
  contract: HelixAskAnswerContract;
  allowedCitations: string[];
  evidenceText: string;
  enforce: boolean;
}): HelixAskClaimGroundingGateResult => {
  const baseEntries = (args.contract.claims ?? []).map((claim) => ({
    text: ensureSentence(normalizeContractText(claim.text, 280)),
    evidenceIds: normalizeCitations(claim.evidence ?? []),
    mode: "explicit" as const,
  }));
  if (!args.enforce || args.allowedCitations.length === 0 || (args.contract.claims?.length ?? 0) === 0) {
    return {
      contract: args.contract,
      entries: baseEntries,
      groundedCount: baseEntries.filter((entry) => entry.evidenceIds.length > 0).length,
      unsupportedCount: baseEntries.filter((entry) => entry.evidenceIds.length === 0).length,
      unsupportedClaims: baseEntries
        .filter((entry) => entry.evidenceIds.length === 0)
        .map((entry) => entry.text)
        .filter(Boolean),
      movedToUncertainty: false,
    };
  }
  const lookup = buildAllowedCitationLookup(args.allowedCitations);
  const groundedClaims: Array<{ text: string; evidence?: string[] }> = [];
  const entries: HelixAskClaimGroundingEntry[] = [];
  const unsupportedClaims: string[] = [];
  for (const claim of args.contract.claims ?? []) {
    const text = ensureSentence(normalizeContractText(claim.text, 280));
    if (!text) continue;
    const evidenceIds = filterAllowedContractCitations(claim.evidence, lookup).slice(0, 4);
    if (evidenceIds.length > 0) {
      groundedClaims.push({ text, evidence: evidenceIds });
      entries.push({ text, evidenceIds, mode: "explicit" });
      continue;
    }
    unsupportedClaims.push(text);
    entries.push({ text, evidenceIds: [], mode: "unsupported" });
  }
  if (groundedClaims.length === 0) {
    const fallbackEvidence = filterAllowedContractCitations(
      normalizeCitations([...(args.contract.sources ?? []), ...args.allowedCitations]),
      lookup,
    ).slice(0, 2);
    const fallbackText =
      ensureSentence(
        normalizeContractText(
          args.contract.summary ||
            "Evidence is limited; add concrete file paths to support additional claims.",
          280,
        ),
      ) ||
      "Evidence is limited; add concrete file paths to support additional claims.";
    groundedClaims.push(
      fallbackEvidence.length > 0
        ? { text: fallbackText, evidence: fallbackEvidence }
        : { text: fallbackText },
    );
  }
  const baseUncertainty = normalizeContractText(args.contract.uncertainty ?? "", 220);
  const unsupportedUncertainty =
    unsupportedClaims.length > 0
      ? ensureSentence(
          normalizeContractText(
            `Unsupported claims moved to uncertainty until evidence IDs are linked: ${unsupportedClaims
              .slice(0, 3)
              .map((entry) => normalizeContractText(entry, 90))
              .filter(Boolean)
              .join(" | ")}`,
            340,
          ),
        )
      : "";
  const nextUncertainty = [baseUncertainty, unsupportedUncertainty].filter(Boolean).join(" ");
  const sourceSeed = normalizeCitations([
    ...(args.contract.sources ?? []),
    ...groundedClaims.flatMap((entry) => entry.evidence ?? []),
    ...(args.contract.comparisons?.flatMap((entry) => entry.evidence ?? []) ?? []),
  ]);
  const sources = filterAllowedContractCitations(sourceSeed, lookup).slice(0, 8);
  return {
    contract: {
      ...args.contract,
      claims: groundedClaims,
      uncertainty: nextUncertainty || args.contract.uncertainty,
      sources: sources.length > 0 ? sources : args.contract.sources,
    },
    entries,
    groundedCount: groundedClaims.filter((entry) => (entry.evidence?.length ?? 0) > 0).length,
    unsupportedCount: unsupportedClaims.length,
    unsupportedClaims,
    movedToUncertainty: unsupportedClaims.length > 0,
  };
};

const buildDeterministicAnswerContractFallback = (args: {
  question: string;
  format: HelixAskFormat;
  definitionFocus: boolean;
  docBlocks: Array<{ path: string; block: string }>;
  codeAlignment?: HelixAskCodeAlignment | null;
  evidenceText: string;
  allowedCitations: string[];
}): HelixAskAnswerContract => {
  const conceptualQuestion =
    !isImplementationQuestion(args.question) || HELIX_ASK_RELATION_QUERY_RE.test(args.question);
  const fallbackDocBlocks = filterFallbackDocBlocks(args.docBlocks);
  const docSource = fallbackDocBlocks.length > 0 ? fallbackDocBlocks : args.docBlocks;
  const evidenceClaims = collectDeterministicEvidenceClaims({
    question: args.question,
    evidenceText: args.evidenceText,
    conceptual: conceptualQuestion,
  });
  const docBullets = docSource
    .slice(0, Math.min(docSource.length, args.definitionFocus ? 4 : 3))
    .map((block, index) =>
      buildDocEvidenceBullet(block, args.definitionFocus && index === 0 ? "Definition" : "Evidence"),
    );
  const codeBullets = conceptualQuestion
    ? []
    : (args.codeAlignment?.spans ?? [])
        .filter((span) => isCodeEvidencePath(span.filePath) || span.isTest)
        .slice(0, 2)
        .map((span) => buildCodeEvidenceBullet(span));

  const derivedClaimLines = [...evidenceClaims, ...docBullets, ...codeBullets]
    .map((line) => sanitizeDeterministicContractLine(summarizeForExtension(line)))
    .filter((line) => line.length >= 20)
    .filter((line) => !isDeterministicMetadataNoise(line))
    .filter((line) => !(conceptualQuestion && DETERMINISTIC_CODE_LINE_RE.test(line)));
  if (derivedClaimLines.length === 0) {
    const fallbackClaims = splitGroundedSentences(args.evidenceText)
      .map((line) => sanitizeDeterministicContractLine(summarizeForExtension(line)))
      .filter((line) => line.length >= 24 && !/^sources?:/i.test(line))
      .filter((line) => !isDeterministicMetadataNoise(line))
      .filter((line) => !(conceptualQuestion && DETERMINISTIC_CODE_LINE_RE.test(line)));
    derivedClaimLines.push(...fallbackClaims.slice(0, 4));
  }

  const asksWhyItMatters =
    /\b(?:why\s+(?:is|does).{0,40}\b(?:important|matter)|why\s+is\s+this\s+important\s+to\s+the\s+solve)\b/i.test(
      args.question,
    );
  if (asksWhyItMatters) {
    derivedClaimLines.unshift(
      "That matters because it tells the solve whether it is still operating inside the intended regime and whether the simplifying assumptions behind that branch remain valid.",
    );
  }

  const uniqueClaims = Array.from(
    new Set(derivedClaimLines.map((line) => line.replace(/\s+/g, " ").trim()).filter(Boolean)),
  ).slice(0, 4);
  const summary =
    ensureSentence(
      normalizeContractText(uniqueClaims[0] ?? "Answer grounded in retrieved evidence.", 360),
    ) || "Answer grounded in retrieved evidence.";
  const sources = normalizeCitations([
    ...args.allowedCitations,
    ...extractFilePathsFromText(args.evidenceText),
  ]).slice(0, 8);
  const claimEvidence = sources.slice(0, 3);
  const claimTexts = uniqueClaims.length > 0 ? uniqueClaims : [summary];
  const claims = claimTexts.map((text) => {
    if (claimEvidence.length > 0) return { text, evidence: claimEvidence };
    return { text };
  });

  const contract: HelixAskAnswerContract = {
    summary,
    claims,
    uncertainty:
      sources.length === 0
        ? "Evidence is limited; add the relevant repo file paths for stronger grounding."
        : undefined,
    tone: /\bplain language\b/i.test(args.question) ? "plain" : undefined,
    sources: sources.length > 0 ? sources : undefined,
  };

  if (args.format === "steps") {
    contract.steps = claimTexts.slice(0, 6);
  } else if (args.format === "compare") {
    contract.comparisons = claimTexts.slice(0, 3).map((detail, index) => {
      const label = index === 0 ? "Definition" : index === 1 ? "Evidence" : "Constraint";
      if (claimEvidence.length > 0) {
        return { label, detail, evidence: claimEvidence };
      }
      return { label, detail };
    });
  }

  return contract;
};

const RenderPlatonicFallback = (args: {
  prompt: string;
  anchors: string[];
  constraints: string[];
  budget: { maxChars: number; maxClaims: number };
  format: HelixAskFormat;
  definitionFocus: boolean;
  docBlocks: Array<{ path: string; block: string }>;
  codeAlignment?: HelixAskCodeAlignment | null;
  evidenceText: string;
  allowedCitations: string[];
}): { contract: HelixAskAnswerContract; rendered: string; rendererPath: string } => {
  const contract = sanitizeHelixAskAnswerContract(
    buildDeterministicAnswerContractFallback({
      question: args.prompt,
      format: args.format,
      definitionFocus: args.definitionFocus,
      docBlocks: args.docBlocks,
      codeAlignment: args.codeAlignment,
      evidenceText: appendEvidenceSources(args.evidenceText, args.anchors, 8, args.constraints.join("\n")),
      allowedCitations: args.allowedCitations,
    }),
    args.allowedCitations,
  );
  const rendered = renderHelixAskAnswerContract(contract, args.format, args.prompt)
    .slice(0, Math.max(220, args.budget.maxChars))
    .trim();
  return {
    contract,
    rendered,
    rendererPath: "RenderPlatonicFallback",
  };
};

type HelixAskAnswerContractGateResult = {
  ok: boolean;
  hardFail: boolean;
  reasons: string[];
  sourceCount: number;
  groundedClaimCount: number;
  uniqueRatio: number;
  mechanismPresent: boolean;
  maturityPresent: boolean;
  missingEvidencePresent: boolean;
};

const normalizeContractGateLine = (value: string): string =>
  value
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const evaluateHelixAskAnswerContractGate = (
  contract: HelixAskAnswerContract,
  format: HelixAskFormat,
  allowedCitations: string[],
  requiresRepoEvidence: boolean,
): HelixAskAnswerContractGateResult => {
  const reasons: string[] = [];
  const summary = normalizeContractText(contract.summary ?? "", 360);
  const claimCount = contract.claims?.length ?? 0;
  const stepCount = contract.steps?.length ?? 0;
  const comparisonCount = contract.comparisons?.length ?? 0;
  const sourceCount = contract.sources?.length ?? 0;
  const groundedClaimCount = (contract.claims ?? []).filter(
    (claim) => (claim.evidence?.length ?? 0) > 0,
  ).length;
  if (!summary) reasons.push("summary_missing");
  if (claimCount === 0 && stepCount === 0 && comparisonCount === 0) {
    reasons.push("content_missing");
  }
  if (format === "steps" && stepCount === 0 && claimCount < 2) {
    reasons.push("steps_missing");
  }
  if (format === "compare" && comparisonCount === 0 && claimCount < 2) {
    reasons.push("comparisons_missing");
  }
  if (requiresRepoEvidence && allowedCitations.length > 0 && sourceCount === 0) {
    reasons.push("repo_sources_missing");
  }
  if (requiresRepoEvidence && allowedCitations.length > 0 && groundedClaimCount === 0) {
    reasons.push("claim_evidence_missing");
  }
  if (requiresRepoEvidence && allowedCitations.length > 0 && groundedClaimCount < claimCount) {
    reasons.push("ungrounded_claim_present");
  }
  const renderedPreview = renderHelixAskAnswerContract(contract, format, "");
  const mechanismPresent = HELIX_ASK_MECHANISM_SENTENCE_RE.test(renderedPreview);
  const maturityPresent = HELIX_ASK_MATURITY_LABEL_RE.test(renderedPreview);
  const missingEvidencePresent = HELIX_ASK_MISSING_EVIDENCE_RE.test(renderedPreview);
  if (!mechanismPresent) reasons.push("mechanism_sentence_missing");
  if (!maturityPresent) reasons.push("maturity_label_missing");
  if (requiresRepoEvidence && sourceCount <= 1) reasons.push("source_coverage_low");
  if (requiresRepoEvidence && sourceCount > 0 && sourceCount <= 2 && !missingEvidencePresent) {
    reasons.push("missing_evidence_section_missing");
  }
  const rawLines = [
    summary,
    ...(contract.claims ?? []).map((claim) => normalizeContractText(claim.text, 260)),
    ...(contract.steps ?? []).map((step) => normalizeContractText(step, 220)),
    ...(contract.comparisons ?? []).map((entry) =>
      normalizeContractText(`${entry.label}: ${entry.detail}`, 260),
    ),
  ].filter(Boolean);
  const normalizedLines = rawLines.map(normalizeContractGateLine).filter(Boolean);
  const uniqueRatio =
    normalizedLines.length > 0
      ? Number(
          (new Set(normalizedLines).size / Math.max(1, normalizedLines.length)).toFixed(3),
        )
      : 1;
  if (normalizedLines.length >= 4 && uniqueRatio < 0.65) {
    reasons.push("repetition_high");
  }
  const hardFail = reasons.includes("summary_missing") || reasons.includes("content_missing");
  return {
    ok: reasons.length === 0,
    hardFail,
    reasons,
    sourceCount,
    groundedClaimCount,
    uniqueRatio,
    mechanismPresent,
    maturityPresent,
    missingEvidencePresent,
  };
};

const sanitizeHelixAskAnswerContract = (
  contract: HelixAskAnswerContract,
  allowedCitations: string[],
  noveltyContext?: HelixAskNoveltyContext,
): HelixAskAnswerContract => {
  const lookup = buildAllowedCitationLookup(allowedCitations);
  const fallbackSummary = "Answer grounded in retrieved evidence.";
  const rawSummary = ensureSentence(normalizeContractText(contract.summary || fallbackSummary, 360));
  const summary =
    !rawSummary || isDeterministicMetadataNoise(rawSummary) || isDeterministicHeadingScaffoldNoise(rawSummary)
      ? fallbackSummary
      : rawSummary;
  const claims = (contract.claims ?? [])
    .map((claim) => {
      const text = ensureSentence(normalizeContractText(claim.text, 280));
      if (!text) return null;
      if (isDeterministicMetadataNoise(text) || isDeterministicHeadingScaffoldNoise(text)) return null;
      const evidence = filterAllowedContractCitations(claim.evidence, lookup);
      return evidence.length > 0 ? { text, evidence } : { text };
    })
    .filter((claim): claim is { text: string; evidence?: string[] } => Boolean(claim));
  if (claims.length === 0) {
    claims.push({ text: summary });
  }
  const steps = (contract.steps ?? [])
    .map((step) => ensureSentence(normalizeContractText(step, 220)))
    .filter(Boolean)
    .slice(0, 6);
  const comparisons = (contract.comparisons ?? [])
    .map((entry) => {
      const label = normalizeContractText(entry.label, 60);
      const detail = ensureSentence(normalizeContractText(entry.detail, 220));
      if (!label || !detail) return null;
      const evidence = filterAllowedContractCitations(entry.evidence, lookup);
      return evidence.length > 0 ? { label, detail, evidence } : { label, detail };
    })
    .filter(
      (entry): entry is { label: string; detail: string; evidence?: string[] } =>
        Boolean(entry),
    )
    .slice(0, 4);
  const uncertainty = normalizeContractText(contract.uncertainty ?? "", 220);
  const mechanismSeed = claims.find((claim) => HELIX_ASK_MECHANISM_SENTENCE_RE.test(claim.text));
  if (!mechanismSeed && claims.length > 0) {
    const first = claims[0].text;
    const second = claims[1]?.text ?? claims[0].text;
    const mechanismLine = buildHelixAskMechanismSentence({
      claimA: first,
      claimB: second,
      evidenceTarget: allowedCitations[1] ?? allowedCitations[0] ?? "retrieved evidence",
      context: noveltyContext ?? { family: "other", prompt: contract.summary ?? "" },
    });
    claims.push({
      text: ensureSentence(
        normalizeContractText(mechanismLine, 340),
      ),
      evidence: claims[0].evidence,
    });
  }
  const maturitySeed = claims.find((claim) => HELIX_ASK_MATURITY_LABEL_RE.test(claim.text));
  if (!maturitySeed) {
    claims.push({
      text: "Maturity (exploratory): this claim set is hypothesis-guided and not yet certified by dedicated test artifacts.",
      evidence: claims[0]?.evidence,
    });
  }
  const sourceSeed = normalizeCitations([
    ...(contract.sources ?? []),
    ...claims.flatMap((claim) => claim.evidence ?? []),
    ...comparisons.flatMap((entry) => entry.evidence ?? []),
  ]);
  const sources = filterAllowedContractCitations(sourceSeed, lookup).slice(0, 8);
  return {
    summary,
    claims,
    steps: steps.length > 0 ? steps : undefined,
    comparisons: comparisons.length > 0 ? comparisons : undefined,
    uncertainty:
      uncertainty ||
      (sources.length <= 2
        ? "Missing evidence: add stronger repo citations and linked test artifacts before upgrading maturity."
        : undefined),
    tone: contract.tone,
    sources: sources.length > 0 ? sources : undefined,
  };
};

const renderHelixAskAnswerContract = (
  contract: HelixAskAnswerContract,
  format: HelixAskFormat,
  question: string,
  noveltyContext?: HelixAskNoveltyContext,
): string => {
  const structuredDetailRequested = shouldExposeHelixAskSecondaryArtifacts(question);
  const conversationalContract = !structuredDetailRequested;
  const isNoisyRenderedContractSentence = (value: string): boolean => {
    const trimmed = value.trim();
    if (!trimmed) return true;
    if (/^(?:key\s+questions?|notes?)\s*:/i.test(trimmed)) return true;
    if (/^section\s*:/i.test(trimmed)) return true;
    if (/^span\s*:/i.test(trimmed)) return true;
    return false;
  };
  const dedupeRenderedContractSentences = (sentences: string[], summary: string): string[] => {
    const deduped: string[] = [];
    const seen = new Set<string>();
    const normalizedSummary = normalizeContractGateLine(summary);
    for (const sentence of sentences) {
      const normalizedSentence = normalizeContractGateLine(sentence);
      if (!normalizedSentence) continue;
      if (normalizedSummary && normalizedSentence === normalizedSummary) continue;
      if (seen.has(normalizedSentence)) continue;
      if (isNoisyRenderedContractSentence(sentence)) continue;
      if (isDeterministicMetadataNoise(sentence) || isDeterministicHeadingScaffoldNoise(sentence)) continue;
      seen.add(normalizedSentence);
      deduped.push(sentence);
    }
    return deduped;
  };
  const wantsPlainLanguage = /\bplain language\b/i.test(question);
  const deterministicLeadPrefix = (seedText: string): string => {
    const variants = wantsPlainLanguage
      ? ["In simple terms:", "Practically:", "Bottom line:"]
      : ["Directly:", "Bottom line:", "Practically:"];
    const seed = Array.from(seedText || question || "helix").reduce(
      (acc, ch) => acc + ch.charCodeAt(0),
      0,
    );
    return variants[seed % variants.length] ?? variants[0]!;
  };
  const leadSummary = (): string => {
    const summary = ensureSentence(normalizeContractText(contract.summary, 360));
    if (!summary) return "";
    if (isDeterministicMetadataNoise(summary) || isDeterministicHeadingScaffoldNoise(summary)) return "";
    if (wantsPlainLanguage && !/^in plain language[,:\s]/i.test(summary)) {
      const prefix = deterministicLeadPrefix(summary);
      if (new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`, "i").test(summary)) {
        return summary;
      }
      return `${prefix} ${summary}`;
    }
    return summary;
  };
  const claimSentencesRaw = (contract.claims ?? [])
    .map((claim) => ensureSentence(normalizeContractText(claim.text, 260)))
    .filter((claim): claim is string => Boolean(claim))
    .filter((claim) => !isDeterministicMetadataNoise(claim))
    .filter((claim) => !isDeterministicHeadingScaffoldNoise(claim));
  const summarySeed = ensureSentence(normalizeContractText(contract.summary, 360)) || "";
  const normalizedSummarySeed = normalizeContractGateLine(summarySeed);
  const claimSentences = dedupeRenderedContractSentences(claimSentencesRaw, summarySeed);
  const semanticClaims = claimSentences.filter(
    (claim) => !/^(?:mechanism|maturity|missing evidence)\b/i.test(claim.trim()),
  );
  const mechanismClaims = claimSentences.filter((claim) =>
    /^mechanism\b/i.test(claim.trim()),
  );
  const maturityClaims = claimSentences.filter((claim) => /^maturity\b/i.test(claim.trim()));
  const missingEvidenceClaims = claimSentences.filter((claim) =>
    /^missing evidence\b/i.test(claim.trim()),
  );
  const practiceUncertainty =
    !conversationalContract &&
    contract.uncertainty &&
    !/^missing evidence\b/i.test(contract.uncertainty.trim())
      ? contract.uncertainty
      : "";
  const practiceCandidate =
    practiceUncertainty ||
    semanticClaims.find((claim) => claim.toLowerCase() !== summarySeed.toLowerCase()) ||
    mechanismClaims[0] ||
    "";
  const normalizePracticeCandidate = (value: string): string => {
    const source = ensureSentence(normalizeContractText(value, 220));
    if (!source) return "";
    if (isDeterministicMetadataNoise(source) || isDeterministicHeadingScaffoldNoise(source)) return "";
    let normalized = source;
    normalized = normalized.replace(/^mechanism\s*:\s*/i, "");
    if (/->/.test(normalized)) {
      normalized = "coupled constraints and feedback loops determine how outcomes evolve over time.";
    }
    return ensureSentence(normalizeContractText(normalized, 220));
  };
  const practiceText = practiceCandidate ? normalizePracticeCandidate(practiceCandidate) : "";
  const practiceLine = practiceText
    ? `In practice, ${practiceText.replace(/^in practice[,:\s]*/i, "")}`
    : "";
  const sectionsByType: Record<string, string[]> = {
    summary: [],
    details: [],
    mechanism: [],
    maturity: [],
    missing: [],
  };
  const summaryLine = leadSummary();
  const variedSummaryLine = noveltyContext
    ? applyHelixAskSummaryVariant(summaryLine, noveltyContext)
    : summaryLine;
  if (variedSummaryLine) sectionsByType.summary.push(variedSummaryLine);
  if (conversationalContract) {
    const conversationalDetails = semanticClaims
      .filter((claim) => /^[A-Z0-9"]/.test(claim.trim()))
      .map((claim, index) => ({
        claim,
        index,
        score:
          (/\b(?:important|matters?|because|lets|allows|keeps|ensures|so that|means|why)\b/i.test(claim)
            ? 6
            : 0) +
          (/\b(?:solve|solver|regime|expansion|shift|geometry|constraint|diagnostic)\b/i.test(claim)
            ? 3
            : 0) -
          (extractFilePathsFromText(claim).length > 0 &&
          !/\b(?:important|matters?|because|lets|allows|keeps|ensures|so that|means|why)\b/i.test(claim)
            ? 4
            : 0) -
          (claim.length < 60 ? 1 : 0),
      }))
      .sort((left, right) => right.score - left.score || left.index - right.index)
      .map((entry) => entry.claim)
      .slice(0, 2);
    if (conversationalDetails.length > 0) {
      const detailLine = conversationalDetails.join(" ");
      sectionsByType.details.push(
        noveltyContext ? applyHelixAskDetailsVariant(detailLine, noveltyContext) : detailLine,
      );
    }
  } else if (format === "steps") {
    const steps = (contract.steps ?? claimSentences).slice(0, 6);
    if (steps.length > 0) {
      const renderedSteps = steps.map((step, index) => `${index + 1}. ${ensureSentence(step)}`);
      sectionsByType.details.push(renderedSteps.join("\n"));
    }
    if (practiceLine) {
      sectionsByType.details.push(practiceLine);
    }
  } else if (format === "compare") {
    const relationNaturalCompare = noveltyContext?.family === "relation";
    const explicitCompareLines = (contract.comparisons ?? [])
      .map((entry) => {
        const detail = ensureSentence(normalizeContractText(entry.detail, 220));
        const label = normalizeContractText(entry.label, 60);
        if (!detail || !label) return "";
        if (normalizedSummarySeed && normalizeContractGateLine(detail) === normalizedSummarySeed) {
          return "";
        }
        if (/^(?:mechanism|maturity|missing evidence)\b/i.test(detail.trim())) {
          return "";
        }
        if (isNoisyRenderedContractSentence(detail)) return "";
        if (relationNaturalCompare) return `- ${ensureSentence(detail)}`;
        return `- ${ensureSentence(`${label}: ${detail}`)}`;
      })
      .filter(Boolean);
    const compareLabels = noveltyContext
      ? getHelixAskCompareLabels(noveltyContext)
      : { what: "What it is", why: "Why it matters", constraint: "Constraint" };
    const compareLines =
      explicitCompareLines.length > 0
        ? explicitCompareLines
        : semanticClaims.slice(0, 3).map((claim, index) => {
            if (relationNaturalCompare) return `- ${ensureSentence(claim)}`;
            if (index === 0) return `- ${ensureSentence(`${compareLabels.what}: ${claim}`)}`;
            if (index === 1) return `- ${ensureSentence(`${compareLabels.why}: ${claim}`)}`;
            return `- ${ensureSentence(`${compareLabels.constraint}: ${claim}`)}`;
          });
    if (compareLines.length > 0) sectionsByType.details.push(compareLines.join("\n"));
    if (practiceLine) sectionsByType.details.push(practiceLine);
  } else {
    const details = claimSentences
      .filter((claim) => claim.toLowerCase() !== contract.summary.toLowerCase())
      .slice(0, 3);
    if (details.length > 0) {
      const detailLine = details.join(" ");
      sectionsByType.details.push(
        noveltyContext ? applyHelixAskDetailsVariant(detailLine, noveltyContext) : detailLine,
      );
    }
    if (practiceLine) sectionsByType.details.push(practiceLine);
  }
  if (!conversationalContract && mechanismClaims[0]) {
    if (noveltyContext?.family === "relation") {
      const relationDetail = buildHelixAskRelationDetailBlock({
        context: noveltyContext,
        evidenceTarget: contract.sources?.[0] ?? "retrieved evidence",
      });
      if (relationDetail.placement === "before_mechanism") {
        sectionsByType.mechanism.push(relationDetail.line);
        sectionsByType.mechanism.push(mechanismClaims[0]);
      } else {
        sectionsByType.mechanism.push(mechanismClaims[0]);
        sectionsByType.mechanism.push(relationDetail.line);
      }
    } else {
      sectionsByType.mechanism.push(mechanismClaims[0]);
    }
  }
  if (!conversationalContract && maturityClaims[0]) sectionsByType.maturity.push(maturityClaims[0]);
  if (!conversationalContract && contract.uncertainty) {
    const missing = ensureSentence(normalizeContractText(contract.uncertainty, 260));
    if (missing) sectionsByType.missing.push(`Missing evidence: ${missing.replace(/^missing evidence:\s*/i, "")}`);
  } else if (!conversationalContract && missingEvidenceClaims[0]) {
    sectionsByType.missing.push(missingEvidenceClaims[0]);
  } else if (!conversationalContract) {
    sectionsByType.missing.push(
      "Missing evidence: add directly relevant repo paths or artifact refs to raise confidence.",
    );
  }
  const orderedSectionTypes = getHelixAskSectionOrder(
    noveltyContext ?? { family: "other", prompt: question },
  );
  const sections = orderedSectionTypes.flatMap((key) => sectionsByType[key] ?? []);
  const compactSections = reduceHelixAskScaffoldRepeats(
    sections,
    noveltyContext ?? { family: "other", prompt: question },
  );
  let text = compactSections.join("\n\n").replace(/\n{3,}/g, "\n\n").trim();
  if ((contract.sources?.length ?? 0) > 0) {
    text = `${text}\n\nSources: ${(contract.sources ?? []).join(", ")}`.trim();
  }
  return text;
};

const isOpenWorldExplainerQuestion = (question: string): boolean =>
  /\b(how\s+does|how\s+can|why\s+does|why\s+can|what\s+are|what\s+is|is\s+life|explain|describe|produce|protect|prevent|inevitable|accident)\b/i.test(
    question,
  ) && !isImplementationQuestion(question);

const isLifeCosmologyConsciousnessPrompt = (question: string): boolean =>
  /\b(life|abiogenesis|universe|cosmology|cosmos|consciousness|stellar consciousness|origin(?:s)? of life|astrobiology)\b/i.test(
    question,
  );

const isSecurityRiskPrompt = (question: string): boolean =>
  /\b(hack|attack|fraud|scam|phish|phishing|steal|theft|financial|bank|identity|ransom|malware|exploit|protect itself)\b/i.test(
    question,
  );

const isEthosDocPath = (value?: string): boolean =>
  Boolean(
    value &&
      /(^|\/)docs\/(?:ethos\/|knowledge\/ethos\/)/i.test(value.replace(/\\/g, "/")),
  );

const classifyFallbackReason = (args: {
  fallbackReason?: string | null;
  failClosedReason?: string | null;
  answerFallbackReason?: string | null;
  answerShortFallbackReason?: string | null;
  toolResultsFallbackReason?: string | null;
  placeholderApplied?: boolean;
  ambiguityApplied?: boolean;
  qualityFloorReasons?: string[] | null;
}): string => {
  const base = String(args.fallbackReason ?? "").trim();
  if (base) return base;
  if (args.failClosedReason) return `fail_closed:${args.failClosedReason}`;
  if (args.answerFallbackReason) return `answer_fallback:${args.answerFallbackReason}`;
  if (args.answerShortFallbackReason) return `answer_short:${args.answerShortFallbackReason}`;
  if (args.toolResultsFallbackReason) return `tool_results:${args.toolResultsFallbackReason}`;
  if (args.placeholderApplied) return "quality_floor:placeholder_rewrite";
  if (args.ambiguityApplied) return "clarify:ambiguity_gate";
  if ((args.qualityFloorReasons ?? []).length > 0) return "quality_floor:enforced";
  return "none";
};

const resolveAmbiguityAppliedForFallbackTaxonomy = (args: {
  ambiguityApplied: boolean;
  equationSelectorAuthorityLock: boolean;
}): boolean => args.ambiguityApplied && !args.equationSelectorAuthorityLock;

const shouldAllowSingleLlmScaffoldFallback = (args: {
  deterministicRepoRuntimeFallbackUsed: boolean;
}): boolean => !args.deterministicRepoRuntimeFallbackUsed;

const expandOpenWorldQualityFloor = (args: {
  text: string;
  question: string;
  evidenceText: string;
  contextFiles: string[];
  allowedSourcePaths: string[];
  format: HelixAskFormat;
  docBlocks: Array<{ path: string; block: string }>;
  codeAlignment?: HelixAskCodeAlignment | null;
}): string => {
  const allowedCitations = normalizeCitations([
    ...args.allowedSourcePaths,
    ...args.contextFiles,
    ...extractFilePathsFromText(args.evidenceText),
    ...extractCitationTokensFromText(args.evidenceText),
  ]);
  const deterministicContract = sanitizeHelixAskAnswerContract(
    buildDeterministicAnswerContractFallback({
      question: args.question,
      format: args.format,
      definitionFocus: false,
      docBlocks: args.docBlocks,
      codeAlignment: args.codeAlignment,
      evidenceText: appendEvidenceSources(args.evidenceText, args.contextFiles, 8, args.evidenceText),
      allowedCitations,
    }),
    allowedCitations,
  );
  const rawClaims = (deterministicContract.claims ?? []).map((claim) => claim.text).filter(Boolean);
  const claims = Array.from(
    new Set(
      rawClaims
        .map((claim) => ensureSentence(normalizeContractText(claim, 260)))
        .filter((claim): claim is string => Boolean(claim))
        .filter((claim) => !GENERIC_GROUNDED_RE.test(claim.trim())),
    ),
  );
  const primarySource = allowedCitations[0] ?? "retrieved evidence";
  const claimA =
    claims[0] ??
    `Retrieved evidence in ${primarySource} identifies concrete factors that shape the answer.`;
  const claimB =
    claims[1] ??
    `A second grounded claim from ${allowedCitations[1] ?? primarySource} narrows uncertainty and prevents generic fallback text.`;
  const mechanismSentence = ensureSentence(
    normalizeContractText(
      `Mechanism: ${claimA} -> coupled constraints and feedback operators -> observable outcomes tied to ${allowedCitations[1] ?? primarySource}, because feedback loops shape the resulting behavior.`,
      340,
    ),
  );
  const maturitySentence =
    "Maturity (exploratory): this answer is mechanism-grounded but remains non-certified until dedicated tests and certificate-linked evidence are attached.";
  const missingEvidenceSentence =
    allowedCitations.length <= 2
      ? "Missing evidence: add direct equation-origin anchors and test artifact links to raise maturity beyond exploratory."
      : "Missing evidence: provide higher-fidelity measurements and verification artifacts to move toward diagnostic/certified maturity.";
  const sections = [
    ensureSentence(normalizeContractText(deterministicContract.summary, 320)) ||
      `Grounded summary derived from ${primarySource}.`,
    ensureSentence(normalizeContractText(claimA, 260)),
    ensureSentence(normalizeContractText(claimB, 260)),
    mechanismSentence,
    maturitySentence,
    missingEvidenceSentence,
  ].filter((value): value is string => Boolean(value) && !GENERIC_GROUNDED_RE.test(value.trim()));
  if (isSecurityRiskPrompt(args.question)) {
    sections.push(
      "Safety actions: enable MFA on financial accounts, lock/freeze credit files, verify payment requests through a second channel, and set real-time bank alerts.",
    );
  }
  let expanded = sections.join("\n\n").trim();
  const claimCount = extractClaimCandidates(expanded, 8).length;
  if (claimCount < 2) {
    expanded = `${expanded}\n\n${ensureSentence(normalizeContractText(claims[2] ?? `Retrieved docs add a second concrete claim tied to cited files such as ${primarySource}.`, 220))}`.trim();
  }
  const sourceLine = allowedCitations.length > 0 ? `Sources: ${allowedCitations.slice(0, 8).join(", ")}` : "";
  if (sourceLine && !hasSourcesLine(expanded)) {
    expanded = `${expanded}\n\n${sourceLine}`.trim();
  }
  return expanded;
};

const enforceCitationLinkedClaims = (text: string, citationToken: string): string => {
  if (!text.trim() || !citationToken.trim()) return text;
  const normalizedCitation = citationToken.trim();
  const parts = text.split(/(?<=[.!?])\s+/);
  const patched = parts.map((part) => {
    const trimmed = part.trim();
    if (trimmed.length < 20 || /^sources\s*:/i.test(trimmed)) return part;
    if (/\[[^\]]+\]|\bdocs\/|\bserver\/|\bclient\/|\bmodules\/|\bartifacts\//i.test(trimmed)) return part;
    return `${trimmed} [${normalizedCitation}]`;
  });
  return patched.join(" ").trim();
};

