const buildAskTurnFallbackDemotedObservationArtifact = (args: {
  turnId: string;
  transcript: string;
  payload: Record<string, unknown>;
  goalHash: string;
}): HelixTurnArtifact | null => {
  const normalized = args.transcript.trim().toLowerCase();
  const fallbackId = classifyAskTurnModelOnlyFallbackId(args.transcript) ??
    (/\belectron\b/.test(normalized) ? "model_only_fallback.generic_electron" : null);
  if (!fallbackId) return null;
  const fallbackText = renderAskTurnModelOnlyFallbackAnswer(fallbackId);
  if (!fallbackText) return null;
  const observation = buildFallbackDemotedObservation(classifyDeterministicFallbackUse({
    promptText: args.transcript,
    payload: args.payload,
    fallbackId,
    fallbackText,
  }));
  if (!observation) return null;
  return {
    artifact_id: `${args.turnId}:deterministic_fallback_observation:${hashDebugExportPayloadShort([fallbackId, fallbackText])}`,
    turn_id: args.turnId,
    producer_item_id: "deterministic_fallback_policy",
    kind: "deterministic_fallback_observation",
    created_at_ms: Date.now(),
    source_scope: "current_turn",
    goal_hash: args.goalHash,
    payload: observation,
  };
};

const generateAskTurnModelOnlyAnswer = async (args: {
  transcript: string;
  model?: string;
  sessionId?: string | null;
  traceId: string;
  personaId?: string;
  tenantId?: string;
  modelVisibleContext?: string | null;
}): Promise<{
  text: string;
  source: "model_planner" | "typed_failure";
  error?: string | null;
  llm_used: boolean;
  answer_source_detail: "deterministic_fallback" | "llm" | "llm_repair" | "typed_failure";
}> => {
  try {
    const fallbackAnswer = buildAskTurnModelOnlyFallbackAnswer(args.transcript);
    if (fallbackAnswer) {
      return {
        text: fallbackAnswer,
        source: "model_planner",
        error: null,
        llm_used: false,
        answer_source_detail: "deterministic_fallback",
      };
    }
    const timeoutMs = clampNumber(readNumber(process.env.HELIX_ASK_MODEL_ONLY_TIMEOUT_MS, 12_000), 1_000, 45_000);
    let timeoutHandle: ReturnType<typeof setTimeout> | null = null;
    const result = await Promise.race([
      llmLocalHandler(
        {
          prompt: buildAskTurnModelOnlyAnswerPrompt(args.transcript, args.modelVisibleContext),
          max_tokens: Math.min(HELIX_ASK_ANSWER_MAX_TOKENS, 520),
          temperature: 0.2,
          model: args.model,
          metadata: { kind: "helix.ask.model_only_answer" },
        },
        {
          sessionId: args.sessionId ?? undefined,
          traceId: `${args.traceId}:model_only_answer`,
          personaId: args.personaId,
          tenantId: args.tenantId,
        },
      ),
      new Promise<never>((_, reject) => {
        timeoutHandle = setTimeout(() => reject(new Error("model_only_answer_timeout")), timeoutMs);
      }),
    ]);
    if (timeoutHandle) clearTimeout(timeoutHandle);
    const text = String((result as { text?: unknown })?.text ?? "").trim();
    if (text && !isAskTurnMetaFinalAnswerText(text) && !isAskTurnModelOnlyWorkspaceLeak(text)) {
      return { text, source: "model_planner", error: null, llm_used: true, answer_source_detail: "llm" };
    }
    if (text && isAskTurnModelOnlyWorkspaceLeak(text)) {
      const repaired = await Promise.race([
        llmLocalHandler(
          {
            prompt: [
              "The previous model-only answer was invalid because it referenced workspace/document evidence.",
              "Answer the user question again using only general knowledge.",
              args.modelVisibleContext
                ? "If the user asks about previous pasted or attached text, use only the admitted conversation memory below."
                : "",
              "Do not mention documents, notes, workspace, files, paths, retrieval, or debug state.",
              "Keep the answer concise: 2-5 sentences or a short bullet list.",
              args.modelVisibleContext ? "" : "",
              args.modelVisibleContext ? `Admitted conversation memory:\n${args.modelVisibleContext.trim()}` : "",
              "",
              `User question: ${args.transcript.trim()}`,
            ].join("\n"),
            max_tokens: Math.min(HELIX_ASK_ANSWER_MAX_TOKENS, 520),
            temperature: 0.2,
            model: args.model,
            metadata: { kind: "helix.ask.model_only_answer_repair" },
          },
          {
            sessionId: args.sessionId ?? undefined,
            traceId: `${args.traceId}:model_only_answer_repair`,
            personaId: args.personaId,
            tenantId: args.tenantId,
          },
        ),
        new Promise<never>((_, reject) => {
          timeoutHandle = setTimeout(() => reject(new Error("model_only_answer_repair_timeout")), timeoutMs);
        }),
      ]);
      if (timeoutHandle) clearTimeout(timeoutHandle);
      const repairedText = String((repaired as { text?: unknown })?.text ?? "").trim();
      if (repairedText && !isAskTurnMetaFinalAnswerText(repairedText) && !isAskTurnModelOnlyWorkspaceLeak(repairedText)) {
        return {
          text: repairedText,
          source: "model_planner",
          error: null,
          llm_used: true,
          answer_source_detail: "llm_repair",
        };
      }
      return {
        text: "I could not safely answer this model-only turn because the generated answer kept using workspace/document evidence.",
        source: "typed_failure",
        error: "model_only_workspace_leak",
        llm_used: true,
        answer_source_detail: "typed_failure",
      };
    }
    return {
      text: "I can answer this as a general conceptual question, but the model did not return a usable answer for this turn.",
      source: "typed_failure",
      error: "model_only_empty_answer",
      llm_used: true,
      answer_source_detail: "typed_failure",
    };
  } catch (error) {
    const errorText = error instanceof Error ? error.message : String(error);
    return {
      text:
        errorText === "model_only_answer_timeout" || errorText === "model_only_answer_repair_timeout"
          ? "I can answer this as a general conceptual question, but the direct model-only answer timed out for this turn."
          : "I can answer this as a general conceptual question, but the model backend was unavailable for this turn.",
      source: "typed_failure",
      error: errorText,
      llm_used: false,
      answer_source_detail: "typed_failure",
    };
  }
};

const composeAskTurnModelOnlyConceptFinalDraft = async (args: {
  turnId: string;
  transcript: string;
  directAnswerText: string;
  canonicalGoalFrame: HelixAskCanonicalGoalFrame;
  richSignal: HelixRichModelOnlyConceptSignal;
  compoundContract: HelixCompoundPromptContract | null;
  outputBudget: HelixFinalAnswerOutputBudgetPolicy;
  traceId: string;
  sessionId?: string | null;
  personaId?: string;
}): Promise<HelixFinalAnswerDraft> => {
  const startedAt = Date.now();
  const conceptPacket = {
    schema: "helix.model_only_concept_composer_packet.v1",
    user_prompt: args.transcript.trim(),
    concept_terms: args.richSignal.concept_terms,
    likely_misconceptions: [
      "zero-dimensional point particle means physically nonexistent",
      "fields emerge from electron movement",
      "probability sphere creates the field",
    ],
    answer_goals: [
      "explain what a field is",
      "explain particles as field excitations or pointlike detections",
      "explain why solidity is emergent from interactions",
      "distinguish mathematical dimensions/notation from physical reality",
      "explain probability clouds/orbitals",
      "gently correct misconceptions",
      "address theory concept badge without hallucinating app-specific meaning",
    ],
    theory_concept_badge_policy: asksForHelixTheoryConceptBadgeImplementation(args.transcript)
      ? "source_targeted_implementation_context_needed"
      : "treat_as_user_conceptual_phrasing",
    compound_contract: args.compoundContract,
    previous_direct_answer_text: args.directAnswerText,
  };
  const fallbackText = args.directAnswerText && !isAskTurnNonSubstantiveDirectAnswer(args.directAnswerText)
    ? args.directAnswerText
    : "I could not produce a substantive model-only concept synthesis for this turn.";
  const buildDraft = (text: string, authority: HelixFinalAnswerDraft["authority"], errorCode: string | null): HelixFinalAnswerDraft => ({
    schema: "helix.final_answer_draft.v1",
    turn_id: args.turnId,
    goal_kind: args.canonicalGoalFrame.goal_kind,
    required_terminal_kind: args.canonicalGoalFrame.required_terminal_kind,
    authority,
    composer_scope: authority === "typed_failure" ? "typed_failure" : "model_only",
    llm_error_code: errorCode,
    duration_ms: Math.max(0, Date.now() - startedAt),
    text: cleanHelixPostObservationDraftText(text, args.transcript),
    artifact_refs: [],
    receipt_refs: [],
    coverage_refs: [],
    composer_input_refs: [`${args.turnId}:rich_model_only_concept_signal`],
    model_step_capability: "model.compose_model_only_concept_answer",
    output_budget: args.outputBudget,
    unsupported_claim_guard: {
      source_targeted: false,
      policy: "not_applicable",
    },
    assistant_answer: false,
    raw_content_included: false,
  });
  const testResponse = process.env.NODE_ENV === "test"
    ? process.env.HELIX_MODEL_ONLY_CONCEPT_FINAL_ANSWER_TEST_RESPONSE
    : undefined;
  try {
    let text = "";
    if (testResponse) {
      text = testResponse.trim();
    } else {
      let timeoutHandle: ReturnType<typeof setTimeout> | null = null;
      const timeoutMs = clampNumber(readNumber(process.env.HELIX_ASK_MODEL_ONLY_CONCEPT_COMPOSER_TIMEOUT_MS, 18_000), 1_000, 60_000);
      const result = await Promise.race([
        llmLocalHandler(
          {
            prompt: [
              "You are composing the final answer for a rich model-only concept prompt.",
              "Do not collapse this prompt into a single entity definition.",
              "Compose a clear conceptual synthesis from general knowledge only.",
              "Address the user's thesis, validate useful intuition, and correct misconceptions gently.",
              "Use sections when the prompt has multiple conceptual parts.",
              "If 'theory concept badge' may be an app-specific Helix feature, say app context would be needed for the badge itself; do not invent implementation details.",
              "Do not mention internal routing, tools, policies, debug state, or this instruction.",
              "Return final answer text only. Do not return JSON.",
              "",
              `Output budget: ${JSON.stringify(args.outputBudget)}`,
              `Concept packet: ${JSON.stringify(conceptPacket).slice(0, 9000)}`,
            ].join("\n"),
            max_tokens: args.outputBudget.max_tokens,
            temperature: 0.2,
            metadata: {
              kind: "helix.ask.model_only_concept_final_composer",
              output_budget: args.outputBudget,
              rich_model_only_concept_signal: args.richSignal,
            },
          },
          {
            sessionId: args.sessionId ?? undefined,
            traceId: `${args.traceId}:model_only_concept_final_draft`,
            personaId: args.personaId ?? "helix-ask-model-only-concept-composer",
          },
        ),
        new Promise<never>((_, reject) => {
          timeoutHandle = setTimeout(() => reject(new Error("model_only_concept_composer_timeout")), timeoutMs);
        }),
      ]);
      if (timeoutHandle) clearTimeout(timeoutHandle);
      text = String((result as { text?: unknown })?.text ?? "").trim();
    }
    if (text && !isAskTurnMetaFinalAnswerText(text) && !isAskTurnModelOnlyWorkspaceLeak(text)) {
      return buildDraft(text, "llm_model_only_concept_composer", null);
    }
    return buildDraft(fallbackText, "deterministic_receipt_fallback", "model_only_concept_composer_empty_or_invalid");
  } catch (error) {
    return buildDraft(
      fallbackText,
      "deterministic_receipt_fallback",
      error instanceof Error && error.message ? error.message.slice(0, 120) : "model_only_concept_composer_failed",
    );
  }
};

const hasConversationQuestionCue = (transcript: string): boolean => {
  const trimmed = transcript.trim();
  if (!trimmed) return false;
  if (HELIX_CONVERSATION_QUESTION_PUNCT_RE.test(trimmed)) return true;
  if (HELIX_CONVERSATION_CJK_DIRECT_QUESTION_RE.test(trimmed)) return true;
  const normalized = trimmed.toLowerCase();
  return HELIX_CONVERSATION_DIRECT_QUESTION_RE.test(normalized);
};

const HELIX_CONVERSATION_STOP_WORDS = new Set([
  "the",
  "and",
  "for",
  "with",
  "that",
  "this",
  "from",
  "what",
  "when",
  "where",
  "which",
  "would",
  "could",
  "should",
  "about",
  "there",
  "their",
  "them",
  "your",
  "into",
  "while",
  "have",
  "need",
  "then",
  "just",
  "like",
  "done",
  "does",
  "is",
  "are",
  "was",
  "were",
]);

const isConversationFillerTurn = (transcript: string): boolean => {
  const normalized = transcript.trim().toLowerCase();
  if (!normalized) return true;
  if (normalized.length <= 6) return true;
  const strippedLead = normalized.replace(HELIX_CONVERSATION_LEADING_FILLER_RE, "").trim();
  if (!strippedLead) return true;
  if (
    strippedLead.length >= 8 &&
    (HELIX_CONVERSATION_EXPLORATORY_RE.test(strippedLead) ||
      HELIX_CONVERSATION_OBSERVE_RE.test(strippedLead) ||
      HELIX_CONVERSATION_VERIFY_RE.test(strippedLead) ||
      HELIX_CONVERSATION_ACT_RE.test(strippedLead) ||
      hasConversationQuestionCue(strippedLead))
  ) {
    return false;
  }
  return (
    normalized.length <= 28 &&
    HELIX_CONVERSATION_FILLER_RE.test(normalized) &&
    strippedLead.length <= 6
  );
};

const isConversationExploratoryTurn = (transcript: string): boolean => {
  const normalized = transcript.trim().toLowerCase();
  if (!normalized) return false;
  if (HELIX_CONVERSATION_VERIFY_RE.test(normalized) || HELIX_CONVERSATION_ACT_RE.test(normalized)) {
    return false;
  }
  if (HELIX_CONVERSATION_OBSERVE_RE.test(normalized)) return true;
  if (HELIX_CONVERSATION_EXPLORATORY_RE.test(normalized)) return true;
  if (hasConversationQuestionCue(transcript) && transcript.trim().length >= 8) return true;
  if (normalized.length >= 20) return true;
  return false;
};

const extractConversationKnowns = (transcript: string): string[] => {
  const tokens = transcript.toLowerCase().match(/[a-z0-9][a-z0-9-]{2,}/g) ?? [];
  const knowns: string[] = [];
  for (const token of tokens) {
    if (HELIX_CONVERSATION_STOP_WORDS.has(token)) continue;
    if (knowns.includes(token)) continue;
    knowns.push(token);
    if (knowns.length >= 6) break;
  }
  return knowns;
};

const buildConversationExplorationPacket = (args: {
  transcript: string;
  mode: HelixConversationMode;
  routeReasonCode: HelixConversationRouteReasonCode;
}): HelixConversationExplorationPacket => {
  const topic = clipConversationText(args.transcript, 120);
  const knowns = extractConversationKnowns(args.transcript);
  const baseGoal =
    args.mode === "verify"
      ? "Validate the claim with explicit pass/fail evidence."
      : args.mode === "act"
        ? "Plan and execute the requested change with deterministic safety checks."
        : args.mode === "clarify"
          ? "Collect one concrete detail needed to continue."
          : "Explore the topic and assemble a grounded explanation.";
  const unknowns =
    args.mode === "verify"
      ? ["claim boundaries", "required evidence", "pass/fail threshold"]
      : args.mode === "act"
        ? ["target change scope", "safety constraints", "execution order"]
        : args.mode === "clarify"
          ? ["missing context detail", "user-specific constraint", "next concrete objective"]
          : ["mechanism details", "evidence anchors", "best next probe"];
  const evidenceNeeded =
    args.mode === "act"
      ? ["preflight checks", "affected files/modules", "post-change verification"]
      : ["citations or grounded references", "deterministic fail reasons", "next testable probe"];
  const nextProbe =
    args.mode === "verify"
      ? `Check whether "${topic}" is supported by explicit evidence and return pass/fail.`
      : args.mode === "act"
        ? `Convert "${topic}" into concrete execution steps and expected receipts.`
        : args.routeReasonCode === "suppressed:clarify_after_attempt1"
          ? `Ask one focused clarifier to unlock "${topic}".`
          : `Run observe-first reasoning for "${topic}" and surface the highest-signal next step.`;
  return {
    topic,
    goal: baseGoal,
    knowns,
    unknowns,
    evidence_needed: evidenceNeeded,
    next_probe: nextProbe,
  };
};

const normalizeConversationRouteDecision = (args: {
  transcript: string;
  classification: z.infer<typeof HelixConversationClassifierSchema>;
}): HelixConversationRouteDecision => {
  const normalized = args.transcript.trim().toLowerCase();
  const explicitVerify = HELIX_CONVERSATION_VERIFY_RE.test(normalized);
  const explicitAct = HELIX_CONVERSATION_ACT_RE.test(normalized);
  const directQuestion = hasConversationQuestionCue(args.transcript);
  const filler = isConversationFillerTurn(normalized);
  const exploratory = isConversationExploratoryTurn(normalized);
  const next = { ...args.classification };

  let routeReasonCode: HelixConversationRouteReasonCode = "suppressed:low_salience";
  let explorationTurn = false;

  if (isAskTurnSimpleConversationStatusCheck(args.transcript)) {
    next.mode = "clarify";
    next.dispatch_hint = false;
    next.clarify_needed = false;
    next.confidence = Math.max(next.confidence, 0.92);
    next.reason = "Simple conversation/status check routed to direct terminal.";
    routeReasonCode = "conversation:simple";
  } else if (explicitVerify) {
    next.mode = "verify";
    next.dispatch_hint = true;
    next.clarify_needed = false;
    next.confidence = Math.max(next.confidence, 0.82);
    routeReasonCode = "dispatch:verify";
  } else if (explicitAct) {
    next.mode = "act";
    next.dispatch_hint = true;
    next.clarify_needed = false;
    next.confidence = Math.max(next.confidence, 0.82);
    routeReasonCode = "dispatch:act";
  } else if (directQuestion) {
    next.mode = "observe";
    next.dispatch_hint = true;
    next.clarify_needed = false;
    next.confidence = Math.max(next.confidence, 0.78);
    next.reason = "Direct question routed to observe lane.";
    routeReasonCode = "dispatch:observe_explore";
    explorationTurn = true;
  } else if (filler) {
    next.mode = "clarify";
    next.dispatch_hint = false;
    next.clarify_needed = false;
    next.confidence = Math.max(next.confidence, 0.72);
    next.reason = "Low-information filler/ack turn.";
    routeReasonCode = "suppressed:filler";
  } else if (exploratory) {
    next.mode = "observe";
    next.dispatch_hint = true;
    next.clarify_needed = false;
    next.confidence = Math.max(next.confidence, 0.72);
    routeReasonCode = "dispatch:observe_explore";
    explorationTurn = true;
  } else if (next.mode === "clarify") {
    next.mode = "observe";
    next.dispatch_hint = true;
    next.clarify_needed = false;
    next.confidence = Math.max(next.confidence, 0.58);
    next.reason = "Clarifier deferred until after first exploration attempt.";
    routeReasonCode = "dispatch:observe_explore";
    explorationTurn = true;
  } else if (next.mode === "verify") {
    next.dispatch_hint = true;
    next.clarify_needed = false;
    routeReasonCode = "dispatch:verify";
  } else if (next.mode === "act") {
    next.dispatch_hint = true;
    next.clarify_needed = false;
    routeReasonCode = "dispatch:act";
  } else if (next.mode === "observe" && next.dispatch_hint) {
    routeReasonCode = "dispatch:observe";
  } else if (next.mode === "observe") {
    next.dispatch_hint = exploratory || normalized.length >= 18;
    next.clarify_needed = false;
    routeReasonCode = next.dispatch_hint ? "dispatch:observe_explore" : "suppressed:low_salience";
    explorationTurn = next.dispatch_hint;
  } else {
    next.dispatch_hint = false;
    next.clarify_needed = false;
    routeReasonCode = "suppressed:low_salience";
  }

  const explorationPacket = buildConversationExplorationPacket({
    transcript: args.transcript,
    mode: next.mode,
    routeReasonCode,
  });
  return {
    classification: next,
    routeReasonCode,
    explorationTurn,
    clarifierPolicy: "after_first_attempt",
    explorationPacket,
  };
};

type HelixConversationPendingInputKind = "clarify" | "confirm";
type HelixAskTurnTransitionErrorCode =
  | "turn_transition_pending_abort"
  | "turn_transition_pending_expired"
  | "turn_transition_invalid_pending_resolution"
  | "turn_transition_double_terminal"
  | "turn_transition_execute_before_plan";

type HelixConversationPendingInputRecord = {
  turnId: string;
  requestId: string;
  kind: HelixConversationPendingInputKind;
  reason: HelixConversationRouteReasonCode;
  prompt: string;
  createdAtMs: number;
  requiredFields?: string[];
  unresolvedFields?: string[];
  candidateAction?: HelixAskTurnSelectedAction | null;
  status?: "pending" | "resolved" | "canceled" | "expired" | "aborted_turn_transition";
  pendingScope?: "artifact_gate" | "action_args" | "confirm";
  resolutionOptions?: string[];
  candidateOptions?: Array<{
    rank: number;
    title: string | null;
    path: string;
    validationStatus?: string | null;
    evidenceSnippet?: string | null;
  }>;
  originIntentHash?: string | null;
  originActionFamily?: string | null;
  expiresAtMs?: number;
};

const helixConversationPendingInputBySession = new Map<string, HelixConversationPendingInputRecord>();
const helixAskEquationExtractionAttemptBySession = new Map<
  string,
  {
    artifact_id: string;
    turn_id: string;
    payload: Record<string, unknown>;
    stored_at_ms: number;
  }
>();
export const __testHelixAskPendingInputStore = {
  set(sessionId: string, record: Record<string, unknown>): void {
    helixConversationPendingInputBySession.set(sessionId, record as HelixConversationPendingInputRecord);
  },
  delete(sessionId: string): void {
    helixConversationPendingInputBySession.delete(sessionId);
  },
};
type HelixAskTurnReasoningContextMode = "attached" | "isolated";
type HelixAskTurnWorkspaceActionLedgerEntry = {
  turn_id: string | null;
  trace_id: string | null;
  step_id: string | null;
  panel_id: string;
  action_id: string;
  args: Record<string, unknown>;
  status: string;
  at_ms: number;
};
type HelixAskTurnWorkspaceSessionSnapshot = {
  sessionId: string;
  activePanel:
    | "docs-viewer"
    | "workstation-notes"
    | "workstation-clipboard-history"
    | "situation-room-sources"
    | "situation-room-pipelines"
    | null;
  activeDocPath: string | null;
  source?: string | null;
  visual_context_capability?: Record<string, unknown> | null;
  attached_visual_evidence?: Record<string, unknown> | null;
  activeNoteId?: string | null;
  activeNoteTitle: string | null;
  activeNoteBody?: string | null;
  lastCreatedNoteId?: string | null;
  lastCreatedNoteTitle?: string | null;
  lastCreatedNoteBody?: string | null;
  recentNotes?: Array<{ id?: string | null; title: string; body?: string | null }>;
  hasDocContext: boolean;
  docContextValid?: boolean;
  docContextPath?: string | null;
  docContextSource?: string | null;
  docContextFailureReason?: string | null;
  preservationReason?: string | null;
  hasNoteContext: boolean;
  hasSituationRoomContext?: boolean;
  situationRoomContext?: Record<string, unknown> | null;
  hasClipboardContext: boolean;
  lastWorkspaceAction: HelixAskTurnSelectedAction | null;
  workspaceActionLedger?: HelixAskTurnWorkspaceActionLedgerEntry[];
  lastUpdatedAtMs: number;
};

const buildHelixToolSurfaceForAskTurn = (args: {
  turnId: string;
  transcript: string;
  workspaceSnapshot?: HelixAskTurnWorkspaceSessionSnapshot | null;
  explicitToolIntent?: boolean;
}) => buildHelixToolSurfacePacket({
  turnId: args.turnId,
  prompt: args.transcript,
  activePanels: args.workspaceSnapshot?.activePanel ? [args.workspaceSnapshot.activePanel] : [],
  focusedPanelId: args.workspaceSnapshot?.activePanel ?? null,
  explicitAttachmentAvailable: Boolean(
    args.workspaceSnapshot?.hasDocContext ||
      args.workspaceSnapshot?.hasSituationRoomContext ||
      args.workspaceSnapshot?.hasClipboardContext ||
      args.workspaceSnapshot?.attached_visual_evidence,
  ),
  explicitToolIntent: args.explicitToolIntent,
  allowMutatingWithoutConfirmation: false,
});

const helixAskTurnWorkspaceSnapshotBySession = new Map<string, HelixAskTurnWorkspaceSessionSnapshot>();
const helixAskTurnLastOpenedDocPathBySession = new Map<string, string>();
const HELIX_ASK_WORKSPACE_ACTION_LEDGER_LIMIT = 20;

const normalizeAskTurnWorkspaceActionLedger = (value: unknown): HelixAskTurnWorkspaceActionLedgerEntry[] => {
  if (!Array.isArray(value)) return [];
  const entries: HelixAskTurnWorkspaceActionLedgerEntry[] = [];
  for (const rawEntry of value) {
    if (!rawEntry || typeof rawEntry !== "object") continue;
    const entry = rawEntry as Record<string, unknown>;
    const panelId = typeof entry.panel_id === "string" && entry.panel_id.trim() ? entry.panel_id.trim() : null;
    const actionId = typeof entry.action_id === "string" && entry.action_id.trim() ? entry.action_id.trim() : null;
    if (!panelId || !actionId) continue;
    const args = entry.args && typeof entry.args === "object" && !Array.isArray(entry.args)
      ? (entry.args as Record<string, unknown>)
      : {};
    entries.push({
      turn_id: typeof entry.turn_id === "string" && entry.turn_id.trim() ? entry.turn_id.trim() : null,
      trace_id: typeof entry.trace_id === "string" && entry.trace_id.trim() ? entry.trace_id.trim() : null,
      step_id: typeof entry.step_id === "string" && entry.step_id.trim() ? entry.step_id.trim() : null,
      panel_id: panelId,
      action_id: actionId,
      args,
      status: typeof entry.status === "string" && entry.status.trim() ? entry.status.trim() : "completed",
      at_ms: typeof entry.at_ms === "number" && Number.isFinite(entry.at_ms) ? entry.at_ms : Date.now(),
    });
  }
  return entries
    .sort((a, b) => a.at_ms - b.at_ms)
    .slice(-HELIX_ASK_WORKSPACE_ACTION_LEDGER_LIMIT);
};

const dedupeAskTurnWorkspaceActionLedger = (
  entries: HelixAskTurnWorkspaceActionLedgerEntry[],
): HelixAskTurnWorkspaceActionLedgerEntry[] => {
  const seen = new Set<string>();
  const result: HelixAskTurnWorkspaceActionLedgerEntry[] = [];
  for (const entry of entries.sort((a, b) => a.at_ms - b.at_ms)) {
    const key = [
      entry.turn_id ?? "",
      entry.trace_id ?? "",
      entry.step_id ?? "",
      entry.panel_id,
      entry.action_id,
      JSON.stringify(entry.args ?? {}),
    ].join("|");
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(entry);
  }
  return result.slice(-HELIX_ASK_WORKSPACE_ACTION_LEDGER_LIMIT);
};

const readAskTurnLatestLedgerAction = (
  ledger: HelixAskTurnWorkspaceActionLedgerEntry[] | undefined,
): HelixAskTurnSelectedAction | null => {
  const latest = (ledger ?? []).filter((entry) => entry.status === "completed").at(-1);
  return latest ? { panel_id: latest.panel_id, action_id: latest.action_id, args: latest.args } : null;
};

const hasValidAskTurnDocContext = (snapshot?: HelixAskTurnWorkspaceSessionSnapshot | null): boolean =>
  Boolean(normalizeAskTurnWorkspaceDocPath(snapshot?.activeDocPath));

const deriveAskTurnNoteTitleFromId = (id: unknown): string | null => {
  if (typeof id !== "string") return null;
  const match = id.trim().match(/^note:(.+)$/i);
  const slug = match?.[1]?.trim();
  if (!slug) return null;
  const title = slug.replace(/[-_]+/g, " ").replace(/\s+/g, " ").trim();
  return title || null;
};

const normalizeAskTurnWorkspaceNoteTitleValue = (title: unknown, id: unknown): string | null => {
  const raw = typeof title === "string" && title.trim() ? title.trim() : null;
  if (raw && !isAskTurnDeicticNoteLabel(raw)) return raw;
  return deriveAskTurnNoteTitleFromId(id);
};

const HELIX_ASK_TURN_NOTE_BODY_CONTEXT_MAX_CHARS = 12000;

const normalizeAskTurnWorkspaceNoteBodyValue = (value: unknown): string | null => {
  if (typeof value !== "string") return null;
  const normalized = value.trim();
  if (!normalized) return null;
  return normalized.slice(0, HELIX_ASK_TURN_NOTE_BODY_CONTEXT_MAX_CHARS);
};

const normalizeAskTurnWorkspaceRecentNotes = (
  value: unknown,
): Array<{ id?: string | null; title: string; body?: string | null }> => {
  if (!Array.isArray(value)) return [];
  const out: Array<{ id?: string | null; title: string; body?: string | null }> = [];
  const seen = new Set<string>();
  for (const entry of value) {
    const record = entry && typeof entry === "object" ? (entry as Record<string, unknown>) : {};
    const id =
      typeof record.id === "string" && record.id.trim()
        ? record.id.trim()
        : typeof record.note_id === "string" && record.note_id.trim()
          ? record.note_id.trim()
          : null;
    const title = normalizeAskTurnWorkspaceNoteTitleValue(record.title ?? record.note_title ?? record.name, id);
    if (!title) continue;
    const key = title.trim().toLowerCase();
    const body = normalizeAskTurnWorkspaceNoteBodyValue(record.body ?? record.content ?? record.text);
    if (seen.has(key)) {
      const existing = out.find((note) => note.title.trim().toLowerCase() === key);
      if (existing && !existing.body && body) existing.body = body;
      continue;
    }
    seen.add(key);
    out.push({ id, title, ...(body ? { body } : {}) });
  }
  return out;
};

const withAskTurnDocContextValidity = (
  snapshot: HelixAskTurnWorkspaceSessionSnapshot,
): HelixAskTurnWorkspaceSessionSnapshot => {
  const activeDocPath = normalizeAskTurnWorkspaceDocPath(snapshot.activeDocPath);
  const docContextValid = Boolean(activeDocPath);
  const source = activeDocPath
    ? (snapshot.docContextSource ?? snapshot.source ?? "active_doc_path")
    : (snapshot.source ?? "none");
  const hadDocContextClaim =
    snapshot.hasDocContext === true || snapshot.docContextFailureReason === "has_doc_context_without_active_doc_path";
  return {
    ...snapshot,
    activeDocPath,
    source,
    hasDocContext: docContextValid,
    docContextValid,
    docContextPath: activeDocPath,
    docContextSource: activeDocPath ? source : null,
    preservationReason:
      snapshot.preservationReason ??
      (activeDocPath ? "preserved_existing_context" : "missing_active_doc_path"),
    docContextFailureReason: activeDocPath
      ? null
      : hadDocContextClaim
        ? "has_doc_context_without_active_doc_path"
        : snapshot.activePanel === "docs-viewer"
          ? "docs_panel_open_without_active_doc_path"
          : "no_docs_panel_or_active_doc_path",
  };
};

const normalizeIncomingAskTurnWorkspaceSnapshot = (args: {
  sessionId: string | null;
  snapshot: unknown;
}): HelixAskTurnWorkspaceSessionSnapshot | null => {
  if (!args.snapshot || typeof args.snapshot !== "object") return null;
  const raw = args.snapshot as Record<string, unknown>;
  const activePanel =
    raw.activePanel === "docs-viewer" ||
    raw.activePanel === "workstation-notes" ||
    raw.activePanel === "workstation-clipboard-history" ||
    raw.activePanel === "situation-room-sources" ||
    raw.activePanel === "situation-room-pipelines"
      ? raw.activePanel
      : null;
  const activeDocPath = normalizeAskTurnWorkspaceDocPath(raw.activeDocPath);
  const rawSource =
    typeof raw.source === "string" && raw.source.trim()
      ? raw.source.trim()
      : typeof raw.docContextSource === "string" && raw.docContextSource.trim()
        ? raw.docContextSource.trim()
        : null;
  const activeNoteId = typeof raw.activeNoteId === "string" && raw.activeNoteId.trim() ? raw.activeNoteId.trim() : null;
  const lastCreatedNoteId = typeof raw.lastCreatedNoteId === "string" && raw.lastCreatedNoteId.trim() ? raw.lastCreatedNoteId.trim() : null;
  const activeNoteTitle = normalizeAskTurnWorkspaceNoteTitleValue(raw.activeNoteTitle, activeNoteId);
  const lastCreatedNoteTitle = normalizeAskTurnWorkspaceNoteTitleValue(raw.lastCreatedNoteTitle, lastCreatedNoteId);
  const activeNoteBody = normalizeAskTurnWorkspaceNoteBodyValue(
    raw.activeNoteBody ?? raw.activeNoteContent ?? raw.noteBody,
  );
  const lastCreatedNoteBody = normalizeAskTurnWorkspaceNoteBodyValue(
    raw.lastCreatedNoteBody ?? raw.lastCreatedNoteContent,
  );
  const recentNotes = normalizeAskTurnWorkspaceRecentNotes(raw.recentNotes ?? (raw.notes && typeof raw.notes === "object" ? (raw.notes as Record<string, unknown>).recentNotes : null));
  const situationRoomContext =
    raw.situationRoomContext && typeof raw.situationRoomContext === "object" && !Array.isArray(raw.situationRoomContext)
      ? (raw.situationRoomContext as Record<string, unknown>)
      : null;
  const visualContextCapability =
    raw.visual_context_capability && typeof raw.visual_context_capability === "object" && !Array.isArray(raw.visual_context_capability)
      ? (raw.visual_context_capability as Record<string, unknown>)
      : null;
  const attachedVisualEvidence =
    raw.attached_visual_evidence && typeof raw.attached_visual_evidence === "object" && !Array.isArray(raw.attached_visual_evidence)
      ? (raw.attached_visual_evidence as Record<string, unknown>)
      : null;
  const snapshot: HelixAskTurnWorkspaceSessionSnapshot = {
    sessionId:
      typeof raw.sessionId === "string" && raw.sessionId.trim()
        ? raw.sessionId.trim()
        : (args.sessionId ?? "anonymous"),
    activePanel,
    activeDocPath,
    source: rawSource ?? (activeDocPath ? "incoming_workspace_snapshot" : "none"),
    activeNoteId,
    activeNoteTitle,
    activeNoteBody,
    lastCreatedNoteId,
    lastCreatedNoteTitle,
    lastCreatedNoteBody,
    recentNotes,
    hasDocContext: raw.hasDocContext === true || Boolean(activeDocPath),
    docContextSource: rawSource ?? (activeDocPath ? "incoming_workspace_snapshot" : null),
    hasNoteContext: raw.hasNoteContext === true || Boolean(activeNoteTitle) || Boolean(lastCreatedNoteTitle),
    hasSituationRoomContext: raw.hasSituationRoomContext === true || Boolean(situationRoomContext),
    situationRoomContext,
    visual_context_capability: visualContextCapability,
    attached_visual_evidence: attachedVisualEvidence,
    hasClipboardContext: raw.hasClipboardContext === true,
    lastWorkspaceAction:
      raw.lastWorkspaceAction && typeof raw.lastWorkspaceAction === "object"
        ? (raw.lastWorkspaceAction as HelixAskTurnSelectedAction)
        : null,
    workspaceActionLedger: normalizeAskTurnWorkspaceActionLedger(raw.workspaceActionLedger),
    lastUpdatedAtMs: typeof raw.lastUpdatedAtMs === "number" ? raw.lastUpdatedAtMs : Date.now(),
  };
  return withAskTurnDocContextValidity(snapshot);
};

const mergeAskTurnWorkspaceSnapshots = (args: {
  incoming: HelixAskTurnWorkspaceSessionSnapshot | null;
  stored: HelixAskTurnWorkspaceSessionSnapshot | null;
}): HelixAskTurnWorkspaceSessionSnapshot | null => {
  if (!args.incoming) return args.stored ? withAskTurnDocContextValidity(args.stored) : null;
  if (!args.stored) {
    const lastOpenedDocPath = normalizeAskTurnWorkspaceDocPath(
      helixAskTurnLastOpenedDocPathBySession.get(args.incoming.sessionId),
    );
    if (lastOpenedDocPath && args.incoming.activePanel !== "docs-viewer") {
      return withAskTurnDocContextValidity({
        ...args.incoming,
        activeDocPath: lastOpenedDocPath,
        source: "last_opened_doc",
        preservationReason: "preserved_last_opened_doc_over_non_doc_panel_snapshot",
      });
    }
    return withAskTurnDocContextValidity(args.incoming);
  }
  const incomingDocPath = normalizeAskTurnWorkspaceDocPath(args.incoming.activeDocPath);
  const storedDocPath = normalizeAskTurnWorkspaceDocPath(args.stored.activeDocPath);
  const lastOpenedDocPath = normalizeAskTurnWorkspaceDocPath(
    helixAskTurnLastOpenedDocPathBySession.get(args.incoming.sessionId) ??
      helixAskTurnLastOpenedDocPathBySession.get(args.stored.sessionId),
  );
  const incomingDocPanelAuthoritative = args.incoming.activePanel === "docs-viewer";
  const incomingNotesPanelAuthoritative = args.incoming.activePanel === "workstation-notes";
  const activeDocPath = incomingDocPanelAuthoritative
    ? (incomingDocPath ?? lastOpenedDocPath ?? storedDocPath)
    : (lastOpenedDocPath ?? storedDocPath ?? incomingDocPath);
  const workspaceActionLedger = dedupeAskTurnWorkspaceActionLedger([
    ...(args.stored.workspaceActionLedger ?? []),
    ...(args.incoming.workspaceActionLedger ?? []),
  ]);
  const latestLedgerAction = readAskTurnLatestLedgerAction(workspaceActionLedger);
  const activeNoteId = incomingNotesPanelAuthoritative
    ? (args.incoming.activeNoteId ?? null)
    : (args.incoming.activeNoteId ?? args.stored.activeNoteId);
  const lastCreatedNoteId = incomingNotesPanelAuthoritative
    ? (args.incoming.lastCreatedNoteId ?? null)
    : (args.incoming.lastCreatedNoteId ?? args.stored.lastCreatedNoteId);
  const activeNoteBody = incomingNotesPanelAuthoritative
    ? (args.incoming.activeNoteBody ?? null)
    : (args.incoming.activeNoteBody ?? args.stored.activeNoteBody ?? null);
  const lastCreatedNoteBody = incomingNotesPanelAuthoritative
    ? (args.incoming.lastCreatedNoteBody ?? null)
    : (args.incoming.lastCreatedNoteBody ??
      args.stored.lastCreatedNoteBody ??
      null);
  const recentNotes = incomingNotesPanelAuthoritative
    ? normalizeAskTurnWorkspaceRecentNotes(args.incoming.recentNotes ?? [])
    : normalizeAskTurnWorkspaceRecentNotes([
        ...(args.incoming.recentNotes ?? []),
        ...(args.stored.recentNotes ?? []),
      ]);
  return withAskTurnDocContextValidity({
    ...args.stored,
    ...args.incoming,
    activeDocPath,
    activeNoteId,
    activeNoteTitle: incomingNotesPanelAuthoritative
      ? normalizeAskTurnWorkspaceNoteTitleValue(args.incoming.activeNoteTitle, activeNoteId)
      : (normalizeAskTurnWorkspaceNoteTitleValue(
          args.incoming.activeNoteTitle,
          activeNoteId,
        ) ??
        normalizeAskTurnWorkspaceNoteTitleValue(
          args.stored.activeNoteTitle,
          activeNoteId,
        )),
    activeNoteBody,
    lastCreatedNoteId,
    lastCreatedNoteTitle: incomingNotesPanelAuthoritative
      ? normalizeAskTurnWorkspaceNoteTitleValue(args.incoming.lastCreatedNoteTitle, lastCreatedNoteId)
      : (normalizeAskTurnWorkspaceNoteTitleValue(
          args.incoming.lastCreatedNoteTitle,
          lastCreatedNoteId,
        ) ??
        normalizeAskTurnWorkspaceNoteTitleValue(
          args.stored.lastCreatedNoteTitle,
          lastCreatedNoteId,
        )),
    lastCreatedNoteBody,
    recentNotes,
    source:
      activeDocPath && activeDocPath === incomingDocPath
        ? (args.incoming.source ?? "incoming_workspace_snapshot")
        : activeDocPath && activeDocPath === lastOpenedDocPath
          ? "last_opened_doc"
          : activeDocPath && activeDocPath === storedDocPath
            ? (args.stored.source ?? "server_session")
            : (args.incoming.source ?? args.stored.source ?? "none"),
    hasNoteContext: incomingNotesPanelAuthoritative
      ? args.incoming.hasNoteContext
      : args.incoming.hasNoteContext || args.stored.hasNoteContext,
    hasClipboardContext: args.incoming.hasClipboardContext || args.stored.hasClipboardContext,
    lastWorkspaceAction: latestLedgerAction ?? args.incoming.lastWorkspaceAction ?? args.stored.lastWorkspaceAction,
    workspaceActionLedger,
    preservationReason: args.incoming.preservationReason ?? args.stored.preservationReason,
    lastUpdatedAtMs: Math.max(args.incoming.lastUpdatedAtMs ?? 0, args.stored.lastUpdatedAtMs ?? 0, Date.now()),
  });
};

const buildAskTurnWorkspaceRefBinding = (args: {
  transcript: string;
  workspaceSnapshot?: HelixAskTurnWorkspaceSessionSnapshot | null;
}): Record<string, unknown> => {
  const normalized = args.transcript.trim().toLowerCase();
  const activeDocPath = normalizeAskTurnWorkspaceDocPath(args.workspaceSnapshot?.activeDocPath);
  const activeNoteTitle = resolveAskTurnWorkspaceNoteTitle(args.workspaceSnapshot);
  const activeNoteId =
    typeof args.workspaceSnapshot?.lastCreatedNoteId === "string" && args.workspaceSnapshot.lastCreatedNoteId.trim()
      ? args.workspaceSnapshot.lastCreatedNoteId.trim()
      : typeof args.workspaceSnapshot?.activeNoteId === "string" && args.workspaceSnapshot.activeNoteId.trim()
        ? args.workspaceSnapshot.activeNoteId.trim()
        : null;
  const deicticBindings: Record<string, string> = {};
  if (/\b(?:this|the|current|active)\s+(?:doc|document|paper)\b/.test(normalized)) {
    deicticBindings["active_doc_reference"] = activeDocPath ? "active_doc" : "missing_active_doc";
  }
  if (/\b(?:this|that|the|current|active)\s+(?:note|notepad)\b/.test(normalized)) {
    deicticBindings["active_note_reference"] = activeNoteTitle ? "active_note" : "missing_active_note";
  }
  const missing: string[] = [];
  if (Object.values(deicticBindings).includes("missing_active_doc")) missing.push("active_doc_path");
  if (Object.values(deicticBindings).includes("missing_active_note")) missing.push("active_note");
  return {
    activeDocPath,
    activeDocTitle: activeDocPath ? readAskTurnDocTitleForPath(activeDocPath) : null,
    activeDocSource: activeDocPath
      ? (args.workspaceSnapshot?.docContextSource ??
        args.workspaceSnapshot?.source ??
        "workspace_snapshot")
      : "none",
    activeNoteId,
    activeNoteTitle,
    activeNoteSource:
      activeNoteTitle && activeNoteTitle === args.workspaceSnapshot?.lastCreatedNoteTitle
        ? "last_created_note"
        : activeNoteTitle
          ? "active_note"
          : "none",
    deicticBindings,
    bindingConfidence: missing.length === 0 ? "high" : "low",
    ambiguityReason: missing.length > 0 ? `missing:${missing.join(",")}` : null,
  };
};
