const resolveAskTurnSituationTargetLanguage = (transcript: string): string | null => {
  const normalized = transcript.trim();
  if (/\b(?:spanish|español|es)\b/i.test(normalized)) return "es";
  if (/\b(?:english|en)\b/i.test(normalized)) return "en";
  if (/\b(?:french|français|fr)\b/i.test(normalized)) return "fr";
  if (/\b(?:german|deutsch|de)\b/i.test(normalized)) return "de";
  const targetMatch = normalized.match(/\b(?:to|into|target(?:\s+language)?(?:\s+is)?|language)\s+([a-z]{2,8})\b/i);
  return targetMatch?.[1]?.trim().toLowerCase() ?? null;
};

const isAskTurnSituationRoomIntent = (transcript: string): boolean =>
  /\b(?:situation\s+room|room\s+sources?|source\s+manager|live\s+source\s+jobs?|pipelines?|translation\s+job|translate\s+job)\b/i.test(
    transcript,
  );

const isAskTurnMinecraftSituationGoalSessionIntent = (transcript: string): boolean => {
  const normalized = transcript.trim().toLowerCase();
  if (!normalized) return false;
  const hasQuestionPrefix = /^(?:what|what's|whats|how|why|am\s+i|are\s+we|should\s+i|should\s+we|can\s+you\s+(?:tell|summarize|explain|check)|tell\s+me)\b/.test(
    normalized,
  );
  const hasExplicitStartCue =
    /\b(?:start|enable|turn\s+on|set\s+up|attach|bind)\b/.test(normalized) ||
    /^(?:monitor|watch|stand\s+by|keep\s+watch)\b/.test(normalized) ||
    /\b(?:monitor|watch|stand\s+by|keep\s+watch)\s+(?:my|the|this|current)\s+(?:minecraft|minehut|mine\s*hut|server|world|game)\b/.test(
      normalized,
    );
  if (hasQuestionPrefix && !hasExplicitStartCue) return false;
  const hasMinecraftScope =
    /\b(?:minecraft|minehut|mine\s*hut|server|world)\b/.test(normalized) &&
    /\b(?:source|session|situation|monitor|watch|standby|dottie|danger|progress|game)\b/.test(
      normalized,
    );
  const hasSituationSessionCue =
    hasExplicitStartCue ||
    /\bonly\s+tell\s+me\b/.test(normalized);
  const hasGoalSessionPhrase =
    /\b(?:start|enable|set\s+up)\s+(?:a\s+)?situation\b/.test(normalized) ||
    /\bsituation\s+goal\s+session\b/.test(normalized);
  return hasSituationSessionCue && (hasMinecraftScope || (hasGoalSessionPhrase && /\bminecraft|minehut|mine\s*hut\b/.test(normalized)));
};

const buildAskTurnMinecraftSituationGoalSessionArgs = (args: {
  transcript: string;
  sessionId?: string | null;
}): Record<string, unknown> => {
  const normalized = args.transcript.trim().toLowerCase();
  const worldEventSourceMissing =
    /\bvisual[-\s]?only\b/.test(normalized) ||
    /\b(?:do\s+not|don't|without|no)\b[\s\S]{0,80}\b(?:minecraft\s+)?(?:plugin|world[-\s]?event|server\s+log|server\s+source|minecraft\s+source)\b/.test(normalized) ||
    /\b(?:minecraft\s+)?(?:plugin|world[-\s]?event|server\s+log|server\s+source|minecraft\s+source)\b[\s\S]{0,80}\b(?:not\s+attached|missing|unavailable|inactive)\b/.test(normalized);
  const standbyMode =
    /\bcritical\s+voice\b/.test(normalized)
      ? "critical_voice"
      : /\bvoice\s+on\s+confirm|confirm\s+(?:before\s+)?(?:voice|speaking|speak)\b/.test(normalized)
        ? "voice_on_confirm"
        : /\bdirect\s+address(?:\s+only)?\b/.test(normalized)
          ? "direct_address_only"
          : "text_only";
  const appendPolicy =
    /\bepisode|episodes|narrat(?:e|ion)|story\b/.test(normalized)
      ? "episodes_and_salience"
      : /\bcallout|callouts\b/.test(normalized)
        ? "callouts_only"
        : "salient_only";
  return {
    thread_id: "helix-ask:desktop",
    room_id: "room:minecraft-minehut",
    ...(worldEventSourceMissing
      ? {
          source_ids: [],
          source_id: null,
          world_id: null,
          world_event_source_status: "configured_missing",
          next_required_action: "attach_world_event_source",
        }
      : {
          source_id: "source:minecraft-server",
          world_id: "minecraft:minehut",
        }),
    objective:
      args.transcript.trim() ||
      "Monitor my Minecraft session and surface danger or meaningful progress.",
    standby_mode: standbyMode,
    append_policy: appendPolicy,
  };
};

const buildAskTurnSituationTranslateJobArgs = (transcript: string): Record<string, unknown> => {
  const targetLanguage = resolveAskTurnSituationTargetLanguage(transcript);
  return {
    kind: "translate",
    ...(targetLanguage ? { target_language: targetLanguage } : {}),
    input_text_policy: "source_text_preferred",
    output_render_policy: "target_language",
    attachment_policy: "manual_only",
    context_injection: "explicit_attachment_only",
    derived_outputs_auto_attach: false,
    command_lane_enabled: false,
  };
};

const isAskTurnSituationRoomTranslateJobIntent = (
  transcript: string,
): boolean => {
  const normalized = transcript.trim().toLowerCase();
  if (!isAskTurnSituationRoomIntent(normalized)) return false;
  const hasTranslateCue = /\b(?:translate|translation)\b/.test(normalized);
  const hasJobRoutingVerb = /\b(?:create|start|make|set\s+up|route|run)\b/.test(normalized);
  const hasJobOrPipelineCue = /\b(?:job|pipeline|pipelines|live\s+source\s+job|source\s+job)\b/.test(normalized);
  const hasSourceScope =
    /\b(?:current\s+room\s+source|room\s+source|situation\s+room\s+source|source\s+feed|live\s+source|active\s+source|selected\s+source)\b/.test(
      normalized,
    ) || /\busing\s+(?:the\s+)?(?:current\s+)?(?:room|source)\b/.test(normalized);
  return (
    hasTranslateCue &&
    hasJobRoutingVerb &&
    hasJobOrPipelineCue &&
    hasSourceScope
  );
};

const isAskTurnSituationRoomCompoundTranslateJobIntent = (transcript: string): boolean => {
  const normalized = transcript.trim().toLowerCase();
  if (!isAskTurnSituationRoomTranslateJobIntent(normalized)) return false;
  return /\b(?:open|show|view|launch)\b[\s\S]{0,140}\b(?:situation\s+room\s+sources|room\s+sources|source\s+manager)\b/.test(
    normalized,
  );
};

const isAskTurnLatestDocPathSpecificEnough = (topic: string, docPath: string | null): boolean => {
  if (!docPath) return false;
  const specificTokens = tokenizeAskTurnDocTopic(topic).filter((token) => token !== "nhm2");
  if (specificTokens.length === 0) return true;
  const haystack = docPath.toLowerCase();
  const hitCount = specificTokens.filter((token) => haystack.includes(token)).length;
  return hitCount >= Math.min(2, specificTokens.length);
};

type HelixAskLatestDocSelectionCandidate = {
  path: string;
  title: string | null;
  modified_at_ms: number | null;
  date_from_filename: string | null;
  matched_tokens: number;
  topic_score: number;
  recency_score: number;
  alias_latest: boolean;
  rank: number;
  reason: string;
};

type HelixAskLatestDocSelectionArtifact = {
  kind: "latest_doc_selection";
  topic: string;
  selected_path: string | null;
  selected_rank: number | null;
  selected_reason: string;
  confidence: "high" | "medium" | "low";
  candidates: HelixAskLatestDocSelectionCandidate[];
  conflicts: Array<{
    type: "alias_vs_newer_file" | "topic_tie" | "date_missing" | "ambiguous_topic";
    message: string;
    paths: string[];
  }>;
};

const extractAskTurnFilenameDate = (docPath: string): string | null => {
  const match = docPath.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
  return match ? `${match[1]}-${match[2]}-${match[3]}` : null;
};

const scoreAskTurnLatestDocCandidate = (tokens: string[], relPath: string, text: string): { score: number; matchedTokens: number } => {
  const pathText = relPath.toLowerCase();
  const bodyText = text.toLowerCase();
  let matchedTokens = 0;
  const score = tokens.reduce((sum, token) => {
    const matched = pathText.includes(token) || bodyText.includes(token);
    if (matched) matchedTokens += 1;
    const pathHit = pathText.includes(token) ? 3 : 0;
    const bodyHit = bodyText.includes(token) ? 2 : 0;
    return sum + pathHit + bodyHit;
  }, 0);
  return { score, matchedTokens };
};

const buildAskTurnLatestDocSelectionArtifact = (
  topic: string | null,
): HelixAskLatestDocSelectionArtifact | null => {
  if (!topic) return null;
  const tokens = tokenizeAskTurnDocTopic(topic);
  if (tokens.length === 0) return null;
  const docsRoot = path.resolve(process.cwd(), "docs");
  if (!fs.existsSync(docsRoot)) return null;
  const rawCandidates: Array<Omit<HelixAskLatestDocSelectionCandidate, "rank" | "reason">> = [];
  const visit = (dir: string) => {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        visit(full);
        continue;
      }
      if (!entry.isFile() || !/\.md$/i.test(entry.name)) continue;
      const rel = path.relative(process.cwd(), full).replace(/\\/g, "/");
      let mtimeMs = 0;
      try {
        mtimeMs = fs.statSync(full).mtimeMs;
      } catch {
        mtimeMs = 0;
      }
      let text = "";
      try {
        text = fs.readFileSync(full, "utf8");
      } catch {
        text = "";
      }
      const scored = scoreAskTurnLatestDocCandidate(tokens, rel, text.slice(0, 6000));
      const score = scored.score;
      if (score <= 0) continue;
      const route = normalizeAskTurnDocRoute(rel);
      const filenameDate = extractAskTurnFilenameDate(route);
      const titleMatch = text.match(/^\s*#\s+(.+)$/m);
      rawCandidates.push({
        path: route,
        title: titleMatch?.[1]?.trim() ?? null,
        modified_at_ms: mtimeMs || null,
        date_from_filename: filenameDate,
        matched_tokens: scored.matchedTokens,
        topic_score: score,
        recency_score: filenameDate ? Number(filenameDate.replace(/-/g, "")) : Math.floor(mtimeMs / 86_400_000),
        alias_latest: /\blatest\b/i.test(entry.name),
      });
    }
  };
  visit(docsRoot);
  if (rawCandidates.length === 0) {
    return {
      kind: "latest_doc_selection",
      topic,
      selected_path: null,
      selected_rank: null,
      selected_reason: "no_candidates",
      confidence: "low",
      candidates: [],
      conflicts: [
        {
          type: "ambiguous_topic",
          message: `No document candidates matched "${topic}".`,
          paths: [],
        },
      ],
    };
  }
  const maxMatchedTokens = Math.max(...rawCandidates.map((candidate) => candidate.matched_tokens));
  const maxTopicScore = Math.max(...rawCandidates.map((candidate) => candidate.topic_score));
  const eligible = rawCandidates.filter(
    (candidate) =>
      candidate.matched_tokens === maxMatchedTokens ||
      (candidate.matched_tokens >= Math.max(1, tokens.length - 1) && candidate.topic_score >= Math.max(1, maxTopicScore - 4)),
  );
  const rankedBase = [...eligible].sort(
    (a, b) =>
      b.matched_tokens - a.matched_tokens ||
      b.recency_score - a.recency_score ||
      b.topic_score - a.topic_score ||
      Number(a.alias_latest) - Number(b.alias_latest) ||
      a.path.localeCompare(b.path),
  );
  const eligiblePaths = new Set(eligible.map((candidate) => candidate.path));
  const rankedAll = [...rawCandidates].sort(
    (a, b) =>
      Number(eligiblePaths.has(b.path)) - Number(eligiblePaths.has(a.path)) ||
      b.matched_tokens - a.matched_tokens ||
      b.topic_score - a.topic_score ||
      b.recency_score - a.recency_score ||
      a.path.localeCompare(b.path),
  );
  const selected = rankedBase[0] ?? rankedAll[0] ?? null;
  const displayCandidates = selected
    ? [selected, ...rankedAll.filter((candidate) => candidate.path !== selected.path)]
    : rankedAll;
  const candidates: HelixAskLatestDocSelectionCandidate[] = displayCandidates
    .slice(0, 12)
    .map((candidate, index) => ({
      ...candidate,
      rank: index + 1,
      reason:
        candidate === selected
          ? "selected:newest_high_topic_match"
          : candidate.alias_latest
            ? "candidate:latest_alias"
            : "candidate:topic_recency_ranked",
    }));
  const selectedCandidate = selected
    ? (candidates.find((candidate) => candidate.path === selected.path) ?? null)
    : null;
  const conflicts: HelixAskLatestDocSelectionArtifact["conflicts"] = [];
  const aliasCandidates = candidates.filter((candidate) => candidate.alias_latest);
  for (const aliasCandidate of aliasCandidates) {
    const newer = candidates.find(
      (candidate) =>
        !candidate.alias_latest &&
        candidate.recency_score > aliasCandidate.recency_score &&
        candidate.matched_tokens >= Math.max(1, aliasCandidate.matched_tokens - 1),
    );
    if (newer) {
      conflicts.push({
        type: "alias_vs_newer_file",
        message: `${aliasCandidate.path} is a latest alias, but ${newer.path} is a newer similarly matching candidate.`,
        paths: [aliasCandidate.path, newer.path],
      });
    }
  }
  const topTwo = candidates.slice(0, 2);
  if (
    topTwo.length === 2 &&
    Math.abs(topTwo[0].topic_score - topTwo[1].topic_score) <= 1 &&
    Math.abs(topTwo[0].recency_score - topTwo[1].recency_score) <= 1
  ) {
    conflicts.push({
      type: "topic_tie",
      message: "Top latest-doc candidates are too close to choose without more context.",
      paths: topTwo.map((candidate) => candidate.path),
    });
  }
  const confidence: HelixAskLatestDocSelectionArtifact["confidence"] =
    !selectedCandidate
      ? "low"
      : conflicts.some((conflict) => conflict.type === "topic_tie")
        ? "medium"
        : selectedCandidate.topic_score >= Math.max(3, tokens.length * 3)
          ? "high"
          : "medium";
  return {
    kind: "latest_doc_selection",
    topic,
    selected_path: selectedCandidate?.path ?? null,
    selected_rank: selectedCandidate?.rank ?? null,
    selected_reason: selectedCandidate?.reason ?? "no_selected_candidate",
    confidence,
    candidates,
    conflicts,
  };
};

const resolveAskTurnLatestDocPathByTopic = (topic: string | null): string | null => {
  const selection = buildAskTurnLatestDocSelectionArtifact(topic);
  return selection?.selected_path ?? null;
};

const buildAskTurnLatestDocAcquisitionAction = (transcript: string): HelixAskTurnSelectedAction | null => {
  const topic = resolveAskTurnLatestDocTopicArg(transcript);
  if (!topic) return null;
  const selection = buildAskTurnLatestDocSelectionArtifact(topic);
  const path = selection?.selected_path ?? null;
  if (!path) return null;
  return {
    panel_id: "docs-viewer",
    action_id: "open_latest_doc_by_topic",
    args: {
      topic,
      ...(path ? { path } : {}),
      ...(selection?.selected_reason ? { selection_reason: selection.selected_reason } : {}),
    },
  };
};

const cleanAskTurnCompoundSourceQuery = (value: string): string => {
  let cleaned = value.trim();
  const mutationTailPatterns = [
    /\s+\band\s+(?:then\s+)?(?:drop|put|save|add|append|write|store|stash|file|park|place|copy)\b[\s\S]*$/i,
    /\s+\b(?:then|after\s+that|also)\s+(?:drop|put|save|add|append|write|store|stash|file|park|place|copy)\b[\s\S]*$/i,
    /\s+\b(?:to|into|in|inside)\s+(?:that|this|the|my|active|current)?\s*(?:note|notepad|scratch|memo|pad)\b[\s\S]*$/i,
    /\s*[.?!]\s+(?:answer|cite|include|use|reply)\b[\s\S]*$/i,
    /\s+\banswer\s+only\b[\s\S]*$/i,
    /\s+\bcite\s+(?:the\s+)?(?:document\s+)?evidence\b[\s\S]*$/i,
  ];
  for (const pattern of mutationTailPatterns) {
    cleaned = cleaned.replace(pattern, "").trim();
  }
  return cleaned
    .replace(/\b(?:that|this|the)\s+location\b$/i, "")
    .replace(/[,.?!;:]+$/g, "")
    .replace(/^["'`]+|["'`]+$/g, "")
    .trim();
};

const cleanAskTurnDocLocateQueryCandidate = (value: string): string => {
  const cleaned = cleanAskTurnCompoundSourceQuery(value)
    .replace(/\b(?:please\s+)?(?:answer|cite)\b[\s\S]*$/i, "")
    .trim();
  const alternatives = cleaned
    .split(/\s+\bor\s+/i)
    .map((entry) => cleanAskTurnCompoundSourceQuery(entry))
    .filter(Boolean);
  return alternatives[0] ?? cleaned;
};

const resolveAskTurnDocLocateQuery = (transcript: string): string | null => {
  const normalized = transcript
    .trim()
    .replace(/[?]+$/g, "")
    .replace(/\s+\b(?:and\s+then|then|after\s+that|also)\b[\s\S]*$/i, "");
  if (!normalized) return null;
  const equationQuery = buildAskTurnEquationRetrievalQuery(normalized);
  if (equationQuery) return equationQuery;
  const locateQueryFieldMatch = normalized.match(/^\s*Locate\s+query\s*:\s*["“]?([\s\S]*?)["”]?\s*$/im);
  const locateQueryField = locateQueryFieldMatch?.[1]?.trim();
  if (locateQueryField) {
    return locateQueryField;
  }
  const explicitQueryFieldMatch = normalized.match(
    /\b(?:with\s+)?query\s*:\s*["'`“”]?([\s\S]*?)(?:["'`“”]?\s*(?:\.|$)|\s+\b(?:return|answer|cite|explain|use)\b[\s\S]*$)/i,
  );
  const explicitQueryField = explicitQueryFieldMatch?.[1]?.trim();
  if (explicitQueryField) {
    const cleaned = cleanAskTurnDocLocateQueryCandidate(explicitQueryField);
    if (cleaned) return cleaned;
  }
  const docsPathFragment = String.raw`\/?docs\/[A-Za-z0-9_./-]+\.md`;
  const explicitDocSaysCues = [
    new RegExp(String.raw`\b(?:find|locate)\s+where\s+${docsPathFragment}\s+(?:says?|states?|mentions?|references?|cites?|talks?\s+about)\s+([\s\S]+)$`, "i"),
    new RegExp(String.raw`\bwhere\s+(?:does\s+)?${docsPathFragment}\s+(?:say|says|state|states|mention|mentions|reference|references|cite|cites|talk\s+about|talks\s+about)\s+([\s\S]+)$`, "i"),
  ];
  for (const cue of explicitDocSaysCues) {
    const query = normalized.match(cue)?.[1]?.trim();
    if (query) {
      const cleaned = cleanAskTurnDocLocateQueryCandidate(query);
      if (cleaned) return cleaned;
    }
  }
  const cues = [
    /\bexplain\s+what\s+(.+?)\s+means?\s+in\s+(?:this|that|the|current|active)\s+(?:doc|document|paper)\b/i,
    /\bfind\s+where\s+(.+?)\s+(?:is|are)\s+(?:found|located)\s+in\s+(?:the\s+)?current\s+(?:doc|dock)\b/i,
    /\bwhere\s+(?:is|are)\s+(.+?)\s+(?:found|located)\s+in\s+(?:the\s+)?current\s+(?:doc|dock)\b/i,
    /\bfind\s+(?:the\s+)?(?:part|bit|section)\s+where\s+(?:it|this|that|the\s+doc(?:ument)?|the\s+paper)?\s*(?:talks?\s+about|mentions?|references?|cites?|says?)\s+(.+?)(?:\s+\band\s+(?:drop|put|save|add|append|write|store|stash|file|park|place)\b[\s\S]*)?$/i,
    /\b(?:grab|pull|collect)\s+(?:the\s+)?(?:part|bit|section)\s+about\s+(.+?)(?:\s+\band\s+(?:drop|put|save|add|append|write|store|stash|file|park|place)\b[\s\S]*)?$/i,
    /\bfind\s+where\s+(?:it|this|that|the\s+doc(?:ument)?|the\s+paper)?\s*(?:says?|talks?\s+about|mentions?|references?|cites?)\s+(.+?)(?:\s+\band\s+(?:drop|put|save|add|append|write|store|stash|file|park|place)\b[\s\S]*)?$/i,
    /\bwhere\s+does\s+it\s+(?:mention|mentions|reference|references|cite|cites|say\s+about|talk\s+about)\s+(.+)$/i,
    /\bwhere\s+in\s+(?:this|that|the|current)?\s*(?:doc|document|paper)\s+does\s+it\s+talk\s+about\s+(.+)$/i,
    /\bwhere\s+does\s+(?:this|that|the|current)?\s*(?:doc|document|paper)\s+(?:mention|mentions|reference|references|cite|cites|say\s+about|talk\s+about)\s+(.+)$/i,
    /\bfind\s+where\s+(?:this|that|the|current)?\s*(?:doc|document|paper)\s+(?:talks?\s+about|mentions?|references?|cites?)\s+(.+)$/i,
    /\bfind\s+where\s+(.+?)\s+(?:is|are)\s+(?:mentioned|referenced|cited)\b/i,
    /\bwhere\s+in\s+(?:this|that|the|current)?\s*(?:doc|document|paper)\s+(?:is|are)\s+(.+?)\s+mentions?$/i,
    /\bwhere\s+(?:is|are)\s+(.+?)\s+(?:mentioned|referenced|cited)\s+in\s+(?:this|that|the|current)?\s*(?:doc|document|paper)\b/i,
    /\bwhere\s+in\s+(?:this|that|the|current)?\s*(?:doc|document|paper)\s+is\s+(.+)$/i,
    /\bfind\s+(.+)\s+in\s+(?:this|that|the|current)?\s*(?:doc|document|paper)\b/i,
    /\blocate\s+(.+)\s+in\s+(?:this|that|the|current)?\s*(?:doc|document|paper)\b/i,
    /\b(?:put|add|append|save|write|store|stash|file|park|place)\s+(.+?)\s+location\s+(?:to|into|in|inside)\b/i,
  ];
  for (const cue of cues) {
    const match = normalized.match(cue);
    const query = match?.[1]?.trim();
    if (query) {
      const cleaned = cleanAskTurnDocLocateQueryCandidate(query);
      if (cleaned) return cleaned;
    }
  }
  const exactAnchorSet = extractAskTurnExactAnchorSet({ turnId: "locate-query", transcript: normalized });
  if (exactAnchorSet.must_preserve.length > 0) {
    return exactAnchorSet.must_preserve.slice(0, 4).join(" ");
  }
  return null;
};

const HELIX_ASK_TURN_DOC_LOCATION_REMINDER_PLACEHOLDER = "{{doc_location_reminder_text}}";
const HELIX_ASK_TURN_DOC_SUMMARY_PLACEHOLDER = "{{doc_summary_text}}";

type AskTurnVoiceOutputIntentKind =
  | "none"
  | "interim_callout"
  | "document_read"
  | "answer_read"
  | "historical_or_conceptual_mention"
  | "muted";

type AskTurnVoiceOutputIntent = {
  kind: AskTurnVoiceOutputIntentKind;
  reasonCodes: string[];
  quotedText: string | null;
  calloutText: string | null;
  sideEffectContentGoal: string | null;
};

const extractAskTurnQuotedVoiceCalloutText = (transcript: string): string | null => {
  const matches = Array.from(transcript.matchAll(/["'`]([^"'`]{1,240})["'`]/g));
  for (const match of matches) {
    const quoted = match[1]?.replace(/\s+/g, " ").trim();
    if (!quoted) continue;
    if (/\b(?:live_env\.|voice\s+callout\s+tool|interim\s+voice|doc(?:ument)?\s+read\s+aloud|tool\s+policy)\b/i.test(quoted)) {
      continue;
    }
    return quoted;
  }
  return null;
};

const cleanAskTurnUnquotedVoiceCalloutText = (value: string | null | undefined): string | null => {
  const cleaned = String(value ?? "")
    .replace(/\s+/g, " ")
    .replace(/^[\s"'`:,.-]+|[\s"'`:,.-]+$/g, "")
    .trim();
  if (!cleaned) return null;
  if (cleaned.length < 2) return null;
  if (/\b(?:live_env\.|voice\s+callout\s+tool|interim\s+voice|tool\s+policy)\b/i.test(cleaned)) return null;
  return clipConversationText(cleaned, 96);
};

const extractAskTurnUnquotedVoiceCalloutText = (transcript: string): string | null => {
  const patterns: RegExp[] = [
    /\buse\s+(?:the\s+)?voice\s+lane\s+to\s+(?:say|speak|announce|read)\s+([\s\S]{2,220})/i,
    /\bsay\s+([\s\S]{2,220}?)\s+(?:out\s*loud|outloud|aloud|through\s+(?:the\s+)?voice\s+lane|via\s+(?:the\s+)?voice\s+lane)\b/i,
    /\bspeak\s+([\s\S]{2,220}?)\s+(?:out\s*loud|outloud|aloud|through\s+(?:the\s+)?voice\s+lane|via\s+(?:the\s+)?voice\s+lane)\b/i,
    /\bread\s+([\s\S]{2,220}?)\s+(?:out\s*loud|outloud|aloud|through\s+(?:the\s+)?voice\s+lane|via\s+(?:the\s+)?voice\s+lane)\b/i,
    /\bannounce\s+([\s\S]{2,220})/i,
    /\btell\s+me\s+out\s*loud\s+([\s\S]{2,220})/i,
    /\bsay\s+this\s+through\s+voice\s*:?\s*([\s\S]{2,220})/i,
    /\bmake\s+(?:a\s+)?voice\s+callout\s+saying\s+([\s\S]{2,220})/i,
  ];
  for (const pattern of patterns) {
    const match = transcript.match(pattern);
    const raw = match?.[1];
    if (!raw) continue;
    const beforeConnector = raw.split(
      /\b(?:then|and\s+then|after\s+that|before\s+you|while\s+you|but\s+also|also)\b/i,
    )[0];
    const cleaned = cleanAskTurnUnquotedVoiceCalloutText(beforeConnector);
    if (cleaned) return cleaned;
  }
  return null;
};

type AskTurnVoiceSideEffectCompoundGoal = {
  calloutText: string;
  contentGoal: string;
  reasonCodes: string[];
};

const hasAskTurnNegatedVoiceCommandPrefix = (transcript: string): boolean =>
  /\b(?:do\s+not|don't|dont|never|no)\b[\s\S]{0,80}\b(?:use\s+(?:the\s+)?voice\s+lane|voice\s+lane\s+to\s+(?:say|speak|announce|read)|speak|say|announce|callout)\b/i.test(transcript);

const cleanAskTurnVoiceSideEffectContentGoal = (value: string | null | undefined): string | null => {
  const cleaned = String(value ?? "")
    .replace(/\s+/g, " ")
    .replace(/^[\s"'`:,.-]+|[\s"'`:,.-]+$/g, "")
    .trim();
  if (cleaned.length < 8) return null;
  if (/^(?:do\s+not|don't|dont)\s+make\s+(?:the\s+)?final\s+answer\s+about\s+(?:the\s+)?voice\s+tool\.?$/i.test(cleaned)) {
    return null;
  }
  return clipConversationText(cleaned, 420);
};

const extractAskTurnVoiceSideEffectCompoundGoal = (transcript: string): AskTurnVoiceSideEffectCompoundGoal | null => {
  const text = transcript.trim();
  if (!text || hasAskTurnNegatedVoiceCommandPrefix(text)) return null;
  const connectorPatterns: RegExp[] = [
    /\buse\s+(?:the\s+)?voice\s+lane\s+to\s+(?:say|speak|announce|read)\s+([\s\S]{2,180}?)\s+(?:then|and\s+then|after\s+that)\s+([\s\S]{8,})/i,
    /\b(?:say|speak|announce|read)\s+([\s\S]{2,180}?)\s+(?:out\s*loud|outloud|aloud|through\s+(?:the\s+)?voice\s+lane|via\s+(?:the\s+)?voice\s+lane)\s*(?:,|;)?\s*(?:then|and\s+then|after\s+that)\s+([\s\S]{8,})/i,
  ];
  for (const pattern of connectorPatterns) {
    const match = text.match(pattern);
    const calloutText = cleanAskTurnUnquotedVoiceCalloutText(match?.[1]);
    const contentGoal = cleanAskTurnVoiceSideEffectContentGoal(match?.[2]);
    if (calloutText && contentGoal) {
      return {
        calloutText,
        contentGoal,
        reasonCodes: ["compound_voice_side_effect", "content_goal_preserved"],
      };
    }
  }
  const sentencePattern =
    /\buse\s+(?:the\s+)?voice\s+lane\s+to\s+(?:say|speak|announce|read)\s+([^.!?]{2,180})[.!?]\s+(?:(?:do\s+not|don't|dont)\s+make\s+(?:the\s+)?final\s+answer\s+about\s+(?:the\s+)?voice\s+tool[.!?]\s+)?([\s\S]{8,})/i;
  const sentenceMatch = text.match(sentencePattern);
  const sentenceCallout = cleanAskTurnUnquotedVoiceCalloutText(sentenceMatch?.[1]);
  const sentenceContent = cleanAskTurnVoiceSideEffectContentGoal(sentenceMatch?.[2]);
  if (sentenceCallout && sentenceContent) {
    return {
      calloutText: sentenceCallout,
      contentGoal: sentenceContent,
      reasonCodes: ["compound_voice_side_effect", "content_goal_preserved", "presentation_constraint_not_voice_mute"],
    };
  }
  return null;
};

const classifyAskTurnVoiceOutputIntent = (transcript: string): AskTurnVoiceOutputIntent => {
  const text = transcript.trim();
  const quotedText = extractAskTurnQuotedVoiceCalloutText(text);
  const sideEffectCompound = extractAskTurnVoiceSideEffectCompoundGoal(text);
  const unquotedText = quotedText ? null : (sideEffectCompound?.calloutText ?? extractAskTurnUnquotedVoiceCalloutText(text));
  const calloutText = quotedText ?? unquotedText;
  const reasonCodes: string[] = [];
  const muted =
    /\b(?:do\s+not|don't|dont|without|avoid|never|no)\b[\s\S]{0,100}\b(?:voice|speak|say|read\s+(?:out\s+)?loud|out\s*loud|callout|announce|interim\s+voice)\b/i.test(text) ||
    /\b(?:mute|disable|turn\s+off|stop)\b[\s\S]{0,80}\b(?:voice|callout|read\s+aloud|speech)\b/i.test(text);
  if (muted && !sideEffectCompound) {
    return {
      kind: "muted",
      reasonCodes: ["voice_output_muted_or_negated"],
      quotedText,
      calloutText,
      sideEffectContentGoal: null,
    };
  }
  const contextualMention =
    (/\b(?:what\s+(?:does|did|is)|explain|describe|policy|meaning|mean|means|earlier|previous|quoted|phrase|debug)\b[\s\S]{0,140}\b(?:live_env\.request_interim_voice_callout|interim\s+voice\s+callout|voice\s+callout\s+tool|read\s+aloud|out\s*loud|voice\s+lane|voice\s+policy)\b/i.test(text) ||
      /\b(?:write|type|copy|quote|include)\s+(?:the\s+)?(?:sentence|phrase|words?)\b[\s\S]{0,160}\b(?:voice\s+lane|say|speak|announce|out\s*loud|aloud)\b/i.test(text) ||
      /\b(?:earlier|previously|last\s+time|we\s+tested|we\s+said)\b[\s\S]{0,180}\b(?:voice\s+lane|say|speak|announce|out\s*loud|aloud|callout)\b/i.test(text)) &&
    !/\b(?:with\s+the\s+voice\s+lane\s+active|voice\s+lane\s+active)\b[\s\S]{0,160}\b(?:use|request|queue|make|create|emit|record)\b[\s\S]{0,120}\b(?:live_env\.request_interim_voice_callout|interim\s+voice\s+callout|voice\s+callout|callout\s+saying)\b/i.test(text);
  if (contextualMention) {
    return {
      kind: "historical_or_conceptual_mention",
      reasonCodes: ["contextual_voice_output_reference"],
      quotedText,
      calloutText,
      sideEffectContentGoal: null,
    };
  }
  const explicitInterimCallout =
    /\blive_env\.request_interim_voice_callout\b/i.test(text) ||
    /\b(?:use|request|queue|make|create|emit|record)\b[\s\S]{0,140}\b(?:interim|provisional|immediate|quick|short|progress|status)?[\s\S]{0,80}\b(?:voice\s+)?callout\b/i.test(text) ||
    /\b(?:interim|provisional|immediate|quick|short|progress|status)\b[\s\S]{0,120}\b(?:voice\s+)?callout\b/i.test(text) ||
    /\b(?:callout|announce|speak|say)\b[\s\S]{0,80}\b(?:saying|that\s+says)\s*["'`]/i.test(text) ||
    /\b(?:use|through|via|with)\s+(?:the\s+)?voice\s+lane\b[\s\S]{0,120}\b(?:say|speak|announce|read)\b[\s\S]{0,40}["'`]/i.test(text) ||
    /\b(?:say|speak|announce|read)\b[\s\S]{0,40}["'`][^"'`]{1,240}["'`][\s\S]{0,80}\b(?:out\s*loud|aloud|through\s+(?:the\s+)?voice\s+lane|via\s+(?:the\s+)?voice\s+lane)\b/i.test(text) ||
    Boolean(unquotedText);
  if (explicitInterimCallout) {
    reasonCodes.push("voice_output_interim_callout_intent");
    if (quotedText) reasonCodes.push("quoted_callout_text");
    if (unquotedText) reasonCodes.push("unquoted_callout_text");
    if (sideEffectCompound) reasonCodes.push(...sideEffectCompound.reasonCodes);
    return {
      kind: "interim_callout",
      reasonCodes: uniqueAskTurnStrings(reasonCodes),
      quotedText,
      calloutText,
      sideEffectContentGoal: sideEffectCompound?.contentGoal ?? null,
    };
  }
  const documentRead =
    isAskTurnReadAloudRequested(text) &&
    /\b(?:this|that|current|active|open|doc|docs|document|paper|file|source|audit|artifact|NHM2|whitepaper|report)\b/i.test(text) &&
    !/\b(?:final\s+answer|answer\s+snapshot|assistant\s+answer|interim|provisional|callout)\b/i.test(text);
  if (documentRead) {
    return {
      kind: "document_read",
      reasonCodes: ["document_read_aloud_intent"],
      quotedText,
      calloutText,
      sideEffectContentGoal: null,
    };
  }
  if (/\b(?:read|speak|say|announce)\b[\s\S]{0,80}\b(?:final\s+answer|answer\s+snapshot|the\s+answer|your\s+answer)\b/i.test(text)) {
    return {
      kind: "answer_read",
      reasonCodes: ["answer_read_aloud_intent"],
      quotedText,
      calloutText,
      sideEffectContentGoal: null,
    };
  }
  return {
    kind: "none",
    reasonCodes: [],
    quotedText,
    calloutText,
    sideEffectContentGoal: null,
  };
};

const {
  isAskTurnDocsReadAloudIntent,
} = createAskTurnDocsReadAloudIntentReader({
  classifyAskTurnVoiceOutputIntent,
});

const HELIX_ASK_CAPABILITY_CATALOG_OBSERVATION_SCHEMA = "helix.capability_catalog_observation.v1" as const;
