const capabilityActionKey = (panelId: string, actionId: string): string => `${panelId}.${actionId}`;
const workspaceActionFamilyByKey = new Map(WORKSPACE_ACTION_REGISTRY.map((entry) => [entry.action_key, entry.family]));

const isAskTurnInformationReflectionAction = (
  action: (typeof WORKSTATION_DYNAMIC_TOOL_ACTIONS)[number],
): boolean => {
  const actionId = action.action_id;
  if (/^(?:identify|verify|read|search|locate|summarize|explain|get_|query_|filter_view|focus_node|export_svg)/i.test(actionId)) return true;
  if (actionId === "image_lens.focus_regions") return true;
  if (action.panel_id === "scientific-calculator" && ["ingest_latex", "solve_expression", "solve_with_steps"].includes(actionId)) return true;
  if (action.panel_id === "workstation-notes" && actionId === "list_notes") return true;
  return true;
};

const inferAskTurnAlignmentToolFamily = (
  action: (typeof WORKSTATION_DYNAMIC_TOOL_ACTIONS)[number] | (typeof RETIRED_WORKSTATION_DYNAMIC_TOOL_ACTIONS)[number],
): string => {
  const actionKey = capabilityActionKey(action.panel_id, action.action_id);
  const registryFamily = workspaceActionFamilyByKey.get(actionKey);
  if (registryFamily === "docs_viewer") return "docs_viewer";
  if (registryFamily === "calculator") return "calculator";
  if (registryFamily === "panel_control" || registryFamily === "notes" || registryFamily === "clipboard") return "workstation";
  if (registryFamily === "situation_room") return "retired_situation_room";
  if (action.panel_id.startsWith("situation-room")) return "retired_situation_room";
  if (action.panel_id === "repo-code") return "repo_code";
  if (action.panel_id === "internet-search" || action.panel_id === "scholarly-research") return "internet_search";
  if (action.panel_id === "docs-viewer") return "docs_viewer";
  if (action.panel_id === "scientific-calculator") return "calculator";
  if (action.panel_id === "live-answer-environment" || action.panel_id === "live_env") {
    if (/voice/i.test(action.action_id)) return "voice_delivery";
    if (/decision|checkpoint/i.test(action.action_id)) return "live_source_decision";
    return "live_source_mail";
  }
  if (action.panel_id === "mission-ethos") return "moral_graph_reflection";
  if (action.panel_id === "civilization-bounds-roadmap") return "civilization_bounds";
  if (action.panel_id === "image-lens") return "workstation_visual_reflection";
  return registryFamily ?? "workstation";
};

const buildAskTurnAlignmentAdmissionRule = (args: {
  kind: HelixAskWorkstationToolAlignmentKind;
  status: HelixAskWorkstationToolAlignmentStatus;
  toolFamily: string;
}): string => {
  if (args.status === "retired_or_legacy") {
    return "Do not admit as an active workstation action; explain the retired status or route to the replacement family.";
  }
  if (args.kind === "information_reflection") {
    return "Admit for evidence/reflection prompts only; return an observation with assistant_answer=false and require solver re-entry before any answer.";
  }
  if (args.toolFamily === "voice_delivery") {
    return "Admit only after a live-source decision requests voice delivery; voice receipts are control/status observations, not content answers.";
  }
  return "Admit only for an affirmative operator command; contextual, negated, future, historical, quoted, or screen-visible mentions are constraints, not execution.";
};

const buildAskTurnAlignmentRegressionPrompt = (args: {
  actionKey: string;
  kind: HelixAskWorkstationToolAlignmentKind;
  status: HelixAskWorkstationToolAlignmentStatus;
}): string =>
  args.status === "retired_or_legacy"
    ? `Is ${args.actionKey} still an active Helix Ask tool, and what replaced it?`
    : args.kind === "information_reflection"
      ? `Use ${args.actionKey} only as evidence and explain what observation would re-enter reasoning.`
      : `Run ${args.actionKey} only when I explicitly ask to change workstation state, and report the receipt as non-answer authority.`;

const buildAskTurnAlignmentTestCoverage = (toolFamily: string): HelixAskWorkstationToolAlignmentRow["test_coverage"] => {
  if (toolFamily === "capability_catalog") {
    return { status: "covered", evidence: ["server/__tests__/helix.ask.tool-family-contract.test.ts"] };
  }
  if (["calculator", "docs_viewer", "repo_code", "internet_search", "live_source_mail", "live_source_decision", "voice_delivery", "workstation"].includes(toolFamily)) {
    return {
      status: "partial",
      evidence: [
        "server/__tests__/helix.ask.tool-family-contract.test.ts",
        "server/__tests__/helix.ask.capability-plan-contract.test.ts",
        "server/__tests__/helix.ask.capability-lifecycle-ledger.test.ts",
      ],
    };
  }
  if (toolFamily === "retired_situation_room") {
    return { status: "partial", evidence: ["server/__tests__/helix.ask.workstation-dynamic-tools.test.ts"] };
  }
  return { status: "under_tested", evidence: ["No direct contract test mapped in this alignment reflection."] };
};

const buildAskTurnWorkstationToolAlignmentRow = (
  action: (typeof WORKSTATION_DYNAMIC_TOOL_ACTIONS)[number] | (typeof RETIRED_WORKSTATION_DYNAMIC_TOOL_ACTIONS)[number],
  status: HelixAskWorkstationToolAlignmentStatus,
): HelixAskWorkstationToolAlignmentRow => {
  const actionKey = capabilityActionKey(action.panel_id, action.action_id);
  const kind = status === "active" && isAskTurnInformationReflectionAction(action as (typeof WORKSTATION_DYNAMIC_TOOL_ACTIONS)[number])
    ? "information_reflection"
    : "utility";
  const toolFamily = inferAskTurnAlignmentToolFamily(action);
  const risk = action.risk ?? (kind === "utility" ? "medium" : "low");
  return {
    action_key: actionKey,
    panel_id: action.panel_id,
    action_id: action.action_id,
    title: action.title ?? null,
    tool_family: toolFamily,
    kind,
    mutating: kind === "utility" || Boolean(action.requires_confirmation) || risk === "medium" || risk === "high",
    risk,
    status,
    required_args: action.required_args ?? [],
    optional_args: action.optional_args ?? [],
    returns_artifact: action.returns_artifact !== false,
    admission_rule: buildAskTurnAlignmentAdmissionRule({ kind, status, toolFamily }),
    regression_prompt: buildAskTurnAlignmentRegressionPrompt({ actionKey, kind, status }),
    test_coverage: buildAskTurnAlignmentTestCoverage(toolFamily),
  };
};

const buildAskTurnWorkstationToolAlignmentReflection = (): HelixAskWorkstationToolAlignmentObservation => {
  const rows = [
    ...WORKSTATION_DYNAMIC_TOOL_ACTIONS.map((action) => buildAskTurnWorkstationToolAlignmentRow(action, "active")),
    ...RETIRED_WORKSTATION_DYNAMIC_TOOL_ACTIONS.map((action) => buildAskTurnWorkstationToolAlignmentRow(action, "retired_or_legacy")),
  ].sort((left, right) => left.action_key.localeCompare(right.action_key));
  const activeRows = rows.filter((row) => row.status === "active");
  const retiredRows = rows.filter((row) => row.status === "retired_or_legacy");
  const reflectionRows = rows.filter((row) => row.kind === "information_reflection");
  const utilityRows = rows.filter((row) => row.kind === "utility");
  const underTestedExamples = rows
    .filter((row) => row.test_coverage.status !== "covered")
    .slice(0, 12)
    .map((row) => `${row.action_key}:${row.test_coverage.status}`);
  return {
    schema: HELIX_ASK_WORKSTATION_TOOL_ALIGNMENT_SCHEMA,
    capability_key: HELIX_ASK_WORKSTATION_TOOL_ALIGNMENT_CAPABILITY,
    rows,
    summary: {
      active_rows: activeRows.length,
      retired_or_legacy_rows: retiredRows.length,
      information_reflection_rows: reflectionRows.length,
      utility_rows: utilityRows.length,
      active_panels: Array.from(new Set(activeRows.map((row) => row.panel_id))).sort(),
      explicit_contract_families: [
        "calculator",
        "internet_search",
        "repo_code",
        "docs_viewer",
        "workspace_directory",
        "workstation",
        "live_source_mail",
        "live_source_decision",
        "voice_delivery",
        "moral_graph_reflection",
        "civilization_bounds",
        "capability_catalog",
      ],
      under_tested_examples: underTestedExamples,
    },
    notes: [
      "Rows are generated from the shared workstation dynamic action registry and the retired action registry.",
      "Information-reflection rows produce evidence or context observations; utility rows change state or produce control/status receipts.",
      "Dottie-related Situation Room rows are legacy: Dottie is represented as preset/context behavior, while voice delivery uses the voice_delivery lane.",
    ],
    assistant_answer: false,
    terminal_eligible: false,
    raw_content_included: false,
  };
};

