const findAskTurnWorkstationToolEvaluationTerminal = (
  artifacts: HelixTurnArtifact[],
): { artifact: HelixTurnArtifact; text: string } | null => {
  for (let index = artifacts.length - 1; index >= 0; index -= 1) {
    const artifact = artifacts[index];
    if (artifact.kind !== "workstation_tool_evaluation") continue;
    const payload = readAskTurnArtifactPayloadRecord(artifact);
    if (payload?.ok === false) continue;
    const supportsGoal = readAskTurnString(payload?.supports_goal);
    if (supportsGoal && supportsGoal !== "true" && supportsGoal !== "partial") continue;
    const text = normalizeAskTurnArtifactText(payload);
    if (text) return { artifact, text };
  }
  return null;
};

