      turn_id: args.turnId,
      goal_kind: "active_doc_identity",
      answer_scope: "workspace_state",
      required_terminal_kind: "active_doc_identity",
      allows_workspace_context: true,
      allows_prior_artifacts: false,
      corpus_anchors: [],
      numeric_tokens: [],
      concept_tokens: [],
      confidence: "high",
