const isAskTurnVisualCaptureDescribeContractIntent = (transcript: string): boolean => {
  if (isAskTurnLiveSourceMailLoopIntent(transcript)) {
    return false;
  }
  if (isAskTurnNegatedIntervalScreenContextPrompt(transcript)) {
    return false;
  }
  return (
    /\b(?:describe|review|analy[sz]e|what\s+(?:do\s+you\s+)?see|what(?:'s|\s+is)\s+(?:happening|on|visible))\b[\s\S]{0,120}\b(?:live|visual|screen|display)\s+(?:capture|source|frame|screen)\b/i.test(
      transcript,
    ) ||
    /\b(?:live|visual|screen|display)\s+(?:capture|source|frame|screen)\b[\s\S]{0,120}\b(?:describe|review|analy[sz]e|see|happening|visible)\b/i.test(
      transcript,
    )
  );
};

const isTheoryFrontierSeedFinderPrompt = (prompt: string): boolean =>
  /\b(?:theory\s+frontier|frontier\s+seed|seed\s+finder|frontier\s+candidate|missing\s+intermediate\s+badges?|unresolved\s+semantic\s+regions?|in\s+between\s+(?:the\s+)?badges?|candidate\s+terrain|biome\s+fields?|probability\s+terrain|verified_frontier_yield_per_budget|frontier\s+projection)\b/i.test(prompt);

const isAskTurnNegatedIntervalScreenContextPrompt = (transcript: string): boolean =>
  isAskTurnVisualScreenTargetIntent(transcript) &&
  /\b(?:haven't|have\s+not|didn't|did\s+not|not\s+yet|not\s+started|without)\b[\s\S]{0,80}\b(?:interval|cadence|every\s+\d+\s*seconds?)\b/i.test(transcript);

const isAskTurnLiveIntervalContractIntent = (transcript: string): boolean =>
  /\b(?:set|change|update|configure)\b[\s\S]{0,80}\b(?:interval|cadence|rate)\b[\s\S]{0,80}\b(?:live|visual|capture|pipeline|source)\b/i.test(
    transcript,
  ) ||
  /\b(?:live|visual|capture|pipeline|source)\b[\s\S]{0,80}\b(?:interval|cadence|rate)\b[\s\S]{0,80}\b(?:set|change|update|configure)\b/i.test(
    transcript,
  );

const isAskTurnDebugDiagnosisContractIntent = (transcript: string): boolean => {
  const voiceOutputIntent = classifyAskTurnVoiceOutputIntent(transcript);
  if (voiceOutputIntent.kind === "interim_callout") return false;
  const explicitRuntimeArtifact =
    /\b(?:debug\s+(?:export|trace|facts?|payload|copy|evidence|log)|terminal_error_code|goal_satisfaction|agent\s+loop|tool\s+calls?|runtime\s+evidence|receipt|artifact)\b/i.test(
      transcript,
    );
  const diagnosticAction =
    /\b(?:why\s+did|why\s+was|what\s+called|what\s+(?:route|tool|capability|classifier)|review\s+the\s+error|what\s+went\s+wrong)\b/i.test(
      transcript,
    ) ||
    /\b(?:inspect|show|open|copy|review|analy[sz]e|diagnos(?:e|is)|explain|summari[sz]e|reason\s+from|given)\b[\s\S]{0,100}\b(?:debug\s+(?:export|trace|facts?|payload|copy|evidence|log)|trace|runtime|agent\s+loop|route|router|classifier|deterministic|tool\s+calls?|receipt|artifact|failure|error)\b/i.test(
      transcript,
    );
  return (
    explicitRuntimeArtifact ||
    diagnosticAction ||
    isWorkstationToolDiagnosticPrompt(transcript)
  );
};

const hasAskTurnDebugEvidenceTopicPhrase = (transcript: string): boolean =>
  /\b(?:debug\s+(?:export|trace|facts?|payload|copy|evidence|log)|console\s+debug|debug\s+console|terminal_error_code|goal_satisfaction|agent\s+loop|tool\s+calls?|runtime\s+evidence|receipt|artifact)\b/i.test(
    transcript,
  );

const isAskTurnExplicitCurrentRuntimeDebugEvidenceRequest = (transcript: string): boolean => {
  if (!hasAskTurnDebugEvidenceTopicPhrase(transcript)) return false;
  if (
    /\b(?:console\s+)?debug\s+check\b/i.test(transcript) &&
    /\banswer\b/i.test(transcript) &&
    !/\b(?:debug\s+(?:export|trace|facts?|payload|copy|evidence|log)|terminal_error_code|goal_satisfaction|tool\s+calls?|runtime\s+evidence|agent\s+loop|inspect|show|open|copy|review|analy[sz]e|diagnos(?:e|is)|read|export)\b/i.test(
      transcript.replace(/\b(?:console\s+)?debug\s+check\b/gi, ""),
    )
  ) {
    return false;
  }
  const currentTurnCue =
    /\b(?:current|this|latest|active|live|right\s+now|now|running|current\s+turn|this\s+turn|latest\s+turn|active\s+turn|the\s+turn)\b/i;
  const debugCue =
    /\b(?:debug\s+(?:export|trace|facts?|payload|copy|evidence|log)|console\s+debug|debug\s+console|terminal_error_code|goal_satisfaction|tool\s+calls?|runtime\s+evidence|agent\s+loop)\b/i;
  const inspectionVerb =
    /\b(?:inspect|show|open|copy|review|analy[sz]e|diagnos(?:e|is)|read|use|export|tell\s+me\s+what)\b/i;
  return (
    new RegExp(`${currentTurnCue.source}[\\s\\S]{0,120}${debugCue.source}`, "i").test(transcript) ||
    new RegExp(`${debugCue.source}[\\s\\S]{0,120}${currentTurnCue.source}`, "i").test(transcript) ||
    new RegExp(`${inspectionVerb.source}[\\s\\S]{0,120}${currentTurnCue.source}[\\s\\S]{0,120}${debugCue.source}`, "i").test(transcript) ||
    /\b(?:from|for)\s+(?:this|the\s+current|the\s+latest|the\s+active)\s+turn\b[\s\S]{0,120}\b(?:debug|trace|payload|tool\s+calls?|goal_satisfaction)\b/i.test(
      transcript,
    )
  );
};

