  /["'`][^"'`]*(?:live_env\.(?:read_live_source_mail|read_processed_live_source_mail|process_live_source_mail|record_live_source_mail_decision|configure_interpreter_profile|compare_mail_to_interpreter_profile)|read\s+live\s+source\s+mail|processed\s+mail|live[-\s]?source\s+mailbox|observer\s+mailbox|stage\s+play\s+mail|interpreter\s+profile|profile\s+note)[^"'`]*["'`]/i.test(transcript) ||
  /\b(?:in\s+the\s+future|future|later|eventually|if|when|before|after|would|could|might|hypothetically)\b[\s\S]{0,140}\b(?:live_env\.(?:read_live_source_mail|read_processed_live_source_mail|process_live_source_mail|record_live_source_mail_decision|configure_interpreter_profile|compare_mail_to_interpreter_profile)|read\s+live\s+source\s+mail|processed\s+mail|live[-\s]?source\s+mailbox|observer\s+mailbox|stage\s+play\s+mail|visual\s+summary\s+mail|interpreter\s+profile|profile\s+note)\b/i.test(transcript) ||
  /\b(?:screen|page|button|label|ui|text)\b[\s\S]{0,90}\b(?:says|shows|reads|contains|labeled|labelled|called|named)\b[\s\S]{0,120}\b(?:live_env\.(?:read_live_source_mail|read_processed_live_source_mail|process_live_source_mail|record_live_source_mail_decision|configure_interpreter_profile|compare_mail_to_interpreter_profile)|read\s+live\s+source\s+mail|processed\s+mail|live[-\s]?source\s+mailbox|observer\s+mailbox|stage\s+play\s+mail|visual\s+summary\s+mail|interpreter\s+profile|profile\s+note)\b/i.test(transcript) ||
  /\b(?:do\s+not|don't|dont|without|not\s+asking\s+to|for\s+now)\b[\s\S]{0,120}\b(?:run|execute|use|read|check|process|create|configure|apply|pause|archive|open|compile|compare)?\b[\s\S]{0,120}\b(?:live_env\.(?:read_live_source_mail|read_processed_live_source_mail|process_live_source_mail|record_live_source_mail_decision|configure_interpreter_profile|compare_mail_to_interpreter_profile)|read\s+live\s+source\s+mail|processed\s+mail|live[-\s]?source\s+mailbox|observer\s+mailbox|stage\s+play\s+mail|visual\s+summary\s+mail|interpreter\s+profile|profile\s+note)\b/i.test(transcript) ||
  /\b(?:explain|describe|what\s+does|what\s+is|what\s+are)\b[\s\S]{0,120}\b(?:live_env\.(?:read_live_source_mail|read_processed_live_source_mail|process_live_source_mail|record_live_source_mail_decision|configure_interpreter_profile|compare_mail_to_interpreter_profile)|read\s+live\s+source\s+mail|processed\s+mail|live[-\s]?source\s+mailbox|observer\s+mailbox|stage\s+play\s+mail|visual\s+summary\s+mail|interpreter\s+profile|profile\s+note)\b[\s\S]{0,80}\b(?:mean|means|for|do|does|is|are)\b/i.test(transcript);

