    /\b(?:wake\s+request|mail\s+refs?|source\s+mail|new\s+source\s+mail|live\s+source\s+mail|live-source\s+mail|observer\s+mailbox|active\s+visual\s+live-source\s+mailbox|latest\s+visual\s+summary\s+mail|stage\s+play\s+mail|visual\s+mail|visual\s+summary\s+mail|latest\s+visual\s+update|visual\s+update|source\s+update|mailbox|wait\s+for\s+next\s+summary)\b/i.test(transcript) ||
    /\b(?:read|check|watch|monitor|observe|use)\b[\s\S]{0,140}\b(?:live\s+source\s+mail|source\s+mail|new\s+source\s+mail|mailbox|mail\s+tool|visual\s+mail|visual\s+summary\s+mail|latest\s+visual\s+update|visual\s+update|source\s+update)\b/i.test(transcript) ||
    /\b(?:live\s+source\s+mail|source\s+mail|new\s+source\s+mail|mailbox|mail\s+tool|visual\s+mail|visual\s+summary\s+mail|latest\s+visual\s+update|visual\s+update|source\s+update)\b[\s\S]{0,140}\b(?:read|check|watch|monitor|observe|decision|decide|mail|show|shows|showing|contains?|reports?|changed|interpret)\b/i.test(transcript) ||
    /\b(?:read|check|watch|monitor|observe|use|process)\b[\s\S]{0,160}\b(?:live-source\s+mailbox|live\s+source\s+mailbox|observer\s+mailbox|stage\s+play\s+mail|latest\s+visual\s+summary\s+mail|visual\s+mail|visual\s+summary\s+mail|latest\s+visual\s+update|visual\s+update|source\s+update)\b/i.test(transcript) ||
    /\b(?:live-source\s+mailbox|live\s+source\s+mailbox|observer\s+mailbox|stage\s+play\s+mail|latest\s+visual\s+summary\s+mail|visual\s+mail|visual\s+summary\s+mail|latest\s+visual\s+update|visual\s+update|source\s+update)\b[\s\S]{0,160}\b(?:read|check|watch|monitor|observe|process|decision|decide|record|show|shows|showing|contains?|reports?|changed|interpret)\b/i.test(transcript);

const hasAskTurnLiveSourceMailInterpretationCue = (transcript: string): boolean => {
  if (isExplicitDocsPathDocumentOperation(transcript)) return false;
  const interpretationCue =
    /\b(?:interpret(?:ation)?|what\s+is\s+happening|what's\s+happening|what\s+happened|what\s+changed|changed|changes|compare|comparison|contract|observed\s+facts?|cautious\s+inferences?|separate\s+observed\s+facts|what\s+should\s+(?:be\s+)?watched\s+next|watch\s+next|what\s+to\s+watch\s+next|story\s+so\s+far|observations?\s+mean|predict(?:ion)?|might\s+happen\s+next|minecraft\s+video\s+predictor|record\s+an?\s+interpretation|summari[sz]e\s+the\s+story)\b/i;
  const sourceCue =
    /\b(?:mail|mailbox|summary|summaries|observation|observations|live\s+source|live-source|visual\s+source|visual\s+summary|screen\s+summary|source\s+update|watch\s+next|story\s+so\s+far|minecraft\s+video\s+predictor|contract)\b/i;
  return interpretationCue.test(transcript) && sourceCue.test(transcript);
};

const isAskTurnProcessedMailCheckpointIntent = (
  transcript: string,
): boolean => {
  if (!isAskTurnLiveSourceMailLoopIntent(transcript)) return false;
  if (isCompactUiMailboxWakePrompt(transcript)) return true;
  if (hasAskTurnVisualObserverProfileCue(transcript)) return false;
  if (hasAskTurnInterpreterProfileConfigCue(transcript)) return false;
  const processedMailCue =
    /\blive_env\.read_processed_live_source_mail\b/i.test(transcript) ||
    /\bstage_play_processed_mail_packet\b/i.test(transcript) ||
    /\b(?:processed\s+(?:live[-\s]?source\s+)?mail|processed\s+packet|visual\s+mail|latest\s+visual\s+update|new\s+source\s+mail)\b/i.test(transcript);
  return (
    processedMailCue || hasAskTurnLiveSourceMailInterpretationCue(transcript)
  );
};

const applyStagePlayMailWakeCanonicalGoalFrame = (
  frame: HelixAskCanonicalGoalFrame,
  routeMetadata?: StagePlayMailWakeRouteMetadata | null,
): HelixAskCanonicalGoalFrame => {
  if (routeMetadata?.invocationKind !== "stage_play_mail_wake") return frame;
  return {
    ...frame,
    goal_kind: "live_source_processed_mail_interpretation",
    answer_scope: "live_environment_state",
    required_terminal_kind: "model_synthesized_answer",
    allows_workspace_context: true,
    allows_prior_artifacts: true,
    concept_tokens: uniqueAskTurnStrings([
      ...frame.concept_tokens,
      "stage_play_mail_wake",
      routeMetadata.wakeRequestId,
      routeMetadata.requiredCanonicalGoal,
      ...(routeMetadata.evidenceRefs ?? []),
    ]),
    classifier_reasons: uniqueAskTurnStrings([
      ...frame.classifier_reasons,
      "stage_play_mail_wake_route_metadata",
      "live_source_mailbox_intent",
      "live_source_mail_loop_intent",
      "processed_mail_interpretation_goal",
      "prefer_read_processed_live_source_mail",
      routeMetadata.requiredCanonicalGoal === "processed_mail_voice_decision"
        ? "prefer_record_live_source_mail_decision"
        : "",
      routeMetadata.requiredPhase ? `live_source_phase:${routeMetadata.requiredPhase}` : "",
    ]),
    confidence: "high",
  };
};

const hardLiveSourceMailboxSourceTargetIntentFromWakeMetadata = (args: {
  turnId: string;
  threadId: string;
  routeMetadata: StagePlayMailWakeRouteMetadata;
  originalSourceTarget?: Record<string, unknown> | null;
}): ReturnType<typeof arbitrateAskSourceTarget> => {
  const original = args.originalSourceTarget ?? {};
  const originalReasons = Array.isArray(original.reasons)
    ? original.reasons.filter((entry): entry is string => typeof entry === "string")
    : [];
  const originalSuppressedRoutes = Array.isArray(original.suppressed_routes)
    ? original.suppressed_routes.filter((entry): entry is string => typeof entry === "string")
    : [];
  const originalRequestedOutputs = Array.isArray(original.requested_outputs)
    ? original.requested_outputs.filter((entry): entry is string => typeof entry === "string")
    : [];
  const allowedCapabilities = uniqueAskTurnStrings(args.routeMetadata.allowedCapabilities ?? []);
  const forbiddenCapabilities = uniqueAskTurnStrings(args.routeMetadata.forbiddenCapabilities ?? []);
  return {
    ...original,
    schema: "helix.ask_source_target_intent.v1",
    turn_id: args.turnId,
    thread_id: args.routeMetadata.mailboxThreadId || args.threadId,
    target_source: "live_source_mailbox",
    target_kind: "live_source_mailbox",
    targetSource: "live_source_mailbox",
    targetKind: "live_source_mailbox",
    strength: "hard",
    explicit_cues: uniqueAskTurnStrings([
      "stage_play_mail_wake_route_metadata",
      args.routeMetadata.wakeRequestId,
    ]),
    reasons: uniqueAskTurnStrings([
      ...originalReasons,
      "stage_play_mail_wake_route_metadata",
      "live_source_mailbox_route_metadata_authoritative",
      "live_source_mailbox_intent",
      "live_source_mail_loop_intent",
    ]),
    requested_outputs: uniqueAskTurnStrings([
      ...originalRequestedOutputs,
      "stage_play_live_source_mail_read_result",
      "stage_play_processed_mail_packet",
      "stage_play_live_source_mail_decision",
      "stage_play_live_source_narrative_state",
      "typed_failure",
    ]) as ReturnType<typeof arbitrateAskSourceTarget>["requested_outputs"],
    suppressed_routes: uniqueAskTurnStrings([
      ...originalSuppressedRoutes,
      ...forbiddenCapabilities,
      "situation_room.describe_visual_capture",
      "situation_context_question",
      "situation_context_pack",
      "visual_capture",
      "visual_deictic",
      "visual_frame_evidence",
      "visual_capture_describe",
      "active_doc_identity",
      "active_doc_summary",
      "doc_summary",
      "doc_open_best",
      "docs-viewer.search_docs",
      "docs-viewer.open",
      "docs-viewer.identify_current_doc",
      "repo-code.search_concept",
      "internet-search.search_web",
      "workspace_os.status",
      "conversation:simple",
      "model_only_concept",
      "no_tool_direct",
    ]),
    precedence_reason: "stage_play_mail_wake_route_metadata",
    must_enter_backend_ask: true,
    allow_client_shortcut: false,
    allow_no_tool_direct: false,
    mailbox_source_target_override: true,
    mailbox_source_target_original_target_source: readAskTurnString(original.target_source) ?? null,
    mailbox_source_target_original_target_kind: readAskTurnString(original.target_kind) ?? null,
    stage_play_mail_wake_route_metadata: {
      ...args.routeMetadata,
      allowedCapabilities,
      forbiddenCapabilities,
      evidenceRefs: uniqueAskTurnStrings(args.routeMetadata.evidenceRefs ?? []),
    },
    route_metadata_source: "request",
    assistant_answer: false,
    raw_content_included: false,
  } as ReturnType<typeof arbitrateAskSourceTarget>;
};

const coerceLiveSourceMailboxSourceTargetIntent = (args: {
  sourceTargetIntent: ReturnType<typeof arbitrateAskSourceTarget> | Record<string, unknown>;
  evidenceTargetArbitration?: Record<string, unknown> | null;
  transcript: string;
  turnId?: string | null;
  threadId?: string | null;
  routeMetadata?: StagePlayMailWakeRouteMetadata | null;
}): ReturnType<typeof arbitrateAskSourceTarget> => {
  const selectedEvidenceTargetSource = readAskTurnString(args.evidenceTargetArbitration?.selected_target_source);
  const originalSourceTarget =
    args.sourceTargetIntent && typeof args.sourceTargetIntent === "object" && !Array.isArray(args.sourceTargetIntent)
      ? (args.sourceTargetIntent as Record<string, unknown>)
      : {};
  if (isExplicitDocsPathDocumentOperation(args.transcript)) {
    return args.sourceTargetIntent as ReturnType<typeof arbitrateAskSourceTarget>;
  }
  if (args.routeMetadata?.invocationKind === "stage_play_mail_wake") {
    return hardLiveSourceMailboxSourceTargetIntentFromWakeMetadata({
      turnId: args.turnId ?? readAskTurnString(originalSourceTarget.turn_id) ?? "ask:stage-play-mail-wake",
      threadId: args.threadId ?? readAskTurnString(originalSourceTarget.thread_id) ?? args.routeMetadata.mailboxThreadId,
      routeMetadata: args.routeMetadata,
      originalSourceTarget,
    });
  }
  const originalTargetSource = readAskTurnString(originalSourceTarget.target_source);
  const mailboxAlreadyHard =
    originalTargetSource === "live_source_mailbox" &&
    originalSourceTarget.must_enter_backend_ask === true &&
    originalSourceTarget.allow_no_tool_direct === false;
  if (mailboxAlreadyHard) {
    return args.sourceTargetIntent as ReturnType<typeof arbitrateAskSourceTarget>;
  }
  const originalReasons = Array.isArray(originalSourceTarget.reasons)
    ? originalSourceTarget.reasons.filter((entry): entry is string => typeof entry === "string")
    : [];
  if (hasExecutableAskTurnMicroReasonerPresetCue(args.transcript)) {
    const originalRequestedOutputs = Array.isArray(originalSourceTarget.requested_outputs)
      ? originalSourceTarget.requested_outputs.filter((entry): entry is string => typeof entry === "string")
      : [];
    const originalSuppressedRoutes = Array.isArray(originalSourceTarget.suppressed_routes)
      ? originalSourceTarget.suppressed_routes.filter((entry): entry is string => typeof entry === "string")
      : [];
    return {
      ...originalSourceTarget,
      target_source: "live_environment",
      target_kind: "live_environment",
      targetSource: "live_environment",
      targetKind: "live_environment",
      strength: "hard",
      reasons: uniqueAskTurnStrings([
        ...originalReasons.filter((reason) => !/mailbox|internet|doc|repo/i.test(reason)),
        "explicit_micro_reasoner_deck_source_target",
      ]),
      requested_outputs: uniqueAskTurnStrings([
        ...originalRequestedOutputs,
        hasAskTurnMicroReasonerDraftCue(args.transcript)
          ? "stage_play_micro_reasoner_prompt_preset_draft"
          : hasAskTurnMicroReasonerPromptRouterCue(args.transcript)
          ? "stage_play_micro_reasoner_prompt_delegation_result"
          : "stage_play_micro_reasoner_prompt_preset_query_result",
        "live_environment_tool_observation",
        "model_synthesized_answer",
        "typed_failure",
      ]) as ReturnType<typeof arbitrateAskSourceTarget>["requested_outputs"],
      suppressed_routes: uniqueAskTurnStrings([
        ...originalSuppressedRoutes,
        "situation_room.describe_visual_capture",
        "visual_capture",
        "visual_deictic",
        "visual_frame_evidence",
        "visual_capture_describe",
        "live_pipeline_control",
        "active_doc_identity",
        "active_doc_summary",
        "doc_open_best",
        "docs-viewer.search_docs",
        "docs-viewer.open",
        "repo-code.search_concept",
        "internet-search.search_web",
        "workspace_os.status",
        "model_only_concept",
        "no_tool_direct",
      ]),
      precedence_reason: "explicit_micro_reasoner_deck_source_target",
      must_enter_backend_ask: true,
      allow_client_shortcut: false,
      allow_no_tool_direct: false,
      assistant_answer: false,
      raw_content_included: false,
    } as ReturnType<typeof arbitrateAskSourceTarget>;
  }
  if (
    selectedEvidenceTargetSource &&
    !["live_environment", "live_source_mailbox"].includes(selectedEvidenceTargetSource)
  ) {
    return args.sourceTargetIntent as ReturnType<typeof arbitrateAskSourceTarget>;
  }
  const explicitStagePlayReflectionRoute =
    isStagePlayReflectionPrompt(args.transcript) ||
    /\blive_env\.reflect_stage_play_context\b/i.test(args.transcript) ||
    /\bstage\s+play\s+reflection\s+capability\b/i.test(args.transcript) ||
    /\breflect\b[\s\S]{0,120}\bstage\s+play\s+badge\s+graph\b/i.test(args.transcript);
  if (explicitStagePlayReflectionRoute) {
    const originalSuppressedRoutes = Array.isArray(originalSourceTarget.suppressed_routes)
      ? originalSourceTarget.suppressed_routes.filter((entry): entry is string => typeof entry === "string")
      : [];
    return {
      ...originalSourceTarget,
      target_source: "live_environment",
      target_kind: "live_environment",
      targetSource: "live_environment",
      targetKind: "live_environment",
      strength: "hard",
      reasons: uniqueAskTurnStrings([
        ...originalReasons.filter((reason) => !/mailbox|mail_loop/i.test(reason)),
        "explicit_stage_play_reflection_source_target",
      ]),
      requested_outputs: [
        "stage_play_badge_graph",
        "stage_play_output_lane_projection",
        "stage_play_live_answer_projection",
        "typed_failure",
      ] as ReturnType<typeof arbitrateAskSourceTarget>["requested_outputs"],
      suppressed_routes: uniqueAskTurnStrings([
        ...originalSuppressedRoutes,
        "situation_room.describe_visual_capture",
        "visual_capture",
        "visual_deictic",
        "visual_frame_evidence",
        "visual_capture_describe",
        "live_pipeline_control",
        "active_doc_identity",
        "active_doc_summary",
        "doc_open_best",
        "docs-viewer.search_docs",
        "docs-viewer.open",
        "repo-code.search_concept",
        "internet-search.search_web",
        "workspace_os.status",
        "model_only_concept",
        "no_tool_direct",
      ]),
      precedence_reason: "explicit_stage_play_reflection_source_target",
      must_enter_backend_ask: true,
      allow_client_shortcut: false,
      allow_no_tool_direct: false,
      assistant_answer: false,
      raw_content_included: false,
    } as ReturnType<typeof arbitrateAskSourceTarget>;
  }
  const preservesLiveEnvironmentStagePlayRoute =
    originalTargetSource === "live_environment" &&
    (
      originalReasons.includes("explicit_stage_play_reflection_source_target") ||
      originalReasons.includes("explicit_stage_play_checkpoint_source_target") ||
      originalReasons.includes("explicit_stage_play_job_planning_source_target") ||
      isStagePlayReflectionPrompt(args.transcript) ||
      isStagePlayCheckpointRequestPrompt(args.transcript) ||
      isStagePlayJobPlanningPrompt(args.transcript)
    );
  if (preservesLiveEnvironmentStagePlayRoute) {
    return args.sourceTargetIntent as ReturnType<typeof arbitrateAskSourceTarget>;
  }
  const mailboxEvidenceRouteWon =
    isCompactUiMailboxWakePrompt(args.transcript) ||
    (
      selectedEvidenceTargetSource === "live_source_mailbox" &&
      isAskTurnLiveSourceMailLoopIntent(args.transcript) &&
      !hasAskTurnExplicitStagePlayOperationCue(args.transcript)
    );
  if (!mailboxEvidenceRouteWon) {
    return args.sourceTargetIntent as ReturnType<typeof arbitrateAskSourceTarget>;
  }
  const originalRequestedOutputs = Array.isArray(originalSourceTarget.requested_outputs)
    ? originalSourceTarget.requested_outputs.filter((entry): entry is string => typeof entry === "string")
    : [];
  const originalSuppressedRoutes = Array.isArray(originalSourceTarget.suppressed_routes)
    ? originalSourceTarget.suppressed_routes.filter((entry): entry is string => typeof entry === "string")
    : [];
  return {
    ...originalSourceTarget,
    target_source: "live_source_mailbox",
    target_kind: "live_source_mailbox",
    targetSource: "live_source_mailbox",
    targetKind: "live_source_mailbox",
    strength: "hard",
    reasons: uniqueAskTurnStrings([
      ...originalReasons,
      "live_source_mailbox_evidence_target_precedence",
    ]),
    requested_outputs: uniqueAskTurnStrings([
      ...originalRequestedOutputs,
      "stage_play_live_source_mail_read_result",
      "stage_play_live_source_mail_decision",
      "stage_play_live_source_narrative_state",
      "typed_failure",
    ]) as ReturnType<typeof arbitrateAskSourceTarget>["requested_outputs"],
    suppressed_routes: uniqueAskTurnStrings([
      ...originalSuppressedRoutes,
      "situation_room.describe_visual_capture",
      "visual_capture",
      "visual_capture_describe",
      "docs-viewer.search_docs",
      "docs-viewer.open",
      "docs-viewer.identify_current_doc",
      "repo-code.search_concept",
      "internet-search.search_web",
      "workspace_os.status",
      "conversation:simple",
      "no_tool_direct",
    ]),
    precedence_reason: mailboxEvidenceRouteWon
      ? "live_source_mailbox_evidence_target_precedence"
      : "live_source_mailbox_route_admission_authoritative",
    must_enter_backend_ask: true,
    allow_client_shortcut: false,
    allow_no_tool_direct: false,
    mailbox_source_target_override: true,
    mailbox_source_target_original_target_source: originalTargetSource ?? null,
    mailbox_source_target_original_target_kind: readAskTurnString(originalSourceTarget.target_kind) ?? null,
    assistant_answer: false,
    raw_content_included: false,
  } as ReturnType<typeof arbitrateAskSourceTarget>;
};

