  hasAskTurnExplicitMailToolCue,
  hasAskTurnExplicitStagePlayOperationCue,
  hasNegatedLiveSourceMailLoopIntent,
  hasContextualLiveSourceMailLoopIntent,
  hasExplicitAskTurnLiveSourceMailLoopCue,
  hasAskTurnLiveSourceMailInterpretationCue,
  hasAskTurnLiveSourceStandingWatchCue,
  isStagePlayJobPlanningPrompt,
