const collectHelixRuntimeComposerRepoEvidence = (
  artifacts: HelixTurnArtifact[],
): Array<Record<string, unknown>> =>
  artifacts.flatMap((artifact): Array<Record<string, unknown>> => {
    if (artifact.kind !== "repo_code_evidence_observation") return [];
    const payload = readAskTurnArtifactPayloadRecord(artifact);
    if (!payload) return [];
    const spans = Array.isArray(payload.spans) ? payload.spans : [];
    return [
      {
        artifact_ref: artifact.artifact_id,
        schema: readAskTurnString(payload.schema) ?? "helix.repo_code_evidence_observation.v1",
        concept: readAskTurnString(payload.concept),
        query: readAskTurnString(payload.query),
        evidence_refs: Array.isArray(payload.evidence_refs) ? payload.evidence_refs.slice(0, 8) : [],
        spans: spans
        .map((entry) =>
            entry && typeof entry === "object" && !Array.isArray(entry)
              ? (entry as Record<string, unknown>)
              : null,
          )
          .filter((entry): entry is Record<string, unknown> => Boolean(entry))
          .slice(0, 8)
          .map((span) => ({
          ref: readAskTurnString(span.ref),
          path: readAskTurnString(span.path),
          start_line: span.start_line,
          end_line: span.end_line,
          excerpt: clipAskText(
            readAskTurnString(span.sanitized_excerpt) ??
              readAskTurnString(span.excerpt) ??
              readAskTurnString(span.raw_excerpt) ??
              "",
            520,
          ),
          reason: readAskTurnString(span.reason),
          source_kind: readAskTurnString(span.source_kind),
          score: span.score,
        })),
      },
    ];
  });

export const __testHelixScholarlyFinalFallback = {
  buildHelixScholarlyResearchFallbackText,
  buildHelixInternetSearchFallbackText,
};

const {
  isCompoundInterimVoiceCalloutPromptText,
  buildCompoundInterimVoiceCalloutFallbackText,
  compoundInterimVoiceReceiptExplanationSatisfied,
  readLatestAskTurnDirectAnswerTextForVoiceSideEffect,
} = createHelixRuntimeVoiceSideEffectComposer({
  extractAskTurnUnquotedVoiceCalloutText,
});

const invokeHelixPostObservationComposerLlm = async (args: {
  turnId: string;
  prompt: string;
  canonicalGoalFrame: HelixAskCanonicalGoalFrame;
  goalSatisfactionEvaluation?: HelixGoalSatisfactionEvaluation | null;
  terminalContract?: HelixGoalTerminalContract | null;
  selectedArtifacts: HelixTurnArtifact[];
  receipts?: Array<Record<string, unknown>>;
  coverageArtifacts?: Array<Record<string, unknown>>;
  agentStepLoop?: unknown;
  answerDecision?: HelixAgentStepDecision | null;
  budgetState?: unknown;
  toolObservations?: Array<Record<string, unknown>>;
  repoDocsSynthesisPacket?: HelixRepoDocsSynthesisPacket | null;
  repoDocsRepairInstruction?: string | null;
  languageContract?: HelixAskLanguageContractV1 | null;
  conversationMemoryPacket?: HelixConversationMemoryPacket | null;
  rollingSessionContextPacket?: HelixRollingSessionContextPacket | null;
  fallbackText: string;
  testResponseEnv?: string;
}): Promise<HelixFinalAnswerDraft> => {
  const startedAt = Date.now();
  const selectedArtifacts = args.selectedArtifacts;
  const receiptRefs = (args.receipts ?? [])
    .map((receipt) => readAskTurnString(receipt.receipt_id))
    .filter((entry): entry is string => Boolean(entry));
  const artifactRefs = selectedArtifacts.map((artifact) => artifact.artifact_id);
  const voiceOutputIntentForFinal = classifyAskTurnVoiceOutputIntent(args.prompt);
  const voiceSideEffectContentGoal = voiceOutputIntentForFinal.sideEffectContentGoal;
  const compoundInterimVoiceFallbackText = buildCompoundInterimVoiceCalloutFallbackText({
    prompt: args.prompt,
    fallbackText: args.fallbackText,
  });
  const repoEvidenceGoalFrame = helixRuntimeFinalAnswerComposer.isHelixRuntimeRepoEvidenceGoalFrame(args.canonicalGoalFrame);
  const scholarlyEvidenceGoalFrame = args.canonicalGoalFrame.goal_kind === "scholarly_research_lookup";
  const internetSearchEvidenceGoalFrame = args.canonicalGoalFrame.goal_kind === "internet_search_lookup";
  const repoEvidenceObservationRefs = selectedArtifacts
    .filter((artifact) => artifact.kind === "repo_code_evidence_observation")
    .map((artifact) => artifact.artifact_id)
    .filter(Boolean);
  const scholarlyObservationRefs = collectHelixRuntimeComposerScholarlyObservationRefs(selectedArtifacts);
  const scholarlySupportRefs = collectHelixRuntimeComposerScholarlySupportRefs(selectedArtifacts);
  const internetSearchObservationRefs = collectHelixRuntimeComposerInternetSearchObservationRefs(selectedArtifacts);
  const internetSearchSupportRefs = collectHelixRuntimeComposerInternetSearchSupportRefs(selectedArtifacts);
  const repoDocsPacketRefs = args.repoDocsSynthesisPacket
    ? collectRepoDocsSynthesisPacketSupportRefs(args.repoDocsSynthesisPacket)
    : [];
  const sourceTargetExactContractRef = args.repoDocsSynthesisPacket?.source_target_exact_contract?.contract_id;
  const coverageRefs = (args.coverageArtifacts ?? [])
    .map((artifact) => readAskTurnString(artifact.coverage_id) ?? readAskTurnString(artifact.ref) ?? readAskTurnString(artifact.schema))
    .filter((entry): entry is string => Boolean(entry));
  const requiresExactExcerpts =
    /\b(?:exact|quote|excerpt|line(?:s)?|verbatim|cite|citation|path)\b/i.test(args.prompt) ||
    args.canonicalGoalFrame.goal_kind === "doc_evidence_location";
  const modelPromptContext = buildHelixModelPromptContext({
    turnId: args.turnId,
    userGoal: args.prompt,
    canonicalGoal: args.canonicalGoalFrame,
    terminalContract: args.terminalContract ?? args.goalSatisfactionEvaluation?.terminal_contract ?? null,
    selectedArtifacts,
    toolObservations: args.toolObservations ?? [],
    goalSatisfaction: args.goalSatisfactionEvaluation ?? null,
    finalAnswerConstraints: {
      source_tool_backed: args.canonicalGoalFrame.answer_scope !== "model_only",
      repo_evidence_goal: repoEvidenceGoalFrame,
      coverage_refs: coverageRefs,
      receipt_refs: receiptRefs,
    },
    commentary: args.answerDecision?.model_decision?.commentary ?? args.answerDecision?.why_this_capability_satisfies_goal,
    requiresExactExcerpts,
  });
  const outputBudget = resolveHelixFinalAnswerOutputBudget({
    prompt: args.prompt,
    canonicalGoalFrame: args.canonicalGoalFrame,
    repoDocsSynthesisPacket: args.repoDocsSynthesisPacket ?? null,
    compactObservationCount: modelPromptContext.compact_observations.length,
    contextEconomyReport: modelPromptContext.economy_report,
    answerDecision: args.answerDecision ?? null,
  });
  const buildDraft = (
    text: string,
    authority: HelixFinalAnswerDraft["authority"],
    errorCode: string | null,
    durationMs: number,
  ): HelixFinalAnswerDraft => ({
    schema: "helix.final_answer_draft.v1",
    turn_id: args.turnId,
    goal_kind: args.canonicalGoalFrame.goal_kind,
    required_terminal_kind: args.canonicalGoalFrame.required_terminal_kind,
    authority,
    composer_scope: authority === "typed_failure"
      ? "typed_failure"
      : args.canonicalGoalFrame.answer_scope === "model_only"
        ? "model_only"
        : "source_tool_backed",
    llm_error_code: errorCode,
    duration_ms: durationMs,
    text: cleanHelixPostObservationDraftText(text, args.prompt),
    artifact_refs: artifactRefs,
    support_refs: repoEvidenceGoalFrame
      ? Array.from(new Set([...repoDocsPacketRefs, ...artifactRefs])).slice(0, 12)
      : scholarlyEvidenceGoalFrame
        ? scholarlySupportRefs
        : internetSearchEvidenceGoalFrame
          ? internetSearchSupportRefs
        : undefined,
    source_target_exact_contract_ref: sourceTargetExactContractRef,
    receipt_refs: receiptRefs,
    coverage_refs: coverageRefs,
    agent_step_loop_ref: args.agentStepLoop ? `${args.turnId}:agent_step_loop` : null,
    composer_trigger_decision_ref: args.answerDecision?.decision_id ?? null,
    composer_trigger_iteration:
      args.agentStepLoop && typeof args.agentStepLoop === "object" && Array.isArray((args.agentStepLoop as HelixAgentRuntimeLoop).iterations)
        ? ([...(args.agentStepLoop as HelixAgentRuntimeLoop).iterations].reverse().find((iteration) => iteration.next_step === "answer")?.iteration ?? null)
        : null,
    composer_input_refs: [
      ...(args.answerDecision?.decision_id ? [args.answerDecision.decision_id] : []),
      ...(args.agentStepLoop ? [`${args.turnId}:agent_runtime_loop`] : []),
      ...(args.goalSatisfactionEvaluation ? [`${args.turnId}:goal_satisfaction_evaluation`] : []),
      ...(args.repoDocsSynthesisPacket ? [args.repoDocsSynthesisPacket.packet_id] : []),
      ...(sourceTargetExactContractRef ? [sourceTargetExactContractRef] : []),
      ...coverageRefs,
      ...receiptRefs,
    ],
    ...(repoEvidenceGoalFrame
      ? {
          model_step_capability: HELIX_MODEL_SYNTHESIZE_FROM_REPO_EVIDENCE_CAPABILITY,
          grounded_in_observation_refs: repoEvidenceObservationRefs,
          repo_docs_synthesis_packet_ref: args.repoDocsSynthesisPacket?.packet_id,
        }
      : {}),
    ...(scholarlyEvidenceGoalFrame
      ? {
          model_step_capability: HELIX_MODEL_SYNTHESIZE_FROM_SCHOLARLY_RESEARCH_CAPABILITY,
          grounded_in_observation_refs: scholarlyObservationRefs,
        }
      : {}),
    ...(internetSearchEvidenceGoalFrame
      ? {
          model_step_capability: HELIX_MODEL_SYNTHESIZE_FROM_INTERNET_SEARCH_CAPABILITY,
          grounded_in_observation_refs: internetSearchObservationRefs,
        }
      : {}),
    model_context_economy_report: modelPromptContext.economy_report,
    compact_observation_refs: modelPromptContext.compact_observations.map((packet) => packet.observation_ref),
    output_budget: outputBudget,
    unsupported_claim_guard: {
      source_targeted: args.canonicalGoalFrame.answer_scope !== "model_only",
      policy: args.canonicalGoalFrame.answer_scope === "model_only" ? "not_applicable" : "selected_artifacts_only",
    },
    assistant_answer: false,
    raw_content_included: false,
  });
  const directVoiceSideEffectAnswerText = voiceSideEffectContentGoal
    ? readLatestAskTurnDirectAnswerTextForVoiceSideEffect(selectedArtifacts)
    : null;
  if (directVoiceSideEffectAnswerText) {
    return buildDraft(
      directVoiceSideEffectAnswerText,
      "llm_post_observation_composer",
      null,
      Math.max(0, Date.now() - startedAt),
    );
  }
  if (
    /^The interim voice callout\b/i.test(args.fallbackText) &&
    !voiceSideEffectContentGoal &&
    !isCompoundInterimVoiceCalloutPromptText(args.prompt)
  ) {
    return buildDraft(
      args.fallbackText,
      "deterministic_receipt_fallback",
      "interim_voice_callout_status_observed",
      Math.max(0, Date.now() - startedAt),
    );
  }
  const configuredTestResponse =
    args.testResponseEnv && process.env.NODE_ENV === "test"
      ? process.env[args.testResponseEnv]
      : undefined;
  if (!shouldUseHelixAgentStepDecisionLlm() && !configuredTestResponse) {
    const deterministicRepoSynthesisText =
      repoEvidenceGoalFrame && args.repoDocsSynthesisPacket
        ? buildDeterministicRepoEvidenceSynthesisText(args.repoDocsSynthesisPacket)
        : null;
    if (deterministicRepoSynthesisText) {
      return buildDraft(
        deterministicRepoSynthesisText,
        "deterministic_repo_evidence_synthesis",
        "post_observation_composer_llm_disabled_repo_evidence_packet_synthesis",
        0,
      );
    }
    return buildDraft(
      voiceSideEffectContentGoal ? args.fallbackText : (compoundInterimVoiceFallbackText ?? args.fallbackText),
      "deterministic_receipt_fallback",
      voiceSideEffectContentGoal
        ? "post_observation_composer_llm_disabled_voice_side_effect_content_goal_pending"
        : compoundInterimVoiceFallbackText
        ? "compound_interim_voice_callout_explanation_fallback_llm_disabled"
        : "post_observation_composer_llm_disabled",
      0,
    );
  }
  const repoDocsPacketJson = JSON.stringify(args.repoDocsSynthesisPacket ?? null);
  const conversationMemoryRendered = args.conversationMemoryPacket
    ? renderHelixConversationMemoryForModel(args.conversationMemoryPacket)
    : null;
  const rollingSessionContextRendered = args.rollingSessionContextPacket
    ? renderHelixRollingSessionContextForModel(args.rollingSessionContextPacket)
    : null;
  const prompt = args.repoDocsSynthesisPacket
    ? [
        "You are the Helix repo/docs post-observation synthesis composer.",
        "Use only the compact repo/docs synthesis packet below.",
        "Answer the user's question directly in natural language.",
        "Explain what the evidence establishes; do not return a file inventory, raw excerpt dump, or line-by-line source list.",
        "Do not claim evidence is missing when compact_evidence is non-empty.",
        "Preserve authority claims exactly: receipts/tool outputs are observations or support, not final-answer authority.",
        "Citations must be compact: use one parenthetical citation or one semicolon-separated Sources sentence. Do not put each source on its own bullet line.",
        ...buildHelixResponseLanguageInstruction(args.languageContract),
        ...(args.repoDocsRepairInstruction ? [`Repair instruction: ${args.repoDocsRepairInstruction}`] : []),
        "Return final answer text only. Do not return JSON.",
        "",
        `User goal: ${args.prompt.trim()}`,
        `Output budget: ${JSON.stringify(outputBudget)}`,
        ...(conversationMemoryRendered ? [`Conversation memory: ${conversationMemoryRendered.slice(0, 1800)}`] : []),
        ...(rollingSessionContextRendered ? [`Rolling session context: ${rollingSessionContextRendered.slice(0, 2200)}`] : []),
        `Canonical goal kind: ${args.canonicalGoalFrame.goal_kind}`,
        `Required terminal kind: ${args.canonicalGoalFrame.required_terminal_kind ?? "repo_code_evidence_answer"}`,
        `Repo/docs synthesis packet: ${repoDocsPacketJson.slice(0, 7000)}`,
      ].join("\n")
    : [
        "You are the Helix shared post-observation final answer composer.",
        "Write the final answer only from compact observations, compact contracts, selected support refs, exact excerpts when present, and goal satisfaction.",
        "This mirrors Codex's observe-result-then-answer step: tool outputs are observations, not the answer by themselves.",
        "Rules:",
        "- Cover the user goal only when the goal satisfaction evaluation says it is satisfied.",
        "- For source/tool-backed turns, never introduce claims, numbers, document facts, or actions outside compact observations and support refs.",
        "- Include formulas, calculator expressions, numeric results, and units when compact observations or exact excerpts support them and the user requested them.",
        "- When explaining calculator dependencies, use the equations in the receipts exactly: do not say a quantity depends only on final speed unless its receipt formula uses only final speed plus constants/given values. For example, F = m a depends on acceleration; v = a t, impulse = F t, and average power = KE / t depend on the time interval.",
        "- Do not append stale missing-section markers like 'Missing interpretation of results' when you already gave a caveat, dependency explanation, or interpretation.",
        "- Preserve line-backed document evidence when document-location artifacts are selected.",
        "- If the user requested a specific number of bullets, produce at least that many visible bullet lines unless the selected artifacts cannot support them; if unsupported, say the missing output requirement explicitly.",
        "- If the user asked to include a document path, include the exact path from the selected document artifact or prompt.",
        "- Keep pure receipt/status panel actions concise when the receipt itself is the requested outcome.",
        "- If coverage is incomplete, say exactly which requested parts are missing.",
        "- For repo-code evidence turns, repo_code_evidence_observation artifacts are the current-turn repo evidence. If repo evidence observations are listed below, do not claim repo evidence is missing; synthesize a natural-language answer from those spans and include compact file refs.",
        "- For scholarly research turns, scholarly_research_observation and scholarly_full_text_observation artifacts are current-turn external paper evidence. Synthesize citations, references, and PDF/full-text excerpts only from those compact records and keep uncertainty explicit.",
        "- For internet search turns, internet_search_observation artifacts are current-turn external web evidence. Synthesize only from compact web results and include compact source links or support refs.",
        "- For live-source mail turns, a stage_play_live_source_mail_decision observation supersedes any earlier stage_play_live_source_mail_read_result. If a decision is recorded, do not say the same mail is still unread or still requiring a decision.",
        "- If a live-source mail decision is draft_text_answer and includes textAnswerDraft.text, surface that text directly as the answer content. Do not replace it with a status-only summary.",
        "- If a live-source mail decision is record_interpretation, derive the answer from narrativeState.interpretedSituation.userRelevantMeaning, narrativeState.watchNext.reason, and narrativeState.prediction.text when present. Do not answer from the raw mailbox read receipt.",
        "- If a live-source mail decision is wait_for_next_summary, say it is waiting only when the user asked for status/check state. Do not infer 'no mail available' unless the read receipt has items: [].",
        "- If a live-source mail decision is request_voice_callout, surface the voiceCalloutDraft or voice receipt. If it is request_stage_play_checkpoint, surface checkpoint request status.",
        "- If the user requested an interim voice callout plus a separate content answer, treat the voice receipt as a side-effect observation and answer the separate content goal. Do not make the final answer about the voice tool unless the user explicitly asked about the voice tool.",
        "- For repo/docs evidence synthesis, answer what the evidence means. Do not return a file inventory or raw excerpt dump.",
        "- Preserve repo/docs authority claims exactly. If the evidence says receipts or tool outputs are observations/supporting artifacts, do not rewrite that as receipts validating, authorizing, or deriving final answers.",
        "- If a repo/docs synthesis packet is provided, treat its compact_evidence refs as the support refs for your claims.",
        "- For Civilization Bounds turns, scenario-frame and roadmap receipts are compact observations. Do not claim no observations were provided when those receipts or receipt refs are listed; synthesize from the frame, roadmap, and missing-evidence fields.",
        ...buildHelixResponseLanguageInstruction(args.languageContract).map((line) => `- ${line}`),
        ...(args.repoDocsRepairInstruction ? [`- Repair instruction: ${args.repoDocsRepairInstruction}`] : []),
        "- Return final answer text only. Do not return JSON.",
        "",
        `User goal: ${args.prompt.trim()}`,
        ...(voiceSideEffectContentGoal ? [`Separate non-voice content goal to answer: ${voiceSideEffectContentGoal}`] : []),
        `Output budget: ${JSON.stringify(outputBudget)}`,
        ...(conversationMemoryRendered ? [`Conversation memory: ${conversationMemoryRendered.slice(0, 1800)}`] : []),
        ...(rollingSessionContextRendered ? [`Rolling session context: ${rollingSessionContextRendered.slice(0, 2200)}`] : []),
        `Canonical goal: ${JSON.stringify(args.canonicalGoalFrame).slice(0, 2200)}`,
        `Compact terminal contract: ${JSON.stringify(modelPromptContext.terminal_contract_compact).slice(0, 1800)}`,
        `Compact observations: ${JSON.stringify(modelPromptContext.compact_observations).slice(0, 12000)}`,
        `Repo/docs synthesis packet: ${repoDocsPacketJson.slice(0, 9000)}`,
        `Goal satisfaction: ${JSON.stringify(args.goalSatisfactionEvaluation ?? null).slice(0, 3200)}`,
        `Exact excerpts: ${JSON.stringify(modelPromptContext.exact_excerpts).slice(0, 3600)}`,
        `Coverage summary refs: ${JSON.stringify(coverageRefs).slice(0, 1200)}`,
        `Budget state: ${JSON.stringify(args.budgetState ?? null).slice(0, 1000)}`,
        `Final answer decision: ${JSON.stringify(args.answerDecision ?? null).slice(0, 2600)}`,
        `Agent-step loop summary: ${JSON.stringify(args.agentStepLoop ? {
          schema: (args.agentStepLoop as Record<string, unknown>)?.schema,
          loop_id: (args.agentStepLoop as Record<string, unknown>)?.loop_id,
          final_state: (args.agentStepLoop as Record<string, unknown>)?.final_state,
        } : null).slice(0, 1000)}`,
        `Context economy report: ${JSON.stringify(modelPromptContext.economy_report).slice(0, 2600)}`,
      ].join("\n");
  try {
    const testResponse =
      configuredTestResponse ??
      (process.env.NODE_ENV === "test" ? process.env.HELIX_POST_OBSERVATION_COMPOSER_TEST_RESPONSE : undefined);
    let modelText = "";
    if (testResponse && process.env.NODE_ENV === "test") {
      modelText = testResponse;
    } else {
      let timeoutHandle: ReturnType<typeof setTimeout> | null = null;
      const rawResult = await Promise.race([
        llmLocalHandler(
          {
            prompt,
            max_tokens: outputBudget.max_tokens,
            temperature: 0,
            metadata: {
              kind: "helix.ask.post_observation_final_answer",
              output_budget: outputBudget,
            },
          },
          {
            sessionId: args.turnId,
            traceId: `${args.turnId}:final_answer_draft`,
            personaId: "helix-ask-post-observation-composer",
          },
        ),
        new Promise<never>((_, reject) => {
          timeoutHandle = setTimeout(() => reject(new Error("post_observation_composer_timeout")), HELIX_CALCULATOR_PLANNER_TIMEOUT_MS);
        }),
      ]);
      if (timeoutHandle) clearTimeout(timeoutHandle);
      modelText = typeof (rawResult as { text?: unknown })?.text === "string" ? String((rawResult as { text?: unknown }).text).trim() : "";
    }
    if (args.fallbackText) {
      modelText = normalizeLiveSourceMailWaitWording(modelText, args.fallbackText);
    }
    if (
      civilizationBoundsComposerContradictsReceipts({
        modelText,
        fallbackText: args.fallbackText,
        selectedArtifacts,
        receiptRefs,
        goalSatisfactionEvaluation: args.goalSatisfactionEvaluation ?? null,
        canonicalGoalFrame: args.canonicalGoalFrame,
      })
    ) {
      return buildDraft(
        args.fallbackText,
        "deterministic_receipt_fallback",
        "civilization_bounds_composer_contradicted_receipts",
        Math.max(0, Date.now() - startedAt),
      );
    }
    const liveSourceMailTextDraft = latestHelixRuntimeLiveSourceMailTextAnswerDraft(selectedArtifacts);
    if (liveSourceMailTextDraft) {
      return buildDraft(
        liveSourceMailTextDraft,
        "llm_post_observation_composer",
        null,
        Math.max(0, Date.now() - startedAt),
      );
    }
    const liveSourceMailInterpretation = latestHelixRuntimeLiveSourceMailInterpretationText(selectedArtifacts);
    if (liveSourceMailInterpretation) {
      return buildDraft(
        liveSourceMailInterpretation,
        "llm_post_observation_composer",
        null,
        Math.max(0, Date.now() - startedAt),
      );
    }
    if (args.fallbackText && isAskTurnNonSubstantiveDirectAnswer(modelText)) {
      return buildDraft(
        voiceSideEffectContentGoal ? args.fallbackText : (compoundInterimVoiceFallbackText ?? args.fallbackText),
        "deterministic_receipt_fallback",
        voiceSideEffectContentGoal
          ? "post_observation_composer_returned_non_substantive_text_for_voice_side_effect_content_goal"
          : compoundInterimVoiceFallbackText
          ? "compound_interim_voice_callout_explanation_fallback_after_non_substantive_text"
          : "post_observation_composer_returned_non_substantive_text",
        Math.max(0, Date.now() - startedAt),
      );
    }
    if (
      compoundInterimVoiceFallbackText &&
      !voiceSideEffectContentGoal &&
      args.fallbackText &&
      modelText &&
      modelText.replace(/\s+/g, " ").trim() === args.fallbackText.replace(/\s+/g, " ").trim()
    ) {
      return buildDraft(
        compoundInterimVoiceFallbackText,
        "deterministic_receipt_fallback",
        "post_observation_composer_returned_receipt_only_for_compound_interim_voice_goal",
        Math.max(0, Date.now() - startedAt),
      );
    }
    if (
      compoundInterimVoiceFallbackText &&
      !voiceSideEffectContentGoal &&
      modelText &&
      !compoundInterimVoiceReceiptExplanationSatisfied(modelText)
    ) {
      return buildDraft(
        compoundInterimVoiceFallbackText,
        "deterministic_receipt_fallback",
        "post_observation_composer_undercovered_compound_interim_voice_goal",
        Math.max(0, Date.now() - startedAt),
      );
    }
    if (args.fallbackText && helixRuntimeFinalAnswerComposer.stagePlayModelAnswerConflictsWithReceipt(modelText, args.fallbackText)) {
      return buildDraft(
        args.fallbackText,
        "deterministic_receipt_fallback",
        "stage_play_composer_contradicted_projection_receipt",
        Math.max(0, Date.now() - startedAt),
      );
    }
    if (args.fallbackText && liveSourceMailModelAnswerConflictsWithDecision(modelText, args.fallbackText)) {
      return buildDraft(
        args.fallbackText,
        "deterministic_receipt_fallback",
        "live_source_mail_composer_contradicted_recorded_decision",
        Math.max(0, Date.now() - startedAt),
      );
    }
    if (
      args.fallbackText && args.canonicalGoalFrame.goal_kind === "calculator_solve" && modelText
    ) {
      const normalizedModelText = modelText.toLowerCase();
      const missingReceiptResults = args.receipts
        .map((receipt) => readAskTurnString(receipt.result_text) ?? readAskTurnString(receipt.result))
        .filter((entry): entry is string => Boolean(entry))
        .filter((result) => {
          const exact = result.toLowerCase();
          const significant = exact.match(/^[-+]?\d+(?:\.\d{0,5})?/)?.[0];
          return (
            !normalizedModelText.includes(exact) &&
            Boolean(
              significant &&
              significant.length >= 4 &&
              !normalizedModelText.includes(significant),
            )
          );
        });
      if (missingReceiptResults.length > 0) {
        return buildDraft(
          args.fallbackText,
          "deterministic_receipt_fallback",
          "post_observation_composer_omitted_receipt_exact_result",
          Math.max(0, Date.now() - startedAt),
        );
      }
    }
    return buildDraft(
      modelText ||
        (voiceSideEffectContentGoal
          ? args.fallbackText
          : compoundInterimVoiceFallbackText || args.fallbackText),
      modelText ? "llm_post_observation_composer" : "deterministic_receipt_fallback",
      modelText
        ? null
        : voiceSideEffectContentGoal
          ? "empty_post_observation_composer_answer_for_voice_side_effect_content_goal"
          : compoundInterimVoiceFallbackText
          ? "compound_interim_voice_callout_explanation_fallback_empty_composer_answer"
          : "empty_post_observation_composer_answer",
      Math.max(0, Date.now() - startedAt),
    );
  } catch (error) {
    return buildDraft(
      voiceSideEffectContentGoal ? args.fallbackText : (compoundInterimVoiceFallbackText ?? args.fallbackText),
      "deterministic_receipt_fallback",
      voiceSideEffectContentGoal
        ? `voice_side_effect_content_goal_fallback:${error instanceof Error && error.message ? error.message.slice(0, 80) : "post_observation_composer_call_failed"}`
        : compoundInterimVoiceFallbackText
        ? `compound_interim_voice_callout_explanation_fallback:${error instanceof Error && error.message ? error.message.slice(0, 80) : "post_observation_composer_call_failed"}`
        : error instanceof Error && error.message ? error.message.slice(0, 120) : "post_observation_composer_call_failed",
      Math.max(0, Date.now() - startedAt),
    );
  }
};

