const readLiveEnvironmentToolObservationPayload = (artifact: HelixTurnArtifact): Record<string, unknown> | null => {
  if (artifact.kind !== "live_environment_tool_observation") return null;
  return readAskTurnArtifactPayloadRecord(artifact);
};

const readLatestInterimVoiceCalloutToolResult = (
  artifacts: HelixTurnArtifact[],
): {
  artifact: HelixTurnArtifact;
  toolPayload: Record<string, unknown>;
  observation: Record<string, unknown>;
  request: Record<string, unknown> | null;
  receipt: Record<string, unknown> | null;
  receiptStatus: string | null;
  requestText: string | null;
} | null => {
  for (const artifact of [...artifacts].reverse()) {
    const toolPayload = readLiveEnvironmentToolObservationPayload(artifact);
    if (readAskTurnString(toolPayload?.tool_name) !== "live_env.request_interim_voice_callout") continue;
    const observation =
      toolPayload?.observation && typeof toolPayload.observation === "object" && !Array.isArray(toolPayload.observation)
        ? (toolPayload.observation as Record<string, unknown>)
        : null;
    if (readAskTurnString(observation?.schema) !== "helix.interim_voice_callout_tool_result.v1") continue;
    const request =
      observation.request && typeof observation.request === "object" && !Array.isArray(observation.request)
        ? (observation.request as Record<string, unknown>)
        : null;
    const receipt =
      observation.receipt && typeof observation.receipt === "object" && !Array.isArray(observation.receipt)
        ? (observation.receipt as Record<string, unknown>)
        : null;
    return {
      artifact,
      toolPayload,
      observation,
      request,
      receipt,
      receiptStatus: readAskTurnString(receipt?.status),
      requestText: readAskTurnString(request?.text),
    };
  }
  return null;
};

const isInterimVoiceCalloutFinalStatus = (status: string | null): boolean =>
  status === "awaiting_client_playback" ||
  status === "queued" ||
  status === "queued_for_retry" ||
  status === "delivered" ||
  status === "expired" ||
  status === "blocked_capacity" ||
  status === "blocked_policy" ||
  status === "blocked_missing_text";

const buildHelixRuntimeInterimVoiceCalloutFallbackText = (artifacts: HelixTurnArtifact[]): string => {
  const result = readLatestInterimVoiceCalloutToolResult(artifacts);
  if (!result || !isInterimVoiceCalloutFinalStatus(result.receiptStatus)) return "";
  const text = result.requestText ? `"${result.requestText}"` : "the requested interim voice callout";
  const status = result.receiptStatus;
  const statusText =
    status === "awaiting_client_playback"
      ? `The interim voice callout ${text} was accepted for client playback handoff; browser playback confirmation is still pending.`
      : status === "queued"
        ? `The interim voice callout ${text} has a legacy queued receipt; browser playback confirmation is still pending.`
      : status === "queued_for_retry"
        ? `The interim voice callout ${text} was queued for retry because voice playback capacity was not available yet.`
      : status === "delivered"
        ? `The interim voice callout ${text} was delivered.`
        : status === "expired"
          ? `The interim voice callout ${text} expired before voice playback capacity recovered.`
        : status === "blocked_capacity"
          ? `The interim voice callout ${text} was requested, but voice playback was blocked by capacity.`
          : status === "blocked_policy"
            ? `The interim voice callout ${text} was blocked by voice policy.`
            : `The interim voice callout could not be queued because no speakable text was provided.`;
  return `${statusText} The callout receipt was evidence-only and did not replace the final answer.`;
};

const applyInterimVoiceCalloutStatusGoalSatisfaction = (args: {
  turnId: string;
  transcript: string;
  evaluation: HelixGoalSatisfactionEvaluation;
  artifacts: HelixTurnArtifact[];
}): { evaluation: HelixGoalSatisfactionEvaluation; artifacts: HelixTurnArtifact[] } => {
  const result = readLatestInterimVoiceCalloutToolResult(args.artifacts);
  if (!result || !isInterimVoiceCalloutFinalStatus(result.receiptStatus)) {
    return { evaluation: args.evaluation, artifacts: args.artifacts };
  }
  const voiceIntent = classifyAskTurnVoiceOutputIntent(args.transcript);
  if (voiceIntent.sideEffectContentGoal) {
    const evaluation: HelixGoalSatisfactionEvaluation = {
      ...args.evaluation,
      observed_results: [
        ...args.evaluation.observed_results.filter((entry) => entry.ref !== result.artifact.artifact_id),
        {
          ref: result.artifact.artifact_id,
          kind: "live_environment_tool_observation",
          status: result.receiptStatus ?? "observed",
          supports_goal: false,
          reason:
            "The interim voice callout receipt is an evidence-only side effect; the preserved content goal still requires a content answer.",
        },
      ],
    };
    return { evaluation, artifacts: args.artifacts };
  }
  const supportReason =
    result.receiptStatus === "awaiting_client_playback"
      ? "The interim voice callout tool returned an awaiting_client_playback receipt; the answer should report browser handoff pending without claiming audio playback occurred."
      : result.receiptStatus === "queued_for_retry"
      ? "The interim voice callout tool returned a queued_for_retry receipt; the answer should report the observed retry state without claiming playback occurred."
      : result.receiptStatus === "blocked_capacity"
      ? "The interim voice callout tool returned a final blocked_capacity receipt; the answer should report the observed voice status without retrying or asking for confirmation."
      : "The interim voice callout tool returned a final voice-lane receipt status; the answer should report that observed status.";
  const evaluation: HelixGoalSatisfactionEvaluation = {
    ...args.evaluation,
    required_evidence: args.evaluation.required_evidence.map((entry) =>
      entry.kind === "live_environment_tool_observation"
        ? {
            ...entry,
            satisfied: true,
            evidence_ref: result.artifact.artifact_id,
            failure_reason: undefined,
          }
        : entry,
    ),
    observed_results: [
      ...args.evaluation.observed_results.filter((entry) => entry.ref !== result.artifact.artifact_id),
      {
        ref: result.artifact.artifact_id,
        kind: "live_environment_tool_observation",
        status: result.receiptStatus ?? "observed",
        supports_goal: true,
        reason: supportReason,
      },
    ],
    satisfaction: "satisfied",
    next_decision: "allow_terminal",
  };
  const artifacts = args.artifacts.map((artifact) =>
    artifact.kind === "goal_satisfaction_evaluation" && artifact.artifact_id === `${args.turnId}:goal_satisfaction_evaluation`
      ? {
          ...artifact,
          payload: evaluation as unknown as Record<string, unknown>,
        }
      : artifact,
  );
  return { evaluation, artifacts };
};

