  value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
const maybeRecordStagePlayAskCheckpointReceipt = (args: {
  payload: Record<string, unknown>;
  turnId: string;
  artifacts: HelixTurnArtifact[];
  finalAnswerDraft: HelixFinalAnswerDraft;
  finalAnswerDraftRef: string;
}): void => {
  const receiptPayload = buildStagePlayAskCheckpointReceiptPayload({
    payload: args.payload,
    turnId: args.turnId,
    artifacts: args.artifacts,
    finalAnswerDraft: args.finalAnswerDraft,
    finalAnswerDraftRef: args.finalAnswerDraftRef,
    createdAt: new Date().toISOString(),
  });
  if (!receiptPayload) return;
  const receipt = recordStagePlayAskCheckpointReceipt(receiptPayload);
  const checkpointQueueCompletion = completeStagePlayCheckpointRequestForGraph({
    graphId: receipt.graphId,
    checkpointRequestId: receipt.checkpointRequestId,
    now: receipt.createdAt,
  });
  args.payload.stage_play_ask_checkpoint_receipt = receipt;
  if (checkpointQueueCompletion) {
    args.payload.stage_play_checkpoint_queue_completion = checkpointQueueCompletion;
  }
  const currentLedger = Array.isArray(args.payload.current_turn_artifact_ledger)
    ? (args.payload.current_turn_artifact_ledger as HelixTurnArtifact[])
    : args.artifacts;
  args.payload.current_turn_artifact_ledger = mergeAskTurnLedgerArtifacts([
    ...currentLedger.filter((artifact) => artifact.artifact_id !== receipt.receiptId),
    {
      artifact_id: receipt.receiptId,
      turn_id: args.turnId,
      producer_item_id: "stage_play_ask_checkpoint_store",
      kind: "stage_play_ask_checkpoint_receipt",
      created_at_ms: Date.now(),
      source_scope: "current_turn",
      goal_hash: hashDebugExportPayloadShort([args.turnId, "stage_play_ask_checkpoint_receipt", receipt.graphId]),
      payload: receipt,
    },
  ]);
};

