    canonicalGoalFrame: args.canonicalGoalFrame,
    availableCapabilities: args.availableCapabilities,
    fallbackDecision: args.decision,
    goalSatisfactionEvaluation: args.goalSatisfactionEvaluation,
    runtimeIntentPacket: args.runtimeIntentPacket,
    terminalContract: args.terminalContract,
    coverageState: args.coverageState,
    budgetState: args.budgetState,
