const resolveLlmHttpBaseHost = (): string | null => {
  const base = process.env.LLM_HTTP_BASE?.trim();
  if (!base) return null;
  try {
    return new URL(base).host || null;
  } catch {
    return null;
  }
};

const resolveLlmApiKeySource = (): "OPENAI_API_KEY" | null => {
  if (process.env.OPENAI_API_KEY?.trim()) return "OPENAI_API_KEY";
  return null;
};

const resolveLlmApiKeyFingerprint = (): string | null => {
  const apiKey = process.env.OPENAI_API_KEY?.trim();
  if (!apiKey) return null;
  return crypto.createHash("sha256").update(apiKey).digest("hex").slice(0, 12);
};

type HelixAskLlmErrorDetails = LlmHttpErrorInfo & { normalizedCode?: string };

const parseHelixAskLlmErrorDetails = (error: unknown): HelixAskLlmErrorDetails => {
  const parsed = classifyLlmHttpError(error);
  let normalizedCode = parsed.code;
  if (!normalizedCode) {
    const message = parsed.message.trim();
    if (/aborterror/i.test(message)) {
      normalizedCode = "abort_error";
    } else if (/timeout/i.test(message)) {
      normalizedCode = "timeout";
    }
  }
  return {
    ...parsed,
    normalizedCode,
  };
};

const parseHelixAskLlmErrorCode = (error: unknown): string | undefined => {
  const details = parseHelixAskLlmErrorDetails(error);
  return details.normalizedCode;
};

const isHelixAskComposerV2TransientLlmErrorCode = (errorCode: string | undefined): boolean => {
  if (!errorCode) return false;
  return /^(?:llm_http_429|llm_http_circuit_open|llm_http_timeout(?::|$)|llm_http_transport(?::|$)|llm_http_5xx(?::|$))/.test(
    errorCode,
  );
};

const isHelixAskTransportPressureFallbackReason = (value: unknown): boolean => {
  const raw = String(value ?? "").trim().toLowerCase();
  if (!raw) return false;
  const normalized = raw.startsWith("stage05_") ? raw.slice("stage05_".length) : raw;
  return isHelixAskComposerV2TransientLlmErrorCode(normalized);
};

const shouldPreserveRepoIntentOnTransportDegradedCoverage = (args: {
  stage05FallbackReason?: unknown;
  contextFiles?: string[];
  retrievalConfidence?: number;
  hybridThreshold: number;
  requiresRepoEvidence?: boolean;
  hasRepoHints?: boolean;
  warpMathBroadPrompt?: boolean;
  intentDomain?: HelixAskDomain;
  explicitRepoExpectation?: boolean;
  coveredSlots?: string[];
}): boolean => {
  if (!isHelixAskTransportPressureFallbackReason(args.stage05FallbackReason)) return false;
  const repoSignal = Boolean(
    args.requiresRepoEvidence ||
      args.hasRepoHints ||
      args.warpMathBroadPrompt ||
      args.explicitRepoExpectation ||
      args.intentDomain === "repo" ||
      args.intentDomain === "hybrid" ||
      args.intentDomain === "falsifiable",
  );
  if (!repoSignal) return false;
  if (!hasRepoCodeEvidencePathsForAsk(args.contextFiles ?? [])) return false;
  const confidence = Number.isFinite(args.retrievalConfidence)
    ? Number(args.retrievalConfidence)
    : 0;
  if (confidence < Math.max(0.35, args.hybridThreshold - 0.15)) return false;
  const covered = new Set(
    (args.coveredSlots ?? [])
      .map((entry) => normalizeSlotId(String(entry ?? "")))
      .filter(Boolean),
  );
  return (
    covered.size >= 2 ||
    covered.has("mechanism") ||
    covered.has("code_path") ||
    covered.has("repo-mapping")
  );
};

const shouldSuppressHelixAskAnswerRescueForRateLimit = (debugPayload: {
  llm_first_rate_limited_source?: unknown;
  llm_first_rate_limited_kind?: unknown;
  llm_first_provider_429_kind?: unknown;
  llm_error_provider_text?: unknown;
} | null | undefined): boolean => {
  if (!debugPayload || typeof debugPayload !== "object") return false;
  const firstSource = String(debugPayload.llm_first_rate_limited_source ?? "").trim().toLowerCase();
  const firstKind = String(debugPayload.llm_first_rate_limited_kind ?? "").trim().toLowerCase();
  const providerKind = String(debugPayload.llm_first_provider_429_kind ?? "").trim().toLowerCase();
  const providerText = String(debugPayload.llm_error_provider_text ?? "").trim().toLowerCase();
  if (firstSource === "provider_429" || firstSource === "local_cooldown") {
    return true;
  }
  if (firstKind === "quota" || providerKind === "quota") return true;
  return /insufficient_quota|exceeded your current quota/.test(providerText);
};

const shouldForceRepoGroundedForRepoApiLookup = (args: {
  intentId?: string | null;
  arbiterMode: "repo_grounded" | "hybrid" | "general" | "clarify";
  explicitRepoExpectation: boolean;
  retrievalConfidence: number;
  repoThreshold: number;
  hasRepoHints: boolean;
  evidenceGateOk: boolean;
  mustIncludeOk: boolean;
  topicMustIncludeOk?: boolean;
  alignmentGateDecision?: "PASS" | "FAIL" | null;
  openWorldBypassMode?: "active" | "inactive";
  failClosedReason?: string | null;
}): boolean => {
  if (args.intentId !== "repo.repo_api_lookup") return false;
  if (args.arbiterMode !== "clarify") return false;
  if (!args.explicitRepoExpectation) return false;
  if (args.topicMustIncludeOk === false) return false;
  const failClosedReason = String(args.failClosedReason ?? "").trim();
  if (failClosedReason === "stage05_summary_hard_fail") {
    return false;
  }
  const confidence = Number.isFinite(args.retrievalConfidence) ? args.retrievalConfidence : 0;
  return confidence >= 0.6;
};

const shouldForceHelixAskShortDefinitionConceptAnswer = (args: {
  intentDomain?: HelixAskDomain;
  conceptAvailable?: boolean;
  conceptDraftAvailable?: boolean;
  ambiguityReason?: unknown;
  ambiguityShortPrompt?: boolean;
  explicitRepoExpectation?: boolean;
  hasFilePathHints?: boolean;
  endpointHintCount?: number;
  reportReason?: unknown;
}): boolean => {
  if (args.intentDomain !== "general") return false;
  if (!args.conceptAvailable || !args.conceptDraftAvailable) return false;
  if (String(args.ambiguityReason ?? "").trim().toLowerCase() !== "short_definition") return false;
  if (args.ambiguityShortPrompt !== true) return false;
  if (args.explicitRepoExpectation || args.hasFilePathHints) return false;
  if ((args.endpointHintCount ?? 0) > 0) return false;
  if (String(args.reportReason ?? "").trim() === "explicit_report_request") return false;
  return true;
};

const shouldUseScientificPreIntentClarify = (args: {
  scientificClarifyEnabled?: boolean;
  requiresRepoEvidence?: boolean;
  explicitRepoExpectation?: boolean;
  hasFilePathHints?: boolean;
  endpointHintCount?: number;
  intentDomain?: HelixAskDomain;
  isRepoQuestion?: boolean;
}): boolean => {
  if (!args.scientificClarifyEnabled) return false;
  if (args.requiresRepoEvidence) return true;
  if (args.explicitRepoExpectation) return true;
  if (args.hasFilePathHints) return true;
  if ((args.endpointHintCount ?? 0) > 0) return true;
  if (args.intentDomain === "repo" || args.intentDomain === "hybrid") return true;
  if (args.isRepoQuestion) return true;
  return false;
};

const hasHelixAskRepoTechnicalCue = (question: string): boolean => {
  const trimmed = question.trim();
  if (!trimmed) return false;
  const hasCodeLikeIdentifier =
    /\b[a-z][a-z0-9]*(?:_[a-z0-9]+){1,}\b/.test(trimmed) ||
    /\b[a-z][a-z0-9_]*[A-Z][A-Za-z0-9_]*\b/.test(trimmed) ||
    /`[A-Za-z_][A-Za-z0-9_]*`/.test(trimmed) ||
    /\b[A-Za-z_][A-Za-z0-9_]*\s*\(\s*\)/.test(trimmed) ||
    /\/api\/[a-z0-9/_-]+/i.test(trimmed);
  if (hasCodeLikeIdentifier) return true;
  const internalMechanicsPrompt =
    /\b(?:how does|where (?:is|are)|walk through|show|describe|explain|what determines|what checks|what does)\b/i.test(
      trimmed,
    ) &&
    /\b(?:debug payload|debug live events|diagnostics?|relation packet|answer contract|citation repair|training-trace|intent directory|topic tags|quality mode|fallback reasons?|source paths?|adapter\/run|sanitizeSourcesLine|report_mode_reason|answer_path|arbiter_mode|arbiter mode|deterministic fallback|relation-?mode|contract parse failures?|goal-?zone harness|pass\/fail across seeds|hybrid explain mode|intent detection|final answer cleanup|relation topology|dual-domain detection|platonic gate scoring|citation allowlists?|graph resolver)\b/i.test(
      trimmed,
    );
  return internalMechanicsPrompt;
};

const shouldBypassHelixAskPreIntentClarifyForCompositionalPrompt = (args: {
  question: string;
  explicitRepoExpectation?: boolean;
  hasFilePathHints?: boolean;
  endpointHintCount?: number;
  requiresRepoEvidence?: boolean;
  intentDomain?: HelixAskDomain;
}): boolean => {
  const trimmed = args.question.trim();
  if (!trimmed) return false;
  if (
    args.explicitRepoExpectation ||
    args.hasFilePathHints ||
    (args.endpointHintCount ?? 0) > 0 ||
    args.requiresRepoEvidence ||
    args.intentDomain === "repo" ||
    args.intentDomain === "hybrid"
  ) {
    return false;
  }
  const writingAdvicePrompt =
    /\b(short answer|brief answer|short response|one sentence|opening paragraph|takeaway|summary|wording|phrasing|structure)\b/i.test(
      trimmed,
    ) &&
    /\b(clean way|best way|good way|how should i|how do i|what(?:'s| is) (?:a )?(?:clean|good|best) way)\b/i.test(
      trimmed,
    );
  if (writingAdvicePrompt) return true;
  if (hasConversationQuestionCue(trimmed)) return false;
  if (trimmed.length > 120) return false;
  return /^(?:say|write|reply|respond|give|tell|draft|compose)\b/i.test(trimmed);
};

const HELIX_ASK_DEFINITION_TARGET_GENERIC_RE =
  /^(?:this|that|it|they|them|thing|things|stuff|term|concept|idea|one|ones|those|these)$/i;

const hasHelixAskConcreteDefinitionTarget = (question: string): boolean => {
  const trimmed = question.trim();
  if (!trimmed) return false;
  const normalized = trimmed.replace(HELIX_CONVERSATION_LEADING_FILLER_RE, "").trim();
  const directMatch = normalized.match(
    /^(?:(?:what\s+(?:is|are))|what's|whats|define|describe|explain|meaning\s+of)\s+(.+?)[.?!]*$/i,
  );
  const meanMatch = normalized.match(
    /^(?:what\s+does)\s+(.+?)\s+mean(?:\s+in\s+.+?)?[.?!]*$/i,
  );
  const matched = directMatch ?? meanMatch;
  if (!matched) return false;
  let target = (matched[1] ?? "").trim();
  target = target.replace(/^["'`([{<\s]+|["'`)\]}>]+$/g, "").trim();
  target = target.replace(/^(?:the|a|an)\s+/i, "").trim();
  target = target.replace(/\b(?:in|for)\s+(?:simple|plain)\s+terms$/i, "").trim();
  if (!target) return false;
  const targetTokens = filterCriticTokens(tokenizeAskQuery(target));
  if (targetTokens.length === 0) return false;
  if (targetTokens.every((token) => HELIX_ASK_DEFINITION_TARGET_GENERIC_RE.test(token))) {
    return false;
  }
  return true;
};

const shouldBypassHelixAskPreIntentClarifyForDefinitionTarget = (args: {
  question: string;
  explicitRepoExpectation?: boolean;
  hasFilePathHints?: boolean;
  endpointHintCount?: number;
  requiresRepoEvidence?: boolean;
}): boolean => {
  const trimmed = args.question.trim();
  if (!trimmed) return false;
  if (args.explicitRepoExpectation) {
    return false;
  }
  return hasHelixAskConcreteDefinitionTarget(trimmed);
};

const shouldBypassHelixAskPreIntentClarifyForGeneralDefinitionTarget = (args: {
  question: string;
  intentDomain?: HelixAskDomain;
  explicitRepoExpectation?: boolean;
  hasFilePathHints?: boolean;
  endpointHintCount?: number;
  requiresRepoEvidence?: boolean;
}): boolean => {
  const trimmed = args.question.trim();
  if (!trimmed) return false;
  if (args.intentDomain && args.intentDomain !== "general") return false;
  if (args.explicitRepoExpectation) return false;
  if (args.requiresRepoEvidence) return false;
  if (args.hasFilePathHints) return false;
  if ((args.endpointHintCount ?? 0) > 0) return false;
  if (isSecurityRiskPrompt(trimmed)) return false;
  if (hasHelixAskRepoTechnicalCue(trimmed)) return false;
  return hasHelixAskConcreteDefinitionTarget(trimmed);
};

const shouldBypassHelixAskPreIntentClarifyForCompareTarget = (question: string): boolean => {
  const trimmed = question.trim();
  if (!trimmed) return false;
  if (!/\b(?:compare|comparison|different|difference|versus|vs\.?|contrast|between)\b/i.test(trimmed)) {
    return false;
  }
  const normalized = trimmed.replace(HELIX_CONVERSATION_LEADING_FILLER_RE, "").trim();
  const compareBody = normalized
    .replace(/^(?:please\s+)?(?:compare|contrast)\b/i, "")
    .replace(/\bdifference\s+between\b/i, "between")
    .trim();
  const segments = compareBody
    .split(/\b(?:and|vs\.?|versus)\b/i)
    .map((part) => part.replace(/^between\b/i, "").replace(/[?.!,;:]+$/g, "").trim())
    .filter(Boolean);
  const informativeSegments = segments.filter((segment) => {
    const tokens = filterCriticTokens(tokenizeAskQuery(segment));
    if (tokens.length === 0) return false;
    if (tokens.every((token) => HELIX_ASK_DEFINITION_TARGET_GENERIC_RE.test(token))) return false;
    return true;
  });
  return informativeSegments.length >= 2;
};

const shouldPreferHelixAskPlannerLlmInFastMode = (args: {
  fastQualityMode: boolean;
  question: string;
  intentDomain: HelixAskDomain;
  requiresRepoEvidence: boolean;
  explicitRepoExpectation: boolean;
  hasFilePathHints: boolean;
  endpointHintCount: number;
}): boolean => {
  if (!args.fastQualityMode) return true;
  const repoSignal =
    args.requiresRepoEvidence ||
    args.explicitRepoExpectation ||
    args.hasFilePathHints ||
    args.endpointHintCount > 0 ||
    args.intentDomain === "repo" ||
    args.intentDomain === "hybrid" ||
    args.intentDomain === "falsifiable" ||
    hasHelixAskRepoTechnicalCue(args.question);
  if (!repoSignal) return false;
  const trimmed = args.question.trim();
  if (
    trimmed.length < 18 &&
    !args.explicitRepoExpectation &&
    !args.hasFilePathHints &&
    args.endpointHintCount <= 0
  ) {
    return false;
  }
  return true;
};

const shouldUseHelixAskRiskTriggeredTwoPass = (args: {
  enabled: boolean;
  allowByPolicy: boolean;
  question: string;
  promptIngested: boolean;
  hasRepoHints: boolean;
  isRepoQuestion: boolean;
  requiresRepoEvidence: boolean;
  format: HelixAskFormat;
  retrievalConfidence: number;
  hybridThreshold: number;
  slotMissingCount: number;
  docMissingCount: number;
}): {
  use: boolean;
  reason:
    | "disabled"
    | "policy"
    | "prompt_ingested"
    | "heuristic_trigger"
    | "risk_trigger"
    | "none";
} => {
  if (!args.enabled) {
    return { use: false, reason: "disabled" };
  }
  if (!args.allowByPolicy) {
    return { use: false, reason: "policy" };
  }
  if (args.promptIngested) {
    return { use: false, reason: "prompt_ingested" };
  }
  const trimmed = args.question.trim();
  if (!trimmed) {
    return { use: false, reason: "none" };
  }
  if (HELIX_ASK_TWO_PASS_TRIGGER.test(trimmed)) {
    return { use: true, reason: "heuristic_trigger" };
  }
  const repoSignal = args.hasRepoHints || args.isRepoQuestion || args.requiresRepoEvidence;
  const coverageGap = args.slotMissingCount > 0 || args.docMissingCount > 0;
  const lowConfidence =
    Number.isFinite(args.retrievalConfidence) &&
    args.retrievalConfidence < Math.max(0.25, args.hybridThreshold - 0.1);
  const formatPressure = args.format === "steps";
  if (repoSignal && (coverageGap || lowConfidence || formatPressure)) {
    return { use: true, reason: "risk_trigger" };
  }
  return { use: false, reason: "none" };
};

const shouldOverrideHelixAskRetrievalRetryPolicy = (args: {
  fastQualityMode: boolean;
  isRepoQuestion: boolean;
  hasRepoHints: boolean;
  missingSlotsForRetry: boolean;
  retrievalConfidence: number;
  hybridThreshold: number;
}): boolean => {
  if (!args.fastQualityMode) return false;
  if (!args.isRepoQuestion) return false;
  if (!args.hasRepoHints) return false;
  return (
    args.missingSlotsForRetry ||
    (Number.isFinite(args.retrievalConfidence) &&
      args.retrievalConfidence < Math.max(0.2, args.hybridThreshold - 0.2))
  );
};

const renderHelixAskSimpleWritingAdviceAnswer = (question: string): string | null => {
  const trimmed = question.trim();
  if (!trimmed) return null;
  const writingAdvicePrompt =
    /\b(short answer|brief answer|short response|one sentence|opening paragraph|takeaway|summary|wording|phrasing|structure)\b/i.test(
      trimmed,
    ) &&
    /\b(clean way|best way|good way|how should i|how do i|what(?:'s| is) (?:a )?(?:clean|good|best) way)\b/i.test(
      trimmed,
    );
  if (!writingAdvicePrompt) return null;
  return (
    "Lead with the direct answer, follow with one sentence that gives the key reason or evidence, " +
    "and end with a caveat or next step only if it changes the outcome. That keeps the response short, " +
    "readable, and easy to expand when the reader needs more context.\n\n" +
    "Sources: docs/helix-ask-flow.md, docs/helix-ask-agent-policy.md"
  );
};

const shouldUseGeneralAmbiguityAnswerFloor = (args: {
  intentDomain: HelixAskDomain;
  requiresRepoEvidence: boolean;
  explicitRepoExpectation: boolean;
  hasFilePathHints: boolean;
  endpointHintCount: number;
}): boolean =>
  args.intentDomain === "general" &&
  !args.requiresRepoEvidence &&
  !args.explicitRepoExpectation &&
  !args.hasFilePathHints &&
  args.endpointHintCount <= 0;

const buildGeneralAmbiguityAnswerFloor = (args: {
  question: string;
  clarifyLine: string;
}): string => {
  const writingAdvice = renderHelixAskSimpleWritingAdviceAnswer(args.question);
  if (writingAdvice) {
    const answer = `${writingAdvice}\n\nClarify: ${args.clarifyLine}`.trim();
    if (answer.length >= HELIX_ASK_QUALITY_MIN_TEXT_CHARS) {
      return answer;
    }
    return (
      `${answer}\n` +
      "Use concrete nouns, measurable evidence, and one explicit uncertainty so reviewers can audit every claim."
    ).trim();
  }
  const compactQuestion = args.question.trim();
  const questionLead = compactQuestion
    ? `Best-effort answer for "${compactQuestion}": keep the response claim-first, include the strongest available evidence line, and keep one explicit uncertainty visible.`
    : "Best-effort answer: keep the response claim-first, include the strongest available evidence line, and keep one explicit uncertainty visible.";
  const scaffold = [
    questionLead,
    "Implication: this supports a provisional decision now, and the decision should update when new evidence directly resolves the uncertainty.",
    `Clarify: ${args.clarifyLine}`,
  ].join("\n\n").trim();
  if (scaffold.length >= HELIX_ASK_QUALITY_MIN_TEXT_CHARS) {
    return scaffold;
  }
  return (
    `${scaffold}\n` +
    "Prefer direct language over abstractions so the reader can verify what is known, what is inferred, and what is still missing."
  ).trim();
};

const renderHelixAskSimpleCompositionalAnswer = (question: string): string | null => {
  const trimmed = question.trim();
  if (!trimmed) return null;
  const matched = trimmed.match(
    /^(?:please\s+)?(?:say|write|reply|respond|give|tell|draft|compose)\s+(.*)$/i,
  );
  if (!matched) return null;
  let body = matched[1]?.trim() ?? "";
  body = body.replace(/\s+in\s+(?:one|1)\s+sentence(?:s)?[.?!]*$/i, "").trim();
  body = body.replace(/\s+using\s+(?:one|1)\s+sentence(?:s)?[.?!]*$/i, "").trim();
  body = body.replace(/^(?:with\s+)/i, "").trim();
  body = body.replace(/^["'`]+|["'`]+$/g, "").trim();
  if (!body) return null;
  if (/^[a-z]/.test(body)) {
    body = body.charAt(0).toUpperCase() + body.slice(1);
  }
  if (!/[.!?]$/.test(body)) {
    body = `${body}.`;
  }
  return body;
};

const isHelixAskHardForcedShortCircuitRule = (rule: string | null | undefined): boolean =>
  rule === "forcedAnswer:pre_intent_clarify" ||
  rule === "forcedAnswer:simple_composition" ||
  rule === "forcedAnswer:math_solver" ||
  rule === "forcedAnswer:math_solver_warp_guard" ||
  rule === "forcedAnswer:constraint_report" ||
  rule === "forcedAnswer:helix_pipeline" ||
  rule === "forcedAnswer:stage05_summary_hard_fail" ||
  rule === "forcedAnswer:research_contract_fail_closed" ||
  rule === "forcedAnswer:concept" ||
  rule === "forcedAnswer:concept_short_definition";

const isHelixAskConceptForcedShortCircuitRule = (rule: string | null | undefined): boolean =>
  rule === "forcedAnswer:concept" || rule === "forcedAnswer:concept_short_definition";

const isHelixAskClarifyForcedShortCircuitRule = (rule: string | null | undefined): boolean =>
  rule === "forcedAnswer:pre_intent_clarify";

const isHelixAskResearchContractFailClosedForcedShortCircuitRule = (
  rule: string | null | undefined,
): boolean => rule === "forcedAnswer:research_contract_fail_closed";

const isHelixAskSimpleForcedShortCircuitRule = (rule: string | null | undefined): boolean =>
  rule === "forcedAnswer:simple_composition";

const isHelixAskPipelineForcedShortCircuitRule = (rule: string | null | undefined): boolean =>
  rule === "forcedAnswer:helix_pipeline";

const shouldFastPathFinalizeHelixAskForcedAnswer = (args: {
  shouldShortCircuitAnswer: boolean;
  fallbackAnswer: string;
  forcedAnswerIsHard: boolean;
  forcedRule?: string | null;
  conceptFastPath: boolean;
  isIdeologyReferenceIntent: boolean;
  verbosity: HelixAskVerbosity;
}): boolean => {
  if (!args.shouldShortCircuitAnswer) return false;
  if (!args.forcedAnswerIsHard) return false;
  const forcedRule = args.forcedRule ?? null;
  if (isHelixAskResearchContractFailClosedForcedShortCircuitRule(forcedRule)) {
    return true;
  }
  const normalizedFallback = String(args.fallbackAnswer ?? "").trim();
  if (!normalizedFallback) return false;
  if (hasSourcesLine(normalizedFallback)) {
    return true;
  }
  if (HELIX_ASK_STRUCTURED_DETERMINISTIC_SECTION_RE.test(normalizedFallback)) {
    return true;
  }
  if (
    args.isIdeologyReferenceIntent &&
    args.conceptFastPath &&
    String(args.verbosity ?? "").trim().length > 0
  ) {
    return true;
  }
  return false;
};

const shouldPreserveHelixAskForcedAnswerAcrossComposer = (args: {
  forcedAnswerPinned: boolean;
  forcedRule?: string | null;
}): boolean =>
  args.forcedAnswerPinned &&
  (isHelixAskConceptForcedShortCircuitRule(args.forcedRule ?? null) ||
    isHelixAskClarifyForcedShortCircuitRule(args.forcedRule ?? null) ||
    isHelixAskResearchContractFailClosedForcedShortCircuitRule(args.forcedRule ?? null) ||
    isHelixAskSimpleForcedShortCircuitRule(args.forcedRule ?? null) ||
    isHelixAskPipelineForcedShortCircuitRule(args.forcedRule ?? null));

const shouldPreserveHelixAskForcedAnswerAcrossFinalizer = (args: {
  forcedAnswerPinned: boolean;
  forcedRule?: string | null;
}): boolean =>
  args.forcedAnswerPinned &&
  (isHelixAskClarifyForcedShortCircuitRule(args.forcedRule ?? null) ||
    isHelixAskResearchContractFailClosedForcedShortCircuitRule(args.forcedRule ?? null) ||
    isHelixAskSimpleForcedShortCircuitRule(args.forcedRule ?? null) ||
    isHelixAskPipelineForcedShortCircuitRule(args.forcedRule ?? null));

const resolveStage05SummaryPolicy = (args?: {
  singleLlm?: boolean;
  llmFirstEnabled?: boolean;
  summaryRequired?: boolean;
  hardFailOnSummaryError?: boolean;
}): {
  llmFirst: boolean;
  summaryRequired: boolean;
  hardFailOnSummaryError: boolean;
} => {
  const llmFirstEnabled =
    typeof args?.llmFirstEnabled === "boolean" ? args.llmFirstEnabled : HELIX_ASK_STAGE05_LLM_FIRST;
  const singleLlm = typeof args?.singleLlm === "boolean" ? args.singleLlm : HELIX_ASK_SINGLE_LLM;
  const llmFirst = llmFirstEnabled && !singleLlm;
  const summaryRequiredRequested =
    typeof args?.summaryRequired === "boolean"
      ? args.summaryRequired
      : HELIX_ASK_STAGE05_SUMMARY_REQUIRED;
  const summaryRequired = summaryRequiredRequested && llmFirst;
  const hardFailRequested =
    typeof args?.hardFailOnSummaryError === "boolean"
      ? args.hardFailOnSummaryError
      : HELIX_ASK_STAGE05_HARD_FAIL_ON_SUMMARY_ERROR;
  const hardFailOnSummaryError = hardFailRequested && summaryRequired;
  return {
    llmFirst,
    summaryRequired,
    hardFailOnSummaryError,
  };
};

const shouldRetryHelixAskOuterLlmCall = (args: {
  errorCode: string | undefined;
  attemptIndex: number;
  maxAttempts: number;
}): boolean => {
  if (!args.errorCode) return false;
  if (args.attemptIndex >= args.maxAttempts) return false;
  if (!isHelixAskComposerV2TransientLlmErrorCode(args.errorCode)) return false;
  if (/^llm_http_429(?::|$)/i.test(args.errorCode)) return false;
  if (/^llm_http_circuit_open$/i.test(args.errorCode)) return false;
  return true;
};

const resolveHelixAskComposerV2TransientRetryDelayMs = (
  errorCode: string | undefined,
  attemptIndex: number,
): number => {
  const attempt = Number.isFinite(attemptIndex) ? Math.max(1, Math.floor(attemptIndex)) : 1;
  let delayMs = Math.min(
    HELIX_ASK_COMPOSER_V2_TRANSIENT_RETRY_MAX_WAIT_MS,
    HELIX_ASK_COMPOSER_V2_TRANSIENT_RETRY_BACKOFF_MS * attempt,
  );
  if (errorCode === "llm_http_circuit_open") {
    const breaker = getLlmHttpBreakerSnapshot();
    const remainingMs =
      typeof breaker.remaining_ms === "number" && Number.isFinite(breaker.remaining_ms)
        ? Math.max(0, Math.floor(breaker.remaining_ms))
        : 0;
    if (remainingMs > 0) {
      delayMs = Math.max(
        delayMs,
        Math.min(remainingMs, HELIX_ASK_COMPOSER_V2_TRANSIENT_RETRY_MAX_WAIT_MS),
      );
    }
  }
  return clampNumber(delayMs, 100, HELIX_ASK_COMPOSER_V2_TRANSIENT_RETRY_MAX_WAIT_MS);
};

const resolveHelixAskAnswerTransientRetryDelayMs = (
  errorCode: string | undefined,
  attemptIndex: number,
): number => {
  const attempt = Number.isFinite(attemptIndex) ? Math.max(1, Math.floor(attemptIndex)) : 1;
  const normalizedCode = String(errorCode ?? "").toLowerCase();
  const retryAfterMatch = normalizedCode.match(/^llm_http_429:(\d+)$/i);
  const retryAfterMs = retryAfterMatch ? Math.max(0, Number(retryAfterMatch[1])) : 0;
  let delayMs = Math.min(
    HELIX_ASK_ANSWER_TRANSIENT_RETRY_MAX_WAIT_MS,
    HELIX_ASK_ANSWER_TRANSIENT_RETRY_BACKOFF_MS * attempt,
  );
  if (normalizedCode === "llm_http_circuit_open") {
    const breaker = getLlmHttpBreakerSnapshot();
    const remainingMs =
      typeof breaker.remaining_ms === "number" && Number.isFinite(breaker.remaining_ms)
        ? Math.max(0, Math.floor(breaker.remaining_ms))
        : 0;
    if (remainingMs > 0) {
      delayMs = Math.max(
        delayMs,
        Math.min(remainingMs, HELIX_ASK_ANSWER_TRANSIENT_RETRY_MAX_WAIT_MS),
      );
    }
  }
  if (retryAfterMs > 0) {
    delayMs = Math.max(delayMs, Math.min(retryAfterMs, HELIX_ASK_ANSWER_TRANSIENT_RETRY_MAX_WAIT_MS));
  }
  return clampNumber(delayMs, 100, HELIX_ASK_ANSWER_TRANSIENT_RETRY_MAX_WAIT_MS);
};

const sleepHelixAskComposerV2Retry = async (delayMs: number): Promise<void> => {
  const bounded = Number.isFinite(delayMs) ? Math.max(0, Math.floor(delayMs)) : 0;
  if (bounded <= 0) return;
  await new Promise<void>((resolve) => {
    setTimeout(resolve, bounded);
  });
};

const extractHelixAskLlmCallMetaFromResult = (
  result: LocalAskResult | null | undefined,
  args: {
    stage: string;
    startedAtMs: number;
    endedAtMs: number;
  },
): HelixAskLlmCallMeta => {
  const endedAtMs = Number.isFinite(args.endedAtMs) ? Math.max(args.startedAtMs, args.endedAtMs) : Date.now();
  const backendCandidate = typeof result?.__llm_backend === "string" ? result.__llm_backend : undefined;
  const backend: LocalLlmBackend =
    backendCandidate === "http" || backendCandidate === "spawn" || backendCandidate === "none"
      ? backendCandidate
      : resolveLlmLocalBackend();
  const providerCalledCandidate = result?.__llm_provider_called;
  const providerCalled =
    typeof providerCalledCandidate === "boolean" ? providerCalledCandidate : backend === "http";
  const statusCandidate = result?.status;
  const status =
    typeof statusCandidate === "number" && Number.isFinite(statusCandidate)
      ? Math.floor(statusCandidate)
      : undefined;
  const model =
    typeof result?.model === "string" && result.model.trim().length > 0
      ? result.model.trim()
      : undefined;
  const routedVia =
    typeof result?.__llm_routed_via === "string" && result.__llm_routed_via.trim().length > 0
      ? result.__llm_routed_via.trim()
      : undefined;
  const retryAfterMs =
    typeof result?.__llm_retry_after_ms === "number" && Number.isFinite(result.__llm_retry_after_ms)
      ? Math.max(0, Math.floor(result.__llm_retry_after_ms))
      : undefined;
  const timeoutMs =
    typeof result?.__llm_timeout_ms === "number" && Number.isFinite(result.__llm_timeout_ms)
      ? Math.max(0, Math.floor(result.__llm_timeout_ms))
      : undefined;
  const maxTokensRequested =
    typeof result?.__llm_max_tokens_requested === "number" &&
    Number.isFinite(result.__llm_max_tokens_requested)
      ? Math.max(0, Math.floor(result.__llm_max_tokens_requested))
      : undefined;
  const maxTokensEffective =
    typeof result?.__llm_max_tokens_effective === "number" &&
    Number.isFinite(result.__llm_max_tokens_effective)
      ? Math.max(0, Math.floor(result.__llm_max_tokens_effective))
      : undefined;
  const retryCount =
    typeof result?.__llm_http_retry_count === "number" &&
    Number.isFinite(result.__llm_http_retry_count)
      ? Math.max(0, Math.floor(result.__llm_http_retry_count))
      : undefined;
  const attempts =
    typeof result?.__llm_http_attempts === "number" && Number.isFinite(result.__llm_http_attempts)
      ? Math.max(0, Math.floor(result.__llm_http_attempts))
      : undefined;
  const retryDelaysMs = Array.isArray(result?.__llm_http_retry_delays_ms)
    ? result.__llm_http_retry_delays_ms
        .map((value) =>
          typeof value === "number" && Number.isFinite(value)
            ? Math.max(0, Math.floor(value))
            : null,
        )
        .filter((value): value is number => value !== null)
        .slice(0, 8)
    : undefined;
  const errorDetails = parseHelixAskLlmErrorDetails(result?.__llm_error_code);
  const providerRequestId =
    typeof result?.__llm_provider_request_id === "string" && result.__llm_provider_request_id.trim().length > 0
      ? result.__llm_provider_request_id.trim()
      : errorDetails.providerRequestId;
  const promptMessagesCount =
    typeof result?.__llm_prompt_messages_count === "number" && Number.isFinite(result.__llm_prompt_messages_count)
      ? Math.max(0, Math.floor(result.__llm_prompt_messages_count))
      : errorDetails.promptMessagesCount;
  const promptChars =
    typeof result?.__llm_prompt_chars === "number" && Number.isFinite(result.__llm_prompt_chars)
      ? Math.max(0, Math.floor(result.__llm_prompt_chars))
      : errorDetails.promptChars;
  const promptTokensEstimate =
    typeof result?.__llm_prompt_tokens_estimate === "number" &&
    Number.isFinite(result.__llm_prompt_tokens_estimate)
      ? Math.max(0, Math.floor(result.__llm_prompt_tokens_estimate))
      : errorDetails.promptTokensEstimate;
  const requestBodyBytes =
    typeof result?.__llm_request_body_bytes === "number" && Number.isFinite(result.__llm_request_body_bytes)
      ? Math.max(0, Math.floor(result.__llm_request_body_bytes))
      : errorDetails.requestBodyBytes;
  const startedAtIso = new Date(args.startedAtMs).toISOString();
  const endedAtIso = new Date(endedAtMs).toISOString();
  return {
    stage: args.stage || "answer",
    backend,
    providerCalled,
    model,
    status,
    routedVia,
    retryAfterMs,
    timeoutMs,
    maxTokensRequested,
    maxTokensEffective,
    retryCount,
    attempts,
    retryDelaysMs,
    transient: retryCount ? retryCount > 0 : undefined,
    errorCode: errorDetails.normalizedCode,
    errorClass: errorDetails.errorClass !== "unknown" ? errorDetails.errorClass : undefined,
    rateLimitSource: errorDetails.rateLimitSource,
    rateLimitKind: errorDetails.rateLimitKind,
    providerRequestId,
    providerRetryAfterRaw: errorDetails.providerRetryAfterRaw,
    providerErrorText: errorDetails.providerErrorText,
    providerRateLimitHeaders: errorDetails.providerRateLimitHeaders,
    promptMessagesCount,
    promptChars,
    promptTokensEstimate,
    requestBodyBytes,
    startedAtIso,
    endedAtIso,
    durationMs: Math.max(0, endedAtMs - args.startedAtMs),
  };
};

const OVERFLOW_CONTEXT_MARKERS = new Set([
  "context:",
  "prompt context:",
  "evidence:",
  "evidence bullets:",
  "evidence steps:",
  "repo evidence:",
  "general reasoning:",
  "constraint evidence:",
  "technical notes:",
  "tree walk:",
]);
const OVERFLOW_ERROR_RE =
  /(context|ctx|token|prompt\s+too\s+long|max(?:imum)?\s+context|n_ctx|exceed)/i;

const parseOverflowPolicy = (value: string): string[] =>
  value
    .split(/_then_|->/g)
    .map((entry) => entry.trim())
    .filter((entry) => entry && entry !== "retry");

const prunePromptContext = (prompt: string): { prompt: string; applied: boolean } => {
  const lines = prompt.split(/\r?\n/);
  const out: string[] = [];
  let inContext = false;
  let applied = false;
  for (const line of lines) {
    const trimmed = line.trim();
    const lowered = trimmed.toLowerCase();
    if (!inContext && OVERFLOW_CONTEXT_MARKERS.has(lowered)) {
      inContext = true;
      applied = true;
      out.push(line);
      out.push("Context omitted due to overflow.");
      continue;
    }
    if (inContext) {
      if (trimmed === HELIX_ASK_ANSWER_START || trimmed === HELIX_ASK_ANSWER_END) {
        inContext = false;
        out.push(line);
      }
      continue;
    }
    out.push(line);
  }
  return { prompt: out.join("\n"), applied };
};

const applyOverflowStep = (args: {
  step: string;
  prompt: string;
  maxTokens: number | undefined;
  fallbackMaxTokens: number;
  allowContextDrop: boolean;
}): { prompt: string; maxTokens: number | undefined; applied: boolean } => {
  if (args.step === "drop_context" && args.allowContextDrop) {
    const pruned = prunePromptContext(args.prompt);
    if (pruned.applied) {
      return { prompt: pruned.prompt, maxTokens: args.maxTokens, applied: true };
    }
    return { prompt: args.prompt, maxTokens: args.maxTokens, applied: false };
  }
  if (args.step === "drop_output") {
    const budget = args.maxTokens ?? args.fallbackMaxTokens;
    const promptTokens = estimateTokenCount(args.prompt);
    const available = Math.max(1, HELIX_ASK_LOCAL_CONTEXT_TOKENS - promptTokens - 8);
    const nextMaxTokens = Math.min(Math.max(1, Math.floor(budget)), available);
    if (args.maxTokens === nextMaxTokens) {
      return { prompt: args.prompt, maxTokens: args.maxTokens, applied: false };
    }
    return { prompt: args.prompt, maxTokens: nextMaxTokens, applied: true };
  }
  return { prompt: args.prompt, maxTokens: args.maxTokens, applied: false };
};

const isOverflowLikely = (prompt: string, maxTokens: number): boolean => {
  const promptTokens = estimateTokenCount(prompt);
  return promptTokens + maxTokens > HELIX_ASK_LOCAL_CONTEXT_TOKENS;
};

const runHelixAskLocalWithOverflowRetry = async (
  input: {
    prompt: string;
    max_tokens?: number;
    temperature?: number;
    seed?: number;
    stop?: string | string[];
    model?: string;
  },
  ctx: {
    personaId: string;
    sessionId?: string;
    traceId?: string;
    onToken?: (chunk: string) => void;
  },
  options: HelixAskOverflowOptions = {},
): Promise<{ result: LocalAskResult; overflow?: HelixAskOverflowMeta; llm?: HelixAskLlmCallMeta }> => {
  assertCurrentHelixExternalExecutionActive();
  const steps = parseOverflowPolicy(HELIX_ASK_OVERFLOW_RETRY_POLICY);
  const fallbackMaxTokens = Math.max(1, Math.floor(options.fallbackMaxTokens ?? 256));
  let prompt = applyDialogueProfilePrompt(
    input.prompt,
    options.dialogueProfile,
    options.dialogueQuestion ?? "",
  );
  let maxTokens = input.max_tokens;
  const appliedSteps: string[] = [];
  let attempts = 0;

  if (HELIX_ASK_OVERFLOW_RETRY && steps.length > 0) {
    for (const step of steps) {
      const budget = maxTokens ?? fallbackMaxTokens;
      if (!isOverflowLikely(prompt, budget)) {
        break;
      }
      const applied = applyOverflowStep({
        step,
        prompt,
        maxTokens,
        fallbackMaxTokens,
        allowContextDrop: options.allowContextDrop !== false,
      });
      if (!applied.applied) {
        continue;
      }
      prompt = applied.prompt;
      maxTokens = applied.maxTokens;
      appliedSteps.push(step);
    }
  }

  while (true) {
    assertCurrentHelixExternalExecutionActive();
    attempts += 1;
    const invokeStartedAtMs = Date.now();
    try {
      const result = (await llmLocalHandler(
        {
          prompt,
          max_tokens: maxTokens ?? input.max_tokens,
          temperature: input.temperature,
          seed: input.seed,
          stop: input.stop,
          model: input.model,
        },
        ctx,
      )) as LocalAskResult;
      assertCurrentHelixExternalExecutionActive();
      const invokeEndedAtMs = Date.now();
      const promptTokens = estimateTokenCount(prompt);
      const overflow =
        appliedSteps.length > 0
          ? {
              applied: true,
              steps: appliedSteps.slice(),
              attempts,
              promptTokens,
              maxTokens: maxTokens ?? fallbackMaxTokens,
            }
          : undefined;
      const llm = extractHelixAskLlmCallMetaFromResult(result, {
        stage: options.label ?? "answer",
        startedAtMs: invokeStartedAtMs,
        endedAtMs: invokeEndedAtMs,
      });
      return { result, overflow, llm };
    } catch (error) {
      assertCurrentHelixExternalExecutionActive();
      const message = error instanceof Error ? error.message : String(error);
      const details = parseHelixAskLlmErrorDetails(error);
      const overflowError = HELIX_ASK_OVERFLOW_RETRY && OVERFLOW_ERROR_RE.test(message);
      if (!overflowError || steps.length === 0) {
        if (error && typeof error === "object") {
          const backend = resolveLlmLocalBackend();
          const errorRecord = error as Record<string, unknown>;
          const retryCount =
            typeof errorRecord.__llm_http_retry_count === "number" &&
            Number.isFinite(errorRecord.__llm_http_retry_count)
              ? Math.max(0, Math.floor(errorRecord.__llm_http_retry_count))
              : undefined;
          const attempts =
            typeof errorRecord.__llm_http_attempts === "number" &&
            Number.isFinite(errorRecord.__llm_http_attempts)
              ? Math.max(0, Math.floor(errorRecord.__llm_http_attempts))
              : undefined;
          const retryDelaysMs = Array.isArray(errorRecord.__llm_http_retry_delays_ms)
            ? errorRecord.__llm_http_retry_delays_ms
                .map((value) =>
                  typeof value === "number" && Number.isFinite(value) ? Math.max(0, Math.floor(value)) : null,
                )
                .filter((value): value is number => value !== null)
                .slice(0, 8)
            : undefined;
          (error as Record<string, unknown>).__llm_call = {
            stage: options.label ?? "answer",
            backend,
            providerCalled: typeof details.providerCalled === "boolean" ? details.providerCalled : backend === "http",
            startedAtIso: new Date(invokeStartedAtMs).toISOString(),
            endedAtIso: new Date().toISOString(),
            durationMs: Math.max(0, Date.now() - invokeStartedAtMs),
            errorCode: details.normalizedCode,
            errorClass: details.errorClass,
            errorMessage: message,
            transient: details.transient,
            status: details.status,
            retryAfterMs: details.retryAfterMs,
            timeoutMs: details.timeoutMs,
            maxTokensRequested: details.maxTokensRequested,
            maxTokensEffective: details.maxTokensEffective,
            retryCount,
            attempts,
            retryDelaysMs,
            circuitOpen: details.circuitOpen,
            circuitRemainingMs: details.circuitRemainingMs,
            rateLimitSource: details.rateLimitSource,
            rateLimitKind: details.rateLimitKind,
            providerRequestId: details.providerRequestId,
            providerRetryAfterRaw: details.providerRetryAfterRaw,
            providerErrorText: details.providerErrorText,
            providerRateLimitHeaders: details.providerRateLimitHeaders,
            promptMessagesCount: details.promptMessagesCount,
            promptChars: details.promptChars,
            promptTokensEstimate: details.promptTokensEstimate,
            requestBodyBytes: details.requestBodyBytes,
          } satisfies HelixAskLlmCallMeta;
        }
        throw error;
      }
      const nextStep = steps[appliedSteps.length];
      if (!nextStep) {
        throw error;
      }
      const applied = applyOverflowStep({
        step: nextStep,
        prompt,
        maxTokens,
        fallbackMaxTokens,
        allowContextDrop: options.allowContextDrop !== false,
      });
      if (!applied.applied) {
        throw error;
      }
      prompt = applied.prompt;
      maxTokens = applied.maxTokens;
      appliedSteps.push(nextStep);
    }
  }
};

const AMBIGUOUS_IGNORE_TOKENS = new Set([
  "helix",
  "ask",
  "system",
  "repo",
  "codebase",
  "pipeline",
  "file",
  "files",
  "path",
  "paths",
  "citations",
  "citation",
  "module",
  "modules",
  "define",
  "defined",
  "definition",
  "explain",
  "describe",
  "meaning",
  "mean",
  "connect",
  "connection",
  "connections",
  "relate",
  "relation",
  "relations",
  "related",
]);

const collectConceptTokens = (conceptMatch: HelixAskConceptMatch | null): Set<string> => {
  if (!conceptMatch) return new Set<string>();
  const values = [
    conceptMatch.card.id,
    conceptMatch.card.label ?? "",
    ...(conceptMatch.card.aliases ?? []),
  ].filter(Boolean);
  const tokens = values
    .flatMap((value) => tokenizeAskQuery(value))
    .flatMap((token) => filterCriticTokens([token]));
  return new Set(tokens.map((token) => token.toLowerCase()));
};

const stripEdgePunctuation = (value: string): string =>
  value.replace(/^[^a-z0-9]+|[^a-z0-9]+$/gi, "");

const stripLeadingArticles = (value: string): string =>
  value.replace(/^(?:a|an|the)\s+/i, "");

const extractClarifySpan = (question: string): string | undefined => {
  const match = question.match(
    /\b(?:what\s+is|what's|whats|define|explain|describe|meaning\s+of)\b\s+(.+)$/i,
  );
  if (!match) return undefined;
  let span = match[1].trim();
  span = span.replace(/[?!.]+$/g, "").trim();
  span = span.replace(
    /\b(?:in|within)\s+(?:this|the)\s+(?:codebase|repo|repository|project|system)\b[\s\S]*$/i,
    "",
  ).trim();
  span = span.replace(
    /\b(?:for)\s+(?:this|the)\s+(?:codebase|repo|repository|project|system)\b[\s\S]*$/i,
    "",
  ).trim();
  span = stripLeadingArticles(span);
  return span || undefined;
};

const normalizeClarifyToken = (value: string): string | undefined => {
  const trimmed = stripEdgePunctuation(value.toLowerCase());
  if (!trimmed) return undefined;
  if (AMBIGUOUS_IGNORE_TOKENS.has(trimmed)) return undefined;
  if (trimmed.length < HELIX_ASK_AMBIGUOUS_TERM_MIN_LEN) return undefined;
  return trimmed;
};

const extractAmbiguousTerms = (
  question: string,
  referenceText: string,
  conceptMatch: HelixAskConceptMatch | null,
): string[] => {
  if (!question.trim()) return [];
  const conceptTokens = collectConceptTokens(conceptMatch);
  const normalizedRef = referenceText.toLowerCase();
  const tokens = filterCriticTokens(tokenizeAskQuery(question));
  const out: string[] = [];
  const seen = new Set<string>();
  for (const token of tokens) {
    const normalized = stripEdgePunctuation(token.toLowerCase());
    if (!normalized) continue;
    if (seen.has(normalized)) continue;
    seen.add(normalized);
    if (normalized.length < HELIX_ASK_AMBIGUOUS_TERM_MIN_LEN) continue;
    if (AMBIGUOUS_IGNORE_TOKENS.has(normalized)) continue;
    if (conceptTokens.has(normalized)) continue;
    if (/^\d+$/.test(normalized)) continue;
    if (normalizedRef.includes(normalized)) continue;
    out.push(normalized);
    if (out.length >= HELIX_ASK_AMBIGUOUS_MAX_TERMS) break;
  }
  return out;
};

const buildAmbiguityClarifyLine = (terms: string[]): string => {
  if (!terms.length) {
    return "Repo evidence was required by the question but could not be confirmed. Please point to the relevant files or clarify the term.";
  }
  if (terms.length === 1) {
    return `I do not see "${terms[0]}" in the repo evidence yet. What do you mean by it, or which file should I use?`;
  }
  const joined = terms.map((term) => `"${term}"`).join(" or ");
  return `I do not see ${joined} in the repo evidence yet. Which files define those terms?`;
};

const filterClarifySlots = (slots: string[]): string[] =>
  slots
    .map((slot) => normalizeSlotName(slot))
    .filter(Boolean)
    .filter((slot) => !STRUCTURAL_SLOTS.has(slot))
    .filter((slot) => !SLOT_IGNORE_TOKENS.has(slot));

const buildSlotClarifyOptions = (
  slotId: string,
  slotPlan?: HelixAskSlotPlan | null,
): string[] => {
  const slot = slotPlan?.slots.find((entry) => entry.id === slotId);
  const label = slot?.label ?? slotId;
  const candidates = listConceptCandidates(label, 3);
  const options = candidates.map(formatAmbiguityCandidateLabel).filter(Boolean);
  if (options.length === 0) {
    (slot?.aliases ?? []).forEach((alias) => alias && options.push(alias));
  }
  const unique = Array.from(new Set(options.map((entry) => entry.trim()).filter(Boolean)));
  return unique.slice(0, 2);
};

const buildSlotClarifyLine = (args: {
  missingSlots: string[];
  slotPlan?: HelixAskSlotPlan | null;
  planClarify?: string;
}): string => {
  const planClarify = sanitizePlanClarifyLine(args.planClarify ?? "");
  if (planClarify && /(file|doc|module|path|repo|codebase|where)/i.test(planClarify)) {
    return planClarify;
  }
  const slots = filterClarifySlots(args.missingSlots);
  if (!slots.length) {
    return "Repo evidence was required by the question but could not be confirmed. Please point to the relevant files or clarify the term.";
  }
  const primary = slots[0];
  const label = args.slotPlan?.slots.find((entry) => entry.id === primary)?.label ?? primary;
  const options = buildSlotClarifyOptions(primary, args.slotPlan);
  if (options.length >= 2) {
    return `I could not confirm "${label}" yet. Do you mean "${options[0]}" or "${options[1]}", or can you point to the relevant files?`;
  }
  if (options.length === 1) {
    return `I could not confirm "${label}" yet. Do you mean "${options[0]}", or can you point to the relevant files?`;
  }
  if (slots.length > 1) {
    return `I could not confirm "${label}" (and ${slots.slice(1, 3).join(", ")}). Please point to the relevant files or clarify the terms.`;
  }
  return `I could not confirm "${label}" yet. Please point to the relevant files or clarify the term.`;
};

const sanitizePlanClarifyLine = (value: string): string => {
  const line = value.trim();
  if (!line) return line;
  if (/did not cover key terms from the question/i.test(line)) {
    return "Repo evidence was required by the question but could not be confirmed. Please point to the relevant files or clarify the term.";
  }
  if (/(?:\b[a-z0-9]+(?:-[a-z0-9]+)*-tree\b)/i.test(line)) {
    return "Repo evidence was incomplete for this request. Please point to the relevant files or clarify the term.";
  }
  return line;
};

const sanitizeEvidenceHintAtom = (value: string): string =>
  String(value ?? "")
    .replace(/\s+/g, " ")
    .replace(/^[,;:\s-]+/, "")
    .replace(/[,;:\s-]+$/, "")
    .trim();

const isLowSignalHeadingHintLabel = (value: string): boolean => {
  const trimmed = sanitizeEvidenceHintAtom(value).replace(/^["'`]+|["'`]+$/g, "").trim();
  if (!trimmed) return true;
  if (/^\d+(?:[.)]|(?:\s*[-:]\s*))?$/i.test(trimmed)) return true;
  if (/^[ivxlcdm]+$/i.test(trimmed)) return true;
  if (/^[a-z]\.?$/i.test(trimmed)) return true;
  const alphaChars = trimmed.replace(/[^a-z]/gi, "").length;
  if (alphaChars < 3) return true;
  return false;
};

const normalizeCheckedFileHint = (value: string): string | null => {
  const normalized = sanitizeEvidenceHintAtom(value).replace(/\\/g, "/");
  if (!normalized) return null;
  const candidate = normalized.replace(/^["'`]+|["'`]+$/g, "").trim();
  if (!candidate) return null;
  if (candidate.startsWith(",")) return null;
  if (!/[a-z0-9]/i.test(candidate)) return null;
  if (candidate.length > 120) return null;
  if (!/[/.]/.test(candidate)) return null;
  if (/^\d+(?:\.\d+)?$/.test(candidate)) return null;
  return candidate;
};

const SCIENTIFIC_REPORT_HEAD_RE =
  /^(Confirmed:|Unverified:|Reasoned connections|Hypotheses \(optional\)|Next evidence:)/im;

const isScientificMicroReport = (text: string): boolean =>
  Boolean(text && SCIENTIFIC_REPORT_HEAD_RE.test(text));

const enforceUnverifiedHeading = (text: string): string => {
  if (!text) return text;
  if (!/^Confirmed:/im.test(text)) return text;
  return text.replace(/^Confirmed:/im, "Unverified:");
};

const sanitizeClaimEvidenceRef = (value?: string): string | null => {
  if (!value) return null;
  const normalized = (normalizeEvidenceRef(value) ?? value).trim();
  if (!normalized) return null;
  const extracted = extractFilePathsFromText(normalized)[0];
  if (extracted) return extracted;
  return null;
};

const extractNextEvidenceLines = (text: string): string[] => {
  if (!text) return [];
  const lines = text.split(/\r?\n/);
  const start = lines.findIndex((line) => /^Next evidence:/i.test(line.trim()));
  if (start < 0) return [];
  const out: string[] = [];
  for (let i = start + 1; i < lines.length; i += 1) {
    const trimmed = lines[i].trim();
    if (!trimmed) {
      if (out.length > 0) break;
      continue;
    }
    if (/^[A-Za-z ].+:\s*$/.test(trimmed) && !/^[-*]\s+/.test(trimmed)) {
      break;
    }
    if (/^[-*]\s+/.test(trimmed)) {
      out.push(trimmed.replace(/^[-*]\s+/, "").trim());
      continue;
    }
    if (out.length > 0) break;
  }
  return out;
};

const buildSlotSurfaceHints = (surfaces?: string[]): string[] => {
  if (!surfaces?.length) return [];
  const set = new Set(surfaces.map((entry) => entry.trim().toLowerCase()).filter(Boolean));
  const hints: string[] = [];
  if (set.has("ethos")) hints.push("docs/ethos");
  if (set.has("knowledge")) hints.push("docs/knowledge");
  if (set.has("docs")) hints.push("docs/");
  if (set.has("code")) hints.push("server/ or client/ or modules/");
  return hints;
};

const buildNextEvidenceHints = (args: {
  question: string;
  missingSlots?: string[];
  slotPlan?: HelixAskSlotPlan | null;
  anchorFiles?: string[];
  searchedTerms?: string[];
  searchedFiles?: string[];
  includeSearchSummary?: boolean;
  planClarify?: string;
  headingSeedSlots?: HelixAskSlotPlanEntry[];
  suppressClarify?: boolean;
  limit?: number;
}): string[] => {
  const limit = Math.max(
    1,
    (args.limit ?? 4) + (args.includeSearchSummary ? 2 : 0),
  );
  const hints: string[] = [];
  const seen = new Set<string>();
  const pushHint = (value: string) => {
    const trimmed = value.trim();
    if (!trimmed) return;
    const key = trimmed.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    hints.push(trimmed);
  };
  const planClarify = (args.planClarify ?? "").trim();
  if (!args.suppressClarify && planClarify && /(file|doc|module|path|repo|codebase|where)/i.test(planClarify)) {
    pushHint(`Clarify: ${planClarify}`);
  }
  if (args.includeSearchSummary) {
    const terms = (args.searchedTerms ?? [])
      .flatMap((entry) => String(entry ?? "").split(","))
      .map((entry) => sanitizeEvidenceHintAtom(entry))
      .filter((entry) => entry && !entry.includes("/") && entry.length <= 60)
      .slice(0, 4);
    if (terms.length > 0) {
      pushHint(`Searched terms: ${terms.join(", ")}`);
    }
    const files = (args.searchedFiles ?? [])
      .flatMap((entry) => String(entry ?? "").split(","))
      .map((entry) => normalizeCheckedFileHint(entry))
      .filter((entry): entry is string => Boolean(entry))
      .slice(0, 4);
    if (files.length > 0) {
      pushHint(`Checked files: ${files.join(", ")}`);
    }
  }
  const dirHints = Array.from(
    new Set(
      (args.anchorFiles ?? [])
        .map((filePath) => filePath.split("/")[0])
        .filter((segment) => Boolean(segment)),
    ),
  ).slice(0, 2);
  if (dirHints.length > 0) {
    pushHint(`Check files under ${dirHints.join(" or ")}.`);
  }
  const slots = filterClarifySlots(args.missingSlots ?? []);
  for (const slotId of slots) {
    const slotEntry = args.slotPlan?.slots.find(
      (entry) => entry.id === slotId || normalizeSlotId(entry.label) === slotId,
    );
    const rawLabel = slotEntry?.label ?? slotId;
    const label = sanitizeEvidenceHintAtom(rawLabel);
    if (!label || isLowSignalHeadingHintLabel(label)) continue;
    const conceptCard =
      resolveConceptCardForSlot(slotId) ??
      (slotEntry?.label ? resolveConceptCardForSlot(slotEntry.label) : null);
    if (conceptCard?.sourcePath) {
      pushHint(`Check ${conceptCard.sourcePath} for "${label}".`);
    } else if (conceptCard?.mustIncludeFiles?.length) {
      conceptCard.mustIncludeFiles.forEach((filePath) =>
        pushHint(`Check ${filePath} for "${label}".`),
      );
    } else {
      const surfaceHints = buildSlotSurfaceHints(slotEntry?.surfaces);
      if (surfaceHints.length > 0) {
        pushHint(`Search ${surfaceHints.join(" or ")} for "${label}".`);
      } else {
        pushHint(`Search docs headings for "${label}".`);
      }
    }
    if (hints.length >= limit) break;
  }
  if (hints.length < limit) {
    const headingSeeds =
      args.headingSeedSlots && args.headingSeedSlots.length > 0
        ? args.headingSeedSlots
        : buildDocHeadingSeedSlots(args.question);
    for (const seed of headingSeeds) {
      if (!seed.label) continue;
      const label = sanitizeEvidenceHintAtom(seed.label);
      if (!label || isLowSignalHeadingHintLabel(label)) continue;
      pushHint(`Search docs headings for "${label}".`);
      if (hints.length >= limit) break;
    }
  }
  return hints.slice(0, limit);
};

const buildScientificMicroReport = (args: {
  question: string;
  claimLedger?: HelixAskClaimLedgerEntry[];
  uncertaintyRegister?: HelixAskUncertaintyEntry[];
  missingSlots?: string[];
  slotPlan?: HelixAskSlotPlan | null;
  anchorFiles?: string[];
  searchedTerms?: string[];
  searchedFiles?: string[];
  includeSearchSummary?: boolean;
  planClarify?: string;
  headingSeedSlots?: HelixAskSlotPlanEntry[];
  hypothesisEnabled?: boolean;
  hypothesisStyle?: "conservative" | "exploratory";
  requiresRepoEvidence?: boolean;
  forceUnverified?: boolean;
}): {
  text: string;
  nextEvidence: string[];
  confirmedCount: number;
  hypothesisCount: number;
} => {
  const sanitizeMicroReportHint = (value: string): string =>
    value
      .normalize("NFKD")
      .replace(/[^\x09\x0A\x0D\x20-\x7E]/g, "")
      .replace(/\s+/g, " ")
      .trim();
  const supportedClaims =
    args.claimLedger?.filter((entry) => entry.supported && entry.type !== "question") ?? [];
  const confirmedItems = supportedClaims.map((entry) => ensureSentence(entry.text)).slice(0, 3);
  const anchorEvidenceHints = normalizeCitations(args.anchorFiles ?? []).slice(0, 4);
  const fallbackAnchorHints =
    anchorEvidenceHints.length > 0
      ? anchorEvidenceHints
      : normalizeCitations(args.searchedFiles ?? []).slice(0, 4);
  if (confirmedItems.length === 0 && fallbackAnchorHints.length > 0) {
    confirmedItems.push(`Retrieved grounded repository anchors: ${fallbackAnchorHints.join(", ")}.`);
  }
  const lines: string[] = [];
  lines.push(args.forceUnverified || confirmedItems.length === 0 ? "Unverified:" : "Confirmed:");
  if (confirmedItems.length > 0) {
    confirmedItems.forEach((item) => lines.push(`- ${item}`));
  } else {
    lines.push(
      `- ${
        args.requiresRepoEvidence
          ? "No repo-evidenced claims were confirmed yet."
          : "No confirmed evidence was found yet."
      }`,
    );
  }
  lines.push("");
  lines.push("Reasoned connections (bounded):");
  if (supportedClaims.length >= 2) {
    const first = supportedClaims[0];
    const second = supportedClaims[1];
    const firstRefPath = sanitizeClaimEvidenceRef(first.evidenceRefs[0]);
    const secondRefPath = sanitizeClaimEvidenceRef(second.evidenceRefs[0]);
    const firstRef = firstRefPath ? `see ${firstRefPath}` : "see cited evidence";
    const secondRef = secondRefPath ? `see ${secondRefPath}` : "see cited evidence";
    const firstText = clipAskText(first.text, 160);
    const secondText = clipAskText(second.text, 160);
    lines.push(
      `- ${firstText} (${firstRef}). ${secondText} (${secondRef}). Bounded linkage supported by cited evidence.`,
    );
  } else if (fallbackAnchorHints.length >= 2) {
    lines.push(
      `- Bounded linkage supported by cited repo evidence (${fallbackAnchorHints[0]} and ${fallbackAnchorHints[1]}).`,
    );
  } else {
    lines.push("- Need at least two grounded points before drawing a connection.");
  }
  const hypothesisEnabled = args.hypothesisEnabled ?? false;
  let hypothesisItems: string[] = [];
  if (hypothesisEnabled && HELIX_ASK_SCIENTIFIC_MAX_HYPOTHESES > 0) {
    const rawCandidates =
      args.claimLedger?.filter((entry) => !entry.supported && entry.type !== "question") ?? [];
    const filtered =
      (args.hypothesisStyle ?? "conservative") === "exploratory"
        ? rawCandidates
        : rawCandidates.filter(
            (entry) => entry.type === "hypothesis" || entry.type === "assumption",
          );
    hypothesisItems = filtered
      .map((entry) => ensureSentence(entry.text))
      .filter(Boolean)
      .slice(0, HELIX_ASK_SCIENTIFIC_MAX_HYPOTHESES);
  }
  if (hypothesisEnabled) {
    lines.push("");
    lines.push("Hypotheses (optional):");
    if (hypothesisItems.length > 0) {
      hypothesisItems.forEach((item) => lines.push(`- ${item}`));
    } else {
      lines.push("- None without additional evidence.");
    }
  }
  const nextEvidence = buildNextEvidenceHints({
    question: args.question,
    missingSlots: args.missingSlots,
    slotPlan: args.slotPlan,
    anchorFiles: args.anchorFiles,
    searchedTerms: args.searchedTerms,
    searchedFiles: args.searchedFiles,
    includeSearchSummary: args.includeSearchSummary,
    planClarify: args.planClarify,
    headingSeedSlots: args.headingSeedSlots,
    limit: 4,
  });
  lines.push("");
  lines.push("Next evidence:");
  if (nextEvidence.length > 0) {
    nextEvidence
      .map((item) => sanitizeMicroReportHint(item))
      .filter(Boolean)
      .forEach((item) => lines.push(`- ${item}`));
  } else {
    lines.push("- Provide the file path or doc section that defines the missing terms.");
  }
  return {
    text: lines.join("\n").trim(),
    nextEvidence,
    confirmedCount: confirmedItems.length,
    hypothesisCount: hypothesisItems.length,
  };
};

type HelixAskFrontierSlotSummary = {
  required: HelixAskFrontierRequiredSlot[];
  present: HelixAskFrontierRequiredSlot[];
  missing: HelixAskFrontierRequiredSlot[];
  ratio: number;
};

type HelixAskFrontierVerification = {
  claims: string[];
  questions: string[];
  supportedClaims: string[];
  unsupportedClaims: string[];
  supportRatio: number;
};

const evaluateFrontierScientificSlots = (
  text: string,
  required: readonly HelixAskFrontierRequiredSlot[] = HELIX_ASK_FRONTIER_REQUIRED_SLOTS,
): HelixAskFrontierSlotSummary => {
  const present: HelixAskFrontierRequiredSlot[] = [];
  for (const slot of required) {
    const patterns = HELIX_ASK_FRONTIER_SLOT_PATTERNS[slot] ?? [];
    if (patterns.some((pattern) => pattern.test(text))) {
      present.push(slot);
    }
  }
  const missing = required.filter((slot) => !present.includes(slot));
  return {
    required: Array.from(required),
    present,
    missing,
    ratio: required.length > 0 ? present.length / required.length : 1,
  };
};

const buildFrontierVerificationQuestions = (claims: string[]): string[] =>
  claims.slice(0, 6).map((claim) => `What evidence supports: ${ensureSentence(claim)}`);

const runFrontierVerificationPass = (
  draft: string,
  evidenceContext: string,
): HelixAskFrontierVerification => {
  const claims = extractClaimCandidates(draft, 6);
  const questions = buildFrontierVerificationQuestions(claims);
  if (claims.length === 0) {
    return {
      claims,
      questions,
      supportedClaims: [],
      unsupportedClaims: [],
      supportRatio: 0,
    };
  }
  const coverage = evaluateClaimCoverage(claims, evidenceContext, {
    minTokens: Math.max(1, HELIX_ASK_EVIDENCE_CLAIM_MIN_TOKENS),
    minRatio: Math.max(0.15, HELIX_ASK_EVIDENCE_CLAIM_MIN_RATIO),
    minSupportRatio: Math.max(0.35, HELIX_ASK_EVIDENCE_CLAIM_SUPPORT_RATIO),
  });
  const unsupported = new Set(coverage.unsupported ?? []);
  return {
    claims,
    questions,
    supportedClaims: claims.filter((claim) => !unsupported.has(claim)),
    unsupportedClaims: claims.filter((claim) => unsupported.has(claim)),
    supportRatio: coverage.supportRatio,
  };
};

const stripTelemetryLeakArtifacts = (
  text: string,
): { text: string; detected: boolean; reasons: string[] } => {
  let next = text;
  const reasons: string[] = [];
  if (/(?:^|\n)\s*(Execution log|Ask debug)\b/i.test(next)) {
    next = next.replace(/(?:^|\n)\s*(Execution log|Ask debug)\b[\s\S]*$/i, "").trim();
    reasons.push("debug_section");
  }
  const linePatterns: RegExp[] = [
    /^Helix Ask:.*$/gim,
    /^Duration:\s*\d+ms.*$/gim,
    /^Two-pass:.*$/gim,
    /^Micro-pass:.*$/gim,
    /^Prompt ingest:.*$/gim,
    /^Graph congruence:.*$/gim,
    /^\[\d{2}:\d{2}:\d{2}(?:\.\d{3})?\]\s+tool=(?:progress|event|error|debug)\s*\|.*$/gim,
    /^tool=(?:progress|event|error|debug)\s*\|.*$/gim,
  ];
  for (const pattern of linePatterns) {
    if (pattern.test(next)) {
      next = next.replace(pattern, "").trim();
      reasons.push(`line:${pattern.source}`);
    }
  }
  const inlinePatterns: Array<{ pattern: RegExp; reason: string }> = [
    {
      pattern:
        /([^\n]*?)\s*\[\d{2}:\d{2}:\d{2}(?:\.\d{3})?\]\s+tool=(?:progress|event|error|debug)\s*\|[^\n]*/gim,
      reason: "inline:timestamp_tool_trace",
    },
    {
      pattern: /([^\n]*?)\s*tool=(?:progress|event|error|debug)\s*\|\s*seq=\d+[^\n]*/gim,
      reason: "inline:tool_seq_trace",
    },
  ];
  for (const { pattern, reason } of inlinePatterns) {
    if (pattern.test(next)) {
      next = next.replace(pattern, "$1").trim();
      reasons.push(reason);
    }
  }
  next = next.replace(/\n{3,}/g, "\n\n").trim();
  return { text: next, detected: reasons.length > 0, reasons };
};

const hasExplicitFrontierLensCandidate = (value: string): boolean =>
  HELIX_ASK_FRONTIER_EXPLICIT_LENS_RE.test(value);

const clipFrontierComparisonField = (value: string, fallback: string): string =>
  ensureSentence(
    clipAskText(
      (value || "").trim() || fallback,
      HELIX_ASK_FRONTIER_COMPARISON_FIELD_MAX_CHARS,
    ) || fallback,
  );

const resolveFrontierLensSeed = (question: string): string => {
  if (!hasExplicitFrontierLensCandidate(question)) {
    return "Lens candidate: Orch-OR-style objective reduction as a speculative consciousness mechanism.";
  }
  if (/\borch(?:estrated)?\s*objective\s*reduction\b|\borch[-\s]?or\b/i.test(question)) {
    return "Lens candidate: Orch-OR-style objective reduction in organized quantum states.";
  }
  if (/\bpenrose\b/i.test(question)) {
    return "Lens candidate: Penrose objective-reduction interpretation.";
  }
  if (/\bhameroff\b|\bmicrotubule\b/i.test(question)) {
    return "Lens candidate: Hameroff/Penrose microtubule-centered consciousness hypothesis.";
  }
  if (/\bops\b/i.test(question)) {
    return "Lens candidate: OPS-style objective-reduction framing with explicit falsifiers.";
  }
  return "Lens candidate: explicit objective-reduction consciousness lens.";
};

const buildFrontierHardGuardClarifyLine = (args: {
  supportRatio: number;
  missingSlots: string[];
  lensRequired: boolean;
  lensCandidateCount: number;
  planClarify?: string;
}): string => {
  const details: string[] = [];
  details.push(`support_ratio=${args.supportRatio.toFixed(2)}`);
  if (args.missingSlots.length > 0) {
    details.push(`missing_slots=${args.missingSlots.join(", ")}`);
  }
  if (args.lensRequired) {
    details.push(
      args.lensCandidateCount > 0
        ? "lens_candidate=present"
        : "lens_candidate=missing",
    );
  }
  const base =
    "I cannot finalize a frontier verdict yet because the evidence contract is incomplete.";
  const action =
    args.planClarify?.trim().length
      ? ensureSentence(args.planClarify)
      : "Please clarify the lens and provide evidence paths so I can run a falsifiable comparison.";
  return `${base} (${details.join("; ")}). ${action}`.trim();
};

const renderFrontierScientificContract = (args: {
  question: string;
  verification: HelixAskFrontierVerification;
  slotSummary: HelixAskFrontierSlotSummary;
  planClarify?: string;
  nextEvidence?: string[];
  requireLensCandidate?: boolean;
}): string => {
  const baselineLine =
    args.verification.supportedClaims[0] ??
    "Mainstream baseline: no certified evidence currently establishes solar subjective awareness.";
  const lensSeed = resolveFrontierLensSeed(args.question);
  const hypothesisAssumptionSeed =
    args.verification.supportRatio > 0
      ? (args.verification.unsupportedClaims[0] ?? "")
      : "";
  const hypothesisAssumption = clipFrontierComparisonField(
    hypothesisAssumptionSeed,
    `${lensSeed} Consciousness-like behavior would require measurable collapse signatures not explained by standard plasma dynamics.`,
  );
  const hypothesisAssumptionWithLens =
    args.requireLensCandidate && !hasExplicitFrontierLensCandidate(hypothesisAssumption)
      ? clipFrontierComparisonField(`${lensSeed} ${hypothesisAssumption}`, lensSeed)
      : hypothesisAssumption;
  const antiHypothesisAssumption = clipFrontierComparisonField(
    "Observed stellar coherence/collapse dynamics are non-conscious physical processes.",
    "Observed stellar dynamics are non-conscious physical processes.",
  );
  const evidenceHints = (args.nextEvidence ?? []).slice(0, 3);
  if (!evidenceHints.length && args.planClarify) {
    evidenceHints.push(args.planClarify);
  }
  if (!evidenceHints.length) {
    evidenceHints.push("Add explicit prediction vs observation checks tied to repo evidence paths.");
  }
  const hypothesisPrediction = clipFrontierComparisonField(
    evidenceHints[0] ?? "",
    "Predict an observable signature unique to the lens that differs from baseline plasma-only dynamics.",
  );
  const antiHypothesisPrediction = clipFrontierComparisonField(
    "Predict known solar behavior remains explainable with standard stellar physics alone.",
    "Predict known solar behavior remains explainable with standard stellar physics.",
  );
  const hypothesisFalsifier = clipFrontierComparisonField(
    evidenceHints[1] ?? evidenceHints[0] ?? "",
    "Falsify if no lens-specific signature appears when tested against baseline predictions.",
  );
  const antiHypothesisFalsifier = clipFrontierComparisonField(
    "Falsify if robust, repeatable signatures appear that standard stellar models cannot explain.",
    "Falsify if repeatable signatures appear that standard stellar models cannot explain.",
  );
  const sharedUncertainty = `support_ratio=${args.verification.supportRatio.toFixed(2)}; missing_slots=${
    args.slotSummary.missing.join(", ") || "none"
  }`;
  const hypothesisUncertainty = clipFrontierComparisonField(
    sharedUncertainty,
    "Diagnostic uncertainty remains high pending direct falsifier tests.",
  );
  const antiHypothesisUncertainty = clipFrontierComparisonField(
    sharedUncertainty,
    "Diagnostic uncertainty remains high pending direct falsifier tests.",
  );
  const uncertaintyLine = `Support ratio=${args.verification.supportRatio.toFixed(
    2,
  )}; missing slots=${args.slotSummary.missing.join(", ") || "none"}.`;
  const lines = [
    "Definitions:",
    "- Consciousness: subjective first-person awareness with reportable internal states.",
    "",
    "Baseline:",
    `- ${ensureSentence(baselineLine)}`,
    "",
    "Hypothesis:",
    `- Assumptions: ${hypothesisAssumptionWithLens}`,
    `- Predictions: ${hypothesisPrediction}`,
    `- Falsifiers: ${hypothesisFalsifier}`,
    `- Uncertainty: ${hypothesisUncertainty}`,
    "",
    "Anti-hypothesis:",
    `- Assumptions: ${antiHypothesisAssumption}`,
    `- Predictions: ${antiHypothesisPrediction}`,
    `- Falsifiers: ${antiHypothesisFalsifier}`,
    `- Uncertainty: ${antiHypothesisUncertainty}`,
    "",
    "Falsifiers:",
    ...evidenceHints.map((hint) => `- ${ensureSentence(hint)}`),
    "",
    "Uncertainty band:",
    `- ${ensureSentence(uncertaintyLine)}`,
    "",
    "Claim tier:",
    "- diagnostic (frontier hypothesis mode; not certified)",
  ];
  return lines.join("\n").trim();
};

const resolveClusterKey = (filePath: string): string => {
  const normalized = normalizeEvidencePath(filePath) ?? filePath;
  const parts = normalized.split("/").filter(Boolean);
  if (parts.length === 0) return "unknown";
  const root = parts[0];
  if (root === "docs" && parts[1]) return `docs/${parts[1]}`;
  if (root === "modules" && parts[1]) return `modules/${parts[1]}`;
  if (root === "client" && parts[1]) return `client/${parts[1]}`;
  if (root === "server" && parts[1]) return `server/${parts[1]}`;
  if (root === "shared" && parts[1]) return `shared/${parts[1]}`;
  if (root === "tests") return "tests";
  if (root === "scripts") return "scripts";
  return parts.slice(0, Math.min(2, parts.length)).join("/");
};

const formatClusterLabel = (key: string): string => key.replace(/_/g, " ");

const computeClusterEntropy = (clusters: AmbiguityCluster[], totalScore: number): number => {
  if (clusters.length <= 1 || totalScore <= 0) return 0;
  const base = Math.log(clusters.length);
  if (!Number.isFinite(base) || base <= 0) return 0;
  let sum = 0;
  for (const cluster of clusters) {
    const p = cluster.score / totalScore;
    if (p <= 0) continue;
    sum += -p * Math.log(p);
  }
  return Math.min(1, Math.max(0, sum / base));
};

const buildAmbiguityClusterSummary = (
  candidates: AskCandidate[],
  targetSpan?: string,
): AmbiguityClusterSummary | null => {
  if (candidates.length === 0) {
    return {
      targetSpan,
      totalScore: 0,
      topScore: 0,
      margin: 0,
      entropy: 0,
      clusters: [],
    };
  }
  const map = new Map<string, AmbiguityCluster>();
  for (const candidate of candidates) {
    const key = resolveClusterKey(candidate.filePath);
    const entry = map.get(key);
    if (entry) {
      entry.score += candidate.rrfScore;
      entry.count += 1;
      if (entry.paths.length < 3) {
        entry.paths.push(candidate.filePath);
      }
    } else {
      map.set(key, {
        key,
        label: formatClusterLabel(key),
        score: candidate.rrfScore,
        mass: 0,
        count: 1,
        paths: [candidate.filePath],
      });
    }
  }
  const clusters = Array.from(map.values()).sort((a, b) => b.score - a.score);
  const totalScore = clusters.reduce((sum, cluster) => sum + cluster.score, 0);
  for (const cluster of clusters) {
    cluster.mass = totalScore > 0 ? cluster.score / totalScore : 0;
  }
  const topScore = clusters[0]?.score ?? 0;
  const secondScore = clusters[1]?.score ?? 0;
  const margin = topScore > 0 ? Math.max(0, (topScore - secondScore) / topScore) : 0;
  const entropy = computeClusterEntropy(clusters, totalScore);
  return {
    targetSpan,
    totalScore,
    topScore,
    margin,
    entropy,
    clusters,
  };
};

const parseLabelList = (raw: string): string[] | null => {
  if (!raw.trim()) return null;
  const match = raw.match(/\[[\s\S]*\]/);
  if (!match) return null;
  try {
    const parsed = JSON.parse(match[0]);
    if (!Array.isArray(parsed)) return null;
    return parsed.map((entry) => String(entry).trim()).filter(Boolean);
  } catch {
    return null;
  }
};

const applyAmbiguityClusterLabels = (
  clusters: AmbiguityCluster[],
  labels: string[] | null,
): AmbiguityCluster[] => {
  if (!labels || labels.length === 0) return clusters;
  return clusters.map((cluster, index) => ({
    ...cluster,
    label: labels[index] ?? cluster.label,
  }));
};

const buildAmbiguityLabelPrompt = (args: {
  question: string;
  targetSpan?: string;
  clusters: AmbiguityCluster[];
}): string => {
  const lines = args.clusters.map((cluster, index) => {
    const samples = cluster.paths.slice(0, 2).join(", ");
    return `- ${index + 1}. key: ${cluster.key}; samples: ${samples || "n/a"}`;
  });
  return [
    "You label ambiguity clusters for a clarification question.",
    "Return a JSON array of short labels (2-6 words) in the same order as the list.",
    `Question: "${args.question}"`,
    args.targetSpan ? `Target: "${args.targetSpan}"` : "",
    "Clusters:",
    ...lines,
    "Return JSON only.",
  ]
    .filter(Boolean)
    .join("\n");
};

const labelAmbiguityClustersWithLlm = async (args: {
  question: string;
  targetSpan?: string;
  clusters: AmbiguityCluster[];
  personaId: string;
  sessionId?: string;
  traceId?: string;
}): Promise<{
  clusters: AmbiguityCluster[];
  applied: boolean;
  overflow?: HelixAskOverflowMeta;
  llm?: HelixAskLlmCallMeta;
}> => {
  if (!HELIX_ASK_AMBIGUITY_LABEL_LLM || args.clusters.length === 0) {
    return { clusters: args.clusters, applied: false };
  }
  const prompt = buildAmbiguityLabelPrompt(args);
  const { result, overflow, llm } = await runHelixAskLocalWithOverflowRetry(
    {
      prompt,
      max_tokens: 96,
      temperature: 0.1,
    },
    {
      personaId: args.personaId,
      sessionId: args.sessionId,
      traceId: args.traceId,
    },
    {
      fallbackMaxTokens: 96,
      allowContextDrop: true,
      label: "ambiguity_labels",
    },
  );
  const labels = parseLabelList(result.text ?? "");
  const labeled = applyAmbiguityClusterLabels(args.clusters, labels);
  return { clusters: labeled, applied: Boolean(labels && labels.length), overflow, llm };
};

const selectClarifyToken = (question: string): string | undefined => {
  const span = extractClarifySpan(question);
  if (span) {
    const spanTokens = filterCriticTokens(tokenizeAskQuery(span));
    for (let i = spanTokens.length - 1; i >= 0; i -= 1) {
      const normalized = normalizeClarifyToken(spanTokens[i]);
      if (normalized) return normalized;
    }
    const normalizedSpan = normalizeClarifyToken(span);
    if (normalizedSpan) return normalizedSpan;
  }
  const tokens = filterCriticTokens(tokenizeAskQuery(question));
  for (let i = tokens.length - 1; i >= 0; i -= 1) {
    const normalized = normalizeClarifyToken(tokens[i]);
    if (normalized) return normalized;
  }
  return undefined;
};

const formatAmbiguityCandidateLabel = (candidate: HelixAskConceptCandidate): string =>
  candidate.card.label ?? candidate.card.id;

const collectAmbiguitySeedLabels = (
  slots: Array<{ label?: string; aliases?: string[] }>,
  limit = 3,
): string[] => {
  const labels: string[] = [];
  const seen = new Set<string>();
  const pushLabel = (value?: string) => {
    if (!value) return;
    const trimmed = value.trim();
    if (!trimmed) return;
    if (trimmed.length < HELIX_ASK_AMBIGUOUS_TERM_MIN_LEN) return;
    const normalized = normalizeSlotName(trimmed);
    if (STRUCTURAL_SLOTS.has(normalized)) return;
    const key = trimmed.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    labels.push(trimmed);
  };
  for (const slot of slots) {
    pushLabel(slot.label);
    if (labels.length >= limit) break;
    for (const alias of slot.aliases ?? []) {
      pushLabel(alias);
      if (labels.length >= limit) break;
    }
    if (labels.length >= limit) break;
  }
  return labels.slice(0, limit);
};

const buildPreIntentClarifyLine = (
  question: string,
  candidates: HelixAskConceptCandidate[],
  clusterSummary?: AmbiguityClusterSummary | null,
  seedLabels: string[] = [],
): string => {
  const clusterLabels = (clusterSummary?.clusters ?? [])
    .map((cluster) => cluster.label)
    .map((value) => String(value ?? "").trim())
    .filter(Boolean);
  const cleanSeedLabels = seedLabels.map((value) => value.trim()).filter(Boolean);
  const candidateLabels = candidates
    .map((candidate) => formatAmbiguityCandidateLabel(candidate).trim())
    .filter(Boolean);
  if (clusterLabels.length >= 2) {
    return `Do you mean "${clusterLabels[0]}" or "${clusterLabels[1]}"? If you mean a repo concept, point me to the file or module.`;
  }
  if (clusterLabels.length === 1) {
    const token =
      selectClarifyToken(question) ??
      clusterSummary?.targetSpan ??
      candidates[0]?.matchedTerm;
    return `Do you mean "${clusterLabels[0]}" in this repo, or the general meaning of "${token ?? "that term"}"? If it's repo-specific, point me to the file or module.`;
  }
  if (cleanSeedLabels.length >= 2) {
    return `Do you mean "${cleanSeedLabels[0]}" or "${cleanSeedLabels[1]}"? If you mean a repo concept, point me to the file or module.`;
  }
  if (cleanSeedLabels.length === 1) {
    const token = selectClarifyToken(question) ?? cleanSeedLabels[0];
    return `Do you mean "${cleanSeedLabels[0]}" in this repo, or the general meaning of "${token}"? If it's repo-specific, point me to the file or module.`;
  }
  if (candidateLabels.length >= 2) {
    return `Do you mean "${candidateLabels[0]}" or "${candidateLabels[1]}"? If you mean a repo concept, point me to the file or module.`;
  }
  if (candidateLabels.length === 1) {
    const label = candidateLabels[0];
    const token = selectClarifyToken(question) ?? candidates[0]?.matchedTerm;
    return `Do you mean "${label}" in this repo, or the general meaning of "${token}"? If it's repo-specific, point me to the file or module.`;
  }
  const token = selectClarifyToken(question);
  if (token) {
    return `What do you mean by "${token}"? If you mean a repo/physics concept, point me to the file or module.`;
  }
  return "Could you clarify the term or point me to the relevant files?";
};

type HelixAskReportBlock = {
  id: string;
  text: string;
  label?: string;
  typeHint?: string;
  slotId?: string;
  slotSurfaces?: string[];
  slotAliases?: string[];
  slotEvidenceCriteria?: string[];
};

type HelixAskReportBlockResult = {
  id: string;
  index: number;
  label?: string;
  text: string;
  answer: string;
  mode: "repo_grounded" | "hybrid" | "general" | "clarify";
  clarify: boolean;
  citations: string[];
  traceId?: string;
  nextEvidence?: string[];
};

type HelixAskReportModeDecision = {
  enabled: boolean;
  reason?: string;
  tokenCount: number;
  charCount: number;
  blockCount: number;
};

const REPORT_MODE_INTENT_RE =
  /\b(?:as\s+a\s+report|report\s+format|generate\s+(?:a\s+)?report|produce\s+(?:a\s+)?report|write\s+(?:a\s+)?report|point[- ]by[- ]point|line by line|go through (each|every)|analyze each)\b/i;
const REPORT_MODE_HEADING_RE = /^#{1,6}\s+(.+)$/;
const REPORT_MODE_BULLET_RE = /^\s*(?:[-*+]|[0-9]+[.)]|[a-zA-Z][.)])\s+(.+)$/;
const REPORT_MODE_SECTION_RE = /^(?:Q:|Question:|Requirement:|Issue:|Task:)\s*(.+)$/i;

const REPORT_MODE_NEGATION_RE = /\b(do not|don't|avoid|without|instead of|switch to plain-language)\b/i;
const REPORT_MODE_REFERENCE_RE = /\b(report|technical notes?|compare\/report|report mode)\b/i;
const REPORT_MODE_CONDITIONAL_GUARD_RE = /\bif you are about to output\b/i;

const IDEOLOGY_TECHNICAL_NOTES_RE = /\n{2,}Technical notes:\s*[\s\S]*$/i;
const IDEOLOGY_COMPARE_REPORT_LITERAL_RE = /\bcompare\/report\b/gi;
const IDEOLOGY_NARRATIVE_SCAFFOLD_LINE_RE =
  /(?:^|\n)\s*(?:Direct Answer|Mechanism Explanation|Inputs\/Outputs|Constraints|Common failure modes|How It Works|Implementation In Repo|Where in repo|Call chain|Definition|Repo anchors|Option A\/B|Key differences|When to choose|Risks|Short answer|Conceptual baseline|How repo solves it|Evidence \+ proof anchors|Uncertainty \/ open gaps)\s*:[^\n]*(?=\n|$)/gi;
const IDEOLOGY_OBJECTIVE_LEAK_LINE_RE =
  /(?:^|\n)\s*(?:Assembly blocked:[^\n]*|Open gaps\s*\/\s*UNKNOWNs?\s*:[^\n]*|UNKNOWN\s*-[^\n]*|Why:[^\n]*|What I checked:[^\n]*|Next retrieval:[^\n]*)(?=\n|$)/gi;
const IDEOLOGY_TECHNICAL_ALLOW_RE =
  /\b(include|add|with|show|provide|give|append)\b(?:\s+[^\s]+){0,2}\s+(technical\s+notes?|technical\s+breakdown|report\s+mode|diagnostic\s+report|debug\s+trace)\b/i;
const IDEOLOGY_TECHNICAL_BLOCK_RE =
  /\b(do not|don't|avoid|without|instead of|switch to plain-language)\b[\s\S]{0,120}\b(technical\s+notes?|compare\/report|report\s+format|report\s+mode)\b/i;
const IDEOLOGY_DOC_ONLY_RE =
  /\b(?:without\s+code(?:-level)?(?:\s+repo\s+details?)?|without\s+implementation(?:\s+details?)?|non-technical|plain-language|someone\s+new\s+to\s+the\s+project|new\s+to\s+the\s+project)\b/i;
const IDEOLOGY_DEFAULT_DOC_SOURCES = [
  "docs/knowledge/ethos/feedback-loop-hygiene.md",
  "docs/ethos/ideology.json",
];

const shouldAllowIdeologyTechnicalNotes = (question: string): boolean => {
  const normalized = question.toLowerCase();
  const explicitAllow = IDEOLOGY_TECHNICAL_ALLOW_RE.test(normalized);
  if (IDEOLOGY_TECHNICAL_BLOCK_RE.test(normalized)) {
    return false;
  }
  return explicitAllow;
};

const shouldPreferIdeologyDocOnlySources = (question: string): boolean =>
  IDEOLOGY_DOC_ONLY_RE.test(question.toLowerCase());

const collectIdeologyDocOnlySources = (paths: string[]): string[] =>
  normalizeCitations(paths)
    .map((entry) => String(normalizeEvidenceRef(entry) ?? entry).replace(/\\/g, "/"))
    .filter((entry) => /^docs\//i.test(entry));

const enforceIdeologyDocOnlySourcesLine = (text: string, sourceCandidates: string[]): string => {
  let cleaned = text
    .replace(/^Sources?:[^\n]*(?:\n|$)/gim, "")
    .replace(/\b(?:server|client|modules|shared|scripts|tests|tools)\/[^\s,;]+/gi, "")
    .replace(/\s{2,}/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  const docSources = collectIdeologyDocOnlySources(sourceCandidates).slice(0, 8);
  const sources =
    docSources.length > 0 ? docSources : IDEOLOGY_DEFAULT_DOC_SOURCES.slice(0, 8);
  if (sources.length > 0) {
    cleaned = `${cleaned}\n\nSources: ${sources.join(", ")}`.trim();
  }
  return cleaned;
};

const stripIdeologyNarrativeLeakage = (value: string): string =>
  value
    .replace(IDEOLOGY_TECHNICAL_NOTES_RE, "")
    .replace(IDEOLOGY_NARRATIVE_SCAFFOLD_LINE_RE, "\n")
    .replace(IDEOLOGY_OBJECTIVE_LEAK_LINE_RE, "\n")
    .replace(IDEOLOGY_COMPARE_REPORT_LITERAL_RE, "comparison report")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

const hasWarpEthosDomainPair = (question: string): boolean => {
  const normalized = question.replace(/\s+/g, " ").trim();
  if (!normalized) return false;
  const hasWarp = HELIX_ASK_RELATION_WARP_QUERY_RE.test(normalized);
  const hasEthos = HELIX_ASK_RELATION_ETHOS_QUERY_RE.test(normalized);
  return hasWarp && hasEthos;
};

const hasWarpEthosRelationConnectorCue = (question: string): boolean => {
  const normalized = question.replace(/\s+/g, " ").trim();
  if (!normalized) return false;
  return (
    HELIX_ASK_RELATION_QUERY_RE.test(normalized) ||
    HELIX_ASK_RELATION_CONNECTOR_RE.test(normalized)
  );
};

const isWarpEthosRelationHeuristicQuestion = (question: string): boolean => {
  if (!question?.trim()) return false;
  return (
    hasWarpEthosDomainPair(question) &&
    hasWarpEthosRelationConnectorCue(question)
  );
};

const isWarpEthosRelationQuestion = (question: string): boolean => {
  if (!question?.trim()) return false;
  const normalized = question.replace(/\s+/g, " ").trim();
  if (!hasWarpEthosDomainPair(normalized)) return false;
  const hasConnector =
    hasWarpEthosRelationConnectorCue(normalized) ||
    /\bdefine\b[\s\S]{0,120}\b(?:then|and)\b[\s\S]{0,80}\bconnect\b/i.test(normalized) ||
    /\bwhat(?:'s| is)\b[\s\S]{0,80}\bbridge\b/i.test(normalized);
  const compactConnector = /\b(?:relation|relationship|connect(?:ion)?|link|bridge|interplay|fit)\b/i.test(
    normalized,
  );
  const policyConnector = /\b(?:constrain(?:ed|s|t)?|govern(?:ed|ance|s)?|bind(?:ing|s)?|cohere(?:nce)?|alignment|policy\s+layer|technical\s+layer|dependency)\b/i.test(
    normalized,
  );
  const hasImplicitIdeologyBridge =
    /\bwhat(?:'s| is)\b[\s\S]{0,120}\b(?:in|within|under)\b[\s\S]{0,40}\b(?:mission\s+ethos|ethos|ideology)\b/i.test(
      normalized,
    ) ||
    /\b(?:warp|warp\s+bubble|warp\s+drive)\b[\s\S]{0,80}\b(?:in|within|under)\b[\s\S]{0,40}\b(?:mission\s+ethos|ethos|ideology)\b/i.test(
      normalized,
    );
  return (
    hasConnector ||
    compactConnector ||
    policyConnector ||
    hasImplicitIdeologyBridge
  );
};

const isExplicitReportRequest = (question: string): boolean => {
  if (!REPORT_MODE_INTENT_RE.test(question)) return false;
  const normalized = question.toLowerCase();
  const hasNegation = REPORT_MODE_NEGATION_RE.test(normalized);
  const hasReportReference = REPORT_MODE_REFERENCE_RE.test(normalized);
  const conditionalGuard = REPORT_MODE_CONDITIONAL_GUARD_RE.test(normalized);
  if (hasReportReference && (hasNegation || conditionalGuard)) {
    return false;
  }
  return true;
};
