const buildMailboxWakeResultProjectionForTurn = (activeTurnId: string) => {
  const mailboxWakeResultForTurn =
    listStagePlayLiveSourceMailWakeResults({ limit: 250 })
      .filter((result) => result.askTurnId === activeTurnId)
      .at(-1) ?? null;
  if (!mailboxWakeResultForTurn) return null;
  const explicitVoiceRefs = readAskTurnStringList((mailboxWakeResultForTurn as Record<string, unknown>).voiceCheckpointRefs);
  const voiceCheckpointRefs = explicitVoiceRefs.length > 0
    ? explicitVoiceRefs
    : mailboxWakeResultForTurn.evidenceRefs.filter((ref) =>
        /^(?:live_source_interim_voice_callout_receipt|helix_interim_voice_callout_receipt|voice_hold_receipt|voice_block_receipt|voice_receipt|stage_play_live_source_voice_delivery_receipt):/i.test(ref)
      );
  const deckVerdict = asDebugExportRecord(mailboxWakeResultForTurn.deckVerdict);
  const transaction = asDebugExportRecord(mailboxWakeResultForTurn.stagePlayWakeTransaction);
  const transactionDeckVerdict = asDebugExportRecord(transaction?.deckVerdict);
  const recommendedNext =
    readDebugExportString(deckVerdict?.recommendedNext) ??
    readDebugExportString(transactionDeckVerdict?.recommendedNext);
  const requiresVoiceCheckpoint =
    voiceCheckpointRefs.length > 0 ||
    mailboxWakeResultForTurn.lifecycleStage === "voice_pending" ||
    recommendedNext === "request_voice_callout" ||
    readDebugExportBoolean(deckVerdict?.voiceCandidate) === true ||
    readDebugExportBoolean(transactionDeckVerdict?.voiceCandidate) === true;
  const requiresVoiceCheckpointSource =
    readDebugExportString(mailboxWakeResultForTurn.requiresVoiceCheckpointSource) ??
    readDebugExportString(transaction?.requiresVoiceCheckpointSource) ??
    readDebugExportString(transaction?.requires_voice_checkpoint_source) ??
    (voiceCheckpointRefs.length > 0
      ? "voice_checkpoint_receipt"
      : mailboxWakeResultForTurn.lifecycleStage === "voice_pending"
        ? "recorded_decision"
        : recommendedNext === "request_voice_callout"
          ? "packet_recommendation"
          : readDebugExportBoolean(deckVerdict?.voiceCandidate) === true ||
              readDebugExportBoolean(transactionDeckVerdict?.voiceCandidate) === true
            ? "deck_voice_candidate"
            : "not_required");
  return {
    schema: "stage_play_live_source_mail_wake_result_projection/v1",
    source: "stage_play_live_source_mail_wake_result",
    ask_turn_id: activeTurnId,
    wake_result_id: mailboxWakeResultForTurn.wakeResultId,
    wake_request_id: mailboxWakeResultForTurn.wakeRequestId,
    status: mailboxWakeResultForTurn.status,
    lifecycle_stage: mailboxWakeResultForTurn.lifecycleStage ?? null,
    lifecycle_reason: mailboxWakeResultForTurn.lifecycleReason ?? null,
    decision_ids: mailboxWakeResultForTurn.decisionIds,
    voice_checkpoint_refs: voiceCheckpointRefs,
    requires_voice_checkpoint: requiresVoiceCheckpoint,
    requires_voice_checkpoint_source: requiresVoiceCheckpointSource,
    evidence_refs: mailboxWakeResultForTurn.evidenceRefs,
    reconciled_from_wake_result: true,
    assistant_answer: false,
    terminal_eligible: false,
    context_role: "tool_evidence",
    raw_content_included: false,
  };
};

const formatMailboxWakeResultProjectionFinalAnswer = (projection: Record<string, unknown>): string => {
  const wakeRequestId = readDebugExportString(projection.wake_request_id) ?? "unknown";
  return `The live-source mailbox wake completed: wake ${wakeRequestId} recorded ${readAskTurnStringList(projection.decision_ids).length} decision receipt(s) and ${readAskTurnStringList(projection.voice_checkpoint_refs).length} voice/hold/block checkpoint ref(s).`;
};

const mailboxWakeResultProjectionIsTerminalComplete = (projection: Record<string, unknown> | null): boolean =>
  Boolean(
    projection &&
    readDebugExportString(projection.status) === "completed" &&
    (
      readDebugExportBoolean(projection.requires_voice_checkpoint) !== true ||
      readAskTurnStringList(projection.voice_checkpoint_refs).length > 0
    ),
  );

const isMailboxWakeResultFinalAnswerText = (value: unknown): boolean =>
  /\blive-source mailbox (?:wake|route) completed\b/i.test(readDebugExportString(value) ?? "");

const MICRODECK_QUERY_CAPABILITY_KEY = "live_env.query_micro_reasoner_presets";
const MICRODECK_DRAFT_CAPABILITY_KEY = "live_env.draft_micro_reasoner_preset";
const MICRODECK_QUERY_OBSERVATION_SCHEMA = "stage_play_micro_reasoner_prompt_preset_query_result/v1";
const MICRODECK_DRAFT_OBSERVATION_SCHEMA = "stage_play_micro_reasoner_prompt_preset_draft/v1";

const enrichDebugExportEnvelopeWithMailboxWakeResult = (
  envelope: HelixDebugExportEnvelope,
): HelixDebugExportEnvelope => {
  const activeTurnId = readDebugExportString(envelope.active_turn_id) ?? readDebugExportString(envelope.backend_turn_id);
  if (!activeTurnId) return envelope;
  const transactionReconciliation = reconcileStagePlayWakeFromTransactionDebug(
    asDebugExportRecord(envelope.stagePlayWakeTransaction) ?? asDebugExportRecord(envelope.stage_play_wake_transaction),
  );
  const mailboxWakeResultProjection = buildMailboxWakeResultProjectionForTurn(activeTurnId);
  if (!mailboxWakeResultProjection) {
    return transactionReconciliation
      ? {
          ...envelope,
          stage_play_live_source_mailbox_wake_reconciliation: transactionReconciliation,
        }
      : envelope;
  }
  const completed = mailboxWakeResultProjectionIsTerminalComplete(mailboxWakeResultProjection);
  const wakeResultObservation = {
    schema: "stage_play_live_source_mail_wake_result_observation/v1",
    source: "stage_play_live_source_mail_wake_result",
    ask_turn_id: activeTurnId,
    wake_result_id: mailboxWakeResultProjection.wake_result_id,
    wake_request_id: mailboxWakeResultProjection.wake_request_id,
    status: mailboxWakeResultProjection.status,
    completed,
    evidence_refs: mailboxWakeResultProjection.evidence_refs,
    assistant_answer: false,
    terminal_eligible: false,
    raw_content_included: false,
  };
  const terminalAuthority = envelope.terminal_answer_authority;
  const sourceTargetIntent = {
    ...(asDebugExportRecord(envelope.source_target_intent) ?? {}),
    schema: "helix.ask_source_target_intent.v1",
    target_source: "live_source_mailbox",
    targetSource: "live_source_mailbox",
    confidence: 1,
    reason: "wake_result_observed_for_ask_turn",
    wakeRequestId: mailboxWakeResultProjection.wake_request_id,
  };
  const stagePlayLiveSourceMailboxDebug = {
    ...(asDebugExportRecord(envelope.stage_play_live_source_mailbox_debug) ?? {}),
    schema: "stage_play.live_source_mailbox_debug.v1",
    source: "stage_play_live_source_mail_wake_result_projection",
    route_selected: "live_source_mailbox",
    route: "live_source_mailbox",
    route_admission: {
      status: "observed",
      reason: "wake_result_observed_for_ask_turn",
    },
    wakeRequestId: mailboxWakeResultProjection.wake_request_id,
    wake_request_id: mailboxWakeResultProjection.wake_request_id,
    wake_request_ids: [mailboxWakeResultProjection.wake_request_id],
    wake_result_id: mailboxWakeResultProjection.wake_result_id,
    wake_status: mailboxWakeResultProjection.status,
    lifecycle_stage: mailboxWakeResultProjection.lifecycle_stage,
    lifecycle_reason: mailboxWakeResultProjection.lifecycle_reason,
    decision_ids: mailboxWakeResultProjection.decision_ids,
    voice_receipt_refs: mailboxWakeResultProjection.voice_checkpoint_refs,
    voice_checkpoint_refs: mailboxWakeResultProjection.voice_checkpoint_refs,
    requires_voice_checkpoint: readDebugExportBoolean(mailboxWakeResultProjection.requires_voice_checkpoint) === true,
    requires_voice_checkpoint_source: mailboxWakeResultProjection.requires_voice_checkpoint_source,
    evidence_refs: mailboxWakeResultProjection.evidence_refs,
    source_target_intent: sourceTargetIntent,
    terminal_authority: terminalAuthority,
    wake_result_observation: wakeResultObservation,
  };
  const resolvedTurnSummary = {
    ...envelope.resolved_turn_summary,
    final_status: envelope.resolved_turn_summary.final_status,
    resolved_route_label: "live_source_mailbox",
    terminal_artifact_kind: envelope.resolved_turn_summary.terminal_artifact_kind,
    terminal_error_code: envelope.resolved_turn_summary.terminal_error_code,
  };
  const stagePlayWakeTransaction = buildStagePlayWakeTransactionDebug({
    activeTurnId,
    payload: envelope as unknown as Record<string, unknown>,
    routeMetadata:
      readStagePlayMailWakeRouteMetadata(asDebugExportRecord(envelope as unknown as Record<string, unknown>)?.route_metadata) ??
      readStagePlayMailWakeRouteMetadata(asDebugExportRecord(envelope as unknown as Record<string, unknown>)?.request_metadata),
    stagePlayMailboxDebug: stagePlayLiveSourceMailboxDebug,
    mailboxWakeResultProjection,
    phaseResolution: asDebugExportRecord(envelope.live_source_turn_phase_resolution),
  });
  if (transactionReconciliation) {
    stagePlayLiveSourceMailboxDebug.wake_reconciliation = transactionReconciliation;
  }
  const enriched: HelixDebugExportEnvelope = {
    ...envelope,
    selected_final_answer: envelope.selected_final_answer,
    final_answer_source: envelope.final_answer_source,
    resolved_turn_summary: resolvedTurnSummary,
    terminal_answer_authority: terminalAuthority,
    source_target_intent: sourceTargetIntent,
    stage_play_live_source_mailbox_debug: stagePlayLiveSourceMailboxDebug,
    ...(stagePlayWakeTransaction
      ? {
          stagePlayWakeTransaction,
          stage_play_wake_transaction: stagePlayWakeTransaction,
        }
      : {}),
    ...(transactionReconciliation
      ? { stage_play_live_source_mailbox_wake_reconciliation: transactionReconciliation }
      : {}),
    mailbox_wake_result_projection: mailboxWakeResultProjection,
    mailbox_wake_result_observation: wakeResultObservation,
  };
  const withoutHash: Record<string, unknown> = { ...enriched };
  delete withoutHash.payload_hash;
  return {
    ...enriched,
    payload_hash: hashDebugExportPayload(withoutHash),
  };
};

const inferMailboxWakeSelectedCapabilityForDebug = (
  transaction: Record<string, unknown> | null,
  projection: Record<string, unknown> | null,
): string => {
  const voiceReceiptId =
    readDebugExportString(transaction?.voiceReceiptId) ??
    readDebugExportString(transaction?.voice_receipt_id) ??
    readAskTurnStringList(asDebugExportRecord(transaction?.artifactRefs)?.voiceReceiptIds).at(0) ??
    readAskTurnStringList(projection?.voice_checkpoint_refs).at(0);
  if (voiceReceiptId) return "live_env.request_interim_voice_callout";
  const decisionReceiptId =
    readDebugExportString(transaction?.decisionReceiptId) ??
    readDebugExportString(transaction?.decision_receipt_id) ??
    readAskTurnStringList(asDebugExportRecord(transaction?.artifactRefs)?.decisionIds).at(0) ??
    readAskTurnStringList(projection?.decision_ids).at(0);
  if (decisionReceiptId) return "live_env.record_live_source_mail_decision";
  const selectedCapability = readDebugExportString(transaction?.selectedCapability) ??
    readDebugExportString(transaction?.selected_capability);
  if (selectedCapability && /^live_env\./i.test(selectedCapability)) return selectedCapability;
  return "live_env.read_processed_live_source_mail";
};

const readMailboxWakeSourceTargetForDebug = (envelope: Record<string, unknown>): string | null => {
  const sourceTargetIntent = asDebugExportRecord(envelope.source_target_intent);
  const evidenceTargetArbitration = asDebugExportRecord(envelope.evidence_target_arbitration);
  const mailboxDebug = asDebugExportRecord(envelope.stage_play_live_source_mailbox_debug);
  return (
    readDebugExportString(sourceTargetIntent?.target_source) ??
    readDebugExportString(sourceTargetIntent?.targetSource) ??
    readDebugExportString(evidenceTargetArbitration?.selected_target_source) ??
    readDebugExportString(mailboxDebug?.route_selected) ??
    readDebugExportString(mailboxDebug?.route) ??
    null
  );
};

const readMailboxWakeSelectedCapabilityForDebug = (envelope: Record<string, unknown>): string | null => {
  const authoritativeCapability = readAuthoritativeMailboxWakeSelectedCapabilityForDebug(envelope);
  if (authoritativeCapability) return authoritativeCapability;
  const transaction =
    asDebugExportRecord(envelope.stagePlayWakeTransaction) ??
    asDebugExportRecord(envelope.stage_play_wake_transaction);
  const agentStepDecision = asDebugExportRecord(envelope.agent_step_decision);
  const capabilityPlan = asDebugExportRecord(envelope.capability_plan);
  const toolAdmission = asDebugExportRecord(envelope.tool_call_admission_decision);
  const mailboxDebug = asDebugExportRecord(envelope.stage_play_live_source_mailbox_debug);
  return (
    readDebugExportString(transaction?.selectedCapability) ??
    readDebugExportString(transaction?.selected_capability) ??
    readDebugExportString(envelope.selected_capability) ??
    readDebugExportString(envelope.executed_capability) ??
    readDebugExportString(asDebugExportRecord(envelope.executed_capability)?.capability) ??
    readDebugExportString(agentStepDecision?.chosen_capability) ??
    readDebugExportString(agentStepDecision?.selected_tool) ??
    readDebugExportString(capabilityPlan?.selected_capability) ??
    readDebugExportString(capabilityPlan?.selected_capability_key) ??
    readDebugExportString(toolAdmission?.selected_capability) ??
    readDebugExportString(toolAdmission?.admitted_tool) ??
    readDebugExportString(mailboxDebug?.capability) ??
    null
  );
};

const preserveMailboxWakePreReconciliationField = (
  envelope: Record<string, unknown>,
  key: string,
  value: unknown,
): void => {
  if (Object.prototype.hasOwnProperty.call(envelope, key)) return;
  envelope[key] = value ?? null;
};

const clearCompletedMailboxWakeStaleFailureMirrors = (
  envelope: Record<string, unknown>,
): void => {
  preserveMailboxWakePreReconciliationField(
    envelope,
    "pre_reconciliation_terminal_error_code",
    readDebugExportString(envelope.terminal_error_code),
  );
  preserveMailboxWakePreReconciliationField(
    envelope,
    "pre_reconciliation_terminal_failure_text",
    readDebugExportString(envelope.terminal_failure_text),
  );
  const typedFailure = asDebugExportRecord(envelope.typed_failure);
  if (typedFailure) {
    preserveMailboxWakePreReconciliationField(envelope, "pre_reconciliation_typed_failure", typedFailure);
    if (!asDebugExportRecord(envelope.rejected_typed_failure)) {
      envelope.rejected_typed_failure = {
        ...typedFailure,
        rejected_reason: "stage_play_mailbox_wake_result_reconciled",
        superseded_by_terminal_artifact_kind: "stage_play_live_source_mail_wake_result",
        assistant_answer: false,
        raw_content_included: false,
      };
    }
  }
  delete envelope.typed_failure;
  delete envelope.terminal_error_code;
  delete envelope.terminal_failure_text;
};

