const prepareHelixAskLiveResponsePayload = (
  payload: unknown,
  options?: {
    mode?: HelixAskLiveDebugMode;
  },
): unknown => {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) return payload;
  const record = payload as Record<string, unknown>;
  syncHelixTypedFailureAuthorityPublicMirrors(record);
  syncMailboxWakeResultResponseProjection(record);
  syncSupersededCompoundCoverageGateFromTerminalAnswer(record);
  syncTerminalProjectionDebugExportMirrors(record);
  ensureHelixAskTurnTranscriptScaffold({
    payload: record,
    eventSource: "reconstructed",
  });
  attachHelixAskRuntimeTransparency(record);
  rememberHelixAskPublicLifecycle(record);
  if (options?.mode === "deep") return record;
  if (!record.debug || typeof record.debug !== "object") return record;
  const slimDebug = buildHelixAskLiveDebugSlim(record);
  if (!slimDebug) return record;
  return {
    ...record,
    debug: slimDebug,
    live_debug_mode: "slim",
  };
};

