const askTurnMentionsLiveSourceMailMemory = (prompt: string): boolean =>
  /\b(?:what\s+have\s+you\s+noticed|noticed\s+so\s+far|what\s+did\s+you\s+notice|anything\s+important|recent\s+(?:mail|updates|observations)|live[-\s]?source\s+(?:mail|updates|context)|watch\s+job|mail\s+decisions)\b/i.test(prompt);

const buildLiveSourceMailContextAnswer = (
  pack: StagePlayLiveSourceMailContextPackV1,
  prompt: string,
): string | null => {
  if (!askTurnMentionsLiveSourceMailMemory(prompt)) return null;
  if (pack.includedReason === "none" || pack.latestDecisions.length === 0) return null;
  const decisionLines = pack.latestDecisions
    .slice(-6)
    .map((decision) => {
      const detail =
        decision.textAnswerDraft ??
        decision.voiceCalloutDraft ??
        decision.rationalePreview;
      return detail ? `- ${decision.decision}: ${detail}` : `- ${decision.decision}`;
    })
    .filter(Boolean);
  if (decisionLines.length === 0) return null;
  const activeObjective = pack.activeWatchJobs.at(-1)?.objectiveText;
  const cursor = pack.currentMailboxCursor ? `Current mailbox cursor: ${pack.currentMailboxCursor}` : null;
  return [
    activeObjective ? `Watch objective: ${activeObjective}` : null,
    "Recent live-source mail decisions:",
    ...decisionLines,
    cursor,
    "This is based on compact live-source mail decisions, not raw capture.",
  ].filter((line): line is string => Boolean(line)).join("\n");
};

const attachLiveSourceMailContextPackToAskPayload = (input: {
  payload: Record<string, unknown>;
  turnId: string;
  threadId: string;
  promptText: string;
  roomId?: string | null;
  environmentId?: string | null;
}): StagePlayLiveSourceMailContextPackV1 => {
  const pack = buildStagePlayLiveSourceMailContextPack({
    threadId: input.threadId,
    roomId: input.roomId ?? null,
    environmentId: input.environmentId ?? null,
  });
  input.payload.live_source_mail_context_pack = pack;
  input.payload.live_source_mail_context_pack_id = pack.contextPackId;
  input.payload.live_source_mail_context_pack_evidence_refs = pack.evidenceRefs;
  if (
    input.payload.ask_turn_preflight_context &&
    typeof input.payload.ask_turn_preflight_context === "object" &&
    !Array.isArray(input.payload.ask_turn_preflight_context)
  ) {
    input.payload.ask_turn_preflight_context = Object.freeze({
      ...(input.payload.ask_turn_preflight_context as Record<string, unknown>),
      live_source_mail_context_pack: pack,
    });
  }
  const currentLedger = Array.isArray(input.payload.current_turn_artifact_ledger)
    ? (input.payload.current_turn_artifact_ledger as HelixTurnArtifact[])
    : [];
  const retainedLedger = currentLedger.filter((artifact) => artifact.kind !== "live_source_mail_context_pack");
  const contextPackArtifact: HelixTurnArtifact = {
    artifact_id: `${input.turnId}:live_source_mail_context_pack:${pack.contextPackId}`,
    turn_id: input.turnId,
    producer_item_id: "stage_play_live_source_mail_context_pack",
    kind: "live_source_mail_context_pack",
    created_at_ms: Date.now(),
    source_scope: "prior_turn_context",
    goal_hash: hashDebugExportPayloadShort([input.turnId, input.promptText, pack.contextPackId]),
    payload: pack,
  };
  input.payload.current_turn_artifact_ledger = mergeAskTurnLedgerArtifacts([...retainedLedger, contextPackArtifact]);
  if (input.payload.debug && typeof input.payload.debug === "object" && !Array.isArray(input.payload.debug)) {
    const debug = input.payload.debug as Record<string, unknown>;
    debug.live_source_mail_context_pack = pack;
    debug.live_source_mail_context_pack_id = pack.contextPackId;
    debug.live_source_mail_context_pack_evidence_refs = pack.evidenceRefs;
    debug.current_turn_artifact_ledger = input.payload.current_turn_artifact_ledger;
    debug.ask_turn_preflight_context = input.payload.ask_turn_preflight_context;
  }
  return pack;
};

const attachLiveSourceConversationContextPackToAskPayload = (input: {
  payload: Record<string, unknown>;
  turnId: string;
  threadId: string;
  promptText: string;
  roomId?: string | null;
  environmentId?: string | null;
  mailPack?: StagePlayLiveSourceMailContextPackV1 | null;
}): StagePlayLiveSourceConversationContextPackV1 => {
  const latestJob = input.mailPack?.activeWatchJobs.at(-1) ?? null;
  const latestNarrative = input.mailPack?.latestNarrativeStates?.at(-1) ?? null;
  const latestPolicyRef = latestJob?.policyId ?? latestNarrative?.policyId ?? null;
  const latestMailIds = input.mailPack?.latestMailItems.slice(-3).map((item) => item.mailId) ?? [];
  const event = recordStagePlayLiveSourceConversationEvent({
    threadId: input.threadId,
    jobId: latestJob?.jobId ?? latestNarrative?.jobId ?? null,
    turnId: input.turnId,
    source: "user_text",
    text: input.promptText,
    mailIds: latestMailIds,
    narrativeStateId: latestNarrative?.narrativeStateId ?? null,
    watchJobPolicyRef: latestPolicyRef,
    evidenceRefs: [
      input.turnId,
      ...(input.mailPack?.evidenceRefs ?? []),
    ],
  });
  const pack = buildStagePlayLiveSourceConversationContextPack({
    threadId: input.threadId,
    jobId: event.jobId ?? null,
    turnId: input.turnId,
  });
  input.payload.live_source_conversation_context_pack = pack;
  input.payload.live_source_conversation_context_pack_id = pack.contextPackId;
  input.payload.live_source_conversation_context_pack_evidence_refs = pack.evidenceRefs;
  if (
    input.payload.ask_turn_preflight_context &&
    typeof input.payload.ask_turn_preflight_context === "object" &&
    !Array.isArray(input.payload.ask_turn_preflight_context)
  ) {
    input.payload.ask_turn_preflight_context = Object.freeze({
      ...(input.payload.ask_turn_preflight_context as Record<string, unknown>),
      live_source_conversation_context_pack: pack,
    });
  }
  const currentLedger = Array.isArray(input.payload.current_turn_artifact_ledger)
    ? (input.payload.current_turn_artifact_ledger as HelixTurnArtifact[])
    : [];
  const retainedLedger = currentLedger.filter((artifact) => artifact.kind !== "live_source_conversation_context_pack");
  const contextPackArtifact: HelixTurnArtifact = {
    artifact_id: `${input.turnId}:live_source_conversation_context_pack:${pack.contextPackId}`,
    turn_id: input.turnId,
    producer_item_id: "stage_play_live_source_conversation_context_pack",
    kind: "live_source_conversation_context_pack",
    created_at_ms: Date.now(),
    source_scope: "prior_turn_context",
    goal_hash: hashDebugExportPayloadShort([input.turnId, input.promptText, pack.contextPackId]),
    payload: pack,
  };
  input.payload.current_turn_artifact_ledger = mergeAskTurnLedgerArtifacts([...retainedLedger, contextPackArtifact]);
  if (input.payload.debug && typeof input.payload.debug === "object" && !Array.isArray(input.payload.debug)) {
    const debug = input.payload.debug as Record<string, unknown>;
    debug.live_source_conversation_context_pack = pack;
    debug.live_source_conversation_context_pack_id = pack.contextPackId;
    debug.live_source_conversation_context_pack_evidence_refs = pack.evidenceRefs;
    debug.current_turn_artifact_ledger = input.payload.current_turn_artifact_ledger;
    debug.ask_turn_preflight_context = input.payload.ask_turn_preflight_context;
  }
  return pack;
};

const promoteLiveSourceMailContextAnswerIfApplicable = (input: {
  payload: Record<string, unknown>;
  pack: StagePlayLiveSourceMailContextPackV1;
  promptText: string;
}): boolean => {
  const answer = buildLiveSourceMailContextAnswer(input.pack, input.promptText);
  if (!answer) return false;
  const existingTerminalKind = readAskTurnString(input.payload.terminal_artifact_kind);
  const existingFinalSource = readAskTurnString(input.payload.final_answer_source);
  const existingTerminalError = readAskTurnString(input.payload.terminal_error_code);
  const mayPromote =
    !existingTerminalKind ||
    existingTerminalKind === "typed_failure" ||
    existingTerminalKind === "model_only_answer" ||
    existingFinalSource === "no_tool_direct" ||
    Boolean(existingTerminalError);
  if (!mayPromote) return false;
  input.payload.ok = true;
  input.payload.response_type = "final_answer";
  input.payload.final_status = "final_answer";
  input.payload.answer = answer;
  input.payload.text = answer;
  input.payload.assistant_answer = answer;
  input.payload.selected_final_answer = answer;
  input.payload.finalAnswer = answer;
  input.payload.final_answer_source = "artifact_synthesis";
  input.payload.terminal_artifact_kind = "live_source_mail_context_pack";
  input.payload.terminal_artifact_id = input.pack.contextPackId;
  delete input.payload.terminal_error_code;
  if (input.payload.terminal_presentation && typeof input.payload.terminal_presentation === "object") {
    const presentation = input.payload.terminal_presentation as Record<string, unknown>;
    presentation.concise_text = answer;
    presentation.terminal_artifact_kind = "live_source_mail_context_pack";
  }
  if (input.payload.debug && typeof input.payload.debug === "object" && !Array.isArray(input.payload.debug)) {
    const debug = input.payload.debug as Record<string, unknown>;
    debug.selected_final_answer = answer;
    debug.final_answer_source = "artifact_synthesis";
    debug.terminal_artifact_kind = "live_source_mail_context_pack";
    debug.terminal_artifact_id = input.pack.contextPackId;
    debug.terminal_error_code = null;
  }
  return true;
};

