    const deadlineScale = clampNumber(runtimeP50Ms / FAST_QUALITY_TOTAL_BUDGET_BASE_MS, 1, 20);
    const FAST_QUALITY_TOTAL_BUDGET_MS = Math.round(FAST_QUALITY_TOTAL_BUDGET_BASE_MS * deadlineScale);
