            payload.current_turn_artifact_ledger = currentTurnArtifacts;
            payload.final_answer_draft = lateFinalDraft;
            payload.model_only_concept_final_answer_draft = lateFinalDraft;
            payload.text = lateFinalText;
            payload.answer = lateFinalText;
            payload.assistant_answer = lateFinalText;
            payload.selected_final_answer = lateFinalText;
            payload.response_type = "final_answer";
            payload.final_status = "final_answer";
